def modulation_depth_scan(ctx: Context, targets: Mapping[str, Any], *,
                          swings=(0.9, 1.3, 1.8, 2.2, 2.6, 3.1, 3.6, 4.5, 5.0, 5.5),
                          eff_scales=(1.0, 1.25, 1.5, 2.0, 2.5, 3.0),
                          conventions=("centered", "one_sided"), mode: str = "oracle",
                          alt_effs: Mapping[str, float] | None = None) -> dict:
    import tempfile
    cal14 = targets["CAL-14"]
    rows = []
    base_cfg = ctx.config(BANK)
    base_efficiency = float(base_cfg.get(LEAF_JUNCTION_EFF))
    # a scratch child of g26 that only widens the leaves' plausible ranges (same values and provenance), so the scan may leave the priors - it is deleted after the scan and never written to the package
    scratch = tempfile.TemporaryDirectory(prefix="mrm_cal14_scan_")
    widened_path = widened_child(BANK, {**ctx.ranges, LEAF_DRIVE_SWING: [0.1, 10.0], LEAF_JUNCTION_EFF: [1.0, 900.0]},
                                 scratch.name)

    def row(convention, swing_v, eff_scale, eff_base):
        ov = {LEAF_DRIVE_SWING: swing_v, LEAF_JUNCTION_EFF: base_efficiency * eff_scale,
            "driver.level_convention": convention}
        cfg = ctx.config(widened_path, ov)
        r = replicas.relOMA_map(cfg, cal14, with_variants=False, mode=mode)
        _, plant = replicas.resolve_plant(cfg)
        ring = replicas.StaticRing(plant)
        lo, hi = ring.nrz_levels(CAL14_BIAS_V)
        swing_pm = float((ring.junction_shift_m(hi)[0] - ring.junction_shift_m(lo)[0]) * 1e12)
        fwhm_pm = float(ring.lam_line / ring.q_loaded * 1e12)
        return {"level_convention": convention, "swing_pp_v": swing_v, "eff_scale": eff_scale, "eff_base": eff_base,
                "eff_at_0v_pm_per_v": base_efficiency * eff_scale, "levels_v": [lo, hi], "swing_pm": swing_pm,
                "fwhm_pm": fwhm_pm, "depth": swing_pm / fwhm_pm, "reloma_db": r.value}
    for convention in conventions:
        for swing_v in swings:
            for eff_scale in eff_scales:
                # the efficiency scales run only at a 1.3 Vpp swing and at the preset's swing - other swings only at scale 1
                if eff_scale != 1.0 and swing_v != 1.3 and swing_v != float(base_cfg.get(LEAF_DRIVE_SWING)):
                    continue
                rows.append(row(convention, swing_v, eff_scale, "context"))
    for name, eff in (alt_effs or {}).items():
        for swing_v in swings:
            rows.append(row("centered", swing_v, float(eff) / base_efficiency, name))
    scratch.cleanup()
    return {"mode": mode, "eff_at_0v_base_pm_per_v": base_efficiency, "alt_effs": dict(alt_effs or {}), "rows": rows}

def row(convention, swing_v, eff_scale, eff_base):
    ov = {LEAF_DRIVE_SWING: swing_v, LEAF_JUNCTION_EFF: base_efficiency * eff_scale,
        "driver.level_convention": convention}
    cfg = ctx.config(widened_path, ov)
    r = replicas.relOMA_map(cfg, cal14, with_variants=False, mode=mode)
    _, plant = replicas.resolve_plant(cfg)
    ring = replicas.StaticRing(plant)
    lo, hi = ring.nrz_levels(CAL14_BIAS_V)
    swing_pm = float((ring.junction_shift_m(hi)[0] - ring.junction_shift_m(lo)[0]) * 1e12)
    fwhm_pm = float(ring.lam_line / ring.q_loaded * 1e12)
    return {"level_convention": convention, "swing_pp_v": swing_v, "eff_scale": eff_scale, "eff_base": eff_base,
            "eff_at_0v_pm_per_v": base_efficiency * eff_scale, "levels_v": [lo, hi], "swing_pm": swing_pm,
            "fwhm_pm": fwhm_pm, "depth": swing_pm / fwhm_pm, "reloma_db": r.value}

def bank_config_for(th, hyp=hyp):
    ov = {LEAF_HEATER_FULL_SCALE: th["full_scale_v"], LEAF_RESONANCE_OFFSET: th["die_resonance_offset_nm"]}
    ov.update({k: v * th["ring_sigma_scale"] for k, v in RING_SIGMA_PATHS.items()})
    ov.update({k: 0.0 for k in DIE_SIGMA_PATHS})
    return ctx.config(BANK, ov, alts={"uncertainty.thermo_optic": hyp})

def predict(th, ref=ref, bank_config_for=bank_config_for):
    d = dac_codes(bank_config_for(th), referencing=ref, n_dies=n_dies, variation="sample")
    return {"CAL-9a": d["swing"], "CAL-9b": d["lane_offsets"], "CAL-9c": d["code_range"]}

def derived(th, ref=ref, bank_config_for=bank_config_for):
    d = dac_codes(bank_config_for(th), referencing=ref, n_dies=n_dies, variation="sample")
    return {"median_of_dies": {k: d[k] for k in ("swing", "lane_offsets", "code_range",
                                                  "infeasible_samples", "victim_rise_k")},
            "per_die": d["per_die"]}

def laser_problems(ctx: Context, targets: Mapping[str, Any]) -> list[Problem]:
    cal12b = targets["CAL-12b"]
    params = [Param("line_offset_ghz", LEAF_LINE_OFFSET, -20.0, 20.0, 0.0, unit="ghz",
                    prior_source="leaf range [-20, 20]"),
              Param("line_sigma_scale", "variation.laser.line_offset_ghz.sigma_scale", 0.25, 2.0, 1.0, log=True,
                    declared_prior=False,
                    prior_source="fit bounds [0.25, 2] x the preset's 4 / 6 GHz die / line sigma (the variation "
                                 "entry declares no range)")]

    def predict(th):
        ov = {LEAF_LINE_OFFSET: th["line_offset_ghz"]}
        ov.update({k: v * th["line_sigma_scale"] for k, v in LINE_SIGMA_PATHS.items()})
        r = replicas.laser_line_statistics(ctx.config(BANK, ov), cal12b)
        return {"CAL-12b": r.value}
    return [Problem(group="laser", hypothesis="gaussian_die_plus_line", params=params, targets=[cal12b],
                    predict=predict, fixed={"preset": BANK, "worlds": 256, "clip_ghz": 20.0})]

def predict(th):
    ov = {LEAF_LINE_OFFSET: th["line_offset_ghz"]}
    ov.update({k: v * th["line_sigma_scale"] for k, v in LINE_SIGMA_PATHS.items()})
    r = replicas.laser_line_statistics(ctx.config(BANK, ov), cal12b)
    return {"CAL-12b": r.value}

def run(groups: Sequence[str] | None = None, *, quick: bool = False, out: str | Path | None = RESULTS_PATH,
        log: Callable[[str], None] = print, prior: CalibrationRun | dict | None = None) -> CalibrationRun:
    targets = core.calibration_targets()
    ctx = fit_groups.Context()
    names = list(GROUP_ORDER) if not groups else [g for g in GROUP_ORDER if g in groups]
    subset = names != list(GROUP_ORDER)
    previous = prior
    if subset and previous is None:
        source_path = Path(out) if out is not None and Path(out).exists() else RESULTS_PATH
        previous = load_results(source_path) if source_path.exists() else None
    previous_context = {}
    if previous is not None:
        previous_context = previous["context"] if isinstance(previous, dict) else previous.context
    previous_groups: dict = {}
    if previous is not None:
        previous_groups = previous.get("groups", {}) if isinstance(previous, dict) else \
            {g: {"decisions": [jsonable(d) for d in gr.decisions]} for g, gr in previous.groups.items()}
    if subset and previous is not None:
        ctx.ranges.update({k: list(v) for k, v in previous_context.get("ranges", {}).items()})
        if not previous_groups:
            # a bare context (no group records) - every leaf of it is an earlier group's
            ctx.device.update(previous_context.get("device", {}))
            ctx.system.update(previous_context.get("system", {}))

    # before rerun group g — load the previous record's leaves of every group that precedes g and is not rerun.
    # this holds for any subset, also a non-contiguous one such as `heater laser` (laser then sees the coupling ... dac leaves).
    # a later group's leaf never enters an earlier group's fit, as in a full run.
    def preceding_context(g: str) -> None:
        if not subset or previous is None:
            return
        for h in GROUP_ORDER[:GROUP_ORDER.index(g)]:
            if h in names or h not in previous_groups:
                continue
            paths = {d.get("path") for d in previous_groups[h].get("decisions", [])}
            previous_count = len(ctx.device) + len(ctx.system)
            ctx.device.update({k: v for k, v in previous_context.get("device", {}).items() if k in paths})
            ctx.system.update({k: v for k, v in previous_context.get("system", {}).items() if k in paths})
            if len(ctx.device) + len(ctx.system) > previous_count:
                log(f"context from the previous run of group {h}: "
                    f"{len(ctx.device) + len(ctx.system) - previous_count} leaves")
    calibration_run = CalibrationRun(
        created_utc=datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        git_commit=_git_commit(), groups={}, context={})
    if subset and isinstance(previous, dict):
        calibration_run.previous_groups = {g: v for g, v in previous.get("groups", {}).items() if g not in names}
        if calibration_run.previous_groups:
            calibration_run.notes.append(f"groups {', '.join(calibration_run.previous_groups)} from the run of "
                                         f"{previous.get('created_utc')}")

    def merged_context() -> dict:
        out_ctx = {k: dict(previous_context.get(k, {})) for k in ("device", "system", "ranges")} if subset else \
            {"device": {}, "system": {}, "ranges": {}}
        out_ctx["device"].update(ctx.device)
        out_ctx["system"].update(ctx.system)
        out_ctx["ranges"].update(ctx.ranges)
        return out_ctx
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        for g in names:
            log(f"group {g}")
            preceding_context(g)
            calibration_run.groups[g] = run_group(g, ctx, targets, quick=quick, log=log)
            calibration_run.context = merged_context()
            if out is not None:
                write_results(calibration_run, out)
    return calibration_run

def preceding_context(g: str) -> None:
    if not subset or previous is None:
        return
    for h in GROUP_ORDER[:GROUP_ORDER.index(g)]:
        if h in names or h not in previous_groups:
            continue
        paths = {d.get("path") for d in previous_groups[h].get("decisions", [])}
        previous_count = len(ctx.device) + len(ctx.system)
        ctx.device.update({k: v for k, v in previous_context.get("device", {}).items() if k in paths})
        ctx.system.update({k: v for k, v in previous_context.get("system", {}).items() if k in paths})
        if len(ctx.device) + len(ctx.system) > previous_count:
            log(f"context from the previous run of group {h}: "
                f"{len(ctx.device) + len(ctx.system) - previous_count} leaves")

def write_results(res: CalibrationRun, path: str | Path = RESULTS_PATH) -> Path:
    path = Path(path)
    record = {"schema": "mrm.calibration.fit/1", "created_utc": res.created_utc, "git_commit": res.git_commit,
         "reject_lr": REJECT_LR, "context": res.context, "notes": res.notes, "before_after": res.before_after,
         "groups": {}}
    for g in GROUP_ORDER:
        if g in res.previous_groups and g not in res.groups:
            record["groups"][g] = res.previous_groups[g]
    for g, group_result in res.groups.items():
        record["groups"][g] = {
            "targets": group_result.targets, "nominal": group_result.nominal, "runtime_s": group_result.runtime_s,
            "comparison": jsonable(group_result.comparison),
            "fits": {h: {k: v for k, v in jsonable(f).items() if k != "profiles"} for h,
                f in group_result.fits.items()},
            "profiles": {h: {n: jsonable(p) for n, p in ps.items()} for h, ps in group_result.profiles.items()},
            "decisions": [jsonable(x) for x in group_result.decisions],
            "extra": jsonable(group_result.extra)}
    record["groups"] = {g: record["groups"][g] for g in GROUP_ORDER if g in record["groups"]}
    path.write_text(json.dumps(record, indent=1, allow_nan=False, default=str))
    return path

def context_from_decisions(record: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
    out: dict[str, dict[str, Any]] = {"device": {}, "system": {}}
    groups = record.get("groups") or {}
    for g in GROUP_ORDER:
        for d in (groups.get(g) or {}).get("decisions") or []:
            p = d.get("path")
            if d.get("write_value", True) and p and not str(p).startswith("variation.") and p != "uncertainty":
                out["device" if d.get("scope") == "device" else "system"][p] = d["value"]
            if g == "coupling_er" and p == fit_groups.LEAF_COUPLER_DISPERSION:
                out["device"][p] = d["value"]
    return out

def _git_commit() -> str | None:
    root = Path(__file__).resolve().parents[2]
    try:
        head = subprocess.run(["git", "rev-parse", "--short", "HEAD"], capture_output=True, text=True,
                              cwd=root, timeout=10).stdout.strip() or None
        if head is None:
            return None
        dirty = subprocess.run(["git", "status", "--porcelain", "--", "mrm", "tests/calibration",
                                ":!mrm/calibration/latest_fit.json", ":!mrm/params/presets/g26_calibrated.yaml"],
                               capture_output=True, text=True, cwd=root, timeout=10).stdout.strip()
        return head + ("-dirty" if dirty else "")
    except Exception:  # noqa: BLE001
        return None

def _first_best(hyps: Sequence[str], fits: Mapping[str, FitResult]) -> str | None:
    if not hyps:
        return None
    c_min = min(fits[h].chi2 for h in hyps)
    return next(h for h in hyps if fits[h].chi2 <= c_min + TIE_DCHI2)

def _leaf_value_and_provenance(cfg, path: str) -> tuple[Any, str]:
    try:
        leaf = cfg.leaf(path)
        return jsonable(leaf.value), str(leaf.provenance)
    except Exception:  # noqa: BLE001 - a leaf absent from the preset
        return None, "absent"

def _identifiability(par: core.Param, profiles: Mapping[str, Profile], fits: Mapping[str, FitResult],
                     rejected: set[str]) -> dict[str, Any]:
    used = {h: p for h, p in profiles.items() if h not in rejected}
    if not used:
        return {"rule": "no profile", "calibrated": False}
    hull = _interval_hull([p.interval for p in used.values()])
    has_open_endpoint = any(p.open_lo or p.open_hi for p in used.values())
    # components - gaps inside one hypothesis' profile, plus gaps between the hypotheses' intervals
    n_components = 1 + sum(p.n_components - 1 for p in used.values())
    intervals = sorted((list(p.interval) for p in used.values()), key=lambda iv: iv[0])
    reach = intervals[0][1]
    for iv in intervals[1:]:
        if iv[0] > reach:
            n_components += 1
        reach = max(reach, iv[1])
    width_fraction = core.half_prior(par, hull)
    declared = bool(getattr(par, "declared_prior", True))
    passes_interval_rule = width_fraction <= 0.5 and not has_open_endpoint and n_components == 1 and declared
    best_by_h = {h: fits[h].theta.get(par.name) for h in used}
    return {"profile_95": hull, "prior": [par.lo, par.hi], "prior_source": par.prior_source,
            "log_prior": par.log, "width_frac": width_fraction, "open": has_open_endpoint, "components": n_components,
            "per_hypothesis": {h: {"interval": p.interval, "interval_raw": p.interval_raw, "best": best_by_h[h],
                                   "open_lo": p.open_lo, "open_hi": p.open_hi, "unique": p.unique,
                                   "chi2_min": p.chi2_min, "threshold": p.threshold}
                               for h, p in used.items()},
            "unique": bool(passes_interval_rule and all(p.unique for p in used.values()) and len(used) == 1),
            "calibrated": bool(passes_interval_rule),
            "rule": ("calibrated: 95 % profile hull within half the prior, closed, one interval" if passes_interval_rule else
                     "kept: " + "; ".join(x for x in (
                         f"width {width_fraction:.2f} of the prior > 0.5" if width_fraction > 0.5 else "",
                         "interval reaches the prior bound (open)" if has_open_endpoint else "",
                         f"{n_components} disjoint intervals across hypotheses" if n_components > 1 else "",
                         "no declared prior range (fit bounds only), so the half-prior rule cannot apply"
                         if not declared else "") if x))}

def _residual_summary(fr: FitResult) -> dict[str, Any]:
    return {t: {"max_abs_residual": v["max_abs_residual"], "z_max": v["z_max"],
                "tolerance_level": v["tolerance_level"]} for t, v in fr.targets.items()}

def _fit_hypotheses(probs: Sequence[Problem], *, extra_starts: int = 0, max_nfev: int = 150, log=print) -> dict:
    fits = {}
    for problem in probs:
        started = time.time()
        fits[problem.hypothesis] = core.fit(problem, max_nfev=max_nfev, extra_starts=extra_starts)
        log(f"  fit {problem.group} {problem.hypothesis}: chi2 {fits[problem.hypothesis].chi2:.4g} "
            f"theta {{{', '.join(f'{k}: {_fmt_sig(v)}' for k, v in fits[problem.hypothesis].theta.items())}}} "
            f"({time.time() - started:.0f} s)")
    return fits

def _profile_leaves(prob: Problem, fr: FitResult, *, n_grid: int, max_nfev: int, log=print,
                    names: Sequence[str] | None = None) -> dict[str, Profile]:
    profiles = {}
    for par in prob.params:
        if par.role != "leaf" or (names is not None and par.name not in names):
            continue
        started = time.time()
        profiles[par.name] = core.profile(prob, fr, par.name, n_grid=n_grid, max_nfev=max_nfev)
        profile_result = profiles[par.name]
        log(f"    profile {prob.hypothesis} {par.name}: [{_fmt_sig(profile_result.interval[0])}, {_fmt_sig(profile_result.interval[1])}] "
            f"frac {profile_result.width_frac:.2f} open {profile_result.open_lo}/{profile_result.open_hi} ({time.time() - started:.0f} s)")
    fr.profiles.update(profiles)
    return profiles

def _coupling_note(fr: FitResult) -> str:
    d = fr.derived or {}
    th = fr.theta
    return (f"cold 0 V coupling ratio x0 {_fmt_sig(d.get('x0_cold_0v', float('nan')))} ({d.get('branch_at_0v')}), "
            f"Q_i {_fmt_sig(d.get('q_intrinsic', float('nan')))}, instrument notch floor "
            f"{_fmt_sig(th.get('notch_floor_db', float('nan')))} dB (measurement nuisance, not written)")

def coupling_context(record: Mapping[str, Any]) -> fit_groups.Context:
    ctx = fit_groups.Context(ranges={k: list(v) for k, v in record.get("context", {}).get("ranges", {}).items()})
    device_values = record.get("context", {}).get("device", {})
    for h in GROUP_ORDER[:GROUP_ORDER.index("coupling_er")]:
        paths = {d.get("path") for d in record.get("groups", {}).get(h, {}).get("decisions", [])}
        ctx.device.update({k: v for k, v in device_values.items() if k in paths})
    return ctx

def _fit_from_dict(d: Mapping[str, Any]) -> FitResult:
    keys = {f.name for f in dataclasses.fields(FitResult)} - {"profiles"}
    return FitResult(**{k: d[k] for k in keys if k in d})

def _group_monitor(ctx, targets, *, n_grid, inner, quick, log):
    problems = fit_groups.monitor_problems(ctx, targets)
    problem_by_hyp = {p.hypothesis: p for p in problems}
    fits = _fit_hypotheses(problems, log=log)
    comparison = core.compare_hypotheses("monitor", list(fits.values()), note="lock set-point of the G26 loop")
    rejected = _rejected_hypotheses(comparison)
    profiles = {h: _profile_leaves(problem_by_hyp[h], fits[h], n_grid=n_grid, max_nfev=inner, log=log) for h in fits
                if h not in rejected}
    nominal = "setpoint=half_max" if "setpoint=half_max" not in rejected else comparison.best
    cfg = ctx.config(fit_groups.BANK)
    par = problem_by_hyp[nominal].params[0]
    ident = _identifiability(par, {h: profiles[h][par.name] for h in profiles}, fits, rejected)
    decision = _leaf_decision(cfg, par, fits[nominal], ident, scope="system", hypothesis=nominal, targets=["CAL-8"],
                              extra_note="CAL-8 identifies only gain x line power x lock factor (the weak drop "
                                         "coupler); the lock factor is the unpublished set-point, so the gain is "
                                         "conditional on it")
    for h, f in fits.items():
        if h != nominal and h not in rejected:
            decision.alternatives[f"cal8_{h.split('=')[1]}_lock"] = {
                "value": float(f.theta[par.name]), "provenance": decision.provenance,
                "note": f"CAL-8 under the {h} lock (chi2 {f.chi2:.3g})"}
    return GroupResult("monitor", ["CAL-8"], nominal, fits, comparison, profiles, [decision], {}, 0.0)

def _interpolate_crossing(rows: list, key: str, target_db: float):
    rows = sorted(rows, key=lambda r: r[key])
    x = np.array([r[key] for r in rows])
    y = np.array([r["reloma_db"] for r in rows])
    depth = np.array([r["depth"] for r in rows])
    crossings = np.flatnonzero((y[:-1] < target_db) & (y[1:] >= target_db))
    if not crossings.size:
        return None, None, (float(np.max(y)) if y.size else float("nan"))
    i = int(crossings[0])
    fraction = (target_db - y[i]) / (y[i + 1] - y[i])
    return float(x[i] + fraction * (x[i + 1] - x[i])), float(depth[i] + fraction * (depth[i + 1] - depth[i])), float(np.max(y))

def _preset_dir() -> Path:
    from mrm.params import config
    return Path(config.PRESET_DIR)

def preset_document(results: Mapping[str, Any]) -> tuple[dict, list[str]]:
    g26_raw = _raw_g26()
    target_meta = _target_meta()
    doc: dict = {"extends": "g26"}
    groups = results["groups"]
    created = results.get("created_utc", datetime.datetime.now(datetime.timezone.utc).isoformat())
    doc["meta"] = {
        "name": PRESET_NAME, "kind": "preset",
        "description": ("g26 with the leaves fitted to the calibration targets CAL-1..CAL-14 (and only to them) "
                        "through the replicas; provenance calibrated only where the half-prior rule holds"),
        "generation_mix": g26_raw.get("meta", {}).get("generation_mix", "") + (
            " Calibrated (mrm.calibration, " + str(created) + "): G25 Q_L, coupling and extinction mechanism, heater "
            "P_FSR / R / droop, junction efficiency, R C (G25 bench targets); G26 monitor gain; Guide line-error "
            "population (see each leaf's targets)."),
    }
    variation: dict = {}
    uncertainty: dict = {}
    selections: dict = {}           # uncertainty entry -> choice -> {leaf path: alternative name}
    for gname, group in groups.items():
        for decision in group["decisions"]:
            path = decision["path"]
            if path in _VARIATION_PSEUDO_PATHS:
                if not decision.get("write_value", True):
                    continue
                _variation_update(variation, g26_raw, decision)
                continue
            g26_leaf = _raw_leaf(g26_raw, path)
            if g26_leaf is None:
                continue
            generation, source = target_meta.get(decision["targets"][0], ("none",
                "VAL-TARGETS")) if decision["targets"] else ("none", "D07")
            leaf: dict = {}
            if decision.get("write_value", True) and decision["value"] is not None:
                leaf["value"] = _round_sig(float(decision["value"]))
                if decision["provenance"] == "calibrated":
                    leaf.update(provenance="calibrated", generation=generation, source=source)
                else:
                    leaf.update(provenance=g26_leaf.get("provenance", decision["provenance"]),
                                generation=g26_leaf.get("generation", generation), source=g26_leaf.get("source",
                                    source))
            else:
                leaf["value"] = g26_leaf.get("value")          # unchanged (needed for a leaf mapping)
            leaf["note"] = decision["note"]
            leaf["targets"] = list(decision["targets"])
            leaf["residual"] = _residual_block(decision["residual"])
            leaf["identifiable"] = _identifiable_block(decision["identifiable"], decision["hypothesis"])
            if decision.get("range"):
                leaf["range"] = [float(x) for x in decision["range"]]
            if decision.get("alternatives"):
                alts = {}
                for an, a in decision["alternatives"].items():
                    alternative = {"value": _round_sig(float(a["value"])), "provenance": a.get("provenance", "assumed"),
                           "note": a.get("note", "")}
                    if alternative["provenance"] == "calibrated":
                        alternative.update(generation=generation, source=source)
                    alts[an] = alternative
                    sel = a.get("select")
                    if sel:
                        # a world of an uncertainty entry selects this alternative (e.g. thermo_optic=H86 its own heater leaves) - restate the parent's entry with the selection added
                        entry_selections = selections.setdefault(sel["entry"], {})
                        entry_selections.setdefault(sel["choice"], {})[path] = an
                leaf["alternatives"] = alts
            if path == fit_groups.LEAF_COUPLER_DISPERSION and "cal_dispersion" in (decision.get("alternatives") or {}):
                # the nominal world must be the config as written - the calibrated dispersion becomes the leaf value and the solver value an alternative that the loss-mechanism worlds select
                cal = decision["alternatives"]["cal_dispersion"]
                leaf["value"] = _round_sig(float(cal["value"]))
                if cal.get("provenance") == "calibrated":
                    leaf.update(provenance="calibrated", generation=generation, source=source)
                else:
                    leaf.update(provenance="assumed", generation=generation, source=source)
                leaf["alternatives"] = {"solver": {
                    "value": g26_leaf.get("value"), "provenance": g26_leaf.get("provenance"),
                    "generation": g26_leaf.get("generation"), "source": g26_leaf.get("source"),
                    "note": "the coupler artefact's dispersion (the g26 value), selected by the loss-mechanism "
                            "worlds of uncertainty.er_mechanism"}}
                # a child's uncertainty entry replaces the parent's - restate its provenance, generation and source
                unc_entry = (g26_raw.get("uncertainty") or {}).get("er_mechanism") or {}
                uncertainty["er_mechanism"] = {"kind": "hypothesis", "nominal": "dispersion",
                                               "choices": {"dispersion": {}},
                                               **{k: unc_entry[k] for k in ("provenance", "generation", "source")
                                                  if k in unc_entry}}
            _set_path(doc, path, leaf)
    if "er_mechanism" in uncertainty:
        # each loss mechanism selects its own coefficient, the solver dispersion and its own branch alpha_other
        coupling_alts = set((_get_path(doc, fit_groups.LEAF_ALPHA_OTHER) or {}).get("alternatives", {}))
        er_choices = uncertainty["er_mechanism"]["choices"]
        for mech, leaf_path in (("ring_t_loss", fit_groups.LEAF_DLN_ALPHA_DT_RING),
                                ("heater_t_loss", fit_groups.LEAF_DLN_ALPHA_DT_HEATER)):
            er_choices[mech] = {leaf_path: mech, fit_groups.LEAF_COUPLER_DISPERSION: "solver"}
            if f"cal_{mech}_branch" in coupling_alts:
                er_choices[mech][fit_groups.LEAF_ALPHA_OTHER] = f"cal_{mech}_branch"
        uncertainty["er_mechanism"]["note"] = (
            "Extinction-droop mechanism, calibrated on CAL-1/CAL-2: 'dispersion' (nominal) is the coupler dispersion "
            "fitted with the under-coupled branch (the leaf value); the loss mechanisms select the solver dispersion "
            "(alternative 'solver') and fit only on the over-coupled branch (the mirror solution), so each selects its "
            "own coefficient AND its own alpha_other (cal_<mechanism>_branch, Q_L at the nominal): the branch is tied "
            "to the mechanism, so this entry is the joint (mechanism, regime) hypothesis and "
            "uncertainty.coupling_regime is its label (follows: er_mechanism). Likelihood ratios: "
            "docs/handoff/calibration.md")
    worlds = ((groups.get("coupling_er") or {}).get("extra") or {}).get("composed_worlds") or {}
    if "er_mechanism" in uncertainty and (g26_raw.get("uncertainty") or {}).get("coupling_regime") is not None:
        uncertainty["coupling_regime"] = _coupling_regime_label(g26_raw, groups["coupling_er"], worlds,
                                                                uncertainty["er_mechanism"])
    for entry, choices in selections.items():
        unc_entry = copy.deepcopy(uncertainty.get(entry) or (g26_raw.get("uncertainty") or {}).get(entry))
        if unc_entry is None:
            raise ValueError(f"uncertainty.{entry} is not in g26: cannot select calibrated alternatives in it")
        for choice, sel in choices.items():
            if choice not in unc_entry["choices"]:
                raise ValueError(f"uncertainty.{entry} has no choice {choice!r}")
            unc_entry["choices"][choice] = {**(unc_entry["choices"][choice] or {}), **sel}
        selected_paths = ", ".join(sorted({p for v in choices.values() for p in v}))
        unc_entry["note"] = (str(unc_entry.get("note", "")) + f" [g26_calibrated: the calibration adds its own leaves "
                             f"to {', '.join(sorted(choices))} ({selected_paths}), refitted in that world]")
        uncertainty[entry] = unc_entry
    if uncertainty:
        doc["uncertainty"] = uncertainty
    if variation:
        doc["variation"] = variation
    header = _preset_header(results)
    return doc, header

def _coupling_regime_label(raw: dict, g: Mapping[str, Any], worlds: Mapping[str, Any], er: dict) -> dict:
    branch_of = {}
    nominal = g.get("nominal")
    for mech in er["choices"]:
        rec = (g["fits"].get(nominal) if mech == er.get("nominal") else worlds.get(f"er_mechanism={mech}")) or {}
        b = (rec.get("derived") or {}).get("branch_at_0v")
        if b not in ("under", "over"):
            raise ValueError(f"coupling_er: the record gives no cold 0 V branch for er_mechanism={mech} "
                             f"(derived.branch_at_0v {b!r}); cannot label its coupling regime")
        branch_of[mech] = b
    labels = [c for c in ("under", "over") if c in branch_of.values()]
    g26_regime = copy.deepcopy((raw.get("uncertainty") or {}).get("coupling_regime")) or {}
    out = {"kind": "hypothesis", "follows": "er_mechanism", "map": dict(branch_of), "choices": {c: {} for c in labels},
           "nominal": branch_of[er["nominal"]]}
    out.update({k: g26_regime[k] for k in ("provenance", "generation", "source") if k in g26_regime})
    over = worlds.get("coupling_regime=over") or {}
    over_derived = over.get("derived") or {}
    over_within_tol = all(t.get("within_tolerance") for t in (over.get("targets") or {}).values()) if over else None
    x0 = {m: (worlds.get(f"er_mechanism={m}") or {}).get("derived", {}).get("x0_cold_0v") for m in branch_of}
    x0[er["nominal"]] = ((g["fits"].get(nominal) or {}).get("derived") or {}).get("x0_cold_0v")
    out["note"] = (
        "Coupling regime: under | over coupled at the 27.9 dB G25 notch. In the calibrated presets the regime is the "
        "second axis of the joint hypothesis uncertainty.er_mechanism (a label entry: follows er_mechanism, never "
        "drawn): the CAL-1/CAL-2 fit lands each extinction mechanism on one branch of the cold 0 V state (the G25 "
        "bench ring, x0 = kappa_e / (kappa_i + kappa_d) of the record), "
        + ", ".join(f"{m} {b}" + (f" (x0 {_round_sig(float(x0[m]), 4)})" if x0.get(m) is not None else "")
                    for m, b in branch_of.items())
        + ", and the crossed worlds miss the CAL-2 tolerance (docs/handoff/calibration.md 4.2). Pinning the label "
        "selects the mechanisms that give it (g26_overcoupled: the loss mechanisms; g26_low_eta, g26_hot_selfheat: "
        "dispersion). The label holds at the nominal Q_L; a q_loaded draw can move a world across critical coupling "
        "(see uncertainty.q_loaded)."
        + (f" g26's independent 'over' choice (alpha_other alternative 'over', the dispersion fit on the over branch) "
           f"is not a world here: chi2 {_round_sig(float(over['chi2']), 3)} against "
           f"{_round_sig(float(over['nominal_chi2']), 3)} for the nominal world, "
           + ("within" if over_within_tol else "outside") + " the CAL-2 tolerance, and it lands "
           + (f"{over_derived['branch_at_0v']}-coupled at 0 V (x0 {_round_sig(float(over_derived['x0_cold_0v']), 4)})"
              if over_derived.get("branch_at_0v") else "on an unknown branch")
           + "; the leaf alternative keeps its value" if over else ""))
    return out

def _variation_update(variation: dict, raw: dict, d: Mapping[str, Any]) -> None:
    scale = float(d["value"])
    raw_variation = raw.get("variation", {})
    if d["path"] == "variation.geometry.ring_sigma_scale":
        geometry = raw_variation.get("geometry", {})
        # a child's variation entry replaces each top key of the parent's (a shallow update) - restate the whole width / thickness mappings, or their die sigmas would be lost
        variation["geometry"] = {
            "width": {**geometry["width"], "ring_sigma_nm": _round_sig(float(geometry["width"]["ring_sigma_nm"]) * scale)},
            "thickness": {**geometry["thickness"],
                          "ring_sigma_nm": _round_sig(float(geometry["thickness"]["ring_sigma_nm"]) * scale)},
            "provenance": d["provenance"] if d["provenance"] == "calibrated" else geometry.get("provenance", "assumed"),
            "note": f"per-ring sigmas x{_round_sig(scale, 4)} ({', '.join(d['targets'])}): {d['note']}"}
    else:
        line_entry = raw_variation.get("laser.line_offset_ghz", {})
        variation["laser.line_offset_ghz"] = {
            "die_sigma": _round_sig(float(line_entry["die_sigma"]) * scale),
            "line_sigma": _round_sig(float(line_entry["line_sigma"]) * scale),
            "provenance": "calibrated" if d["provenance"] == "calibrated" else line_entry.get("provenance", "inferred"),
            "generation": line_entry.get("generation", "Guide"), "source": line_entry.get("source", "YOLE"),
            "note": f"die and line sigma x{_round_sig(scale, 4)} ({', '.join(d['targets'])}): {d['note']}"}

def bank_config(path: str | Path = PRESET_PATH):
    from mrm.validation import replicas
    return replicas.load_config(Path(path))

def _round_sig(x: Any, sig: int = 6) -> Any:
    if isinstance(x, float) and math.isfinite(x) and x != 0.0:
        return float(f"{x:.{sig}g}")
    if isinstance(x, list):
        return [_round_sig(v, sig) for v in x]
    if isinstance(x, dict):
        return {k: _round_sig(v, sig) for k, v in x.items()}
    return x

def _raw_g26() -> dict:
    from mrm.params import config
    return config.yaml_load((_preset_dir() / "g26.yaml").read_text())

def _raw_leaf(raw: dict, path: str) -> dict | None:
    node: Any = raw
    for k in path.split("."):
        if not isinstance(node, dict) or k not in node:
            return None
        node = node[k]
    return node if isinstance(node, dict) else None

def _get_path(tree: dict, path: str) -> Any:
    node: Any = tree
    for k in path.split("."):
        if not isinstance(node, dict) or k not in node:
            return None
        node = node[k]
    return node

def _set_path(tree: dict, path: str, value: Any) -> None:
    keys = path.split(".")
    node = tree
    for k in keys[:-1]:
        node = node.setdefault(k, {})
    node[keys[-1]] = value

def _residual_block(res: Mapping[str, Any]) -> dict:
    block = {}
    for target_id, residual in res.items():
        block[target_id] = {"max_abs": _round_sig(residual.get("max_abs_residual")),
            "z_max": _round_sig(residual.get("z_max"), 3),
                    "tolerance": residual.get("tolerance_level")}
    return block

def _identifiable_block(ident: Mapping[str, Any], hypothesis: str) -> dict:
    keys = ("profile_95", "prior", "width_frac", "open", "components", "unique", "calibrated")
    out = {k: _round_sig(jsonable(ident.get(k)), 5) for k in keys if k in ident}
    out["hypothesis"] = hypothesis
    out["rule"] = ident.get("rule")
    return out

def before_after(results: Mapping[str, Any], *, ids: Sequence[str] | None = None,
                 preset_path: str | Path = preset.PRESET_PATH,
                 bench_preset_path: str | Path | None = preset.BENCH_PRESET_PATH, log=print) -> dict[str, dict]:
    targets = calibration_targets()
    if bench_preset_path is not None and Path(bench_preset_path).exists():
        bench, bench_name = preset.bank_config(bench_preset_path), Path(bench_preset_path).stem
    else:
        bench, bench_name = preset.bench_config(results), "g25_test_vehicle + calibrated device leaves"
    bank = preset.bank_config(preset_path)
    table = {}
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        for target_id, target in targets.items():
            if ids and target_id not in ids:
                continue
            before = _replica_record(target, None)
            after = _replica_record(target, bench if target.generation == "G25" else bank)
            table[target_id] = {"before": before, "after": after, "plant_after": bench_name
                        if target.generation == "G25" else Path(preset_path).stem, "fit": bool(target.fit)}
            log(f"  {target_id}: before {before.get('level')} (|r| {_fmt_residual(before.get('max_abs_residual'))}) -> "
                f"after {after.get('level')} (|r| {_fmt_residual(after.get('max_abs_residual'))})")
    return table

def format_table(table: Mapping[str, dict]) -> str:
    rows = [f"{'id':8s} {'before':>10s} {'|res| before':>14s} {'after':>10s} {'|res| after':>13s}"]
    for target_id, record in table.items():
        before, after = record["before"], record["after"]
        rows.append(f"{target_id:8s} {str(before.get('level')):>10s} {_fmt_residual(before.get('max_abs_residual')):>14s} "
                    f"{str(after.get('level')):>10s} {_fmt_residual(after.get('max_abs_residual')):>13s}")
    return "\n".join(rows)

def _replica_record(t, plant) -> dict:
    started = time.time()
    result = replicas.run_target(t, plant)
    record: dict[str, Any] = {"status": result.status, "value": jsonable(result.value), "notes": list(result.notes)[:3],
                           "runtime_s": time.time() - started}
    if result.status == "ok":
        evaluation = evaluate(t, result.value)
        record.update(level=evaluation.level, passed=evaluation.passed,
            max_abs_residual=evaluation.max_abs_residual, z=evaluation.z)
    return record

def register(name: str, help: str, setup: Callable[[argparse.ArgumentParser], None],
             run: Callable[[argparse.Namespace], int]) -> None:
    if name in COMMANDS and COMMANDS[name].run is not run:
        raise ValueError(f"mrm command {name!r} is registered twice")
    COMMANDS[name] = Command(name, help, setup, run)

def _load_providers() -> None:
    global _PROVIDERS_LOADED
    if _PROVIDERS_LOADED:
        return
    for spec in PROVIDERS:
        module_name, _, function_name = spec.partition(":")
        try:
            module = importlib.import_module(module_name)
        except ModuleNotFoundError as e:
            if e.name and (module_name == e.name or module_name.startswith(e.name + ".")):
                continue                     # the provider module itself is absent - skip it
            raise                            # an import error INSIDE the provider is a real error
        getattr(module, function_name or "register_cli")(register)
    _PROVIDERS_LOADED = True

def main(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(list(sys.argv[1:] if argv is None else argv))
    return int(args._run(args) or 0)

