def with_period(self, period_ticks: int, phase_ticks: int = 0) -> "ControllerSpec":
    period_ticks = int(period_ticks)
    if period_ticks < 1:
        raise TimingError(f"controller period must be >= 1 tick, got {period_ticks}")
    if int(phase_ticks) < 0:
        raise TimingError(f"controller phase must be >= 0 ticks, got {phase_ticks}")
    if self.tick_jitter_ticks >= period_ticks:
        raise TimingError(
            f"tick jitter {self.tick_jitter_ticks} ticks must be below the period {period_ticks}"
        )
    max_monitor_samples = samples_per_step(period_ticks + self.tick_jitter_ticks, self.adc.period_ticks)
    channel_dimensions = dict(self.dims, M=max_monitor_samples)
    layout = make_abi_layout(
        self.channels,
        channel_dimensions,
        self.bindings,
        obs_ids={channel_field.name: channel_field.ch_id for channel_field in self.layout.obs},
        act_ids={channel_field.name: channel_field.ch_id for channel_field in self.layout.act},
    )
    return dataclasses.replace(
        self,
        period_ticks=period_ticks,
        phase_ticks=int(phase_ticks),
        samples_per_step=max_monitor_samples,
        layout=layout,
    )

def to_dict(self) -> dict:
    serialized_spec = {}
    for field in dataclasses.fields(self):
        field_value = getattr(self, field.name)
        if field.name == "nominal":
            serialized_spec[field.name] = _serialize_nominal_design(field_value)
        elif field.name == "channels":
            serialized_spec[field.name] = {
                channel_name: dataclasses.asdict(channel_spec)
                for channel_name, channel_spec in field_value.items()
            }
        elif field.name == "layout":
            serialized_spec[field.name] = field_value.describe()
        elif dataclasses.is_dataclass(field_value):
            serialized_spec[field.name] = dataclasses.asdict(field_value)
        elif field.name == "temp_sensors":
            serialized_spec[field.name] = [
                dataclasses.asdict(sensor_facts) for sensor_facts in field_value
            ]
        else:
            serialized_spec[field.name] = field_value
    return serialized_spec

def fingerprint(self) -> str:
    serialized_spec = json.dumps(self.to_dict(), sort_keys=True, default=_serialize_json_value)
    return hashlib.sha256(serialized_spec.encode()).hexdigest()[:16]

def _serialize_json_value(value):
    if isinstance(value, (np.integer,)):
        return int(value)
    if isinstance(value, (np.floating,)):
        return float(value)
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, (set, frozenset, tuple)):
        return list(value)
    return repr(value)

def nominal_line_grid_hz(cfg, n_lines: int) -> list[float] | None:
    from mrm.params.units import to_si

    # the config value of `key` in config units (a `{value: ...}` leaf is unwrapped).
    def read_config_value(key):
        config_value = cfg.get(key, None)
        return (
            config_value.get("value")
            if isinstance(config_value, Mapping) and "value" in config_value
            else config_value
        )

    lines = read_config_value("channel_plan.lines")
    if lines:
        line_frequencies_hz = []
        for line_config in lines:
            frequency_thz = line_config.get("freq_thz")
            frequency_thz = (
                frequency_thz.get("value") if isinstance(frequency_thz, Mapping) else frequency_thz
            )
            line_frequencies_hz.append(float(to_si("freq_thz", frequency_thz)))
        return line_frequencies_hz
    center_frequency_thz, line_spacing_ghz = (
        read_config_value("channel_plan.center_thz"),
        read_config_value("channel_plan.spacing_ghz"),
    )
    if center_frequency_thz is None or line_spacing_ghz is None:
        return None
    center_frequency_hz, line_spacing_hz = (
        float(to_si("channel_plan.center_thz", center_frequency_thz)),
        float(to_si("channel_plan.spacing_ghz", line_spacing_ghz)),
    )
    return [
        center_frequency_hz + (line_index - (n_lines - 1) / 2.0) * line_spacing_hz
        for line_index in range(int(n_lines))
    ]

def read_config_value(key):
    config_value = cfg.get(key, None)
    return (
        config_value.get("value")
        if isinstance(config_value, Mapping) and "value" in config_value
        else config_value
    )

def _serialize_nominal_design(nominal_design):
    if nominal_design is None:
        return None
    if hasattr(nominal_design, "fingerprint") and callable(nominal_design.fingerprint):
        return {"fingerprint": nominal_design.fingerprint()}
    if hasattr(nominal_design, "to_dict") and callable(nominal_design.to_dict):
        return nominal_design.to_dict()
    if isinstance(nominal_design, Mapping):
        return dict(nominal_design)
    return repr(nominal_design)

def __init__(self, data: Mapping[str, Any], what: str = "sensor"):
    readonly_channels = {}
    for channel_name, channel_values in data.items():
        channel_array = np.asarray(channel_values)
        if channel_array.flags.writeable:
            channel_array = channel_array.view()
            channel_array.flags.writeable = False
        readonly_channels[channel_name] = channel_array
    self._channels_by_name = readonly_channels
    self._channel_kind = what

def __getitem__(self, name: str) -> np.ndarray:
    try:
        return self._channels_by_name[name]
    except KeyError:
        raise UndeclaredChannelError(
            f"{self._channel_kind} channel {name!r} is not declared for this controller (declared: {sorted(self._channels_by_name)})"
        ) from None

def __post_init__(self):
    object.__setattr__(self, "tick", int(self.tick))
    if not isinstance(self.sensors, StrictChannels):
        object.__setattr__(self, "sensors", StrictChannels(self.sensors, "sensor"))
    if not isinstance(self.new, StrictChannels):
        object.__setattr__(self, "new", StrictChannels(self.new, "new-sample flag of"))

