@property
def active_ring(self) -> int:
    if self.active is None:
        return -1
    active_ring_indices = np.flatnonzero(self.active)
    return int(active_ring_indices[0]) if active_ring_indices.size == 1 else -1

def controller_telemetry(ctrl: Any) -> dict[str, np.ndarray]:
