def __init__(self, params: Mapping[str, Any] | Any | None = None, **overrides: Any):
    self.params = self._make_params(params, overrides)
    self.spec: ControllerSpec | None = None

@classmethod
def _make_params(cls, params, overrides):
    settings_class = cls.Params
    if params is not None and isinstance(params, settings_class):
        return dataclasses.replace(params, **overrides) if overrides else params
    setting_values = dict(params or {})
    setting_values.update(overrides)
    allowed_settings = {field.name for field in dataclasses.fields(settings_class)}
    unknown_settings = set(setting_values) - allowed_settings
    if unknown_settings:
        raise TypeError(
            f"{cls.__name__}: unknown controller.params {sorted(unknown_settings)}; allowed: {sorted(allowed_settings)}"
        )
    return settings_class(**setting_values)

def _require_controller_spec(self) -> ControllerSpec:
    if self.spec is None:
        raise RuntimeError(f"{type(self).__name__}: call reset(spec) first")
    return self.spec

def shape(self, *symbols) -> tuple[int, ...]:
    dimensions = self._require_controller_spec().dims
    return tuple(
        dimensions[dimension] if isinstance(dimension, str) else int(dimension) for dimension in symbols
    )

def __getitem__(self, name: str):
    channel_values = self._source_channels[name]  # raises UndeclaredChannelError for undeclared names
    channel_spec = self._controller_spec.channels[name]
    channel_axes = [
        axis for axis in channel_spec.shape if not (self._contains_sample_flags and axis == "M")
    ]
    slice_indices = [self._world_index]
    if self._ring_index is not None:
        for axis in channel_axes[1:]:
            if axis == "N":
                slice_indices.append(self._ring_index)
            elif axis == "M":
                slice_indices.append(slice(None))
            elif axis == 1:
                slice_indices.append(0)
            else:
                slice_indices.append(slice(None))
    selected_values = channel_values[tuple(slice_indices)]
    if self._ring_index is not None and not self._contains_sample_flags and channel_spec.agg == "block":
        valid_sample_count = int(
            self._source_channels[channel_spec.count_channel][self._world_index, self._ring_index]
        )
        selected_values = selected_values[:valid_sample_count]
    return selected_values

@property
def t_s(self) -> float:
