def t_s(self) -> float:
    return self.tick * self.dt_s

def _has_integer_dtype(value) -> bool:
    value_array = np.asarray(value)
    return value_array.dtype.kind in "biu"

def _get_held_command(self, spec: ControllerSpec, obs: Observation, channel_name: str) -> np.ndarray:
    if channel_name not in self._held_commands:
        if channel_name not in spec.channels or spec.channels[channel_name].kind != "actuator":
            raise UndeclaredChannelError(
                f"{channel_name!r} is not an actuator bound to this controller "
                f"(bound: {sorted(spec.actuators)})"
            )
        readback_channel = channel_name + ".applied"
        if readback_channel in spec.channels:
            self._held_commands[channel_name] = np.array(obs.sensors[readback_channel], dtype=np.int64)
        else:
            self._held_commands[channel_name] = np.full(
                spec.shape_of(channel_name), spec.channels[channel_name].init, dtype=np.int64
            )
    return self._held_commands[channel_name]

def __init__(
    self, factory: Callable[[RingContext], Any], *, name: str | None = None, latency_ticks: int = 0
):
    super().__init__()
    self.factory = factory
    if name is not None:
        self.name = name
    self.latency_ticks = int(latency_ticks)
    self._controller_instances: list[list[Any]] = []

def reset(self, spec: ControllerSpec) -> None:
    super().reset(spec)
    self._reset_held_commands()
    self._controller_instances = [
        [self.factory(RingContext(spec, world_index, ring_index)) for ring_index in range(spec.n_rings)]
        for world_index in range(spec.n_batch)
    ]

def step(self, obs: Observation) -> dict[str, np.ndarray]:
    spec = self._require_controller_spec()
    written_channels: set[str] = set()
    for world_index in range(spec.n_batch):
        for ring_index in range(spec.n_rings):
            if obs.active is not None and not obs.active[ring_index]:
                continue
            ring_observation = RingObservation(
                obs.tick,
                obs.dt_s,
                world_index,
                ring_index,
                _ControllerChannelSlice(obs.sensors, spec, world_index, ring_index, False),
                _ControllerChannelSlice(obs.new, spec, world_index, ring_index, True),
            )
            ring_actions = (
                self._controller_instances[world_index][ring_index].step(ring_observation) or {}
            )
            for channel_name, command_value in ring_actions.items():
                held_commands = self._get_held_command(spec, obs, channel_name)
                if spec.channels[channel_name].shape != ("B", "N"):
                    raise ChannelError(
                        f"PerRing can only write (B, N) channels; {channel_name} is {spec.channels[channel_name].shape}"
                    )
                if np.ndim(command_value) != 0 or not _has_integer_dtype(command_value):
                    raise TypeError(
                        f"PerRing ring ({world_index}, {ring_index}) wrote {channel_name} = {command_value!r}; expected one integer code"
                    )
                held_commands[world_index, ring_index] = int(command_value)
                written_channels.add(channel_name)
    return {channel_name: self._held_commands[channel_name].copy() for channel_name in written_channels}

def telemetry(self) -> dict[str, np.ndarray]:
    spec = self._require_controller_spec()
    telemetry_arrays: dict[str, np.ndarray] = {}
    for world_index in range(spec.n_batch):
        for ring_index in range(spec.n_rings):
            for metric_name, metric_value in controller_telemetry(
                self._controller_instances[world_index][ring_index]
            ).items():
                if metric_name not in telemetry_arrays:
                    telemetry_arrays[metric_name] = np.full((spec.n_batch, spec.n_rings), np.nan)
                telemetry_arrays[metric_name][world_index, ring_index] = float(metric_value)
    return telemetry_arrays

def __init__(
    self, factory: Callable[[DieContext], Any], *, name: str | None = None, latency_ticks: int = 0
):
    super().__init__()
    self.factory = factory
    if name is not None:
        self.name = name
    self.latency_ticks = int(latency_ticks)
    self._controller_instances: list[Any] = []

def reset(self, spec: ControllerSpec) -> None:
    super().reset(spec)
    self._reset_held_commands()
    self._controller_instances = [
        self.factory(DieContext(spec, world_index)) for world_index in range(spec.n_batch)
    ]

def step(self, obs: Observation) -> dict[str, np.ndarray]:
    spec = self._require_controller_spec()
    written_channels: set[str] = set()
    for world_index in range(spec.n_batch):
        world_observation = DieObservation(
            obs.tick,
            obs.dt_s,
            world_index,
            _ControllerChannelSlice(obs.sensors, spec, world_index, None, False),
            _ControllerChannelSlice(obs.new, spec, world_index, None, True),
            obs.active,
        )
        world_actions = self._controller_instances[world_index].step(world_observation) or {}
        for channel_name, command_values in world_actions.items():
            held_commands = self._get_held_command(spec, obs, channel_name)
            command_array = np.asarray(command_values)
            if command_array.shape != held_commands.shape[1:]:
                raise ChannelError(
                    f"PerDie element {world_index} wrote {channel_name} with shape {command_array.shape}; expected {held_commands.shape[1:]}"
                )
            if not _has_integer_dtype(command_array):
                raise TypeError(
                    f"PerDie element {world_index} wrote {channel_name} with dtype {command_array.dtype}; expected integer codes"
                )
            held_commands[world_index] = command_array
            written_channels.add(channel_name)
    return {channel_name: self._held_commands[channel_name].copy() for channel_name in written_channels}

def telemetry(self) -> dict[str, np.ndarray]:
    spec = self._require_controller_spec()
    telemetry_arrays: dict[str, np.ndarray] = {}
    for world_index in range(spec.n_batch):
        for metric_name, metric_values in controller_telemetry(
            self._controller_instances[world_index]
        ).items():
            if metric_name not in telemetry_arrays:
                telemetry_arrays[metric_name] = np.full((spec.n_batch, spec.n_rings), np.nan)
            telemetry_arrays[metric_name][world_index] = np.asarray(metric_values, dtype=np.float64)
    return telemetry_arrays

def __init__(self, spec: ControllerSpec, on_out_of_range: str | None = None):
    self.spec = spec
    self.mode = spec.on_out_of_range if on_out_of_range is None else on_out_of_range
    if self.mode not in ON_OUT_OF_RANGE:
        raise ValueError(f"on_out_of_range = {self.mode!r}: must be one of {ON_OUT_OF_RANGE}")
    self.counts = {
        channel_name: np.zeros(spec.shape_of(channel_name), dtype=np.int64)
        for channel_name in spec.actuators
    }

def reset(self) -> None:
    for clip_counts in self.counts.values():
        clip_counts[...] = 0

def validate(self, actions: Mapping[str, Any]) -> dict[str, np.ndarray]:
    if not isinstance(actions, Mapping):
        raise TypeError(
            f"controller step() must return a dict of channel -> array (use {{}} to hold every "
            f"actuator), got {type(actions).__name__}"
        )
    spec = self.spec
    validated_actions: dict[str, np.ndarray] = {}
    for name, command_values in actions.items():
        if name not in spec.bindings:
            if name in spec.channels:
                raise ChannelError(f"controller wrote {name!r}, which is a sensor channel")
            raise UndeclaredChannelError(
                f"controller wrote unknown channel {name!r}; actuators bound to the "
                f"controller: {sorted(spec.actuators)}"
            )
        if spec.bindings[name] != "controller":
            raise BindingError(
                f"controller wrote {name!r}, which is bound to the {spec.bindings[name]} "
                f"(controller_interface.bind)"
            )
        channel_spec = spec.channels[name]
        command_array = np.asarray(command_values)
        expected_shape = spec.shape_of(name)
        if command_array.shape != expected_shape:
            raise ChannelError(
                f"{name}: expected shape {expected_shape} {channel_spec.shape}, got {command_array.shape}"
            )
        if command_array.dtype.kind not in "biu":
            raise TypeError(
                f"{name}: expected integer codes ({channel_spec.dtype}), got dtype {command_array.dtype}; round "
                f"explicitly, e.g. np.rint(x).astype(np.int64)"
            )
        if (
            command_array.dtype == np.uint64
        ):  # a uint64 above INT64_MAX would wrap negative in the int64 cast
            command_array = np.minimum(command_array, np.uint64(INT64_MAX))
        integer_commands = command_array.astype(np.int64)
        outside_limits = (integer_commands < channel_spec.min) | (integer_commands > channel_spec.max)
        if outside_limits.any():
            if self.mode == "error":
                first_invalid_index = tuple(int(index) for index in np.argwhere(outside_limits)[0])
                raise ActionRangeError(
                    f"{name}{list(first_invalid_index)} = {int(integer_commands[first_invalid_index])} outside [{channel_spec.min}, {channel_spec.max}] "
                    f"({channel_spec.unit}); set controller_interface.on_out_of_range: clip to "
                    f"saturate instead"
                )
            self.counts[name] += outside_limits
            integer_commands = np.clip(integer_commands, channel_spec.min, channel_spec.max)
        validated_actions[name] = integer_commands.astype(channel_spec.np_dtype)
    return validated_actions

def merge_round_robin(
    spec: ControllerSpec, actions: Mapping[str, Any], held: np.ndarray, active_ring: int
) -> Mapping[str, Any]:
    if active_ring < 0 or not isinstance(actions, Mapping):
        return actions
    merged_actions = dict(actions)
    inactive_rings = np.ones(spec.n_rings, dtype=bool)  # the rings that keep the held command
    inactive_rings[int(active_ring)] = False
    for name, command_values in actions.items():
        channel_spec = spec.channels.get(name)
        if channel_spec is None or channel_spec.kind != "actuator" or tuple(channel_spec.shape) != ("B", "N"):
            continue
        command_array = np.asarray(command_values)
        if command_array.shape != spec.shape_of(name) or command_array.dtype.kind not in "biu":
            continue
        command_array = (
            command_array.astype(np.int64)
            if command_array.dtype != np.uint64
            else np.minimum(command_array, np.uint64(INT64_MAX)).astype(np.int64)
        )
        actuator_field = spec.layout.act_field(name)  # where this channel sits in the held act vector
        command_array[:, inactive_rings] = np.asarray(held)[
            :, actuator_field.offset : actuator_field.offset + actuator_field.size
        ][:, inactive_rings]
        merged_actions[name] = command_array
    return merged_actions

def validate_telemetry(tel: Mapping[str, Any], spec: ControllerSpec) -> dict[str, np.ndarray]:
    validated_telemetry = {}
    expected_shape = (spec.n_batch, spec.n_rings)
    for metric_name, metric_values in tel.items():
        metric_array = np.asarray(metric_values)
        if metric_array.dtype.kind not in "biuf":
            raise TypeError(f"telemetry {metric_name!r}: dtype {metric_array.dtype} is not numeric")
        if metric_array.shape != expected_shape:
            raise ChannelError(
                f"telemetry {metric_name!r}: expected shape (B, N) = {expected_shape}, got {metric_array.shape}"
            )
        validated_telemetry[metric_name] = metric_array.astype(np.float64)
    return validated_telemetry

def __init__(self, spec_child: ControllerSpec):
    self.spec = spec_child
    self.max_samples_per_step = spec_child.samples_per_step
    self.sensor_values: dict[str, np.ndarray] = {}
    self.new_sample_flags: dict[str, np.ndarray] = {}
    self.sample_block_channels = {
        channel_name: channel_spec
        for channel_name, channel_spec in spec_child.sensors.items()
        if channel_spec.agg == "block"
    }
    self.count_channels = {
        channel_spec.count_channel for channel_spec in self.sample_block_channels.values()
    }
    self.initialized = False

def _clear_observation_window(self):
    for channel_name, channel_spec in self.spec.sensors.items():
        if channel_spec.agg == "block":
            self.sensor_values[channel_name][...] = 0
        elif channel_spec.agg in ("sum", "count") and channel_name not in self.count_channels:
            self.sensor_values[channel_name][...] = 0
        elif channel_spec.agg == "all":
            self.sensor_values[channel_name][...] = True
        elif channel_spec.agg == "any":
            self.sensor_values[channel_name][...] = False
    for count_channel in self.count_channels:
        self.sensor_values[count_channel][...] = 0
    for sample_flags in self.new_sample_flags.values():
        sample_flags[...] = False

def add_observation(self, obs: Observation) -> None:
    spec = self.spec
    if not self.initialized:
        for channel_name, channel_spec in spec.sensors.items():
            self.sensor_values[channel_name] = np.zeros(
                channel_spec.resolve_shape(spec.dims), dtype=channel_spec.np_dtype
            )
            self.new_sample_flags[channel_name] = np.zeros(
                (spec.n_batch,) + channel_spec.flag_shape(spec.dims), dtype=bool
            )
        self.initialized = True
        self._clear_observation_window()
    incoming_counts = {
        count_channel: np.asarray(obs.sensors[count_channel]) for count_channel in self.count_channels
    }
    for channel_name, channel_spec in spec.sensors.items():
        incoming_values = np.asarray(obs.sensors[channel_name])
        if channel_spec.agg == "block":
            continue
        if channel_name in self.count_channels:
            continue
        if channel_spec.agg == "latest":
            self.sensor_values[channel_name][...] = incoming_values
        elif channel_spec.agg in ("sum", "count"):
            self.sensor_values[channel_name] += incoming_values.astype(
                self.sensor_values[channel_name].dtype
            )
        elif channel_spec.agg == "all":
            self.sensor_values[channel_name] &= incoming_values.astype(bool)
        elif channel_spec.agg == "any":
            self.sensor_values[channel_name] |= incoming_values.astype(bool)
        self.new_sample_flags[channel_name] |= np.asarray(obs.new[channel_name], dtype=bool)
    for count_channel in self.count_channels:
        sample_channels = [
            channel_name
            for channel_name, channel_spec in self.sample_block_channels.items()
            if channel_spec.count_channel == count_channel
        ]
        new_sample_counts = incoming_counts[count_channel]
        stored_sample_counts = self.sensor_values[count_channel]
        for world_index in range(spec.n_batch):
            for ring_index in range(spec.n_rings):
                new_sample_count = int(new_sample_counts[world_index, ring_index])
                if new_sample_count <= 0:
                    continue
                stored_sample_count = int(stored_sample_counts[world_index, ring_index])
                for channel_name in sample_channels:
                    new_samples = np.asarray(obs.sensors[channel_name])[
                        world_index, ring_index, :new_sample_count
                    ]
                    retained_samples = np.concatenate(
                        [
                            self.sensor_values[channel_name][
                                world_index, ring_index, :stored_sample_count
                            ],
                            new_samples,
                        ]
                    )[-self.max_samples_per_step :]
                    self.sensor_values[channel_name][world_index, ring_index, : retained_samples.size] = (
                        retained_samples
                    )
                stored_sample_counts[world_index, ring_index] = min(
                    stored_sample_count + new_sample_count, self.max_samples_per_step
                )
        for channel_name in sample_channels + [count_channel]:
            self.new_sample_flags[channel_name] |= np.asarray(obs.new[channel_name], dtype=bool)

def release_observation(self, tick: int, dt_s: float, active: np.ndarray | None) -> Observation:
    child_observation = Observation(
        tick,
        dt_s,
        {
            channel_name: channel_values.copy()
            for channel_name, channel_values in self.sensor_values.items()
        },
        {
            channel_name: sample_flags.copy()
            for channel_name, sample_flags in self.new_sample_flags.items()
        },
        active,
    )
    self._clear_observation_window()
    return child_observation

def __init__(self, children: Sequence[tuple], schedule: str = "simultaneous", name: str = "composite"):
    if schedule not in SCHEDULES:
        raise ValueError(f"schedule {schedule!r} must be one of {SCHEDULES}")
    if not children:
        raise ValueError("CompositeController needs at least one child")
    self.children = []
    for child_index, entry in enumerate(children):
        if len(entry) not in (2, 3):
            raise ValueError(
                f"child {child_index}: expected (controller, rate_hz[, phase_ticks]), got {entry!r}"
            )
        child_controller, child_rate_hz = entry[0], float(entry[1])
        child_phase_ticks = int(entry[2]) if len(entry) == 3 else 0
        if not isinstance(child_controller, Controller):
            raise TypeError(
                f"child {child_index} ({child_controller!r}) does not implement the Controller protocol"
            )
        if controller_fast_kernel(child_controller) is not None:
            # the plant would never call it (a composite runs on the Python path and has no fast_kernel), so a dither written as a fast_kernel would silently vanish
            raise TypeError(
                f"child {child_index} ({getattr(child_controller, 'name', child_controller)!r}) declares a fast_kernel, which a "
                f"CompositeController cannot run; run that controller alone"
            )
        self.children.append((child_controller, child_rate_hz, child_phase_ticks))
    self.schedule = schedule
    self.name = name
    self.latency_ticks = max(int(child.latency_ticks) for child, _, _ in self.children)
    self.fast_kernel = None
    self.spec: ControllerSpec | None = None
    self._child_specs: list[ControllerSpec] = []
    self._observation_windows: list[_ChildObservationWindow] = []

@classmethod
def from_params(cls, params: Mapping[str, Any]) -> "CompositeController":
    from mrm.control import registry

    child_controllers = []
    for child_index, child_config in enumerate(params.get("children", ())):
        if "name" not in child_config or "rate_hz" not in child_config:
            raise ValueError(f"controller.params.children[{child_index}] needs name and rate_hz")
        child_controller = registry.create(child_config["name"], child_config.get("params"))
        child_controllers.append(
            (child_controller, float(child_config["rate_hz"]), int(child_config.get("phase_ticks", 0)))
        )
    return cls(
        child_controllers,
        schedule=params.get("schedule", "simultaneous"),
        name=params.get("name", "composite"),
    )

def child_periods(self, tick_s: float) -> list[int]:
    return [
        rate_to_period_ticks(child_rate_hz, tick_s, f"controller.params.children[{child_index}].rate_hz")
        for child_index, (_, child_rate_hz, _) in enumerate(self.children)
    ]

def base_period_ticks(self, tick_s: float) -> int:
    base_period = 0
    for child_period, (_, _, child_phase) in zip(self.child_periods(tick_s), self.children):
        base_period = math.gcd(base_period, child_period)
        base_period = math.gcd(base_period, child_phase) if child_phase else base_period
    return base_period

def reset(self, spec: ControllerSpec) -> None:
    if spec.schedule != "simultaneous":
        raise ValueError(
            f"CompositeController: controller_interface.schedule = {spec.schedule!r}; the engine "
            f"would multiplex the composite's output over the rings on top of its own schedule "
            f"({self.schedule!r}). Set the interface schedule to simultaneous and the composite's "
            f"schedule (controller.params.schedule) to round_robin"
        )
    self.spec = spec
    self._reset_held_commands()
    child_periods = self.child_periods(spec.tick_s)
    timing_errors = []
    for child_index, (child_period, (_, _, child_phase)) in enumerate(zip(child_periods, self.children)):
        if child_period % spec.period_ticks or (child_phase - spec.phase_ticks) % spec.period_ticks:
            timing_errors.append(
                f"child {child_index}: period {child_period} / phase {child_phase} ticks is not on the composite's base grid of "
                f"{spec.period_ticks} ticks (set controller_interface.update_rate_hz to "
                f"1 / ({self.base_period_ticks(spec.tick_s)} * dt))"
            )
    if timing_errors:
        raise TimingError("; ".join(timing_errors))
    self._child_specs = [
        dataclasses.replace(spec.with_period(child_period, child_phase), schedule=self.schedule)
        for child_period, (_, _, child_phase) in zip(child_periods, self.children)
    ]
    self._observation_windows = [_ChildObservationWindow(child_spec) for child_spec in self._child_specs]
    for (child_controller, _, _), child_spec in zip(self.children, self._child_specs):
        child_controller.reset(child_spec)

def step(self, obs: Observation) -> dict[str, np.ndarray]:
    spec = self.spec
    if spec is None:
        raise RuntimeError("CompositeController: call reset(spec) first")
    written_channels: set[str] = set()
    # recover the scheduled edge - the actual tick can be late by up to tick_jitter_ticks
    base_edge_index = int(edge_index(obs.tick, spec.period_ticks, spec.phase_ticks))
    scheduled_tick = spec.phase_ticks + base_edge_index * spec.period_ticks
    if base_edge_index < 0 or obs.tick - scheduled_tick > spec.tick_jitter_ticks:
        raise TimingError(
            f"CompositeController called at tick {obs.tick}, which is not on its base grid "
            f"(period {spec.period_ticks}, phase {spec.phase_ticks}, jitter <= "
            f"{spec.tick_jitter_ticks} ticks)"
        )
    for (child_controller, _, _), child_spec, observation_window in zip(
        self.children, self._child_specs, self._observation_windows
    ):
        observation_window.add_observation(obs)
        if not is_edge(scheduled_tick, child_spec.period_ticks, child_spec.phase_ticks):
            continue
        active_rings = None
        active_ring_index = -1
        if self.schedule == "round_robin":
            active_ring_index = (
                int(edge_index(scheduled_tick, child_spec.period_ticks, child_spec.phase_ticks))
                % spec.n_rings
            )
            active_rings = np.zeros(spec.n_rings, dtype=bool)
            active_rings[active_ring_index] = True
        child_actions = (
            child_controller.step(
                observation_window.release_observation(obs.tick, obs.dt_s, active_rings)
            )
            or {}
        )
        for channel_name, command_values in child_actions.items():
            held_commands = self._get_held_command(spec, obs, channel_name)
            command_array = np.asarray(command_values)
            if command_array.shape != held_commands.shape:
                raise ChannelError(
                    f"child {child_controller.name!r} wrote {channel_name} with shape {command_array.shape}; expected {held_commands.shape}"
                )
            if command_array.dtype.kind not in "biu":
                raise TypeError(
                    f"child {child_controller.name!r} wrote {channel_name} with dtype {command_array.dtype}; expected integer codes"
                )
            if active_ring_index >= 0 and spec.channels[channel_name].shape[:2] == ("B", "N"):
                held_commands[:, active_ring_index] = command_array[:, active_ring_index]
            else:
                held_commands[...] = command_array
            written_channels.add(channel_name)
    return {channel_name: self._held_commands[channel_name].copy() for channel_name in written_channels}

def telemetry(self) -> dict[str, np.ndarray]:
    combined_telemetry = {}
    child_names = [child.name for child, _, _ in self.children]
    for child_index, (child_controller, _, _) in enumerate(self.children):
        metric_prefix = (
            child_controller.name
            if child_names.count(child_controller.name) == 1
            else f"{child_controller.name}{child_index}"
        )
        for metric_name, metric_values in controller_telemetry(child_controller).items():
            combined_telemetry[f"{metric_prefix}.{metric_name}"] = metric_values
    return combined_telemetry

@nb.njit(cache=True)
def sensor_channel_offset(integer_spec, channel_id):
    if channel_id < 0 or channel_id >= integer_spec[SPEC_I_N_OBS_IDS]:
        return np.int64(-1)
    return integer_spec[integer_spec[SPEC_I_OBS_TABLE] + channel_id]

@nb.njit(cache=True)
def new_sample_flags_offset(integer_spec, channel_id):
    if channel_id < 0 or channel_id >= integer_spec[SPEC_I_N_OBS_IDS]:
        return np.int64(-1)
    return integer_spec[integer_spec[SPEC_I_NEW_TABLE] + channel_id]

@nb.njit(cache=True)
def actuator_channel_offset(integer_spec, channel_id):
    if channel_id < 0 or channel_id >= integer_spec[SPEC_I_N_ACT_IDS]:
        return np.int64(-1)
    return integer_spec[integer_spec[SPEC_I_ACT_TABLE] + channel_id]

@nb.njit(cache=True)
def integer_controller_parameter(integer_spec, parameter_index):
    return integer_spec[integer_spec[SPEC_I_USER] + parameter_index]

@nb.njit(cache=True)
def float_controller_parameter(float_spec, parameter_index):
    return float_spec[SPEC_F_HEADER + parameter_index]

@nb.njit(cache=True)
def fast_new_sample_flag_index(ring_index, ring_count):
    return FO_HEADER + ring_index

@nb.njit(cache=True)
def fast_monitor_code_index(ring_index, ring_count):
    return FO_HEADER + ring_count + ring_index

@nb.njit(cache=True)
def fast_sample_tick_index(ring_index, ring_count):
    return FO_HEADER + 2 * ring_count + ring_index

@nb.njit(cache=True)
def fast_heater_offset_index(ring_index, ring_count):
    return ring_index

@nb.njit(cache=True)
def fast_bias_offset_index(ring_index, ring_count):
    return ring_count + ring_index

@nb.njit(cache=True)
def obs_offset(spec_i64, ch_id):
    return sensor_channel_offset(spec_i64, ch_id)

@nb.njit(cache=True)
def new_offset(spec_i64, ch_id):
    return new_sample_flags_offset(spec_i64, ch_id)

@nb.njit(cache=True)
def act_offset(spec_i64, ch_id):
    return actuator_channel_offset(spec_i64, ch_id)

@nb.njit(cache=True)
def user_i64(spec_i64, k):
    return integer_controller_parameter(spec_i64, k)

@nb.njit(cache=True)
def user_f64(spec_f64, k):
    return float_controller_parameter(spec_f64, k)

@nb.njit(cache=True)
def fo_new(i, n):
    return fast_new_sample_flag_index(i, n)

@nb.njit(cache=True)
def fo_code(i, n):
