def bg_eps(self, Y):
    if self.two_d:
        return np.full_like(Y, self.n["clad"] ** 2, dtype=float)
    permittivity = np.where(Y < 0.0, self.n["box"] ** 2, self.n["clad"] ** 2)
    slab_um = self.xs.slab_nm * 1e-3
    if slab_um > 0:
        permittivity = np.where((Y >= 0.0) & (Y < slab_um), self.n["si"] ** 2, permittivity)
    return permittivity

def in_core_y(self, Y):
    if self.two_d:
        return np.ones_like(Y, dtype=bool)
    return (Y >= self.core_y[0]) & (Y <= self.core_y[1])

def eps_bus(self, X, Y):
    background = self.bg_eps(Y)
    return np.where((np.abs(X) < self.w_b / 2) & self.in_core_y(Y), self.n["si"] ** 2, background)

def eps_ring_local(self, U, Y):
    background = self.bg_eps(Y)
    return np.where((np.abs(U) < self.w_r / 2) & self.in_core_y(Y), self.n["si"] ** 2, background)

