def kappa2(self, lam_um: float, gap_nm: float, xs: common.XSec | None = None, **kw) -> dict:
    bus, ring, g = self.sampled(lam_um, xs)
    return cmt_overlap(bus, ring, g, gap_nm * 1e-3, dz=self.settings.dz_um, **kw)

def _interp_gap_for_k2(gaps, k2, target, *, extrapolate: bool = False):
    ln_k2 = np.log(np.asarray(k2))
    gaps_nm = np.asarray(gaps, float)
    ln_target = math.log(target)
    if not (ln_k2.min() <= ln_target <= ln_k2.max()):
        if not extrapolate:
            return None
        by_gap = np.argsort(gaps_nm)
        gaps_sorted, ln_sorted = gaps_nm[by_gap], ln_k2[by_gap]
        if ln_target < ln_sorted[-1]:
            d_log_power_coupling_d_gap_per_nm = (ln_sorted[-1] - ln_sorted[-2]) / (
                gaps_sorted[-1] - gaps_sorted[-2]
            )
            return float(gaps_sorted[-1] + (ln_target - ln_sorted[-1]) / d_log_power_coupling_d_gap_per_nm)
        d_log_power_coupling_d_gap_per_nm = (ln_sorted[1] - ln_sorted[0]) / (gaps_sorted[1] - gaps_sorted[0])
        return float(gaps_sorted[0] + (ln_target - ln_sorted[0]) / d_log_power_coupling_d_gap_per_nm)
    order = np.argsort(ln_k2)
    from scipy.interpolate import PchipInterpolator

    f = PchipInterpolator(ln_k2[order], gaps_nm[order])
    return float(f(ln_target))

def q_to_k2(q: float, lam_um: float, fsr_hz: float) -> float:
    freq_hz = common.C0 / (lam_um * 1e-6)
    return float(-math.expm1(-2 * math.pi * freq_hz / fsr_hz / q))

def design_gaps(gaps, k2, lam_um: float, fsr_hz: float) -> dict:
    out = {"targets": {"q_loaded_nominal": Q_L_NOMINAL, "q_loaded_range": Q_L_RANGE, "q_i_nominal": Q_I_NOMINAL,
                       "q_i_range": Q_I_RANGE, "notch_db_nominal": NOTCH_DB_NOMINAL,
                       "kappa_d_over_kappa_nominal": KD_OVER_K_NOMINAL, "kappa_d_over_kappa_prior": KD_OVER_K_PRIOR,
                       "fsr_thz": fsr_hz / 1e12}}

    # the gap whose per-pass coupling gives the decay-rate Q qe.
    def gap_for_q(qe):
        k2 = q_to_k2(qe, lam_um, fsr_hz)
        g = _interp_gap_for_k2(gaps, k2_tab, k2)
        if g is not None:
            return {"q_e": qe, "kappa2": k2, "gap_nm": g}
        return {"q_e": qe, "kappa2": k2, "gap_nm": _interp_gap_for_k2(gaps, k2_tab, k2, extrapolate=True),
                "extrapolated": True}
    k2_tab = k2
    # critical coupling at the nominal Q_i and drop - kappa_e = kappa_i + kappa_d, Q_L = 1/(1/Qi + 1/Qe + 1/Qd)
    # with kappa_d = x kappa - 1/Qd = x/Q_L and 1/Qe = 1/Qi + x/Q_L  ->  1/Q_L = 2/Qi + 2x/Q_L
    kd_over_k = KD_OVER_K_NOMINAL
    ql_crit = Q_I_NOMINAL * (1 - 2 * kd_over_k) / 2.0
    qe_crit = 1.0 / (1.0 / Q_I_NOMINAL + kd_over_k / ql_crit)
    out["critical"] = {**gap_for_q(qe_crit), "q_loaded": ql_crit, "q_i": Q_I_NOMINAL, "kappa_d_over_kappa": kd_over_k}
    # mirror branches at the nominal Q_L and notch depth - kappa_i' + kappa_e = kappa, |kappa_i' - kappa_e| = r kappa
    notch_amp = 10 ** (-NOTCH_DB_NOMINAL / 20.0)
    for name, sgn in (("under", -1), ("over", +1)):
        rows = []
        for ql in (Q_L_RANGE[0], Q_L_NOMINAL, Q_L_RANGE[1]):
            qe = 2 * ql / (1 + sgn * notch_amp)
            qi_eff = 2 * ql / (1 - sgn * notch_amp)           # Q of kappa_i + kappa_d
            qd = ql / kd_over_k
            qi = 1.0 / (1.0 / qi_eff - 1.0 / qd)
            rows.append({**gap_for_q(qe), "q_loaded": ql, "q_i_implied": qi, "notch_db": NOTCH_DB_NOMINAL})
        out[name] = {"nominal": rows[1], "q_loaded_range": [rows[0], rows[2]]}
    # drop gaps for the prior
    out["drop"] = {}
    for label, kd_case in (("low", KD_OVER_K_PRIOR[0]), ("nominal", KD_OVER_K_NOMINAL), ("high", KD_OVER_K_PRIOR[1])):
        qd = ql_crit / kd_case
        out["drop"][label] = {**gap_for_q(qd), "kappa_d_over_kappa": kd_case, "q_d": qd}
    return out

def gap_for_q(qe):
    k2 = q_to_k2(qe, lam_um, fsr_hz)
    g = _interp_gap_for_k2(gaps, k2_tab, k2)
    if g is not None:
        return {"q_e": qe, "kappa2": k2, "gap_nm": g}
    return {"q_e": qe, "kappa2": k2, "gap_nm": _interp_gap_for_k2(gaps, k2_tab, k2, extrapolate=True),
            "extrapolated": True}

def meep2d_runs(*, n1: float, n2: float, w: float, R: float, lam: float, gaps_um, resolutions) -> list:
    out = []
    if not os.path.exists(common.MEEP_PYTHON):
        return [{"error": "meep interpreter not found"}]
    with tempfile.TemporaryDirectory() as td:
        sp = Path(td) / "meep2d.py"
        sp.write_text(MEEP2D_SCRIPT)
        for gp in gaps_um:
            for res in resolutions:
                par = {"res": res, "R": R, "w": w, "gap": gp, "n1": n1, "n2": n2, "lam": lam}
                r = subprocess.run([common.MEEP_PYTHON, "-I", str(sp), json.dumps(par)], capture_output=True,
                                   text=True, timeout=7200)
                line = [ln for ln in r.stdout.splitlines() if ln.startswith("{")]
                if line:
                    d = json.loads(line[-1])
                    mid = len(d["kappa2"]) // 2
                    out.append({"gap_nm": gp * 1e3, "res": res, "kappa2": d["kappa2"][mid], "t2": d["t2"][mid],
                                "kappa2_vs_lam": d["kappa2"], "lam_um": d["lam_um"], "seconds": d["seconds"],
                                "params": par})
                else:
                    out.append({"gap_nm": gp * 1e3, "res": res, "error": (r.stderr or r.stdout)[-300:], "params": par})
                common.log(f"  meep2d gap {gp} res {res}: {out[-1].get('kappa2')}")
    return out

