def load_r_ref(xs: common.XSec, out_dir: Path) -> tuple[float, dict]:
    for directory in (out_dir, common.DATA_DIR):
        path = Path(directory) / f"modes_{xs.name}.json"
        if path.exists():
            data = json.loads(path.read_text())
            return float(data["r_ref_um"]), {"source": str(path.name), "sha256": common.sha256_file(path),
                "n_g": data["n_g"],
                                          "fsr_thz": data.get("fsr_thz")}
    extractor = modes.Extractor(xs, modes.Settings(mesh_scale=3.0))
    radius_result = modes.find_r_ref(extractor)
    return float(radius_result["r_ref_um"]), {"source": "computed here (no modes artefact)", "r_ref": radius_result}

def nominal_doping(xs_name: str, topology: str = DEFAULT_TOPOLOGY) -> Doping:
    xs = XSECS[xs_name]
    if topology == "lateral":
        return dataclasses.replace(DOPING_NOMINAL, topology="lateral", junction_offset_nm=0.0)
    if topology == "lshape":
        return dataclasses.replace(DOPING_NOMINAL, topology="lshape", junction_offset_nm=xs.width_nm / 2 - 100.0,
                                   y_junction_nm=xs.slab_nm + 30.0)
    raise ValueError(f"unknown topology {topology!r}")

def _sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()

def _sig(x, nd=6):
    if x is None:
        return None
    x = float(x)
    if not math.isfinite(x):
        return None
    return float(f"{x:.{nd}g}")

def v_grid(quick=False):
    step = V_STEP_QUICK if quick else V_STEP_FULL
    n = int(round((V_MAX - V_MIN) / step)) + 1
    return np.round(np.linspace(V_MIN, V_MAX, n), 6)

@contextlib.contextmanager
def _quiet(enabled=True):
    if not enabled:
        yield
        return
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        yield

def richardson(values, hs, order=None):
    v = np.asarray(values, float)
    h = np.asarray(hs, float)
    out = {"values": _sigs(v), "h": _sigs(h)}
    if v.size < 3:
        out.update(extrapolated=_sig(v[-1]), observed_order=None, error_estimate=_sig(abs(v[-1] - v[-2])) if v.size > 1
                   else None)
        return out
    v1, v2, v3 = v[-3:]
    h1, h2, h3 = h[-3:]
    d12, d23 = v1 - v2, v2 - v3
    p = None
    if d12 != 0 and d23 != 0 and np.sign(d12) == np.sign(d23) and abs(d23) < abs(d12):
        r = h1 / h2
        if abs(h2 / h3 - r) < 1e-6 * r:
            p = math.log(abs(d12 / d23)) / math.log(r)
            if not 0.2 <= p <= 8.0:          # the same accepted range as the bracketed solve below
                p = None
        else:
            from scipy.optimize import brentq

            def g(pp):
                return (h1 ** pp - h2 ** pp) / (h2 ** pp - h3 ** pp) - d12 / d23
            try:
                p = brentq(g, 0.2, 8.0)
            except Exception:
                p = None
    forced = False
    if p is None and order is not None:
        p, forced = order, True
    if p is None or p <= 0.2:
        spread = float(np.max(v[-3:]) - np.min(v[-3:]))
        out.update(extrapolated=_sig(v3), observed_order=None, error_estimate=_sig(spread),
                   note="no observed order in [0.2, 8] (non-monotone or non-asymptotic): finest value, error = "
                        "spread of the last three")
        return out
    ext = v3 + (v3 - v2) / ((h2 / h3) ** p - 1.0)
    out.update(extrapolated=_sig(ext), observed_order=_sig(p, 4), error_estimate=_sig(abs(v3 - ext)),
               rel_error_estimate=_sig(abs(v3 - ext) / max(abs(ext), 1e-300), 4))
    if forced:
        out["order_forced"] = True      # 'observed_order' is then the assumed order, not an observation
    return out

def _smooth_step(u_nm, sigma_nm):
    from scipy.special import erf
    u = np.asarray(u_nm, float)
    if sigma_nm <= 0:
        return (u > 0).astype(float) + 0.5 * (u == 0)
    return 0.5 * (1.0 + erf(u / (math.sqrt(2.0) * sigma_nm)))

def n_body_indicator(x_nm, y_nm, d: Doping):
    sx = _smooth_step(np.asarray(x_nm, float) - d.junction_offset_nm, d.grading_nm)
    if d.topology == "lateral":
        return sx
    if d.topology == "lshape":
        if y_nm is None:
            raise ValueError("the lshape profile needs y")
        sy = _smooth_step(np.asarray(y_nm, float) - d.y_junction_nm, d.grading_nm)
        return 1.0 - (1.0 - sx) * (1.0 - sy)
    raise ValueError(f"unknown topology {d.topology!r}")

def junction_length_nm(xs: XSec, d: Doping):
    if d.topology == "lateral":
        return xs.film_nm
    return (d.junction_offset_nm + xs.width_nm / 2) + d.y_junction_nm

def _graded_lines(lo, hi, feats, hmax, must):
    def h_at(x):
        return min([hmax] + [hf + gf * max(0.0, abs(x - xf) - af) for xf, hf, af, gf in feats])
    pts = [lo]
    x = lo
    while x < hi:
        h1 = h_at(x)
        h2 = h_at(min(x + h1, hi))
        x = x + 0.5 * (h1 + h2)
        pts.append(min(x, hi))
    pts = np.array(pts)
    must = np.unique(np.asarray(must, float))
    keep = [p for p in pts if np.min(np.abs(must - p)) >= 0.4 * h_at(p)]
    return np.unique(np.concatenate([keep, must]))

def run_devsim(*args, **kw):
    try:
        return _run_devsim(*args, **kw)
    except Exception as exc:
        if type(exc).__module__.startswith("devsim"):
            raise RuntimeError(f"DEVSIM: {exc} [{_DEVSIM_STAGE[0]}]") from None
        raise

def dc(v_anode):
    _DEVSIM_STAGE[0] = f"dc {-v_anode:+.4f} V reverse"
    devsim.circuit_alter(name="V1", value=voff + v_anode)
    try:
        devsim.solve(type="dc", absolute_error=1e10, relative_error=DC_REL_TOL, maximum_iterations=40)
    except Exception:
        # coarse meshes at high doping stall above 1e-8 (round-off in depleted nodes) - accept 1e-6 there
        devsim.solve(type="dc", absolute_error=1e10, relative_error=DC_REL_TOL_FALLBACK, maximum_iterations=80)

def go(cur, target, hmax=0.25):
    h = min(hmax, abs(target - cur)) or hmax
    while abs(target - cur) > 1e-12:
        nxt = cur + math.copysign(min(h, abs(target - cur)), target - cur)
        try:
            dc(-nxt)
            cur = nxt
            h = min(hmax, 1.5 * h)
        except Exception:
            h *= 0.5
            if h < 2e-4:
                raise
    return cur

def walk(targets):
    cur = 0.0
    for vt_ in targets:
        cur = go(cur, vt_)
        record(vt_)

def scipy_solver_callback(**kw):
    import array

    import scipy.sparse as sps
    import scipy.sparse.linalg as spl
    action = kw["action"]
    if action == "init":
        solver_state = _SpluObject(kw["n"], kw["transpose"])
        return {"solver_object": solver_state, "matrix_format": "csc", "status": True, "message": ""}
    solver_state = kw["solver_object"]
    if action == "factor":
        ap = np.frombuffer(kw["Ap"], dtype=np.dtype(kw["Ap"].typecode))
        ai = np.frombuffer(kw["Ai"], dtype=np.dtype(kw["Ai"].typecode))
        ax = np.frombuffer(kw["Ax"], dtype=float)
        solver_state.is_complex = bool(kw["is_complex"])
        if solver_state.is_complex:
            ax = ax[0::2] + 1j * ax[1::2]
        n = ap.size - 1
        A = sps.csc_matrix((ax.copy(), ai.astype(np.int64), ap.astype(np.int64)), shape=(n, n))
        solver_state.lu = None
        try:
            solver_state.lu = spl.splu(A, permc_spec="MMD_AT_PLUS_A", options={"SymmetricMode": False})
        except RuntimeError as exc:
            return {"status": False, "message": f"splu: {exc}"}
        return {"status": True, "message": ""}
    if action == "solve":
        b = np.frombuffer(kw["b"], dtype=float)
        if solver_state.is_complex:
            b = b[0::2] + 1j * b[1::2]
        x = solver_state.lu.solve(b, trans="T" if solver_state.transpose else "N")
        if solver_state.is_complex:
            xi = np.empty(2 * x.size)
            xi[0::2], xi[1::2] = x.real, x.imag
            x = xi
        return {"status": True, "message": "", "x": array.array("d", np.asarray(x, float).tobytes())}
    raise RuntimeError("unsupported action " + str(action))

def umfpack_leakfree_callback(**kw):
    from devsim.umfpack import umfshim
    if kw["action"] == "init":
        for o in _LIVE_SOLVERS:
            for attr in ("numeric", "symbolic", "matrix", "lu", "x"):
                if hasattr(o, attr):
                    setattr(o, attr, None)
        _LIVE_SOLVERS.clear()
        out = umfshim.local_solver_callback(**kw) if DEVSIM_SOLVER == "umfpack" else scipy_solver_callback(**kw)
        _LIVE_SOLVERS.append(out["solver_object"])
        return out
    if DEVSIM_SOLVER == "umfpack" and kw["action"] == "factor":
        so = kw["solver_object"]
        if so.umf_control is None and UMFPACK_STRATEGY is not None:
            from devsim.umfpack import umfpack_loader
            so.umf_control = umfpack_loader.umf_control(so.gdata, "complex" if kw["is_complex"] else "real")
            so.umf_control.Control[5] = float(UMFPACK_STRATEGY)
    return umfshim.local_solver_callback(**kw) if DEVSIM_SOLVER == "umfpack" else scipy_solver_callback(**kw)

def _devsim_reset():
    import devsim
    devsim.reset_devsim()
    for o in _LIVE_SOLVERS:
        for attr in ("numeric", "symbolic", "matrix", "lu", "x"):
            if hasattr(o, attr):
                setattr(o, attr, None)
    _LIVE_SOLVERS.clear()
    devsim.set_parameter(name="direct_solver", value="custom")
    devsim.set_parameter(name="solver_callback", value=umfpack_leakfree_callback)

def _ni_extrapolated(t_k):
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", materials.MaterialRangeWarning)
        return float(materials.ni_si_per_cm3(t_k))

def carriers_per_m(sweep):
    area_density_weight = sweep["vol_um2"] * 1e-12 * 1e6  # area um^2 -> m^2, density cm^-3 -> m^-3
    return sweep["n"] @ area_density_weight, sweep["p"] @ area_density_weight

def _crossing(x, f, from_right):
    idx = range(len(x) - 1, 0, -1) if from_right else range(0, len(x) - 1)
    for i in idx:
        j = i - 1 if from_right else i + 1
        if np.sign(f[i]) != np.sign(f[j]):
            return x[i] + (x[j] - x[i]) * (0 - f[i]) / (f[j] - f[i])
    return np.nan

@Functional
def f(w):
    return w["g"]

def power_fraction(self, regions):
    regions = (regions,) if isinstance(regions, str) else tuple(regions)
    tot = sum(float(np.real(self.mode.calculate_power(elements=r))) for r in regions)
    return tot / float(np.real(self.mode.calculate_power()))

def __init__(self, xg, yg, W, xs: XSec, d: Doping, meta=None):
    from scipy.interpolate import RegularGridInterpolator
    self.xg, self.yg, self.W = np.asarray(xg), np.asarray(yg), np.asarray(W)
    self.xs, self.d = xs, d
    self.meta = meta or {}
    self._interpolator = RegularGridInterpolator((self.xg, self.yg), self.W, bounds_error=False, fill_value=None)

def weight_at(self, x_um, y_um):
    x, y = _nudge_into_si(x_um, y_um, self.xs, self.d)
    return self._interpolator(np.stack([x, y], -1))

def weight_field(mode_props, xs, d):
    g = mode_props["weight_grid"]
    return WeightField(g["xg"], g["yg"], g["W"], xs, d, meta={"res_um": mode_props["res_um"],
                                                              "radius_um": mode_props["radius_um"]})

def _isolated(fn, *args, **kw):
    if not ISOLATE:
        return fn(*args, **kw)
    import importlib
    import multiprocessing as mp
    from concurrent.futures import ProcessPoolExecutor
    fn = getattr(importlib.import_module("mrm.extraction.junction"), fn.__name__)
    with ProcessPoolExecutor(max_workers=1, mp_context=mp.get_context("spawn")) as ex:
        return ex.submit(fn, *args, **kw).result()

def _distance_to_junction(X, Y, d: Doping):
    xt, yj = d.junction_offset_nm, d.y_junction_nm
    if d.topology == "lateral":
        n_reg = X > xt
        return n_reg, np.abs(X - xt)
    n_reg = (X > xt) | (Y > yj)
    dist = np.where(~n_reg, np.minimum(xt - X, yj - Y),
                    np.where((X >= xt) & (Y >= yj), np.hypot(X - xt, Y - yj),
                             np.where(X >= xt, X - xt, Y - yj)))
    return n_reg, dist

def H(s):
    da = (1j - q_loss) * a0 / (s - 1j * dlt + kap / 2)
    dac = (-1j - q_loss) * np.conj(a0) / (s + 1j * dlt + kap / 2)
    return -math.sqrt(ke) * (np.conj(t0) * da + t0 * dac)

def f3db_ghz(h_func, f_max_ghz=400.0):
    from scipy.optimize import brentq
    fg = np.linspace(0.01, f_max_ghz, 8000) * 1e9
    mag = np.abs(h_func(fg)) ** 2 - 0.5
    idx = np.where(np.sign(mag[:-1]) != np.sign(mag[1:]))[0]
    if idx.size == 0:
        return float("nan")
    i = idx[0]
    return brentq(lambda f: abs(h_func(np.array([f]))[0]) ** 2 - 0.5, fg[i], fg[i + 1]) / 1e9

def eo_bandwidth_ghz(tau_rc_s, *, q_loaded, x_detune, q_loss=0.0, kappa_e_frac=0.5):
    def h(f):
        return h_opt(f, q_loaded=q_loaded, x_detune=x_detune, q_loss=q_loss, kappa_e_frac=kappa_e_frac) / \
            (1 + 2j * math.pi * np.asarray(f) * tau_rc_s)
    return f3db_ghz(h)

def h(f):
    return h_opt(f, q_loaded=q_loaded, x_detune=x_detune, q_loss=q_loss, kappa_e_frac=kappa_e_frac) / \
        (1 + 2j * math.pi * np.asarray(f) * tau_rc_s)

def fill_for_cal5(v, dneff, n_g, lam_m=LAMBDA0_M, relief_pm=None):
    s1 = shift_pm(np.interp(CAL5_V, v, dneff), n_g, 1.0, lam_m)
    y = np.array(CAL5_SHIFT_PM, float)
    if relief_pm is not None:
        y = y + np.asarray(relief_pm, float)
    f_end = (CAL5_AVG_PM_PER_V * 1.6 + (relief_pm[-1] if relief_pm is not None else 0.0)) / s1[-1]
    f_lsq = float(s1 @ y / (s1 @ s1))
    res = f_lsq * s1 - y
    return {"fill_endpoint": float(f_end), "fill_lsq": f_lsq, "lsq_residual_pm": _sigs(res, 4),
            "lsq_rms_pm": float(np.sqrt(np.mean(res ** 2))), "shift_at_fill1_pm": _sigs(s1, 5)}

def ng_hypotheses(n_g_solver, n_eff, dneff_dt, t_k=T_REF_K, lam_m=LAMBDA0_M):
    alpha_l = float(materials.alpha_l_si_per_k(t_k))
    out = {"H_solver": {"n_g": n_g_solver, "basis": "femwell bent mode at r_ref"},
           "H86_via_R1": {"n_g": lam_m * (dneff_dt + n_eff * alpha_l) / (H86_PM_PER_K * 1e-12),
                          "basis": "R1 with dn_eff/dT from the solver, dlambda/dT = 85.9 pm/K"}}
    L = 2 * math.pi * P_RING_R_UM * 1e-6
    for k, (f0, flo, fhi) in FSR_HYPOTHESES_THZ.items():
        out[f"FSR_{k}_R7.5um"] = {"n_g": C0 / (f0 * 1e12 * L), "n_g_range": [C0 / (fhi * 1e12 * L),
                                                                            C0 / (flo * 1e12 * L)],
                                  "basis": f"FSR {f0} THz ({flo}-{fhi}) at R = 7.5 um pinned"}
    return out

def resolve_r_ref(xs: XSec, d: Doping, log=print, res_um=0.02):
    p = OUT_DIR / f"modes_{xs.name}.json"
    sc = OUT_DIR / f"modes_{xs.name}.sidecar.json"
    if p.exists() and sc.exists():
        try:
            side = json.loads(sc.read_text())
            if side.get("sha256") == _sha256(p):
                r = float(json.loads(p.read_text())["r_ref_um"])
                return r, {"source": f"modes_{xs.name}.json", "sha256": side["sha256"]}
        except Exception as exc:          # fall back to the local computation
            log(f"  modes artefact unreadable ({exc!r}); computing r_ref here")
    hist = []
    mode_props = _isolated(mode_properties, xs, d, res_um=res_um, radius_um=np.inf, with_dn_check=False)
    r = C0 / (2 * math.pi * mode_props["n_g"] * FSR_DESIGN_HZ) * 1e6
    hist.append({"r_um": r, "n_g": mode_props["n_g"], "from": "straight"})
    for _ in range(2):
        mode_props = _isolated(mode_properties, dataclasses.replace(xs, r_ref_um=r), d, res_um=res_um, radius_um=r,
                               with_dn_check=False)
        r_new = C0 / (2 * math.pi * mode_props["n_g"] * FSR_DESIGN_HZ) * 1e6
        hist.append({"r_um": r_new, "n_g": mode_props["n_g"], "from": f"bent at {r:.5f}"})
        if abs(r_new - r) < 1e-4:
            r = r_new
            break
        r = r_new
    return r, {"source": "self-consistent 1.8 THz FSR (junction.py; modes artefact absent)", "iterations": hist,
               "res_um": res_um}

def _summary_numbers(v, dneff, alpha, n_g, v_ac, c, r):
    avg_shift_pm_per_v = float(shift_pm(_at(v, dneff, 1.6), n_g)) / 1.6
    tau_rc_s = _at(v_ac, r, 1.0) * _at(v_ac, c, 1.0)
    return {"dneff_1v6": _at(v, dneff, 1.6), "dneff_1v": _at(v, dneff, 1.0), "dneff_4v": _at(v, dneff, 4.0),
            "dneff_fwd0v5": _at(v, dneff, -0.5), "eff_avg_0_1v6_pm_per_v_fill1": avg_shift_pm_per_v,
            "alpha_fca_0v_per_m": _at(v, alpha, 0.0), "alpha_fca_2v_per_m": _at(v, alpha, 2.0),
            "c_1v_f_per_m": _at(v_ac, c, 1.0), "c_2v_f_per_m": _at(v_ac, c, 2.0),
            "r_series_1v_ohm_m": _at(v_ac, r, 1.0), "f_rc_1v_ghz": 1.0 / (2 * math.pi * tau_rc_s) / 1e9}

def devsim_settings(topology, *, quick=False, prod=None, direct_res_floor_um=None):
    cfg = dict(QUICK if quick else PROD[topology])
    for k, x in (prod or {}).items():
        if x is None:
            continue
        if k not in ("scale", "ladder", "study"):
            raise ValueError(f"unknown DEVSIM setting {k!r}")
        cfg[k] = [float(y) for y in x] if k == "ladder" else float(x)
    if len(cfg["ladder"]) != 3 or any(b >= a for a, b in zip(cfg["ladder"][:-1], cfg["ladder"][1:])):
        raise ValueError("the ladder needs three scales, coarse to fine")
    cfg["direct_mode_res_floor_um"] = (DIRECT_MODE_RES_FLOOR_UM if direct_res_floor_um is None
                                       else float(direct_res_floor_um))
    return cfg

def jacobian(xs, d, wf_ref, n_g, *, quick, scale, mode_res_um, log=print, light=False):
    v_jac = V_SUBSET
    steps = [("width_nm", 20.0, "geom"), ("film_nm", 10.0, "geom"), ("slab_nm", 10.0, "geom"),
             ("log10_na_cm3", 0.1, "dop"), ("log10_nd_cm3", 0.1, "dop"), ("junction_offset_nm", 20.0, "dop"),
             ("plus_gap_nm", 50.0, "dop"), ("contact_gap_nm", 200.0, "dop"), ("grading_nm", 10.0, "dop_fwd"),
             ("outer_side", None, "swap")]
    if d.topology == "lshape":
        steps.insert(6, ("y_junction_nm", 10.0, "dop"))
    if quick:
        steps = [steps[0], steps[3]]
    elif light:
        steps = [x for x in steps if x[0] in ("width_nm", "film_nm", "slab_nm", "log10_na_cm3", "log10_nd_cm3",
                                              "junction_offset_nm", "y_junction_nm")]
    rows, base = {}, None
    for name, h, kind in steps:
        vals = []
        signs = (+1, -1) if kind in ("geom", "dop") else (+1, 0)
        for sgn in signs:
            xs2, d2, wf, ng2 = xs, d, wf_ref, n_g
            if sgn == 0:
                if base is None:
                    run0 = _devsim_and_overlap(xs, d, v_jac, wf_ref, scale)
                    base = dict(_run_summary(run0, n_g, contact_resistance_ohm_m(d, T_REF_K, xs)), n_g=n_g)
                vals.append(base)
                continue
            if kind == "geom":
                xs2 = dataclasses.replace(xs, **{name: getattr(xs, name) + sgn * h})
            elif kind == "swap":
                xs2 = dataclasses.replace(xs, r_ref_um=-xs.r_ref_um)    # mirror - p side outside
            elif name.startswith("log10_"):
                key = name[6:]
                d2 = dataclasses.replace(d, **{key: getattr(d, key) * 10 ** (sgn * h)})
            else:
                d2 = dataclasses.replace(d, **{name: getattr(d, name) + sgn * h})
            if kind in ("geom", "swap"):
                mode_props = _isolated(mode_properties, xs2, d2, res_um=mode_res_um, radius_um=xs2.r_ref_um,
                                       with_dn_check=False)
                wf, ng2 = weight_field(mode_props, xs2, d2), mode_props["n_g"]
            run = _devsim_and_overlap(xs2, d2, v_jac, wf, scale)
            vals.append(dict(_run_summary(run, ng2, contact_resistance_ohm_m(d2, T_REF_K, xs2)), n_g=ng2))
        denom = 2 * h if kind in ("geom", "dop") else (h if h else 1.0)
        rows[name] = {k: (vals[0][k] - vals[1][k]) / denom for k in vals[0]}
        log(f"  jacobian {name}: d(pm/V)/d = {rows[name]['eff_avg_0_1v6_pm_per_v_fill1']:.4g}, "
            f"d(alpha0)/d = {rows[name]['alpha_fca_0v_per_m']:.4g}, d(C1)/d = {rows[name]['c_1v_f_per_m']:.3g}")
    names = list(rows)
    keys = list(next(iter(rows.values())))
    return {"d": names, "step": {n: h for n, h, _ in steps if n in rows},
            "of": {k: [_sig(rows[n][k], 5) for n in names] for k in keys},
            "base": {k: _sig(v_, 7) for k, v_ in (base or {}).items()},
            "note": ("central differences (grading: forward step from the nominal 2 nm; outer_side: the difference "
                     "'p outside' minus 'n outside' (the nominal), not a derivative); densities per decade (log10); "
                     "geometry steps re-solve the mode and n_g; DEVSIM scale %.4g, mode res %.4g um; "
                     "eff_avg is at fill 1 with the perturbed n_g" % (scale, mode_res_um))}

def uncertainty_budget(conv, checks, jac, plasma_alt, summary):
    def rel(entry):
        try:
            return abs(float(entry.get("rel_error_estimate") or (entry["error_estimate"] / entry["extrapolated"])))
        except Exception:
            return None
    out = {"numerical": {}, "model": {}, "assumption_jacobian": "see artefact.jacobian (per unit of each input)"}
    devsim_conv = conv.get("devsim_mesh", {})
    mode_conv = conv.get("mode_mesh", {})
    for k in ("dneff_1v6", "alpha_fca_0v_per_m", "c_1v_f_per_m", "r_series_1v_ohm_m"):
        a = rel(devsim_conv.get(k, {})) if k in devsim_conv else None
        b = rel(mode_conv.get(k, {})) if k in mode_conv else None
        out["numerical"][k] = {"devsim_mesh_rel": _sig(a, 3), "mode_mesh_rel": _sig(b, 3)}
    out["model"]["plasma_dispersion_soref_vs_nsm_dneff"] = _sig(plasma_alt["soref1987"]["ratio_1v6"] - 1, 3)
    out["model"]["plasma_dispersion_soref_vs_nsm_alpha"] = _sig(plasma_alt["soref1987"]["ratio_alpha_0v"] - 1, 3)
    out["model"]["not_modelled"] = ["incomplete ionization (B ~1e18: 5-15 % fewer holes at 300 K)",
                                    "band-gap narrowing (V_bi lower by a few tens of mV)",
                                    "vertical implant profiles (box profiles assumed)",
                                    "sidewall angle and roughness", "pads, vias and C_pad"]
    return out

def rel(entry):
    try:
        return abs(float(entry.get("rel_error_estimate") or (entry["error_estimate"] / entry["extrapolated"])))
    except Exception:
        return None

def _tool_versions():
    vers = {"python": platform.python_version(), "numpy": np.__version__}
    for mod in ("scipy", "devsim", "femwell", "skfem", "gmsh", "shapely", "tidy3d"):
        try:
            with _quiet(True), warnings.catch_warnings():
                warnings.simplefilter("ignore")
                mm = __import__(mod)
            vers[mod] = getattr(mm, "__version__", "?")
        except Exception:
            vers[mod] = None
    return vers

def _json_default(o):
    if isinstance(o, np.ndarray):
        return o.tolist()
    if isinstance(o, (np.floating,)):
        return float(o)
    if isinstance(o, (np.integer,)):
        return int(o)
    return str(o)

def _apparent_order(vals, hs):
    v1, v2, v3 = (float(x) for x in vals[-3:])
    h1, _, h3 = (float(x) for x in hs[-3:])
    d12, d23 = v1 - v2, v2 - v3
    if d12 == 0 or d23 == 0 or (d12 > 0) != (d23 > 0):
        return None
    return math.log(d12 / d23) / math.log(math.sqrt(h1 / h3))

def free_order_rows(block):
    rows = {}
    for k, entry in block.items():
        if not (isinstance(entry, dict) and "values" in entry and "h" in entry) or len(entry["values"]) < 3:
            continue
        vals = np.asarray(entry["values"], float)
        free_fit = richardson(vals, entry["h"])
        apparent = _apparent_order(vals, entry["h"])
        d12, d23 = vals[-3] - vals[-2], vals[-2] - vals[-1]
        if d12 == 0 or d23 == 0 or (d12 > 0) != (d23 > 0):
            pattern = "non-monotone"
        elif abs(d23) >= abs(d12):
            pattern = "increments grow under refinement (no convergence visible at these levels)"
        elif free_fit["observed_order"] is None:
            # richardson() accepts only orders in [0.2, 8] - say on which side of that range the sequence falls
            if apparent > 8.0:
                pattern = "apparent order above 8 (the first increment dominates; not in the asymptotic range)"
            elif apparent < 0.2:
                pattern = "apparent order below 0.2 (the increments shrink too slowly; not in the asymptotic range)"
            else:
                pattern = "no order in [0.2, 8] fits the three levels (not in the asymptotic range)"
        else:
            pattern = "monotone, order observed"
        forced = bool(entry.get("order_forced", entry.get("observed_order") is not None
                                and free_fit["observed_order"] is None))
        if forced:
            entry["order_forced"] = True
        finest_magnitude = abs(vals[-1])
        rows[k] = {"observed_order": free_fit["observed_order"], "apparent_order": apparent,
                   "pattern": pattern, "order_forced_in_stored_entry": forced,
                   "last3_spread_rel": float(np.ptp(vals[-3:]) / finest_magnitude),
                   "all_levels_spread_rel": float(np.ptp(vals) / finest_magnitude),
                   "finest_step_rel": float(abs(vals[-1] - vals[-2]) / finest_magnitude)}
        if free_fit["observed_order"] is not None:
            rows[k]["free_rel_error_estimate"] = free_fit.get("rel_error_estimate")
    return rows

def _free_order_summary(rows, spread_key):
    forced = sorted(k for k, r in rows.items() if r["order_forced_in_stored_entry"])
    spreads = [r[spread_key] for r in rows.values()]
    return {"entries": len(rows), "order_forced": forced, "observed": sorted(set(rows) - set(forced)),
            f"{spread_key}_range": [min(spreads), max(spreads)] if spreads else None}

def jacobian_remesh_noise(art, side):
    jac = art.get("jacobian") or {}
    conv = side.get("convergence") or {}
    devsim_conv, mode_conv = conv.get("devsim_mesh") or {}, conv.get("mode_mesh") or {}

    def spread(block, key, last3):
        e = block.get(key)
        if not isinstance(e, dict) or "values" not in e:
            return None
        x = np.asarray(e["values"], float)
        x = x[-3:] if last3 else x
        return float(np.ptp(x) / abs(x[-1]))
    # widths of the assumed input ranges (current-code ranges - densities in decades)
    d_, xs_d = art["doping"], art["xsec"]
    dop = Doping(**{k: d_[k] for k in Doping.__dataclass_fields__ if k in d_})
    xs = dataclasses.replace(XSECS[xs_d["name"]], **{k: xs_d[k] for k in ("width_nm", "film_nm", "slab_nm")})
    rng = {**GEOMETRY_RANGES_BY_XSEC.get(xs.name, GEOMETRY_RANGES_NM), **doping_ranges(xs, dop)}
    widths = {}
    for name in jac.get("d", []):
        key = name[6:] if name.startswith("log10_") else name
        lohi = rng.get(key)
        if lohi and all(isinstance(x, (int, float)) for x in lohi):
            widths[name] = math.log10(lohi[1] / lohi[0]) if name.startswith("log10_") else lohi[1] - lohi[0]
    out, flagged = {}, []
    for k, vals in (jac.get("of") or {}).items():
        base = (jac.get("base") or {}).get(k)
        if k == "f_rc_1v_ghz":
            parts = [spread(devsim_conv, "c_1v_f_per_m", False), spread(devsim_conv, "r_series_1v_ohm_m", False)]
            s_dev = sum(x for x in parts if x is not None) if any(x is not None for x in parts) else None
        else:
            s_dev = spread(devsim_conv, _JAC_LADDER_KEY.get(k, ""), False)
        if base is None or s_dev is None:
            continue
        s_mode = spread(mode_conv, _JAC_MODE_KEY.get(k, ""), True) or 0.0
        row = {}
        for name, jv in zip(jac["d"], vals):
            h = (jac.get("step") or {}).get(name)
            if name not in JACOBIAN_REMESHED or not h or jv is None:
                row[name] = 0.0
                continue
            s = s_dev + (s_mode if name in JACOBIAN_MODE_RESOLVED else 0.0)
            ratio = s * abs(base) / h / max(abs(jv), 1e-300)
            row[name] = float(ratio)
            width = widths.get(name)
            effect = abs(jv) * width / abs(base) if width else None
            if ratio > 0.2 and (effect is None or effect > 1e-3):
                flagged.append({"of": k, "d": name, "noise_over_value": round(float(ratio), 3),
                                "effect_over_range_rel": None if effect is None else round(float(effect), 5)})
        out[k] = row
    return {"noise_over_value": out, "above_0p2": flagged,
            "note": "upper estimate (the ladder spread also holds the systematic part that cancels in a difference on "
                    "similar meshes); doping-level, grading and outer_side steps reuse the nominal DEVSIM mesh "
                    "(0 here). above_0p2 lists the entries whose noise may exceed 20 % of their value and whose "
                    "effect over the assumed range exceeds 1e-3 of the output (entries with a smaller effect, such "
                    "as the implant and contact gaps on dn_eff and C, are zero within noise and negligible)"}

def spread(block, key, last3):
    e = block.get(key)
    if not isinstance(e, dict) or "values" not in e:
        return None
    x = np.asarray(e["values"], float)
    x = x[-3:] if last3 else x
    return float(np.ptp(x) / abs(x[-1]))

def range_notes(art, out_dir=OUT_DIR):
    notes = []
    d, xs_d = art["doping"], art["xsec"]
    rec = d.get("ranges") or {}
    dop = Doping(**{k: d[k] for k in Doping.__dataclass_fields__ if k in d})
    xs = dataclasses.replace(XSECS[xs_d["name"]], **{k: xs_d[k] for k in ("width_nm", "film_nm", "slab_nm")})
    sugg = {k: list(v) for k, v in doping_ranges(xs, dop).items()}
    for k, lohi in rec.items():
        if k in d and isinstance(d[k], (int, float)) and not lohi[0] <= d[k] <= lohi[1]:
            notes.append(f"doping.{k} = {d[k]:g} lies outside its recorded range [{lohi[0]:g}, {lohi[1]:g}] (the "
                         f"lateral range about the rib centre); read it as the nominal +-60 nm, {sugg[k]}, as the "
                         f"handoff's Jacobian table does" if k == "junction_offset_nm" else
                         f"doping.{k} = {d[k]:g} lies outside its recorded range [{lohi[0]:g}, {lohi[1]:g}]")
    for k in ("y_junction_nm", "outer_side"):
        if k in sugg and k not in rec:
            notes.append(f"doping.{k} = {d[k]} has no recorded range; the current code writes {sugg[k]}"
                         + (" (reviewer assumption: from the slab top to 60 nm above it)" if k == "y_junction_nm"
                            else " (two-valued; jacobian stores the difference)"))
    fixed = [k for k in DOPING_UNRANGED if k in d and k not in rec]
    if fixed:
        notes.append("fixed without a range and not swept: " + ", ".join(f"{k} = {d[k]:g}" for k in fixed))
    if max(d["na_cm3"], d["nd_cm3"]) > 3e18:
        notes.append(f"the body doping (N_A {d['na_cm3']:g}, N_D {d['nd_cm3']:g} cm^-3, selected by CAL-5) lies above "
                     "the 5e17-3e18 cm^-3 research range that doping.provenance quotes as containing it; it is inside "
                     "the recorded assumed range 5e17-5e18")
    g = GEOMETRY_RANGES_BY_XSEC.get(xs_d["name"])
    rg = xs_d.get("ranges") or {}
    if g and rg.get("film_nm") and list(rg["film_nm"]) != list(g["film_nm"]):
        notes.append(f"xsec.ranges.film_nm {list(rg['film_nm'])} spans both film hypotheses; the modes artefact of "
                     f"{xs_d['name']} uses {list(g['film_nm'])} (the current code writes that)")
    if "sidewall_deg" not in rg:
        notes.append(f"xsec.sidewall_deg = {xs_d.get('sidewall_deg')} is assumed without a range or Jacobian (as in "
                     "the modes artefacts); listed as not modelled")
    return {"notes": notes, "suggested_ranges": {"doping": sugg, "xsec": {k: list(v) for k, v in (g or {}).items()}}}

def mesh_counts(xs: XSec, d: Doping, scale):
    coords, names, el, info = build_devsim_mesh(xs, d, scale)
    n_triangles = info["triangles"]
    triangle_elements = np.asarray(el[:5 * n_triangles], dtype=np.int64).reshape(n_triangles, 5)
    silicon_mask = triangle_elements[:, 1] == names.index("si")
    return {"scale": float(scale), "h_junction_nm": 1.0 * scale, "triangles": int(n_triangles),
            "nodes": int(np.unique(triangle_elements[:, 2:]).size),
            "nodes_si": int(np.unique(triangle_elements[silicon_mask, 2:]).size)}

def _modes_artefact(out_dir, xs_name):
    data_path, side_path = out_dir / f"modes_{xs_name}.json", out_dir / f"modes_{xs_name}.sidecar.json"
    if not (data_path.exists() and side_path.exists()):
        return None, f"no modes artefact for {xs_name}"
    side = json.loads(side_path.read_text())
    if side.get("sha256") != _sha256(data_path):
        return None, f"modes_{xs_name}.json fails its sha256"
    return (json.loads(data_path.read_text()), side), None

