def slab_neff(n_sub: float, n_f: float, n_cov: float, t_um: float, lam_um: float, pol: str = "TE",
              order: int = 0) -> float | None:
    from scipy.optimize import brentq
    k0 = 2 * math.pi / lam_um
    lo = max(n_sub, n_cov) + 1e-9
    hi = n_f - 1e-9
    if t_um <= 0:
        return None

    def f(N):
        kap = k0 * math.sqrt(n_f ** 2 - N ** 2)
        g1 = k0 * math.sqrt(N ** 2 - n_sub ** 2)
        g2 = k0 * math.sqrt(N ** 2 - n_cov ** 2)
        if pol == "TE":
            a1, a2 = math.atan(g1 / kap), math.atan(g2 / kap)
        else:
            a1, a2 = math.atan(n_f ** 2 * g1 / (n_sub ** 2 * kap)), math.atan(n_f ** 2 * g2 / (n_cov ** 2 * kap))
        return kap * t_um - order * math.pi - a1 - a2
    if f(lo) * f(hi) > 0:
        return None
    return brentq(f, lo, hi, xtol=1e-14)

def f(N):
    kap = k0 * math.sqrt(n_f ** 2 - N ** 2)
    g1 = k0 * math.sqrt(N ** 2 - n_sub ** 2)
    g2 = k0 * math.sqrt(N ** 2 - n_cov ** 2)
    if pol == "TE":
        a1, a2 = math.atan(g1 / kap), math.atan(g2 / kap)
    else:
        a1, a2 = math.atan(n_f ** 2 * g1 / (n_sub ** 2 * kap)), math.atan(n_f ** 2 * g2 / (n_cov ** 2 * kap))
    return kap * t_um - order * math.pi - a1 - a2

def window(self, xs: common.XSec | None = None, *, bent: bool, pml: bool = False, R: float | None = None,
           pml_um: float = 1.0, pml_strength: float = 2.0, extra_um: float = 0.0) -> common.Domain:
    xs = xs or self.xs
    width_um = xs.width_nm * 1e-3
    ymin = -1.5 if xs.below_box == "sio2" else -1.0
    half_x_um = max(2.0, width_um / 2 + 1.6)
    if not pml:
        return common.Domain(-half_x_um, half_x_um + (0.5 if bent else 0.0), ymin, 1.5)
    # place the absorbing PML beyond the outer radiation caustic
    caustic_x_um = self.caustic_um(xs, R)
    right = max(half_x_um, caustic_x_um + 1.2) + extra_um + pml_um
    return common.Domain(-half_x_um - pml_um * 0.5, right, ymin, 1.5, pml_left_um=pml_um * 0.5, pml_right_um=pml_um,
                         pml_strength=pml_strength)

def ng(
    self, *, lam: float | None = None, h: float | None = None, rich: bool = False, **kw
) -> tuple[float, float, float]:
    lam = self.lam0_um if lam is None else lam
    h = self.settings.dlam_um if h is None else h
    f = lambda l: self.neff(lam=l, **kw)
    neff = f(lam)
    d_effective_index_d_wavelength, index_wavelength_derivative_error = common.central_diff(
        f, lam, h, richardson_steps=rich
    )
    return (
        neff,
        neff - lam * d_effective_index_d_wavelength,
        (lam * index_wavelength_derivative_error if rich else float("nan")),
    )

def dndt(self, *, t_k: float | None = None, **kw) -> float:
    t_k = self.t_ref_k if t_k is None else t_k
    h = self.settings.dt_k
    return (self.neff(t_k=t_k + h, **kw) - self.neff(t_k=t_k - h, **kw)) / (2 * h)

def index_weights_fd(self, **kw) -> dict:
    index_step = self.settings.dn_idx
    materials = ["si", "box", "clad"] + (["air"] if self.xs.below_box == "air" else [])
    weights = {}
    for mname in materials:
        weights[mname] = (self.neff(dn={mname: +index_step}, **kw) - self.neff(dn={mname: -index_step},
            **kw)) / (2 * index_step)
    return weights

def find_r_ref(ex: Extractor, fsr_hz: float = common.FSR_DESIGN_HZ) -> dict:
    _, ng_straight, _ = ex.ng()
    radius_um = common.r_for_fsr_um(ng_straight, fsr_hz)
    history = [{"r_um": radius_um, "n_g_used": ng_straight, "from": "straight"}]
    for _ in range(6):
        _, ng_bent, _ = ex.ng(R=radius_um)
        next_radius_um = common.r_for_fsr_um(ng_bent, fsr_hz)
        history.append({"r_um": next_radius_um, "n_g_used": ng_bent, "from": f"bent at {radius_um:.5f}"})
        if abs(next_radius_um - radius_um) < 2e-5:
            radius_um = next_radius_um
            break
        radius_um = next_radius_um
    return {"r_ref_um": radius_um, "iterations": history, "fsr_hz": fsr_hz}

def fractions_block(m: common.ModeSol, xs: common.XSec) -> dict:
    regs = ["core"] + (["slab"] if xs.is_rib else []) + ["box", "clad"] + (["air"] if "air" in m.regions else [])
    power_fractions = {r: m.power_fraction(r) for r in regs}
    energy_fractions = {r: m.energy_fraction(r) for r in regs}
    out = {"power_fraction": {"si": power_fractions["core"] + power_fractions.get("slab", 0.0),
        "si_rib": power_fractions["core"],
                              "si_slab": power_fractions.get("slab", 0.0), "box": power_fractions["box"],
                                  "clad": power_fractions["clad"]},
           "energy_fraction": {"si": energy_fractions["core"] + energy_fractions.get("slab", 0.0),
               "box": energy_fractions["box"], "clad": energy_fractions["clad"]},
           "mode_area_um2": m.mode_area_um2(), "te_fraction": m.te_fraction(),
           "power_centroid_x_um": m.centroid_x_um()}
    if "air" in m.regions:
        out["power_fraction"]["air"] = power_fractions["air"]
        out["energy_fraction"]["air"] = energy_fractions["air"]
    return out

def family_block(ex: Extractor, R: float) -> dict:
    n = common.indices(ex.xs, ex.lam0_um, ex.t_ref_k)
    n_slab = {p: slab_neff(n["box"], n["si"], n["clad"], ex.xs.slab_nm * 1e-3, ex.lam0_um, p) if ex.xs.is_rib else None
              for p in ("TE", "TM")}
    n_clad = max(n["clad"], n["box"])
    out = {"slab_te0_n_eff": n_slab["TE"], "slab_tm0_n_eff": n_slab["TM"], "cladding_index": n_clad}
    te0 = ex.neff()
    mid = 0.5 * (te0 + n_clad)
    for fam in ("TM0", "TE1"):
        block = {}
        n_straight = None
        try:
            m = ex.mode(family=fam, num_modes=12, n_guess=mid)
            n_straight = float(np.real(m.n_eff))
            block["straight"] = {"n_eff": n_straight, "n_g": ex.ng(family=fam, num_modes=12, n_guess=mid)[1],
                                 "te_fraction": m.te_fraction(), "core_power_fraction": m.power_fraction("core")}
        except RuntimeError as e:
            block["straight"] = {"found": False, "note": str(e)[:300]}
        if n_straight is not None:
            try:
                m = ex.mode(family=fam, R=R, num_modes=12, n_guess=n_straight, near=n_straight, near_tol=0.03)
                n_bent = float(np.real(m.n_eff))
                rad_loss = radiation_loss(ex, R, family=fam, full=False, n_guess=n_bent, near=n_bent)
                block["bent"] = {"n_eff": n_bent,
                                 "n_g": ex.ng(family=fam, R=R, num_modes=12, n_guess=n_bent, near=n_bent,
                                              near_tol=0.03)[1],
                                 "te_fraction": m.te_fraction(), "core_power_fraction": m.power_fraction("core"),
                                 "alpha_rad_db_per_cm": rad_loss.get("alpha_rad_db_per_cm"),
                                 "pml": rad_loss["fem_pml"]}
            except RuntimeError as e:
                block["bent"] = {"found": False, "note": str(e)[:300]}
        # guidance - straight, n_eff above the lateral radiation channel (the TE slab mode for a rib - TM0 and TE1 both leak into it below its index - the cladding for a strip) - bent, PML loss below 100 dB/cm
        n_channel = n_slab["TE"] if ex.xs.is_rib else n_clad
        block["guided_straight"] = bool(n_straight is not None and n_straight > n_channel)
        a = block.get("bent", {}).get("alpha_rad_db_per_cm")
        block["guided_bent"] = bool(a is not None and a < 100.0)
        block["criterion"] = ("straight: n_eff above the lateral radiation channel (TE slab mode of a rib, cladding "
                              "of a strip); bent: FEM-PML radiation loss < 100 dB/cm (about the intrinsic loss of the "
                              "doped ring). A family that is not guided cannot form a resonance dip of useful Q.")
        out[fam] = block
    return out

def jacobian_block(ex: Extractor, R: float, base: dict) -> dict:
    from mrm import materials
    d_names, rows = [], {}
    outs = {"n_eff_per_nm": [], "lambda_res_nm_per_nm": [], "n_g_per_nm": [], "dlambda_dt_pm_per_k_per_nm": [],
            "alpha_rad_db_per_cm_per_nm": []}
    alpha_l = float(materials.alpha_l_si_per_k(ex.t_ref_k))
    for name, step in ex.settings.jac_steps_nm:
        if name == "slab_nm" and not ex.xs.is_rib:
            continue
        vals = {}
        for sign in (+1, -1):
            xs_step = ex.xs.replace(**{name: getattr(ex.xs, name) + sign * step})
            n0, n_g, _ = ex.ng(xs=xs_step, R=R)
            dndt = ex.dndt(xs=xs_step, R=R)
            dlam_dt_pm = ex.lam0_um * 1e3 / n_g * (dndt + n0 * alpha_l) * 1e3
            a = None
            if ex.settings.pml:
                try:
                    a = ex.mode(xs=xs_step, R=R, pml=True).alpha_db_per_cm
                except RuntimeError:
                    a = None
            vals[sign] = {"n_eff": n0, "n_g": n_g, "dlambda_dt": dlam_dt_pm, "alpha_rad": a}
            common.log(f"  jac {name} {sign * step:+}: {vals[sign]}")
        d_names.append(name)
        rows[name] = {"step_nm": step, "plus": vals[1], "minus": vals[-1]}
        dn = (vals[1]["n_eff"] - vals[-1]["n_eff"]) / (2 * step)
        outs["n_eff_per_nm"].append(dn)
        outs["lambda_res_nm_per_nm"].append(ex.lam0_um * 1e3 / base["n_g"] * dn)
        outs["n_g_per_nm"].append((vals[1]["n_g"] - vals[-1]["n_g"]) / (2 * step))
        outs["dlambda_dt_pm_per_k_per_nm"].append((vals[1]["dlambda_dt"] - vals[-1]["dlambda_dt"]) / (2 * step))
        if vals[1]["alpha_rad"] is not None and vals[-1]["alpha_rad"] is not None:
            outs["alpha_rad_db_per_cm_per_nm"].append((vals[1]["alpha_rad"] - vals[-1]["alpha_rad"]) / (2 * step))
        else:
            outs["alpha_rad_db_per_cm_per_nm"].append(0.0)
    if not ex.settings.pml:
        outs.pop("alpha_rad_db_per_cm_per_nm")
    return {"d": d_names, "of": outs, "evaluations": rows,
            "note": "central differences at fixed r_ref and fixed order; lambda_res_nm_per_nm = (lambda0/n_g) "
                    "dn_eff/dp; evaluated at T_ref; alpha_rad from the FEM PML (first configuration)"}

def slab_sweep(ex: Extractor, R: float, slabs_nm=(40.0, 50.0, 60.0, 80.0, 100.0)) -> dict:
    rows = []
    for s in slabs_nm:
        xs2 = ex.xs.replace(slab_nm=s)
        n0, ngv, _ = ex.ng(xs=xs2, R=R)
        try:
            a = ex.mode(xs=xs2, R=R, pml=True).alpha_db_per_cm
        except RuntimeError:
            a = None
        rows.append({"slab_nm": s, "n_eff": n0, "n_g": ngv, "alpha_rad_db_per_cm": a})
        common.log(f"  slab sweep {s}: {rows[-1]}")
    return {"r_um": R, "rows": rows}

def exact(R, pol):
    nus = np.linspace(k0 * n2 * R * 1.3, k0 * n1 * R * 0.999, 3000)
    v = np.array([fun(x, R, pol) for x in nus])
    roots = [brentq(fun, nus[i], nus[i + 1], args=(R, pol), xtol=1e-13)
             for i in range(len(nus) - 1) if np.sign(v[i]) != np.sign(v[i + 1])
             and abs(v[i]) < 1e3 and abs(v[i + 1]) < 1e3]
    return max(roots) / (k0 * R)

def mesh2d(h):
