        return from_meshio(mesh_from_OrderedDict(
            polys, {"core": {"resolution": h, "distance": 0.5, "SizeMax": 0.1}}, default_resolution_max=0.1))

def meep_check(st: Settings, *, R: float = MEEP_CYL_R_UM, m_order: int | None = None, resolutions=(30, 40, 60, 80),
               precomputed: str | None = None) -> dict:
    if not os.path.exists(common.MEEP_PYTHON):
        return {"skipped": "meep interpreter not found"}
    lam = 1.31
    xs = common.XSECS["strip400x200"]
    n = common.indices(xs, lam, common.T_REF_C + T0_K)
    nsi, nox = n["si"], n["clad"]
    ex = Extractor(xs.replace(top_kind="beol", box_kind="beol"), Settings(mesh_scale=st.meep_pred_scale))
    const = {"si": nsi, "box": nox, "clad": nox, "air": 1.0}

    # bent n_eff at wavelength l (um) with the constant indices, in bend formulation `form`.
    def neff_const(l, form):
        dom = ex.window(bent=True)
        P = ex.problem(ex.xs, dom, st.meep_pred_scale)
        ms = P.solve(const, l, radius_um=R, formulation=form, dom=dom, num_modes=3)
        return float(np.real(common.pick_mode(ms, "TE0").n_eff))
    if m_order is None:
        m_order = int(round(neff_const(lam, "exact") * 2 * math.pi * R / lam))
    # the resonance of order m - n_eff(lambda) 2 pi R = m lambda, solved by 6 Newton steps (FD slope, 1 nm step)
    pred = {}
    for form in ("exact", "isotropic"):
        l = lam
        for _ in range(6):
            ne = neff_const(l, form)
            ne2 = neff_const(l + 0.001, form)
            g = ne * 2 * math.pi * R - m_order * l
            dg = (ne2 - ne) / 0.001 * 2 * math.pi * R - m_order
            l -= g / dg
        pred[form] = l
    rows, src = None, None
    if precomputed and Path(precomputed).exists():
        pre = json.loads(Path(precomputed).read_text())
        cand = [r for r in pre if r.get("params", {}).get("m") == m_order and abs(r["params"]["R"] - R) < 1e-12
                and abs(r["params"]["nsi"] - nsi) < 1e-9 and abs(r["params"]["nox"] - nox) < 1e-9]
        if cand:
            rows, src = cand, {"file": precomputed, "sha256": common.sha256_file(Path(precomputed))}
    if rows is None:
        rows = meep_cyl_runs(R=R, m_order=m_order, nsi=nsi, nox=nox, lam_guess_um=pred["exact"],
                             resolutions=resolutions)
    series, verdict = meep_series_verdict(rows, pred)
    return {"R_um": R, "m": m_order, "n_si": nsi, "n_ox": nox, "fem_pred_lambda_um": pred,
            "fem_pred_h_core_nm": 10.0 * st.meep_pred_scale, "rows": rows,
            "precomputed_source": src, "series": series, "verdict": verdict,
            "fem_pred_difference_nm": (pred["isotropic"] - pred["exact"]) * 1e3,
            "note": "Meep's cylindrical runs converge slowly (first order) and, without subpixel averaging, "
                    "erratically (staircasing); the analytic Bessel benchmark is the decisive check (Meep is optional)"}

def neff_const(l, form):
    dom = ex.window(bent=True)
    P = ex.problem(ex.xs, dom, st.meep_pred_scale)
    ms = P.solve(const, l, radius_um=R, formulation=form, dom=dom, num_modes=3)
    return float(np.real(common.pick_mode(ms, "TE0").n_eff))

def meep_order_sensitivity(series_avg: dict | None, pred: dict) -> dict | None:
    if not series_avg or len(series_avg.get("lam_um", [])) < 3:
        return None
    res, lam = list(series_avg["res"]), [float(v) for v in series_avg["lam_um"]]
    h = [1.0 / r for r in res]
    triples = []
    for i in range(len(h) - 2):
        r = common.richardson(h[i:i + 3], lam[i:i + 3])
        triples.append({"res": res[i:i + 3], "p": r.get("p"), "f0_um": r["f0"]})
    fit = [t for t in triples if t["p"] is not None]
    if not fit:
        return None
    q, f1, f2 = h[1] / h[0], lam[0], lam[1]

    # limit (um) of the two finest levels for an assumed order p (it increases with p, as f2 > f1).
    def f0_at(p):
        return f1 - (f2 - f1) / (q ** p - 1.0)

    # the order in [0.2, 5] that puts the two-level limit on `target` (bisection. None if out of range).
    def p_needed(target):
        lo, hi = 0.2, 5.0
        if (f0_at(lo) - target) * (f0_at(hi) - target) > 0:
            return None
        for _ in range(200):
            mid = 0.5 * (lo + hi)
            if (f0_at(lo) - target) * (f0_at(mid) - target) <= 0:
                hi = mid
            else:
                lo = mid
        return 0.5 * (lo + hi)

    ps = [t["p"] for t in fit]
    f0s = [t["f0_um"] for t in fit]
    p_lo, p_hi, f_lo, f_hi = min(ps), max(ps), min(f0s), max(f0s)
    need = {k: p_needed(v) for k, v in pred.items()}
    return {"triples": triples, "order_range": [p_lo, p_hi], "f0_range_um": [f_lo, f_hi],
            "half_range_nm": 0.5 * (f_hi - f_lo) * 1e3,
            "dlimit_dorder_nm": (f0_at(1.05) - f0_at(0.95)) / 0.1 * 1e3,
            "order_needed_two_finest": need,
            "inside_f0_range": {k: bool(f_lo <= v <= f_hi) for k, v in pred.items()},
            "order_needed_inside_observed_range": {k: (v is not None and p_lo <= v <= p_hi) for k, v in need.items()},
            "note": "free-order Richardson on every consecutive triple of the averaged series; the half-range of "
                    "their limits is comparable to the 2.04 nm exact-isotropic difference, so the Meep check alone "
                    "only disfavours the isotropic map (it needs an order outside the observed range); the "
                    "decisive checks are the analytic Bessel benchmark and the Tidy3D bend shifts"}

def p_needed(target):
    lo, hi = 0.2, 5.0
    if (f0_at(lo) - target) * (f0_at(hi) - target) > 0:
        return None
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if (f0_at(lo) - target) * (f0_at(mid) - target) <= 0:
            hi = mid
        else:
            lo = mid
    return 0.5 * (lo + hi)

def solve_k(m, R, k):
    k = complex(k)
    for _ in range(80):
        f = det(k, m, R)
        df = (det(k + 1e-7, m, R) - det(k - 1e-7, m, R)) / 2e-7
        dk = f / df
        k -= dk
        if abs(dk) < 1e-13 * abs(k):
            break
    return k

def __post_init__(self):
    self.taus = np.asarray(self.taus, float)
    self.res = np.asarray(self.res, float)
    if self.res.shape[-1] != self.taus.size:
        raise ValueError("last axis of res must match taus")

@property
def dc(self) -> np.ndarray:
    return self.res.sum(axis=-1)

def splu_factory(A, permc_spec: str = "MMD_AT_PLUS_A"):
    lu = spla.splu(sp.csc_matrix(A), permc_spec=permc_spec)
    return lu.solve

def __init__(self, n: int, cap: int):
    self.V = np.empty((n, cap))
    self.k = 0          # number of basis vectors in use

def rational_krylov_basis(K, M, B, shifts, n_moments: int = 2, factor=splu_factory, tol: float = 1e-9,
                          log=None) -> np.ndarray:
    B = np.asarray(B, float)
    if B.ndim == 1:
        B = B[:, None]
    basis = _GrowingBasis(B.shape[0], len(shifts) * n_moments * B.shape[1])
    for sig in shifts:
        A = (K + sig * M) if sig else K
        solve = factor(A)
        X = np.asarray(solve(B), float).reshape(B.shape)
        kept = basis.append(X, tol)
        for _ in range(n_moments - 1):
            X = np.asarray(solve(M @ X), float).reshape(B.shape)
            kept += basis.append(X, tol)
        del solve, A
        if log:
            log(f"  krylov shift {sig:.3e} rad/s: kept {kept}, basis {basis.k}")
    return np.ascontiguousarray(basis.V[:, :basis.k])

def separate_poles(taus, min_ratio: float = 1.15) -> np.ndarray:
    t = np.sort(np.asarray(taus, float))[::-1].copy()
    for _ in range(50):
        moved = False
        for k in range(1, t.size):
            if t[k - 1] / t[k] < min_ratio:
                c = np.sqrt(t[k - 1] * t[k])
                t[k - 1], t[k] = c * np.sqrt(min_ratio), c / np.sqrt(min_ratio)
                moved = True
        if not moved:
            break
        t = np.sort(t)[::-1]
    return t

@property
def film_thick_um(self) -> float:
    return self.film_nm * 1e-3

@property
