@property
def rib_width_um(self) -> float:
    return self.width_nm * 1e-3

@property
def die_radius_um(self) -> float:
    return self.die_side_mm * 1e3 / np.sqrt(np.pi)

@property
def z_bot(self) -> float:
    return -self.box_um - self.sub_um

@property
