def _float_or_array(x):
    x = np.asarray(x, dtype=float)
    return float(x) if x.ndim == 0 else x

def _check_range(name: str, x, lo: float | None, hi: float | None, unit: str = "") -> None:
    x = np.asarray(x, dtype=float)
    if x.size == 0:
        return
    bad_lo = lo is not None and np.nanmin(x) < lo
    bad_hi = hi is not None and np.nanmax(x) > hi
    if bad_lo or bad_hi:
        warnings.warn(f"{name}: evaluated at [{np.nanmin(x):.4g}, {np.nanmax(x):.4g}] {unit}, outside the supported "
                      f"range [{lo}, {hi}] {unit}; the result is an extrapolation",
                      MaterialRangeWarning, stacklevel=3)

def _corner_value(spec: dict, corner: str) -> float:
    if corner == "nominal":
        return float(spec["nominal"])
    if corner == "low":
        return float(spec["range"][0])
    if corner == "high":
        return float(spec["range"][1])
    if corner in spec:
        return float(spec[corner])
    raise ValueError(f"corner must be nominal, low or high (got {corner!r})")

def _wavelength_um(lam_m, name="lambda", lo=None, hi=None):
    lam = _as_array(lam_m) * 1e6
    if np.any(lam <= 0.0):
        raise ValueError(f"{name}: wavelength must be positive (lam_m in metres)")
    if np.nanmax(lam) > 100.0:
        raise ValueError(f"{name}: lam_m={np.nanmax(lam) / 1e6:g} looks like nm or um; pass metres")
    _check_range(name, lam, lo, hi, "um")
    return lam

def n_si_li1980(lam_m, t_k):
    lam = _wavelength_um(lam_m, "n_si_li1980", 1.2, 14.0)
    T = _as_array(t_k)
    _check_range("n_si_li1980", T, 100.0, 750.0, "K")
    return _float_or_array(_li1980_parts(lam, T)[0])

def n_si_frey2006(lam_m, t_k):
    lam = _wavelength_um(lam_m, "n_si_frey2006", 1.1, 5.6)
    T = _as_array(t_k)
    if np.any(T > 300.5) or np.any(T < 20.0):
        raise ValueError("Frey 2006 Sellmeier is valid only for 20-300 K (it diverges near 320 K)")
    return _float_or_array(_frey2006_parts(lam, T)[0])

def si_index_offset_frey(lam_m):
    lam = _wavelength_um(lam_m, "si_index_offset_frey", 1.1, 5.6)
    t = _coeffs("si_index_recommended")["t_level_k"]
    return _float_or_array(_frey2006_parts(lam, t)[0] - _li1980_parts(lam, t)[0])

def n_si(lam_m, t_k, level: str = "frey"):
    if level not in ("frey", "li"):
        raise ValueError("level must be 'frey' (recommended) or 'li'")
    lam = _wavelength_um(lam_m, "n_si", 1.2, 5.6)
    T = _as_array(t_k)
    _check_range("n_si", T, 100.0, 750.0, "K")
    n = _li1980_parts(lam, T)[0]
    if level == "frey":
        t = _coeffs("si_index_recommended")["t_level_k"]
        n = n + _frey2006_parts(lam, t)[0] - _li1980_parts(lam, t)[0]
    return _float_or_array(n)

def dn_dt_si_per_k(lam_m, t_k):
    lam = _wavelength_um(lam_m, "dn_dt_si_per_k", 1.2, 14.0)
    T = _as_array(t_k)
    _check_range("dn_dt_si_per_k", T, 100.0, 750.0, "K")
    return _float_or_array(_li1980_parts(lam, T)[1])

def d2n_dt2_si_per_k2(lam_m, t_k):
    lam = _wavelength_um(lam_m, "d2n_dt2_si_per_k2", 1.2, 14.0)
    T = _as_array(t_k)
    _check_range("d2n_dt2_si_per_k2", T, 100.0, 750.0, "K")
    return _float_or_array(_li1980_parts(lam, T)[2])

def dn_dt_si_sigma_per_k(t_k):
    coefficients = _coeffs("si_dn_dt")
    T = _as_array(t_k)
    s = coefficients["sigma_300K"] + (coefficients["sigma_375K"] - coefficients["sigma_300K"]) / 75.0 * np.maximum(T - 300.0, 0.0)
    return _float_or_array(s)

def dn_dlam_si_per_m(lam_m, t_k, level: str = "frey"):
    if level not in ("frey", "li"):
        raise ValueError("level must be 'frey' or 'li'")
    lam = _wavelength_um(lam_m, "dn_dlam_si_per_m", 1.2, 5.6)
    T = _as_array(t_k)
    _check_range("dn_dlam_si_per_m", T, 100.0, 750.0, "K")
    d = _li1980_parts(lam, T)[3]
    if level == "frey":
        t = _coeffs("si_index_recommended")["t_level_k"]
        d = d + _frey2006_parts(lam, t)[1] - _li1980_parts(lam, t)[3]
    return _float_or_array(d * 1e6)

def n_g_si(lam_m, t_k, level: str = "frey"):
    lam = _as_array(lam_m)
    return _float_or_array(_as_array(n_si(lam_m, t_k, level)) - lam * _as_array(dn_dlam_si_per_m(lam_m, t_k, level)))

def dn_dt_si_cocorullo1523_per_k(t_k):
    a = _coeffs("si_dn_dt_cocorullo1523")["a"]
    T = _as_array(t_k)
    _check_range("dn_dt_si_cocorullo1523_per_k", T, 300.0, 550.0, "K")
    return _float_or_array(a[0] + a[1] * T + a[2] * T**2)

def n_sio2_malitson(lam_m):
    lam = _wavelength_um(lam_m, "n_sio2_malitson", 0.21, 3.71)
    coefficients = _coeffs("sio2_index_malitson")
    l2 = lam**2
    u = 1.0 + sum(b * l2 / (l2 - cc**2) for b, cc in zip(coefficients["B"], coefficients["C"]))
    return _float_or_array(np.sqrt(u))

def _malitson_dn_dlam_um(lam):
    coefficients = _coeffs("sio2_index_malitson")
    l2 = lam**2
    u = 1.0 + sum(b * l2 / (l2 - cc**2) for b, cc in zip(coefficients["B"], coefficients["C"]))
    du = sum(b * (-2.0 * lam * cc**2) / (l2 - cc**2) ** 2 for b, cc in zip(coefficients["B"], coefficients["C"]))
    return du / (2 * np.sqrt(u))

def _sio2_kind(kind):
    try:
        return _SIO2_KINDS[kind]
    except KeyError:
        raise ValueError(f"SiO2 kind must be one of {sorted(_SIO2_KINDS)} (got {kind!r})") from None

def dn_dlam_sio2_per_m(lam_m):
    lam = _wavelength_um(lam_m, "dn_dlam_sio2_per_m", 0.21, 3.71)
    return _float_or_array(_malitson_dn_dlam_um(lam) * _coeffs("sio2_index_malitson")["n_air"] * 1e6)

def n_g_sio2(lam_m, t_k, kind: str = "thermal"):
    return _float_or_array(_as_array(n_sio2(lam_m, t_k, kind))
                           - _as_array(lam_m) * _as_array(dn_dlam_sio2_per_m(lam_m)))

def n_si3n4_luke(lam_m):
    lam = _wavelength_um(lam_m, "n_si3n4_luke", 0.31, 5.5)
    coefficients = _coeffs("si3n4_index_luke")
    l2 = lam**2
    return _float_or_array(np.sqrt(1.0 + sum(b * l2 / (l2 - cc**2) for b, cc in zip(coefficients["B"],
        coefficients["C"]))))

def alpha_l_si_per_k(t_k):
    coefficients = _coeffs("si_alpha_l")
    T = _as_array(t_k)
    _check_range("alpha_l_si_per_k", T, 120.0, 1500.0, "K")
    return _float_or_array((coefficients["a"] * (1.0 - np.exp(-coefficients["b"] * (T - coefficients["t0_k"]))) + coefficients["c"] * T) * 1e-6)

def expansion_strain_si(t_k, t_ref_k):
    coefficients = _coeffs("si_alpha_l")
    T, T0 = _as_array(t_k), _as_array(t_ref_k)
    _check_range("expansion_strain_si", np.concatenate([np.ravel(T), np.ravel(T0)]), 120.0, 1500.0, "K")

    def prim(x):
        return (coefficients["a"] * (x + np.exp(-coefficients["b"] * (x - coefficients["t0_k"])) / coefficients["b"]) + 0.5 * coefficients["c"] * x**2) * 1e-6

    return _float_or_array(prim(T) - prim(T0))

def alpha_l_sio2_per_k(t_k):
    coefficients = _coeffs("sio2_alpha_l")
    T = _as_array(t_k)
    _check_range("alpha_l_sio2_per_k", T, *_valid_range("sio2_alpha_l", "t_k"), unit="K")
    return _float_or_array(coefficients["a293"] + coefficients["slope_per_k2"] * (T - coefficients["t0_k"]))

def dlambda_dt_ceiling_pm_per_k(lam_m, t_k, neff_over_ng=0.6, level: str = "frey"):
    lam = _as_array(lam_m)
    ng = _as_array(n_g_si(lam_m, t_k, level))
    if isinstance(neff_over_ng, str):
        if neff_over_ng != "all_si":
            raise ValueError("neff_over_ng must be a number or 'all_si'")
        neff_over_ng = _as_array(n_si(lam_m, t_k, level)) / ng
    thermo_optic = lam * _as_array(dn_dt_si_per_k(lam_m, t_k)) / ng * 1e12
    expansion = lam * _as_array(neff_over_ng) * _as_array(alpha_l_si_per_k(t_k)) * 1e12
    return _float_or_array(thermo_optic + expansion), _float_or_array(thermo_optic), _float_or_array(expansion)

def k_si_bulk_w_per_m_k(t_k):
    coefficients = _coeffs("k_si_bulk")
    T = _as_array(t_k)
    _check_range("k_si_bulk_w_per_m_k", T, 250.0, 500.0, "K")
    return _float_or_array(coefficients["k300"] * (T / 300.0) ** coefficients["exponent"])

def _valid_range(key: str, var: str):
    r = data()[key].get("valid_range", {}).get(var)
    return (None, None) if r is None else (float(r[0]), float(r[1]))

def k_low_k_w_per_m_k(t_k, kind: str = "dense"):
    coefficients = _coeffs("k_low_k")
    if kind not in ("dense", "porous30"):
        raise ValueError("low-k kind must be 'dense' or 'porous30'")
    T = _as_array(t_k)
    return _float_or_array(np.full_like(T, coefficients[kind]))

def k_metal_w_per_m_k(metal: str, t_k, corner: str = "nominal"):
    if metal not in _METALS:
        raise ValueError(f"metal must be one of {_METALS}")
    v = _corner_value(_coeffs("k_metals")[metal], corner)
    return _float_or_array(np.full_like(_as_array(t_k), v))

def thermal_boundary_resistance_m2_k_per_w(interface: str = "si_sio2"):
    coefficients = _coeffs("thermal_boundary_resistance")
    if interface not in coefficients:
        raise ValueError(f"interface must be one of {sorted(coefficients)}")
    return float(coefficients[interface])

def _cp_palankovski(T, c):
    x = (T / 300.0) ** c["beta"]
    return c["c300"] + c["c1"] * (x - 1.0) / (x + c["c1"] / c["c300"])

def cp_si_j_per_kg_k(t_k):
    T = _as_array(t_k)
    _check_range("cp_si_j_per_kg_k", T, 200.0, 500.0, "K")
    return _float_or_array(_cp_palankovski(T, _coeffs("cp_si")))

def cp_sio2_j_per_kg_k(t_k):
    T = _as_array(t_k)
    _check_range("cp_sio2_j_per_kg_k", T, 250.0, 500.0, "K")
    return _float_or_array(_cp_palankovski(T, _coeffs("cp_sio2")))

def rho_c_j_per_m3_k(material: str, t_k, corner: str = "nominal"):
    T = _as_array(t_k)
    material_key = _RHO_C_ALIASES.get(material.lower())
    if material_key is None:
        raise ValueError(f"unknown material {material!r} for rho_c; use one of {sorted(_RHO_C_ALIASES)}")
    if material_key == "si":
        return _float_or_array(RHO_SI_KG_PER_M3 * _as_array(cp_si_j_per_kg_k(T)))
    if material_key == "sio2":
        return _float_or_array(RHO_SIO2_KG_PER_M3 * _as_array(cp_sio2_j_per_kg_k(T)))
    return _float_or_array(np.full_like(T, _corner_value(_coeffs("rho_c")[material_key], corner)))

def thermal_properties(material: str, t_k, film_nm=None, corner: str = "nominal") -> dict:
    material_key = material
    if material_key == "si_film":
        if film_nm is None:
            raise ValueError("si_film needs film_nm")
        conductivity = k_si_film_w_per_m_k(t_k, film_nm)
    elif material_key == "si_bulk":
        conductivity = k_si_bulk_w_per_m_k(t_k)
    elif material_key in ("sio2_thermal", "sio2_pecvd"):
        conductivity = k_sio2_w_per_m_k(t_k, material_key.split("_")[1])
    elif material_key in ("low_k_dense", "low_k_porous30"):
        conductivity = k_low_k_w_per_m_k(t_k, material_key[len("low_k_"):])
    elif material_key in _METALS:
        conductivity = k_metal_w_per_m_k(material_key, t_k, corner)
    else:
        raise ValueError(f"material must be one of {THERMAL_MATERIALS}")
    heat_capacity = rho_c_j_per_m3_k(material_key, t_k, corner)
    return {"k_w_per_m_k": conductivity, "rho_c_j_per_m3_k": heat_capacity,
            "diffusivity_m2_per_s": _float_or_array(_as_array(conductivity) / _as_array(heat_capacity))}

def _plasma_coeffs(model, band_um):
    if model not in PLASMA_MODELS:
        raise ValueError(f"model must be one of {sorted(PLASMA_MODELS)}")
    c = _coeffs(PLASMA_MODELS[model])
    key = f"{band_um:g}"
    if key not in c:
        raise ValueError(f"{model}: band_um must be one of {sorted(c)} (got {band_um})")
    k = c[key]
    if model == "nsm2011":
        return k["p"], k["q"], k["r"], k["s"], k["a"], k["b"], k["c"], k["d"]
    return k["pe"], k["qe"], k["ph"], k["sh"], k["ae"], k["be"], k["ah"], k["bh"]

def plasma_dispersion(ne_per_cm3, nh_per_cm3, model: str = "nsm2011", band_um: float = 1.3, warn: bool = True):
    Ne, Nh = _as_array(ne_per_cm3), _as_array(nh_per_cm3)
    if np.any(Ne < 0) or np.any(Nh < 0):
        raise ValueError("carrier densities must be >= 0 (use plasma_dispersion_change for a depletion change)")
    if warn:
        nz = np.concatenate([np.ravel(Ne[Ne > 0]), np.ravel(Nh[Nh > 0])])
        _check_range(f"plasma_dispersion[{model}]", nz, 1e17, 1e20, "cm^-3")
    p, q, r, s, a, b, c, d = _plasma_coeffs(model, band_um)
    dn = -(p * Ne**q + r * Nh**s)
    da_per_cm = a * Ne**b + c * Nh**d
    return _float_or_array(dn), _float_or_array(da_per_cm * 100.0)

def plasma_dispersion_change(ne0_per_cm3, nh0_per_cm3, ne1_per_cm3, nh1_per_cm3, model: str = "nsm2011",
                             band_um: float = 1.3):
    n1, a1 = plasma_dispersion(ne1_per_cm3, nh1_per_cm3, model, band_um, warn=False)
    n0, a0 = plasma_dispersion(ne0_per_cm3, nh0_per_cm3, model, band_um, warn=False)
    return _float_or_array(_as_array(n1) - _as_array(n0)), _float_or_array(_as_array(a1) - _as_array(a0))

def plasma_dispersion_derivatives(ne_per_cm3, nh_per_cm3, model: str = "nsm2011", band_um: float = 1.3) -> dict:
    Ne, Nh = _as_array(ne_per_cm3), _as_array(nh_per_cm3)
    if np.any(Ne <= 0) or np.any(Nh <= 0):
        raise ValueError("densities must be > 0 for the derivatives")
    p, q, r, s, a, b, c, d = _plasma_coeffs(model, band_um)
    return {"dn_dne_cm3": _float_or_array(-p * q * Ne ** (q - 1)),
            "dn_dnh_cm3": _float_or_array(-r * s * Nh ** (s - 1)),
            "sigma_e_cm2": _float_or_array(a * b * Ne ** (b - 1)),
            "sigma_h_cm2": _float_or_array(c * d * Nh ** (d - 1))}

def plasma_temperature_factor(t_k, quantity: str = "dn", corner: str = "nominal"):
    coefficients = _coeffs("plasma_temperature")
    if quantity not in ("dn", "dalpha"):
        raise ValueError("quantity must be 'dn' or 'dalpha'")
    T = _as_array(t_k)
    return _float_or_array(1.0 + _corner_value(coefficients[quantity], corner) * (T - coefficients["t_ref_k"]))

def eg_si_ev(t_k):
    coefficients = _coeffs("si_bandgap")
    T = _as_array(t_k)
    return _float_or_array(coefficients["eg0"] - coefficients["a"] * T**2 / (T + coefficients["b"]))

def ni_si_per_cm3(t_k):
    coefficients = _coeffs("si_intrinsic_density")
    T = _as_array(t_k)
    _check_range("ni_si_per_cm3", T, 78.0, 400.0, "K")   # 340-400 K - extrapolation used by the materials notes
    return _float_or_array(coefficients["A"] * (T / 300.0) ** coefficients["m"] * np.exp(-coefficients["B"] / T))

def vbi_v(na_per_cm3, nd_per_cm3, t_k):
    T = _as_array(t_k)
    return _float_or_array(K_B_EV * T * np.log(_as_array(na_per_cm3) * _as_array(nd_per_cm3)
                                               / _as_array(ni_si_per_cm3(T)) ** 2))

def dvbi_dt_v_per_k(na_per_cm3, nd_per_cm3, t_k):
    coefficients = _coeffs("si_intrinsic_density")
    T = _as_array(t_k)
    return _float_or_array(_as_array(vbi_v(na_per_cm3, nd_per_cm3,
        T)) / T - 2.0 * K_B_EV * (coefficients["m"] + coefficients["B"] / T))

def mobility_masetti_cm2_per_v_s(n_per_cm3, carrier: str = "n"):
    if carrier not in ("n", "p"):
        raise ValueError("carrier must be 'n' or 'p'")
    coefficients = _coeffs("doped_si_mobility")["masetti_" + carrier]
    N = _as_array(n_per_cm3)
    return _float_or_array(coefficients["mu_min1"] * np.exp(-coefficients["Pc"] / N)
                           + (coefficients["mu_max"] - coefficients["mu_min2"]) / (1.0 + (N / coefficients["Cr"]) ** coefficients["alpha"])
                           - coefficients["mu1"] / (1.0 + (coefficients["Cs"] / N) ** coefficients["beta"]))

def resistivity_doped_si_ohm_m(n_per_cm3, t_k=300.0, carrier: str = "n", model: str = "arora"):
    N = _as_array(n_per_cm3)
    if model == "arora":
        mu = _as_array(mobility_arora_cm2_per_v_s(N, t_k, carrier))
    elif model == "masetti":
        mu = _as_array(mobility_masetti_cm2_per_v_s(N, carrier))
    else:
        raise ValueError("model must be 'arora' or 'masetti'")
    return _float_or_array(1.0 / (Q_E * N * mu) * 1e-2)

def tcr_doped_si_per_k(n_per_cm3, t_k=300.0, carrier: str = "n", h_k: float = 0.05):
    T = _as_array(t_k)
    rho_plus = _as_array(resistivity_doped_si_ohm_m(n_per_cm3, T + h_k, carrier))
    rho_minus = _as_array(resistivity_doped_si_ohm_m(n_per_cm3, T - h_k, carrier))
    rho_reference = _as_array(resistivity_doped_si_ohm_m(n_per_cm3, T, carrier))
    return _float_or_array((rho_plus - rho_minus) / (2 * h_k) / rho_reference)

def heater_tcr_per_k(family: str, corner: str = "nominal") -> float:
    fam = HEATER_ROM_FAMILY_MAP.get(family, family)
    coefficients = _coeffs("heater_tcr_family")
    if fam not in HEATER_FAMILIES:
        raise ValueError(f"family must be one of {HEATER_FAMILIES} or {tuple(HEATER_ROM_FAMILY_MAP)}")
    return _corner_value(coefficients[fam], corner)

def ge_pd_dark_current_a(i0_a, t_k, t0_k=298.15, ea_ev=None):
    activation_ev = ge_pd_dark_ea_ev() if ea_ev is None else ea_ev
    T, T0 = _as_array(t_k), _as_array(t0_k)
    _check_range("ge_pd_dark_current_a", T, 270.0, 380.0, "K")
    return _float_or_array(_as_array(i0_a) * np.exp(-_as_array(activation_ev) / K_B_EV * (1.0 / T - 1.0 / T0)))

def _source_and_provenance(key):
    entry = data()[key]
    return entry.get("source", ""), entry.get("provenance", "")

_RHO_C_ALIASES = {
    "si": "si", "si_film": "si", "si_bulk": "si", "si_doped": "si",
    "sio2": "sio2", "sio2_thermal": "sio2", "sio2_pecvd": "sio2", "sio2_beol": "sio2", "sio2_fused": "sio2",
    "box": "sio2", "cu": "cu", "cu_beol": "cu", "cu_bulk": "cu", "w": "w", "w_film": "w", "w_bulk": "w",
    "tin": "tin", "tin_film": "tin", "low_k": "low_k", "low_k_dense": "low_k", "low_k_porous30": "low_k",
}

