def _weakest_member(ctx: RelationContext, members) -> str:
    from mrm.params.config import provenance_rank
    return max(members, key=lambda m: provenance_rank(ctx.prov.get(m, "assumed")))

def integral_s(t, t0, s0, beta):
    x = t - t0
    return s0 * (x + 0.5 * beta * x * x)

def solve_t_for_shift(t_start, shift, t0, s0, beta):
    c = (integral_s(t_start, t0, s0, beta) + shift) / s0
    discriminant = 1.0 + 2.0 * beta * c
    if np.any(discriminant < 0):
        raise ValueError("no temperature reaches the requested shift: s(T) changes sign first (check beta)")
    return t0 + 2.0 * c / (1.0 + np.sqrt(discriminant))

def _fsr_hz_from_given(ctx: RelationContext):
    wavelength_m = ctx.vals["derived.optics.lambda_line_m"]
    if ctx.known(P_FSR_THZ):
        return ctx.vals[P_FSR_THZ], P_FSR_THZ
    if ctx.known(P_FSR_NM):
        return C0 * ctx.vals[P_FSR_NM] / (wavelength_m * wavelength_m), P_FSR_NM
    return None, None

def recompute(m):
    current_length_m = _TWO_PI * ctx.vals[P_RADIUS]
    if m == P_RADIUS:
        ctx.set(P_RADIUS, C0 / (ctx.vals[P_NG] * fsr * _TWO_PI), name, (P_NG, fsr_key), "R = c/(2 pi n_g FSR)",
                tex=_TEX_R, eq="5.14")
    elif m == P_NG:
        ctx.set(P_NG, C0 / (fsr * current_length_m), name, (P_RADIUS, fsr_key), "n_g = c/(FSR * 2 pi R)",
            tex=_TEX_NG,
                eq="5.14")
    else:
        recomputed_fsr_hz = C0 / (ctx.vals[P_NG] * current_length_m)
        if fsr_key == P_FSR_THZ:
            ctx.set(P_FSR_THZ, recomputed_fsr_hz, name, (P_NG, P_RADIUS), "FSR = c/(n_g 2 pi R)",
                    tex=r"\Delta f_{\mathrm{FSR}} = \frac{c}{n_g\, 2\pi R}", eq="5.14")
        else:
            ctx.set(P_FSR_NM, recomputed_fsr_hz * line_wavelength_m ** 2 / C0, name, (P_NG, P_RADIUS),
                    "FSR_lambda = lambda^2/(n_g 2 pi R)",
                    tex=r"\Delta\lambda_{\mathrm{FSR}} = \frac{\lambda_L^2}{n_g\, 2\pi R}", eq="5.13")

def _residual_r3_geometry(v: dict) -> float:
    L = v["derived.optics.length_m"]
    r_fsr = _max_rel_diff(v["derived.optics.fsr_hz"] * v[P_NG] * L / C0, 1.0)
    r_order = _max_rel_diff(v["derived.optics.n_eff_phase"] * L, v[P_ORDER] * v["derived.optics.lambda_res_cold_m"])
    r_length = _max_rel_diff(L, _TWO_PI * v[P_RADIUS])
    return max(r_fsr, r_order, r_length)

def _thermo_optic_beta(ctx: RelationContext):
    if not ctx.order2:
        return np.zeros_like(np.asarray(ctx.vals[P_S0], float)[..., :1])
    if not ctx.known(P_BETA):
        raise UnderdeterminedError("R1_thermo_optic: thermo_optic_order 2 needs ring.thermal.dlambda_dt_beta_per_k")
    return ctx.vals[P_BETA]

def _solve_r2_heater_efficiency(ctx: RelationContext) -> None:
    name = "R2_heater_efficiency"
    span_m = _p_fsr_span(ctx)
    span_path = P_FSR_SPAN
    have_power, have_efficiency = ctx.known(P_PFSR), ctx.known(P_EFF)
    if have_power and have_efficiency:
        residual = _max_rel_diff(ctx.vals[P_EFF] * ctx.vals[P_PFSR], span_m)

        def recompute(m):
            if m == P_EFF:
                ctx.set(P_EFF, span_m / ctx.vals[P_PFSR], name, (span_path, P_PFSR), "eff = FSR/P_FSR", tex=_TEX_EFF)
            else:
                ctx.set(P_PFSR, span_m / ctx.vals[P_EFF], name, (span_path, P_EFF), "P_FSR = FSR/eff", tex=_TEX_PFSR)
        _resolve_overdetermined(ctx, name, residual, [P_PFSR, P_EFF], recompute)
    elif have_power:
        ctx.set(P_EFF, span_m / ctx.vals[P_PFSR], name, (span_path, P_PFSR),
                "efficiency = FSR_lambda / P_FSR (P_FSR is the anchor; FSR_lambda of the P_FSR measurement)",
                tex=_TEX_EFF)
    elif have_efficiency:
        ctx.set(P_PFSR, span_m / ctx.vals[P_EFF], name, (span_path, P_EFF), "P_FSR = FSR_lambda/efficiency",
                tex=_TEX_PFSR)
    else:
        raise UnderdeterminedError(f"{name}: ring.heater.p_fsr_mw (the heater anchor) is required")

def recompute(m):
    if m == P_EFF:
        ctx.set(P_EFF, span_m / ctx.vals[P_PFSR], name, (span_path, P_PFSR), "eff = FSR/P_FSR", tex=_TEX_EFF)
    else:
        ctx.set(P_PFSR, span_m / ctx.vals[P_EFF], name, (span_path, P_EFF), "P_FSR = FSR/eff", tex=_TEX_PFSR)

def _residual_r2_heater(v: dict) -> float:
    span = v.get(P_FSR_SPAN, v["derived.optics.fsr_m"])
    r_eff = _max_rel_diff(v[P_EFF] * v[P_PFSR], span)
    s0, t0, beta = v[P_S0], v[P_T0], v["derived.thermal.beta_eff_per_k"]
    shift = integral_s(v[P_TLOCK], t0, s0, beta) - integral_s(v[P_OFFSET_T], t0, s0, beta)
    r_lock = float(np.max(np.abs(shift - np.mod(v[P_OFFSET], v["derived.optics.fsr_m"])) / v["derived.optics.fsr_m"]))
    if "derived.thermal.dt_fsr_k" in v:
        t_meas = v[P_PFSR_T]
        shift = integral_s(t_meas + v[P_Z] * v[P_PFSR], t0, s0, beta) - integral_s(t_meas, t0, s0, beta)
        r_z = _max_rel_diff(shift, span)
    else:
        r_z = _max_rel_diff(v[P_Z] * v["derived.thermal.s_lock_m_per_k"], v[P_EFF])
    return max(r_eff, r_lock, r_z)

def _cold_resonance_omega(ctx_or_vals) -> np.ndarray:
    values = ctx_or_vals.vals if isinstance(ctx_or_vals, RelationContext) else ctx_or_vals
    return _TWO_PI * C0 / values["derived.optics.lambda_res_cold_m"]

def _solve_r4_q_from_anchors(ctx: RelationContext, name: str) -> None:
    have_q = {p: ctx.known(p) for p in (P_QL, P_QI, P_QT, P_QD)}
    use_drop_share = ctx.known(P_XD)
    values = ctx.vals

    # check the extra equation when drop Q and drop share are both given.
    def check_drop_share() -> None:
        residual = _max_rel_diff(values[P_QL] / values[P_QD], values[P_XD])
        if residual > max(ctx.tolerance.get(name, 0.0), _EXACT_RTOL):
            raise OverdeterminedError(f"{name}: q_drop and kappa_d_over_kappa are both given and disagree "
                                      f"({residual:.3g})")

    check_drop_share_after_solve = False
    if use_drop_share and have_q[P_QD]:
        if have_q[P_QL]:
            check_drop_share()
        else:
            check_drop_share_after_solve = True     # Q_L comes from the rate sum below
        use_drop_share = False
    if use_drop_share:
        x = values[P_XD]
        free = [p for p in (P_QL, P_QI, P_QT) if not have_q[p]]
        if len(free) != 1:
            raise (UnderdeterminedError if len(free) > 1 else OverdeterminedError)(
                f"{name}: with kappa_d_over_kappa given, exactly one of q_loaded, q_intrinsic, q_through must be free "
                f"(free: {free})")
        f = free[0]  # config path of the one free Q member
        if f == P_QL:
            loaded_q = (1.0 - x) / (1.0 / values[P_QI] + 1.0 / values[P_QT])
            ctx.set(P_QL, loaded_q, name, (P_QI, P_QT, P_XD), "(1 - x_d)/Q_L = 1/Q_i + 1/Q_t",
                    tex=r"\frac{1 - x_d}{Q_L} = \frac{1}{Q_{\mathrm{int}}} + \frac{1}{Q_t}", eq="5.24")
        else:
            other = P_QT if f == P_QI else P_QI
            inverse_q = (1.0 - x) / values[P_QL] - 1.0 / values[other]
            if np.any(inverse_q <= 0):
                raise ValueError(f"{name}: inconsistent Q: (1 - x_d)/Q_L <= 1/{other.rsplit('.', 1)[1]} "
                                 f"(min {float(np.min(inverse_q)):.3g}); the coupling and loss cannot be solved")
            ctx.set(f, 1.0 / inverse_q, name, (P_QL, other, P_XD), "1/Q = (1 - x_d)/Q_L - 1/Q_other",
                    tex=r"\frac{1}{%s} = \frac{1 - x_d}{Q_L} - \frac{1}{%s}" % (SYMBOLS[f], SYMBOLS[other]),
                        eq="5.24")
        ctx.set(P_QD, values[P_QL] / x, name, (P_QL, P_XD), "Q_d = Q_L / x_d", tex=r"Q_d = \frac{Q_L}{x_d}")
    else:
        free = [p for p, h in have_q.items() if not h]
        if len(free) > 1:
            raise UnderdeterminedError(f"{name}: {len(free)} of q_loaded, q_intrinsic, q_through, q_drop are free "
                                       f"({free}); give all but one (or kappa_d_over_kappa)")
        if not free:
            residual = _max_rel_diff(1.0 / values[P_QL], 1.0 / values[P_QI] + 1.0 / values[P_QT] + 1.0 / values[P_QD])

            def recompute(m):
                _solve_one_free_q(ctx, m, name)
            _resolve_overdetermined(ctx, name, residual, [P_QL, P_QI, P_QT, P_QD], recompute)
        else:
            _solve_one_free_q(ctx, free[0], name)
        if check_drop_share_after_solve:
            check_drop_share()

def check_drop_share() -> None:
    residual = _max_rel_diff(values[P_QL] / values[P_QD], values[P_XD])
    if residual > max(ctx.tolerance.get(name, 0.0), _EXACT_RTOL):
        raise OverdeterminedError(f"{name}: q_drop and kappa_d_over_kappa are both given and disagree "
                                  f"({residual:.3g})")

def _solve_r5_latency(ctx: RelationContext) -> None:
    name = "R5_latency"
    if ctx.dt is None:
        raise UnderdeterminedError(f"{name}: sim.dt_plant_s is required")
    owners: dict[str, str] = {}
    for channel, key in LATENCY_OWNERS.items():
        if key in owners:
            raise OverdeterminedError(f"{name}: {key} owns two channels ({owners[key]}, {channel})")
        owners[key] = channel
        if ctx.known(key):
            ticks = np.rint(np.asarray(ctx.vals[key]) * ctx.latency_scale / ctx.dt).astype(np.int64)
            if np.any(ticks < 0):
                raise ValueError(f"{name}: negative latency for {channel}")
            ctx.set(f"derived.timing.{channel}.latency_ticks", ticks, name, (key, "uncertainty: latency scale"),
                    "round(latency_s * latency_scale / dt_plant_s)",
                    tex=r"\mathrm{round}\!\left(\frac{\text{latency} \times \text{latency scale}}{\Delta t}\right)")

def solve(ctx: RelationContext) -> RelationContext:
    for relation in RELATIONS:
        relation.solver(ctx)
    return ctx

def residuals(vals: dict) -> dict[str, float]:
    out = {}
    for relation in RELATIONS:
        try:
            out[relation.name] = float(relation.residual(vals))
        except KeyError:
            # optional members are handled inside each residual.
            # a missing required member must fail the closure check.
            out[relation.name] = float("nan")
    return out

@property
def name(self) -> str:
    return self.path.rsplit(".", 1)[-1]

def when(*pairs) -> Condition:
    if len(pairs) >= 2 and isinstance(pairs[0], str):
        return ((pairs[0], tuple(pairs[1:])),)
    return tuple((p, tuple(v)) for p, v in pairs)

def extend(keys: Iterable[Key]) -> None:
    for key in keys:
        if key.path in SCHEMA:
            raise ValueError(f"schema key {key.path!r} registered twice")
        SCHEMA[key.path] = key

def suggest(path: str, n: int = 3) -> list[str]:
    if path in DELETED:
        return []
    keys = list(SCHEMA)
    out = difflib.get_close_matches(path, keys, n=n, cutoff=0.75)
    parent, _, last = path.rpartition(".")
    siblings = [k for k in keys if k.rpartition(".")[0] == parent]
    for candidate in difflib.get_close_matches(last, [s.rpartition(".")[2] for s in siblings], n=n, cutoff=0.6):
        candidate_path = f"{parent}.{candidate}" if parent else candidate
        if candidate_path not in out:
            out.append(candidate_path)
    return out[:n]

def table_field(table_key: Key, name: str) -> Key | None:
    for field in table_key.fields:
        if field.name == name or field.path == name:
            return field
    return None

def check_units() -> list[str]:
    errors = []
    for key in SCHEMA.values():
        try:
            parse_key(key.path)
        except UnitError as e:
            errors.append(str(e))
        for field in key.fields:
            try:
                parse_key(field.path)
            except UnitError as e:
                errors.append(f"{key.path}[]: {e}")
    return errors

def check_conditions(get: Callable[[str], Any], present: set[str]) -> list[str]:
    errors = []
    for key in SCHEMA.values():
        is_set = key.path in present
        if key.required and not is_set and not key.derived_only:
            errors.append(f"missing required key {key.path!r} ({key.doc})")
        if key.required_if and _condition_holds(key.required_if, get) and not is_set:
            condition_text = ", ".join(f"{p} in {list(v)}" for p, v in key.required_if)
            errors.append(f"missing key {key.path!r}: required when {condition_text}")
        if key.forbidden_if and _condition_holds(key.forbidden_if, get) and is_set:
            condition_text = ", ".join(f"{p} in {list(v)}" for p, v in key.forbidden_if)
            errors.append(f"key {key.path!r} is forbidden when {condition_text}")
    return errors

def enum_code(path: str, value: Any) -> int:
    key = SCHEMA[path]
    return key.enum.index(value)

def _condition_holds(cond: Condition, get: Callable[[str], Any]) -> bool:
    for path, values in cond:
        value = get(path)
        if value is None:
            key = SCHEMA.get(path)
            value = key.default if key is not None else None
        if value not in values:
            return False
    return True

ENUM_ALIASES = {
    "experiment.kind": {"quasi_static": "locked_steady_state"},   # renamed 2026-10-21 (docs/CHANGELOG.md)
}

def check_tex(tex: str) -> list[str]:
    problems = []
    if not tex or not tex.strip():
        return ["empty"]
    for ch in "|$&#":
        if ch in tex:
            problems.append(f"character {ch!r} (use \\vert for a bar)")
    brace_depth, delimiter_depth, cursor, length = 0, 0, 0, len(tex)
    while cursor < length:
        character = tex[cursor]
        if character == "\\":
            match = re.match(r"[A-Za-z]+", tex[cursor + 1:])
            if match:
                command = match.group(0)
                cursor += 1 + len(command)
                if command not in KNOWN_COMMANDS:
                    problems.append(f"unknown command \\{command}")
                elif command == "left":
                    delimiter_depth += 1
                elif command == "right":
                    delimiter_depth -= 1
                if command in ("left", "right"):
                    if cursor >= length or not (tex[cursor] in "().[]" or tex[cursor:].startswith(("\\vert", "\\{",
                        "\\}", "\\langle",
                                                                                "\\rangle"))):
                        problems.append(f"\\{command} without a delimiter")
                if command in _BRACED_ARG_COUNT:
                    argument_cursor = cursor
                    for _k in range(_BRACED_ARG_COUNT[command]):
                        while argument_cursor < length and tex[argument_cursor] == " ":
                            argument_cursor += 1
                        if argument_cursor >= length or tex[argument_cursor] != "{":
                            problems.append(f"\\{command} needs a braced argument")
                            break
                        argument_depth, argument_cursor = 1, argument_cursor + 1
                        while argument_cursor < length and argument_depth:
                            argument_depth += {"{": 1, "}": -1}.get(tex[argument_cursor],
                                0) if tex[argument_cursor - 1] != "\\" else 0
                            argument_cursor += 1
                continue
            if cursor + 1 < length and tex[cursor + 1] in _ESCAPED_CHARS:
                cursor += 2
                continue
            problems.append(f"bad escape at {cursor}")
            cursor += 1
            continue
        if character == "{":
            brace_depth += 1
        elif character == "}":
            brace_depth -= 1
            if brace_depth < 0:
                problems.append("unbalanced '}'")
                brace_depth = 0
        elif character in "^_":
            argument_cursor = cursor + 1
            while argument_cursor < length and tex[argument_cursor] == " ":
                argument_cursor += 1
            if argument_cursor >= length or tex[argument_cursor] in "}^_":
                problems.append(f"{character} without a target")
        cursor += 1
    if brace_depth:
        problems.append("unbalanced '{'")
    if delimiter_depth:
        problems.append("unbalanced \\left/\\right")
    return problems

def _tex_argument(s: str, i: int) -> tuple[str, int]:
    while i < len(s) and s[i] == " ":
        i += 1
    if i >= len(s):
        return "", i
    if s[i] == "{":
        brace_depth, end = 1, i + 1
        while end < len(s) and brace_depth:
            if s[end] == "\\":
                end += 2
                continue
            brace_depth += {"{": 1, "}": -1}.get(s[end], 0)
            end += 1
        return s[i + 1:end - 1], end
    if s[i] == "\\":
        match = re.match(r"\\([A-Za-z]+|.)", s[i:])
        return match.group(0), i + len(match.group(0))
    return s[i], i + 1

def to_unicode(tex: str) -> str:
    out, cursor, source = [], 0, tex
    while cursor < len(source):
        character = source[cursor]
        if character == "\\":
            match = re.match(r"\\([A-Za-z]+|.)", source[cursor:])
            command = match.group(1)
            cursor += len(match.group(0))
            if command in _GREEK:
                out.append(_GREEK[command])
            elif command in ("mathrm", "text", "operatorname", "mathbf"):
                argument, cursor = _tex_argument(source, cursor)
                out.append(to_unicode(argument))
            elif command == "mathcal":
                argument, cursor = _tex_argument(source, cursor)
                out.append({"R": "ℛ", "F": "ℱ", "L": "ℒ"}.get(argument, argument))
            elif command in ("overline", "bar"):
                argument, cursor = _tex_argument(source, cursor)
                out.append("⟨" + to_unicode(argument) + "⟩")
            elif command in ("hat", "tilde", "dot"):
                argument, cursor = _tex_argument(source, cursor)
                out.append(to_unicode(argument) + {"hat": "̂", "tilde": "̃", "dot": "̇"}[command])
            elif command in ("frac", "tfrac", "dfrac"):
                numerator, cursor = _tex_argument(source, cursor)
                denominator, cursor = _tex_argument(source, cursor)
                numerator, denominator = to_unicode(numerator), to_unicode(denominator)
                wrap = lambda x: f"({x})" if re.search(r"[ +\-−]", x) else x  # noqa: E731
                out.append(f"{wrap(numerator)}/{wrap(denominator)}")
            elif command == "sqrt":
                argument, cursor = _tex_argument(source, cursor)
                argument = to_unicode(argument)
                out.append("√" + (argument if len(argument) == 1 else f"({argument})"))
            elif command in ("left", "right", "bigl", "bigr", "Bigl", "Bigr"):
                if cursor < len(source) and source[cursor] == ".":
                    cursor += 1
            elif command in _COMMAND_GLYPHS:
                out.append(_COMMAND_GLYPHS[command])
            elif command in (",", ";", ":", " "):
                out.append(" " if command != "," else " ")
            elif command == "!":
                pass
            else:
                out.append(command)
        elif character in "^_":
            argument, cursor = _tex_argument(source, cursor + 1)
            text = to_unicode(argument)
            table = _SUPERSCRIPTS if character == "^" else _SUBSCRIPTS
            if text and all(ch in table for ch in text):
                out.append("".join(table[ch] for ch in text))
            else:
                out.append(("^" if character == "^" else "_") + text)
        elif character in "{} ":
            cursor += 1                                   # TeX spacing comes from commands
        elif character in "+-=":
            previous = "".join(out).rstrip()
            operator = {"-": "−"}.get(character, character)
            out.append(f" {operator} " if previous and previous[-1] not in "(,=±−+_^/" else operator)
            cursor += 1
        else:
            out.append(character)
            cursor += 1
    return re.sub(r"\s+", " ", "".join(out)).strip()

def _unit_label(path: str) -> str:
    try:
        _, spec = parse_key(path)
    except ValueError:
        return ""
    return spec.expr or ""

def _format_number(x) -> str:
    if isinstance(x, (bool, np.bool_)):
        return str(bool(x))
    if isinstance(x, (int, np.integer)):
        return str(int(x))
    if isinstance(x, (float, np.floating)):
        x = float(x)
        if x == 0 or (1e-3 <= abs(x) < 1e5):
            return f"{x:.6g}"
        return f"{x:.4g}"
    return str(x)

def format_value(v: Any, max_items: int = 8) -> str:
    if v is None:
        return "null"
    if isinstance(v, np.ndarray):
        v = v.tolist()
    if isinstance(v, (list, tuple)):
        flat = np.asarray(v, dtype=object).ravel().tolist() if v and not isinstance(v[0], dict) else v
        if flat and all(isinstance(x, (int, float, np.integer, np.floating)) for x in flat):
            arr = np.asarray(flat, float)
            if arr.size > 1 and np.allclose(arr, arr[0], rtol=0, atol=0):
                return f"{_format_number(flat[0])} (x{arr.size})"
            items = [_format_number(x) for x in flat[:max_items]]
            return "[" + ", ".join(items) + (", ..." if len(flat) > max_items else "") + "]"
        return f"<{len(v)} items>"
    if isinstance(v, dict):
        return "{" + ", ".join(list(map(str, v))[:max_items]) + (", ..." if len(v) > max_items else "") + "}"
    return _format_number(v)

def show(cfg: Config) -> str:
    lines = [f"# {cfg.name} ({cfg.kind}); files: {', '.join(cfg.files)}", f"# config hash {cfg.hash()[:12]}"]
    paths = sorted(set(cfg.leaves) | set(cfg.settings) | set(cfg.open_values))
    for path in paths:
        if path in cfg.leaves:
            leaf = cfg.leaves[path]
            if leaf.is_free:
                lines.append(f"{path} = <derived>")
                continue
            tag = ", ".join(str(x) for x in (leaf.provenance, leaf.generation, leaf.source) if x)
            alt = f" (alt: {leaf.selected_alt})" if leaf.selected_alt else ""
            unit = _unit_label(path)
            lines.append(f"{path} = {format_value(leaf.value)}{' ' + unit if unit else ''}  [{tag}]{alt}")
        elif path in cfg.settings:
            lines.append(f"{path} = {format_value(cfg.settings[path])}")
        else:
            lines.append(f"{path} = {format_value(cfg.open_values[path])}  (open)")
    for name, entry in sorted(cfg.uncertainty.items()):
        pin = f" pinned={entry.pinned}" if entry.pinned is not None else ""
        lines.append(f"uncertainty.{name}: {entry.kind} target={entry.target}{pin}")
    for path, entry in sorted(cfg.variation.items()):
        lines.append(f"variation.{path}: " + ", ".join(f"{k}={v}" for k, v in entry.fields.items()
                                                       if k not in ("provenance", "generation", "source", "note")))
    if cfg.geometry:
        lines.append("variation.geometry: " + ", ".join(k for k in cfg.geometry if k in
                                                        ("width", "thickness", "slab", "gap_through", "gap_drop")))
    return "\n".join(lines)

def _derived_rows(cfg: Config, d: Derived) -> list[tuple]:
    rows = []
    values = d.params.values
    for path, derivation in sorted(d.params.derivations.items()):
        value = values.get(path)
        if value is None or path.startswith("derived.timing"):
            continue
        key = schema.lookup(path)
        if key is not None:
            display_value = from_si(path, np.asarray(value, float))
            unit = _unit_label(path)
        else:
            display_value, unit = np.asarray(value), "SI"
        rows.append((path, format_value(np.asarray(display_value).ravel()), unit,
                     effective_provenance(path, cfg, d.params.derivations), derivation.relation, derivation.formula))
    return rows

def _explain_derived(path: str, cfg: Config, d: Derived, depth: int, max_depth: int, lines: list[str],
                     stack: frozenset) -> None:
    pad = "  " * depth
    derivation = d.params.derivations.get(path)
    value = d.params.values.get(path)
    if path in cfg.leaves and not cfg.leaves[path].is_free:
        leaf = cfg.leaves[path]
        lines.append(f"{pad}{path} = {format_value(leaf.value)} {_unit_label(path)}  "
                     f"[{leaf.provenance}, {leaf.generation}, {leaf.source}]")
        return
    if derivation is None:
        lines.append(f"{pad}{path}: (not set)")
        return
    if schema.lookup(path) is not None and value is not None:
        shown = f"{format_value(np.asarray(from_si(path, np.asarray(value, float))).ravel())} {_unit_label(path)}"
    else:
        shown = f"{format_value(np.asarray(value).ravel())} SI" if value is not None else "?"
    provenance = effective_provenance(path, cfg, d.params.derivations)
    lines.append(f"{pad}{path} = {shown}  [derived by {derivation.relation}; provenance {provenance} (weakest input)]")
    lines.append(f"{pad}  formula: {derivation.formula}")
    if derivation.note:
        lines.append(f"{pad}  note: {derivation.note}")
    if depth >= max_depth or path in stack:
        return
    for i in derivation.inputs:
        if i in cfg.leaves or i in d.params.derivations:
            _explain_derived(i, cfg, d, depth + 1, max_depth, lines, stack | {path})

def explain(cfg: Config, path: str, *, max_depth: int = 6, thermal_hook="auto") -> str:
    lines: list[str] = []
    if path.startswith("uncertainty."):
        entry = cfg.uncertainty.get(path[len("uncertainty."):])
        if entry is None:
            raise ConfigError(f"no uncertainty entry {path!r}")
        lines.append(f"{path}: {entry.kind}" + (f", pinned to {entry.pinned}" if entry.pinned is not None else ""))
        for k, v in entry.fields.items():
            lines.append(f"  {k}: {format_value(v)}")
        lines.append(f"  set in: {', '.join(entry.origin)}")
        return "\n".join(lines)
    leaf = cfg.leaves.get(path)
    if leaf is not None and not leaf.is_free:
        lines.append(f"{path} = {format_value(leaf.value)} {_unit_label(path)}")
        lines.append(f"  provenance: {leaf.provenance}" + (f" (before override: {leaf.base_provenance})"
                                                            if leaf.base_provenance else ""))
        for f in ("generation", "source", "range", "note", "textbook", "disagrees", "targets", "residual",
                  "identifiable"):
            v = getattr(leaf, f)
            if v is not None:
                lines.append(f"  {f}: {format_value(v) if not isinstance(v, str) else v}")
        if leaf.artefact:
            a = leaf.artefact
            lines.append(f"  artefact: {a.get('file')}:{a.get('key')} sha256 {str(a.get('sha256'))[:12]}... "
                         f"(sidecar {a.get('sidecar')})")
        if leaf.alternatives:
            for n, a in sorted(leaf.alternatives.items()):
                mark = " <- selected" if n == leaf.selected_alt else ""
                alternative_value = a.get("value") if "value" in a else a.get("from")
                lines.append(f"  alternative {n}: {format_value(alternative_value)} ({a.get('provenance',
                    leaf.provenance)}){mark}")
        lines.append("  chain: " + " -> ".join(leaf.origin))
        key = schema.lookup(path)
        if key is not None and key.relation:
            lines.append(f"  member of: {', '.join(key.relation)}")
        for n, entry in sorted(cfg.uncertainty.items()):
            from mrm.params.config import _hypothesis_choice_map
            if entry.target == path or (entry.kind == "hypothesis"
                                    and any(path in m for m in _hypothesis_choice_map(entry).values())):
                lines.append(f"  varied per world by uncertainty.{n} ({entry.kind})")
        if path in cfg.variation:
            lines.append(f"  varied per device by variation.{path}")
        return "\n".join(lines)
    nominal_view = derive(cfg, thermal_hook=thermal_hook)
    if path in nominal_view.diagnostics:
        v = nominal_view.diagnostics[path]
        lines.append(f"{path} = {format_value(np.asarray(v).ravel())} {DIAGNOSTIC_UNITS.get(path, '')}  "
                     f"[diagnostic; provenance {nominal_view.provenance.get(path)} (weakest input)]")
        for i in nominal_view.inputs.get(path, []):
            if i in cfg.leaves or i in nominal_view.params.derivations:
                _explain_derived(i, cfg, nominal_view, 1, max_depth, lines, frozenset())
        return "\n".join(lines)
    if path in nominal_view.params.derivations:
        _explain_derived(path, cfg, nominal_view, 0, max_depth, lines, frozenset())
        return "\n".join(lines)
    suggestions = schema.suggest(path)
    raise ConfigError(f"{path!r} is not a leaf, derived quantity or diagnostic of this config"
                      + (f" (did you mean {', '.join(suggestions)}?)" if suggestions else ""))

def diff(a: Config, b: Config) -> str:
    out = []
    for p in sorted(set(a.leaves) | set(b.leaves)):
        left_leaf, right_leaf = a.leaves.get(p), b.leaves.get(p)
        if left_leaf is None:
            out.append(f"+ {p} = {format_value(right_leaf.value)} [{right_leaf.provenance}]")
        elif right_leaf is None:
            out.append(f"- {p} = {format_value(left_leaf.value)} [{left_leaf.provenance}]")
        else:
            left_value, right_value = np.asarray(left_leaf.value, dtype=object), np.asarray(right_leaf.value,
                dtype=object)
            same = left_value.shape == right_value.shape and bool(np.all(left_value == right_value))
            if not same or left_leaf.provenance != right_leaf.provenance or left_leaf.selected_alt != right_leaf.selected_alt:
                left_selection = f" alt={left_leaf.selected_alt}" if left_leaf.selected_alt else ""
                right_selection = f" alt={right_leaf.selected_alt}" if right_leaf.selected_alt else ""
                out.append(f"~ {p}: {format_value(left_leaf.value)} [{left_leaf.provenance}{left_selection}] -> "
                           f"{format_value(right_leaf.value)} [{right_leaf.provenance}{right_selection}]")
    for p in sorted(set(a.settings) | set(b.settings)):
        left_value, right_value = a.settings.get(p), b.settings.get(p)
        if left_value != right_value:
            out.append(f"~ {p}: {format_value(left_value)} -> {format_value(right_value)}")
    for n in sorted(set(a.uncertainty) | set(b.uncertainty)):
        left_entry, right_entry = a.uncertainty.get(n), b.uncertainty.get(n)
        left_spec = (left_entry.fields, left_entry.pinned) if left_entry else None
        right_spec = (right_entry.fields, right_entry.pinned) if right_entry else None
        if left_spec != right_spec:
            out.append(f"~ uncertainty.{n}: {left_spec[1] if left_spec else 'absent'} -> {right_spec[1] if right_spec else 'absent'}"
                       if left_spec and right_spec and left_spec[0] == right_spec[0] else f"~ uncertainty.{n} differs")
    for p in sorted(set(a.variation) | set(b.variation)):
        left_entry, right_entry = a.variation.get(p), b.variation.get(p)
        if (left_entry.fields if left_entry else None) != (right_entry.fields if right_entry else None):
            out.append(f"~ variation.{p} differs")
    if a.geometry != b.geometry:
        out.append("~ variation.geometry differs")
    return "\n".join(out)

def keys_markdown() -> str:
    def cond(c):
        return " and ".join(f"{p}={'|'.join(map(str, v))}" for p, v in c)
    out = ["| key | type | level | unit | rules | meaning |", "|---|---|---|---|---|---|"]
    for key in schema.SCHEMA.values():
        unit = parse_key(key.path)[1].expr or ""
        rules = []
        if not key.physical:
            rules.append("setting")
        if key.required:
            rules.append("required")
        if key.required_if:
            rules.append("required if " + cond(key.required_if))
        if key.forbidden_if:
            rules.append("forbidden if " + cond(key.forbidden_if))
        if key.derived_only:
            rules.append("derived only")
        if key.per_world:
            rules.append("per-world switch")
        if key.tick:
            rules.append(f"whole ticks ({key.tick})")
        if key.enum:
            rules.append("enum: " + ", ".join(map(str, key.enum)))
        if key.default is not None and not key.physical:
            rules.append(f"default {key.default}")
        type_text = key.type + (f" ({key.table_kind}: " + ", ".join(f.name for f in key.fields) + ")" if key.fields else "")
        out.append(f"| `{key.path}` | {type_text} | {key.level if key.physical else ''} | {unit} | {'; '.join(rules)} | "
                   f"{_md_cell(key.doc)} |")
    return "\n".join(out) + "\n"

def _load_config(args, preset=None, extra_set=(), extra_alt=()):
    return load(preset or args.preset, list(args.overrides) + list(extra_set), list(args.alts) + list(extra_alt),
                sources=args.sources, data_root=args.data_root)

def _run_params(args) -> int:
    command = args.params_cmd
    try:
        if command == "show":
            print(show(_load_config(args)))
        elif command == "table":
            text = table(_load_config(args), derived=not args.no_derived, thermal_hook=_thermal_hook_arg(args))
            if args.out:
                with open(args.out, "w") as stream:
                    stream.write(text)
                print(f"wrote {args.out}")
            else:
                sys.stdout.write(text)
        elif command == "explain":
            print(explain(_load_config(args), args.path, thermal_hook=_thermal_hook_arg(args)))
        elif command == "diff":
            a = _load_config(args, args.preset)
            b = _load_config(args, args.other, args.set_b, args.alt_b)
            text = diff(a, b)
            print(text if text else "(no differences)")
        elif command == "keys":
            sys.stdout.write(keys_markdown())
        elif command == "validate":
            exit_code = 0
            for preset_name in args.presets:
                try:
                    messages = validate(_load_config(args, preset_name), batch=args.batch,
                        thermal_hook=_thermal_hook_arg(args))
                    print(f"{preset_name}: OK")
                    for m in messages:
                        print(f"  warning: {m}")
                except (ConfigError, ValueError) as e:
                    exit_code = 1
                    print(f"{preset_name}: FAILED\n  {e}")
            return exit_code
        else:  # pragma: no cover - argparse enforces the choices
            raise SystemExit(f"unknown params command {command}")
    except (ConfigError, ValueError) as e:     # value errors include realization and relation failures
        print(f"error: {type(e).__name__}: {e}", file=sys.stderr)
        return 1
    return 0

def register_cli(register) -> None:
    register("params", "inspect presets: show | table | explain | diff | validate | keys", _setup_params,
             _run_params)

@property
def si_unit(self) -> str:
    if self.kind == "celsius":
        return "K"
    if self.kind == "dbm":
        return "W"
    if self.kind == "db":
        return "ln(P2/P1)"
    if self.kind == "db_per_len":
        return "m^-1 (ln power)"
    if self.kind == "db_per_hz":
        return "Hz^-1"
    parts = []
    for name, exponent in zip(_DIM_NAMES, self.dims):
        if exponent == 0:
            continue
        if exponent == 1:
            parts.append(name)
        else:
            exponent_text = f"{exponent:g}"
            parts.append(f"{name}^{exponent_text}")
    return " ".join(parts) if parts else "1"

def _factor(tok: str) -> tuple[float, tuple[float, ...]] | None:
    match = _TOKEN_RE.match(tok)
    if not match:
        return None
    base, exponent_text = match.group(1), match.group(2)
    if base not in TOKENS:
        return None
    scale, dims, _ = TOKENS[base]
    exponent = int(exponent_text) if exponent_text else 1
    return scale ** exponent, tuple(d * exponent for d in dims)

def _parse_expr(tokens: list[str]) -> UnitSpec | None:
    if not tokens:
        return None
    expr = "_".join(tokens)
    # specials
    if tokens == ["c"]:
        return UnitSpec(expr, "celsius", 1.0, _DIM_K)
    if tokens == ["dbm"]:
        return UnitSpec(expr, "dbm", 1e-3, _DIM_W)
    if tokens == ["db"]:
        return UnitSpec(expr, "db", _LN10_OVER_10, _DIM_NONE)
    if tokens[0] == "db" and len(tokens) >= 3 and tokens[1] == "per":
        denominator_spec = _parse_expr(tokens[2:])
        if denominator_spec is None or denominator_spec.kind != "linear":
            return None
        if denominator_spec.dims == _DIM_M or denominator_spec.dims == tuple(float(x) for x in _DIM_M):
            return UnitSpec(expr, "db_per_len", denominator_spec.scale,
                tuple(-factor_dims for factor_dims in denominator_spec.dims))
        if tuple(denominator_spec.dims) == tuple(float(x) for x in _DIM_HZ) and tokens[2:] == ["hz"]:
            return UnitSpec(expr, "db_per_hz", 1.0, tuple(-factor_dims for factor_dims in denominator_spec.dims))
        return None
    if any(unit_token in _SPECIAL for unit_token in tokens):
        return None
    scale = 1.0
    dims = [0.0] * 5
    sign = 1.0
    n_factors = 0
    i = 0
    while i < len(tokens):
        unit_token = tokens[i]
        if unit_token == "per":
            if i == len(tokens) - 1:
                return None
            sign = -1.0
            i += 1
            continue
        root_exponent = 1.0
        if unit_token == "rt":
            if i == len(tokens) - 1:
                return None
            root_exponent = 0.5
            i += 1
            unit_token = tokens[i]
        factor = _factor(unit_token)
        if factor is None:
            return None
        factor_scale, factor_dims = factor
        scale *= factor_scale ** (sign * root_exponent)
        for j in range(5):
            dims[j] += sign * root_exponent * factor_dims[j]
        n_factors += 1
        i += 1
    if n_factors == 0:
        return None
    # a 'per' that is not followed by factors was rejected above - a trailing operator is invalid
    return UnitSpec(expr, "linear", scale, tuple(dims))

@lru_cache(maxsize=4096)
def parse_key(key: str) -> tuple[str, UnitSpec]:
    segment = key.rsplit(".", 1)[-1]
    tokens = segment.split("_")
    for i in range(1, len(tokens)):
        spec = _parse_expr(tokens[i:])
        if spec is not None:
            name = "_".join(tokens[:i])
            qualifier = tokens[i - 1]      # the qualifier right before the unit decides whether it is a difference
            if spec.kind == "celsius" and qualifier in _DIFF_QUALIFIERS:
                raise UnitError(f"{key!r}: '_c' is an absolute (affine) temperature; a difference or spread must "
                                f"use '_k'")
            if spec.kind == "dbm" and qualifier in ("sigma", "delta", "offset", "step", "swing"):
                raise UnitError(f"{key!r}: a spread or step of a power is a ratio; use '_db', not '_dbm'")
            # a special token inside a compound unit cannot be parsed, and the longest-match rule would then pick a shorter unit and leave the special token in the name - 'shift_ghz_per_c' would read as name 'shift_ghz_per' in absolute degC, 'x_db_per_s' as name 'x_db' in 1/s.
            # Refuse both.
            if qualifier == "per" and spec.kind in ("celsius", "dbm", "db"):
                raise UnitError(f"{key!r}: '_per_{spec.expr}' is not a unit; a coefficient per degree is '_per_k' "
                                f"('_c' is affine, '_db'/'_dbm' are logarithmic)")
            if qualifier in _SPECIAL and tokens[i] == "per":
                raise UnitError(f"{key!r}: '_{qualifier}_{spec.expr}' is not a supported unit (only dB per length "
                                f"and dB per Hz are)")
            return name, spec
    return segment, _UNITLESS

def to_si(key: str | UnitSpec, value):
    spec = key if isinstance(key, UnitSpec) else unit_of(key)
    x = np.asarray(value, dtype=np.float64)
    if spec.kind in ("none",):
        out = x
    elif spec.kind == "linear":
        out = x * spec.scale
    elif spec.kind == "celsius":
        out = x + CELSIUS_OFFSET_K
    elif spec.kind == "db":
        out = x * _LN10_OVER_10
    elif spec.kind == "dbm":
        out = 1e-3 * np.power(10.0, x / 10.0)
    elif spec.kind == "db_per_len":
        out = x * _LN10_OVER_10 / spec.scale
    elif spec.kind == "db_per_hz":
        out = np.power(10.0, x / 10.0)
    else:  # pragma: no cover - kinds are closed
        raise UnitError(f"unknown unit kind {spec.kind}")
    return out if out.ndim else float(out)

def from_si(key: str | UnitSpec, value):
    spec = key if isinstance(key, UnitSpec) else unit_of(key)
    x = np.asarray(value, dtype=np.float64)
    if spec.kind == "none":
        out = x
    elif spec.kind == "linear":
        out = x / spec.scale
    elif spec.kind == "celsius":
        out = x - CELSIUS_OFFSET_K
    elif spec.kind == "db":
        out = x / _LN10_OVER_10
    elif spec.kind == "dbm":
        out = 10.0 * np.log10(np.maximum(x, 1e-300) / 1e-3)
    elif spec.kind == "db_per_len":
        out = x * spec.scale / _LN10_OVER_10
    elif spec.kind == "db_per_hz":
        out = 10.0 * np.log10(np.maximum(x, 1e-300))
    else:  # pragma: no cover
        raise UnitError(f"unknown unit kind {spec.kind}")
    return out if out.ndim else float(out)

def describe(key: str) -> str:
    name, spec = parse_key(key)
    if spec.kind == "none":
        return "unitless"
    if spec.kind == "linear":
        return f"{spec.expr} -> {spec.si_unit} (x {spec.scale:g})"
    return f"{spec.expr} -> {spec.si_unit} ({spec.kind})"

def pattern_mode_from_name(name: str) -> tuple[int, int]:
    if name == "off":
        return PATTERN_OFF, 0
    if name == "binomial":
        return PATTERN_BINOMIAL, 0
    if name.startswith("prbs"):
        k = int(name[4:])
        if k not in PRBS_TAPS:
            raise ValueError(f"unknown PRBS order {k}; known {sorted(PRBS_TAPS)}")
        return PATTERN_PRBS, k
    raise ValueError(f"unknown pattern_noise {name!r}; known {PATTERN_NAMES}")

@njit(cache=True)
def prbs_bits(k, t):
    n = (1 << k) - 1
    a = np.empty(n + k, np.uint8)
    for i in range(k):
        a[i] = 1
    for m in range(k, n + k):
        a[m] = a[m - t] ^ a[m - k]
    return a[:n].copy()

@njit(cache=True)
def _pack_bits32(bits):
    n_bits = bits.shape[0]
    n_words = (n_bits + 31) // 32
    words = np.zeros(n_words, np.int64)
    prefix_counts = np.zeros(n_words + 1, np.int64)
    for i in range(n_bits):
        if bits[i]:
            words[i >> 5] |= np.int64(1) << (i & 31)
    for w in range(n_words):
        prefix_counts[w + 1] = prefix_counts[w] + popcount32(words[w])
    return words, prefix_counts

def prbs_table(k: int) -> tuple[np.ndarray, np.ndarray, int]:
    if k not in PRBS_TAPS:
        raise ValueError(f"unknown PRBS order {k}")
    if k > PRBS_TABLE_MAX_K:
        raise ValueError(f"PRBS{k} is not tabulated (period 2^{k} - 1 bits); it falls back to the binomial model")
    if k not in _PRBS_TABLES:
        words, pre = _pack_bits32(prbs_bits(k, PRBS_TAPS[k]))
        _PRBS_TABLES[k] = (words, pre, (1 << k) - 1)
    return _PRBS_TABLES[k]

@njit(cache=True)
def prbs_ones_before(words, pre, x):
    word_index = x >> 5
    remaining_bits = x & 31
    if remaining_bits == 0:
        return pre[word_index]
    return pre[word_index] + popcount32(words[word_index] & ((np.int64(1) << remaining_bits) - 1))

@njit(cache=True)
def prbs_window_ones(words, pre, period, start, nbits):
    if nbits <= 0:
        return np.int64(0)
    total_ones = pre[pre.shape[0] - 1]
    full_periods = nbits // period
    remaining_bits = nbits - full_periods * period
    start_in_period = start % period
    end_in_period = start_in_period + remaining_bits
    ones_count = full_periods * total_ones
    if end_in_period <= period:
        ones_count += prbs_ones_before(words, pre, end_in_period) - prbs_ones_before(words, pre, start_in_period)
    else:
        ones_count += (total_ones - prbs_ones_before(words, pre, start_in_period)) + prbs_ones_before(words, pre,
            end_in_period - period)
    return ones_count

def q_from_ber(ber: float) -> float:

    if not 0.0 < ber < 0.5:
        raise ValueError("ber must be in (0, 0.5)")
    return float(math.sqrt(2.0) * erfcinv(2.0 * ber))

@njit(cache=True, _nrt=False)
def ber_from_oma(oma_rx_w, oma_sens_w, q_ref, ber_floor):
    if not (oma_rx_w > 0.0) or not (oma_sens_w > 0.0):
        return 0.5
    q = q_ref * oma_rx_w / oma_sens_w
    ber = 0.5 * math.erfc(q / _SQRT2)
    return ber if ber > ber_floor else ber_floor

@njit(cache=True, _nrt=False)
def p_above(mu, sig, thr):
    edge = thr + 0.5
    if sig > 0.0:
        return 0.5 * math.erfc((edge - mu) / (sig * _SQRT2))
    return 1.0 if mu >= edge else 0.0

@njit(cache=True)
def _bits_in_tick(k, bpt_i, bpt_f):
    if bpt_i >= 0:
        return np.int64(bpt_i)
    return np.int64(math.floor((k + 1) * bpt_f)) - np.int64(math.floor(k * bpt_f))

@njit(cache=True, _nrt=False)
def _ones_in_bits(mode, n, rho, words, pre, period, start, key, ring, tick, slot):
    if n <= 0:
        return np.int64(0)
    if rho <= 0.0:
        return np.int64(0)
    if rho >= 1.0:
        return np.int64(n)
    if mode == PATTERN_OFF:
        return np.int64(math.floor(rho * n + 0.5))
    if mode == PATTERN_PRBS and period > 0 and abs(rho - 0.5) < 1e-12:
        return prbs_window_ones(words, pre, period, start, n)
    return rng.binomial(key, ring, tick, slot, n, rho)

@njit(cache=True, _nrt=False, inline="always")
def pattern_tick_row(k, mode, bpt_i, bpt_f, density, traffic_on, words, pre, period, key, bitpos,
                     out_n1, out_nb, out_rho):
    for n in range(density.shape[0]):
        ones_density = density[n]
        if ones_density < 0.0:
            ones_density = 0.0
        elif ones_density > 1.0:
            ones_density = 1.0
        if not traffic_on[n]:
            out_n1[n] = 0
            out_nb[n] = 0
            out_rho[n] = ones_density
            continue
        bit_count = _bits_in_tick(k, bpt_i, bpt_f)
        ones_count = _ones_in_bits(mode, bit_count, ones_density, words, pre, period, bitpos[n], key, n, k,
            _SLOT_PATTERN)
        out_n1[n] = ones_count
        out_nb[n] = bit_count
        out_rho[n] = ones_density if (mode == PATTERN_OFF or bit_count == 0) else ones_count / bit_count
        if period > 0:
            bitpos[n] = (bitpos[n] + bit_count) % period
        else:
            bitpos[n] += bit_count

@njit(cache=True)
def pattern_tick(k, mode, bpt_i, bpt_f, density, traffic_on, words, pre, period, key, bitpos, out_n1, out_nb,
                 out_rho):
    for b in range(density.shape[0]):
        pattern_tick_row(k, mode, bpt_i, bpt_f, density[b], traffic_on[b], words, pre, period, key[b], bitpos[b],
                         out_n1[b], out_nb[b], out_rho[b])

@njit(cache=True)
def errors_tick_row(k, oma_tx_w, nbits, link_t, oma_sens_w, q_ref, ber_floor, period, lat, key, lam, fv, fr, fm,
                    out_new):
    for n in range(oma_tx_w.shape[0]):
        out_new[n] = False
        if nbits[n] > 0:
            lam[n] += ber_from_oma(oma_tx_w[n] * link_t, oma_sens_w[n], q_ref, ber_floor) * nbits[n]
        _errors_close(k, n, period, lat, key, lam, fv, fr, fm, out_new)

@njit(cache=True, _nrt=False)
def _errors_close(k, n, period, lat, key, lam, fv, fr, fm, out_new):
    if period > 0 and (k + 1) % period == 0:
        cnt = rng.poisson(key, n, k + 1, _SLOT_ERR, lam[n])
        lam[n] = 0.0
        fifo_push(fv, fr, fm, n, cnt, k + 1 + lat)
        out_new[n] = True

@njit(cache=True, _nrt=False, inline="always")
def errors_tick_ber_row(k, ber, nbits, period, lat, key, lam, fv, fr, fm, out_new):
    # whether instant k + 1 closes a counting period is the same for every lane, so it is tested once per tick (this saves ~0.2 us per tick)
    close = period > 0 and (k + 1) % period == 0
    for n in range(ber.shape[0]):
        out_new[n] = False
        if nbits[n] > 0:
            lam[n] += ber[n] * nbits[n]
        if close:
            _errors_close(k, n, period, lat, key, lam, fv, fr, fm, out_new)

@njit(cache=True)
def errors_tick(k, oma_tx_w, nbits, link_t, oma_sens_w, q_ref, ber_floor, period, lat, key, lam, fv, fr, fm,
                out_new):
    for b in range(oma_tx_w.shape[0]):
        errors_tick_row(k, oma_tx_w[b], nbits[b], link_t[b], oma_sens_w[b], q_ref, ber_floor, period, lat[b],
                        key[b], lam[b], fv[b], fr[b], fm[b], out_new[b])

@njit(cache=True, _nrt=False)
def errors_release_row(now, fv, fr, fm, latest, out_valid):
    for n in range(fm.shape[0]):
        out_valid[n] = False
        while True:
            count_ready, error_count, release_tick = fifo_pop_ready(fv, fr, fm, n, now)
            if not count_ready:
                break
            latest[n] = error_count
            out_valid[n] = True

@njit(cache=True)
def errors_release(now, fv, fr, fm, latest, out_valid):
    for b in range(fm.shape[0]):
        errors_release_row(now, fv[b], fr[b], fm[b], latest[b], out_valid[b])

@njit(cache=True, _nrt=False)
def bitstat_window_row(edge, n_win, mode, density, mu1, mu0, sig1, sig0, thr, words, pre, period, bitpos, key,
                       out_above, out_n1, out_a1, out_a0):
    for n in range(density.shape[0]):
        scenario_density = density[n]
        if scenario_density < 0.0:
            scenario_density = 0.0
        elif scenario_density > 1.0:
            scenario_density = 1.0
        start = bitpos[n] - n_win
        if period > 0:
            start = start % period
            if start < 0:
                start += period
        ones_count = _ones_in_bits(mode, n_win, scenario_density, words, pre, period, start, key, n, edge, _SLOT_BS_N1)
        zeros_count = n_win - ones_count
        above_from_ones = rng.binomial(key, n, edge, _SLOT_BS_A1, ones_count, p_above(mu1[n], sig1[n], thr[n]))
        above_from_zeros = rng.binomial(key, n, edge, _SLOT_BS_A0, zeros_count, p_above(mu0[n], sig0[n], thr[n]))
        out_above[n] = above_from_ones + above_from_zeros
        out_n1[n] = ones_count
        out_a1[n] = above_from_ones
        out_a0[n] = above_from_zeros

@njit(cache=True)
def bitstat_window(edge, n_win, mode, density, mu1, mu0, sig1, sig0, thr, words, pre, period, bitpos, key,
                   out_above, out_n1, out_a1, out_a0):
    for b in range(density.shape[0]):
        bitstat_window_row(edge, n_win, mode, density[b], mu1[b], mu0[b], sig1[b], sig0[b], thr[b], words, pre,
                           period, bitpos[b], key[b], out_above[b], out_n1[b], out_a1[b], out_a0[b])

def _arr_b(x, B, name, dtype=np.float64):
    array = np.asarray(x, dtype=dtype).reshape(-1)
    if array.size == 1:
        return np.full(B, array[0], dtype=dtype)
    if array.size != B:
        raise ValueError(f"{name}: shape {np.shape(x)} is not scalar or (B={B},)")
    return array.copy()

def _arr_bn(x, B, N, name, dtype=np.float64):
    array = np.asarray(x, dtype=dtype)
    if array.ndim == 1:
        array = array.reshape(1, -1) if array.shape[0] == N else array.reshape(-1, 1)
    try:
        return np.ascontiguousarray(np.broadcast_to(array, (B, N))).copy()
    except ValueError:
        raise ValueError(f"{name}: shape {np.shape(x)} does not broadcast to (B={B}, N={N})") from None

def _keys(seeds, B, stream) -> np.ndarray:
    seeds = _arr_b(seeds, B, "seeds", np.int64)
    sid = rng.stream_id(stream) if isinstance(stream, str) else int(stream)
    return np.array([rng.stream_key(int(s), sid) for s in seeds], dtype=np.uint64)

@classmethod
def from_plant_params(cls, pp, **kw) -> "DatapathHw":
    d, t = pp.datapath, pp.timing
    dt = float(t.dt_s)
    br = np.asarray(d.bitrate_hz, dtype=float).reshape(-1)
    if not np.all(np.isfinite(br)):
        raise ValueError("datapath.bitrate_gbps is needed for the data path")
    args = dict(bitrate_hz=float(br[0]), pattern_noise=PATTERN_NAMES[int(pp.flags.pattern_noise)],
                bitstat_window_bits=int(d.bitstat_window_bits) or BITSTAT_WINDOW_BITS_DEFAULT,
                error_count_period_s=(int(d.error_count_period_ticks) * dt if d.error_count_period_ticks
                                      else ERROR_COUNT_PERIOD_S_G26),
                error_count_latency_s=np.asarray(t.error_count_latency_ticks).reshape(-1) * dt)

    # the DatapathParams field as an array, or None when it is absent or not finite everywhere.
    def finite(name):
        v = getattr(d, name, None)
        if v is None:
            return None
        v = np.asarray(v, dtype=float)
        return v if np.all(np.isfinite(v)) else None
    sens = finite("rx_sensitivity_oma_w")
    if sens is not None:
        args["rx_sensitivity_oma_dbm"] = 10.0 * np.log10(sens / 1e-3)      # W -> dBm
    link = finite("link_transmission")
    if link is not None:
        args["link_loss_db"] = -10.0 * np.log10(link.reshape(-1))          # transmission -> dB loss
    for name, arg in (("ber_ref", "ber_ref"), ("ber_floor", "ber_floor"), ("bitstat_bw_hz", "bitstat_bw_hz"),
                      ("bitstat_noise_a_per_rt_hz", "bitstat_noise_a_per_rt_hz")):
        v = finite(name)
        if v is not None:
            args[arg] = float(v.reshape(-1)[0])
    args.update(kw)
    return cls.build(int(pp.batch), int(pp.n_rings), dt, **args)

def finite(name):
    v = getattr(d, name, None)
    if v is None:
        return None
    v = np.asarray(v, dtype=float)
    return v if np.all(np.isfinite(v)) else None

def ber(self, oma_tx_w) -> np.ndarray:
    from scipy.special import erfc
    received_oma_w = _arr_bn(oma_tx_w, self.B, self.N, "oma_tx_w") * self.link_t[:, None]
    q = self.q_ref * received_oma_w / self.oma_sens_w
    bit_error_rate = np.where(received_oma_w > 0, 0.5 * erfc(q / math.sqrt(2.0)), 0.5)
    return np.maximum(bit_error_rate, self.ber_floor)

@njit(cache=True)
def _bidx(a, i):
    return i if a.shape[0] > 1 else 0

@njit(cache=True, _nrt=False)
def dac_frac(code, n_bits, err_row, bow_lsb):
    weighted_code = 0.0
    endpoint_weight = 0.0
    for i in range(n_bits):
        bit_weight = float(1 << i) + err_row[i]
        endpoint_weight += bit_weight
        if (code >> i) & 1:
            weighted_code += bit_weight
    full_scale_code = float((1 << n_bits) - 1)
    ideal_fraction = code / full_scale_code
    weighted_code += bow_lsb * 4.0 * ideal_fraction * (1.0 - ideal_fraction)
    return weighted_code / endpoint_weight

@njit(cache=True)
def _pwm_high_clocks(c, d, period_clocks):
    whole_periods = c // period_clocks
    remaining_clocks = c - whole_periods * period_clocks
    return whole_periods * d + (remaining_clocks if remaining_clocks < d else d)

@njit(cache=True, _nrt=False)
def latch_row(cmd, cmd_valid, reg, pending, has_pending, last_update, tick, min_update_ticks, code_lo, code_hi):
    for n in range(reg.shape[0]):
        if cmd_valid[n]:
            c = cmd[n]
            if c < code_lo:
                c = code_lo
            elif c > code_hi:
                c = code_hi
            pending[n] = c
            has_pending[n] = 1
        if has_pending[n] != 0 and tick - last_update[n] >= min_update_ticks:
            reg[n] = pending[n]
            last_update[n] = tick
            has_pending[n] = 0

@njit(cache=True, _nrt=False)
def fifo_row(reg, fifo, tick, latency_ticks, out_code):
    fifo_depth = fifo.shape[1]
    write_slot = tick % fifo_depth
    read_slot = (tick - latency_ticks) % fifo_depth
    for n in range(reg.shape[0]):
        fifo[n, write_slot] = reg[n]
        out_code[n] = fifo[n, read_slot]

@njit(cache=True)
def heater_target_row(code, law, bits, pwm_bits, bit_err, bow, pwm_ripple, tick, dt_clk, out_u, out_ripple):
    for n in range(code.shape[0]):
        u, rip = heater_target_one(code[n], law, bits, pwm_bits, bit_err[_bidx(bit_err, n)], bow[_bidx(bow, n)],
                                   pwm_ripple, tick, dt_clk)
        out_u[n] = u
        out_ripple[n] = rip

@njit(cache=True)
def bias_target_row(code, bits, bit_err, bow, v_min, v_max, out_v):
    for n in range(code.shape[0]):
        out_v[n] = bias_target_one(code[n], bits, bit_err[_bidx(bit_err, n)], bow[_bidx(bow, n)],
                                   v_min[_bidx(v_min, n)], v_max[_bidx(v_max, n)])

@njit(cache=True, _nrt=False)
def bias_target_one(c, bits, er, bw, lo, hi):
    return lo + (hi - lo) * dac_frac(c, bits, er, bw)

@njit(cache=True)
def _x_plus_expm1_neg(x):
    if x < 1e-3:
        return x * x * (0.5 - x * (1.0 / 6.0 - x * (1.0 / 24.0 - x / 120.0)))
    return x + math.expm1(-x)

@njit(cache=True, _nrt=False)
def actuator_quiescent_row(reg, has_pending, fifo, y_slew, y_out, target, tol):
    for n in range(reg.shape[0]):
        if has_pending[n] != 0:
            return False
        for j in range(fifo.shape[1]):
            if fifo[n, j] != reg[n]:
                return False
        if y_slew[n] != target[n] or abs(y_out[n] - target[n]) > tol:
            return False
    return True

@njit(cache=True, _nrt=False)
def settle_advance_row(target, y_slew, y_out, tau, dt, n_ticks):
    for n in range(target.shape[0]):
        settle_time_s = tau[_bidx(tau, n)]
        y_slew[n] = target[n]
        if settle_time_s <= 0.0:
            y_out[n] = target[n]
        else:
            y_out[n] = target[n] + (y_out[n] - target[n]) * math.exp(-n_ticks * dt / settle_time_s)

@njit(cache=True)
def _power_from_v2(v2, r_o, k):
    power_quadratic_discriminant = r_o * r_o + 4.0 * k * v2
    if power_quadratic_discriminant < 0.0:
        return v2 / r_o, 1
    return 2.0 * v2 / (r_o + math.sqrt(power_quadratic_discriminant)), 0

@njit(cache=True, _nrt=False, inline="always")
def heater_power_row(
    u, law, t_pre, g_self, r0, alpha, t0, v_fs, i_fs, p_fs, v_comp, out_p, out_v, out_i, out_r, out_flags
):
    for n in range(u.shape[0]):
        drive_fraction = u[n]
        if drive_fraction < 0.0:
            drive_fraction = 0.0
        reference_resistance_ohm = r0[_bidx(r0, n)]
        tcr_per_k = alpha[_bidx(alpha, n)]
        resistance_before_own_heat_ohm = reference_resistance_ohm * (
            1.0 + tcr_per_k * (t_pre[_bidx(t_pre, n)] - t0[_bidx(t0, n)])
        )
        if resistance_before_own_heat_ohm < 1e-3 * reference_resistance_ohm:
            resistance_before_own_heat_ohm = (
                1e-3 * reference_resistance_ohm
            )  # guard against an unphysical negative resistance from a large negative TCR swing
        d_resistance_d_power_ohm_per_w = (
            reference_resistance_ohm * tcr_per_k * g_self[_bidx(g_self, n)]
        )  # ohm/W - resistance rise per watt within the tick
        compliance_voltage_v = v_comp[_bidx(v_comp, n)]
        flags_n = 0
        if law == LAW_CURRENT:
            heater_current_a = drive_fraction * i_fs[_bidx(i_fs, n)]
            electrothermal_loop_gain = d_resistance_d_power_ohm_per_w * heater_current_a * heater_current_a
            at_compliance = False
            runaway_without_compliance_limit = False
            if electrothermal_loop_gain >= 1.0:
                flags_n |= FLAG_RUNAWAY
                if math.isinf(compliance_voltage_v):
                    # no compliance limit - the implicit solve has no finite root within the tick.
                    # Fall back to the explicit (lagged) power at the start-of-tick resistance, so the runaway shows as growth over the next ticks instead of a NaN that would poison the thermal state.
                    runaway_without_compliance_limit = True
                else:
                    at_compliance = True
                heater_power_w = heater_current_a * heater_current_a * resistance_before_own_heat_ohm
                heater_resistance_ohm = resistance_before_own_heat_ohm
            else:
                heater_power_w = (
                    heater_current_a
                    * heater_current_a
                    * resistance_before_own_heat_ohm
                    / (1.0 - electrothermal_loop_gain)
                )
                heater_resistance_ohm = (
                    resistance_before_own_heat_ohm + d_resistance_d_power_ohm_per_w * heater_power_w
                )
                if heater_current_a * heater_resistance_ohm > compliance_voltage_v:
                    at_compliance = True
            if runaway_without_compliance_limit:
                heater_voltage_v = heater_current_a * heater_resistance_ohm
            elif at_compliance:  # the current source saturates at v_comp
                flags_n |= FLAG_COMPLIANCE
                heater_power_w, runaway = _power_from_v2(
                    compliance_voltage_v * compliance_voltage_v,
                    resistance_before_own_heat_ohm,
                    d_resistance_d_power_ohm_per_w,
                )
                if runaway:
                    flags_n |= FLAG_RUNAWAY
                heater_resistance_ohm = (
                    resistance_before_own_heat_ohm + d_resistance_d_power_ohm_per_w * heater_power_w
                )
                heater_voltage_v = compliance_voltage_v
                heater_current_a = compliance_voltage_v / heater_resistance_ohm
            else:
                heater_voltage_v = heater_current_a * heater_resistance_ohm
        elif law == LAW_POWER:
            heater_power_w = drive_fraction * p_fs[_bidx(p_fs, n)]
            heater_resistance_ohm = (
                resistance_before_own_heat_ohm + d_resistance_d_power_ohm_per_w * heater_power_w
            )
            heater_voltage_v = math.sqrt(heater_power_w * heater_resistance_ohm)
            if heater_voltage_v > compliance_voltage_v:
                flags_n |= FLAG_COMPLIANCE
                heater_power_w, runaway = _power_from_v2(
                    compliance_voltage_v * compliance_voltage_v,
                    resistance_before_own_heat_ohm,
                    d_resistance_d_power_ohm_per_w,
                )
                if runaway:
                    flags_n |= FLAG_RUNAWAY
                heater_resistance_ohm = (
                    resistance_before_own_heat_ohm + d_resistance_d_power_ohm_per_w * heater_power_w
                )
                heater_voltage_v = compliance_voltage_v
            heater_current_a = heater_voltage_v / heater_resistance_ohm
        else:  # voltage and dac_pwm
            full_scale_voltage_v = v_fs[_bidx(v_fs, n)]
            if law == LAW_DAC_PWM:
                if drive_fraction > 1.0:
                    drive_fraction = 1.0
                mean_squared_voltage_v2 = (
                    drive_fraction * full_scale_voltage_v * full_scale_voltage_v
                )  # <V^2> - u is already a power fraction
            else:
                mean_squared_voltage_v2 = (drive_fraction * full_scale_voltage_v) * (
                    drive_fraction * full_scale_voltage_v
                )
            if mean_squared_voltage_v2 > compliance_voltage_v * compliance_voltage_v:
                flags_n |= FLAG_COMPLIANCE
                mean_squared_voltage_v2 = compliance_voltage_v * compliance_voltage_v
            heater_power_w, runaway = _power_from_v2(
                mean_squared_voltage_v2, resistance_before_own_heat_ohm, d_resistance_d_power_ohm_per_w
            )
            if runaway:
                flags_n |= FLAG_RUNAWAY
            heater_resistance_ohm = (
                resistance_before_own_heat_ohm + d_resistance_d_power_ohm_per_w * heater_power_w
            )
            heater_voltage_v = math.sqrt(mean_squared_voltage_v2)
            heater_current_a = heater_voltage_v / heater_resistance_ohm
        out_p[n] = heater_power_w
        out_v[n] = heater_voltage_v
        out_i[n] = heater_current_a
        out_r[n] = heater_resistance_ohm
        out_flags[n] = out_flags[n] | flags_n

@njit(cache=True, _nrt=False)
def supply_limit_row(p, v, i, p_max, i_max, flags):
    total_power_w = 0.0
    total_current_a = 0.0
    for n in range(p.shape[0]):
        total_power_w += p[n]
        total_current_a += i[n]
    supply_scale = 1.0
    if total_power_w > p_max and total_power_w > 0.0:
        supply_scale = min(supply_scale, math.sqrt(p_max / total_power_w))
    if total_current_a > i_max and total_current_a > 0.0:
        supply_scale = min(supply_scale, i_max / total_current_a)
    if supply_scale < 1.0:
        for n in range(p.shape[0]):
            p[n] *= supply_scale * supply_scale
            v[n] *= supply_scale
            i[n] *= supply_scale
            flags[n] = flags[n] | FLAG_SUPPLY
    return supply_scale

@njit(cache=True, _nrt=False)
def nrz_levels_row(v_bias, swing_vpp, mode, v_floor, v_ceil, out_lo, out_hi, out_flags):
    for n in range(out_lo.shape[0]):
        bias_v = v_bias[_bidx(v_bias, n)]
        swing_v = swing_vpp[_bidx(swing_vpp, n)]
        if mode == LEVELS_ONE_SIDED:
            low_voltage_v = bias_v - swing_v
            high_voltage_v = bias_v
        else:
            low_voltage_v = bias_v - 0.5 * swing_v
            high_voltage_v = bias_v + 0.5 * swing_v
        level_flags = 0
        if low_voltage_v < v_floor:
            low_voltage_v = v_floor
            level_flags |= FLAG_FORWARD_CLIP
        if high_voltage_v < v_floor:
            high_voltage_v = v_floor
            level_flags |= FLAG_FORWARD_CLIP
        if high_voltage_v > v_ceil:
            high_voltage_v = v_ceil
            level_flags |= FLAG_GRID_CLIP
        if low_voltage_v > v_ceil:
            low_voltage_v = v_ceil
            level_flags |= FLAG_GRID_CLIP
        out_lo[n] = low_voltage_v
        out_hi[n] = high_voltage_v
        out_flags[n] = out_flags[n] | level_flags

@njit(cache=True)
def nrz_levels(v_bias, swing_vpp, mode, v_floor, v_ceil, out_lo, out_hi, out_flags):
    for b in range(out_lo.shape[0]):
        nrz_levels_row(v_bias[_bidx(v_bias, b)], swing_vpp[_bidx(swing_vpp, b)], mode, v_floor, v_ceil,
                       out_lo[b], out_hi[b], out_flags[b])

@njit(cache=True, inline="always")
def grid_index(x, grid):
    g = grid.shape[0]
    span = grid[_as_unsigned_array_index(g - 1)] - grid[0]
    j = np.int64(0)
    if span > 0.0:
        u = (x - grid[0]) * ((g - 1) / span)
        if u > 0.0:
            j = np.int64(u) if u < g - 2 else np.int64(g - 2)
    # j >= 0 here, so the unsigned casts below are safe (see _as_unsigned_array_index)
    if grid[_as_unsigned_array_index(j)] < x and x <= grid[_as_unsigned_array_index(j + 1)]:
        return j
    if j + 2 < g and grid[_as_unsigned_array_index(j + 1)] < x and x <= grid[_as_unsigned_array_index(j + 2)]:
        return j + 1
    if j >= 1 and grid[_as_unsigned_array_index(j - 1)] < x and x <= grid[_as_unsigned_array_index(j)]:
        return j - 1
    return np.int64(np.searchsorted(grid, x) - 1)

@njit(cache=True, _nrt=False)
def _interp_lin(x, grid, col):
    g = grid.shape[0]
    if x != x:
        return np.nan, True
    if x <= grid[0]:
        return col[0], x < grid[0]
    if x >= grid[g - 1]:
        return col[g - 1], x > grid[g - 1]
    j = grid_index(x, grid)
    gj = grid[_as_unsigned_array_index(j)]
    w = (x - gj) / (grid[_as_unsigned_array_index(j + 1)] - gj)
    cj = col[_as_unsigned_array_index(j)]
    return cj + w * (col[_as_unsigned_array_index(j + 1)] - cj), False

@njit(cache=True, inline="always")
def _interp_bracket(x, grid):
    g = grid.shape[0]
    if x != x:
        return np.int64(-1), 0.0, True
    if x <= grid[0]:
        return np.int64(-1), 0.0, x < grid[0]
    if x >= grid[g - 1]:
        return np.int64(-1), 0.0, x > grid[g - 1]
    j = grid_index(x, grid)
    gj = grid[_as_unsigned_array_index(j)]
    return j, (x - gj) / (grid[_as_unsigned_array_index(j + 1)] - gj), False

@njit(cache=True, inline="always")
def _interp_at(x, j, w, grid, col):
    if x != x:
        return np.nan
    if j < 0:
        return col[0] if x <= grid[0] else col[grid.shape[0] - 1]
    cj = col[_as_unsigned_array_index(j)]
    return cj + w * (col[_as_unsigned_array_index(j + 1)] - cj)

@njit(cache=True)
def junction_eval(v, grid, dneff_tab, alpha_tab, c_tab, rs_tab, fill, length_m,
                  out_dneff, out_alpha, out_c_f, out_rs_ohm, out_flags):
    for b in range(out_dneff.shape[0]):
        junction_eval_row(v[_bidx(v, b)], grid, dneff_tab[_bidx(dneff_tab, b)], alpha_tab[_bidx(alpha_tab, b)],
                          c_tab[_bidx(c_tab, b)], rs_tab[_bidx(rs_tab, b)], fill[_bidx(fill, b)],
                          length_m[_bidx(length_m, b)],
                          out_dneff[b], out_alpha[b], out_c_f[b], out_rs_ohm[b], out_flags[b])

@njit(cache=True)
def junction_swing_capacitance_row(v_lo, v_hi, grid, c_col, fill, length_m, out_c_eff):
    for n in range(out_c_eff.shape[0]):
        lo = v_lo[_bidx(v_lo, n)]
        hi = v_hi[_bidx(v_hi, n)]
        fl = fill[_bidx(fill, n)] * length_m[_bidx(length_m, n)]
        if abs(hi - lo) > 1e-9:
            out_c_eff[n] = fl * _integ_lin(lo, hi, grid, c_col) / (hi - lo)
        else:
            cp, _ = _interp_lin(0.5 * (lo + hi), grid, c_col)
            out_c_eff[n] = fl * cp

@njit(cache=True)
def junction_swing_capacitance(v_lo, v_hi, grid, c_tab, fill, length_m, out_c_eff):
    for b in range(out_c_eff.shape[0]):
        junction_swing_capacitance_row(v_lo[_bidx(v_lo, b)], v_hi[_bidx(v_hi, b)], grid, c_tab[_bidx(c_tab, b)],
                                       fill[_bidx(fill, b)], length_m[_bidx(length_m, b)], out_c_eff[b])

@njit(cache=True)
def data_activity_heat(c_eff, swing_vpp, bitrate_hz, transition_density, enable, r_s, r_drv,
                       p_static_w, e_tr_j, add_load_share, out_pj, out_pd):
    for b in range(out_pj.shape[0]):
        data_activity_heat_row(c_eff[_bidx(c_eff, b)], swing_vpp[_bidx(swing_vpp, b)], bitrate_hz,
                               transition_density[_bidx(transition_density, b)], enable[_bidx(enable, b)],
                               r_s[_bidx(r_s, b)], r_drv[_bidx(r_drv, b)], p_static_w[_bidx(p_static_w, b)],
                               e_tr_j[_bidx(e_tr_j, b)], add_load_share, out_pj[b], out_pd[b])

def _param_bn(x, B, N, name):
    parameter_array = np.asarray(x, dtype=np.float64)
    if parameter_array.ndim == 0:
        parameter_array = parameter_array.reshape(1, 1)
    elif parameter_array.ndim == 1:
        parameter_array = (
            parameter_array.reshape(1, -1) if parameter_array.shape[0] == N else parameter_array.reshape(-1, 1)
        )
    if parameter_array.ndim != 2 or parameter_array.shape[0] not in (1, B) or parameter_array.shape[1] not in (1, N):
        raise ValueError(f"{name}: shape {np.shape(x)} does not broadcast to (B={B}, N={N})")
    return np.ascontiguousarray(parameter_array)

def _param_b(x, B, name, dtype=np.float64):
    parameter_array = np.atleast_1d(np.asarray(x, dtype=dtype))
    if parameter_array.ndim != 1 or parameter_array.shape[0] not in (1, B):
        raise ValueError(f"{name}: shape {np.shape(x)} is not scalar or (B={B},)")
    return np.ascontiguousarray(parameter_array)

def _whole_ticks(seconds, dt_s, name):
    latencies_s = np.atleast_1d(np.asarray(seconds, dtype=np.float64))
    return np.array([seconds_to_ticks(float(x), dt_s, name) for x in latencies_s.reshape(-1)],
        dtype=np.int64).reshape(latencies_s.shape)

def _update_period_ticks(rate_hz, dt_s, name):
    f = float(rate_hz)
    if math.isinf(f) and f > 0:
        return 1
    return rate_to_period_ticks(f, dt_s, name)

def _check_full_scales(law_codes, B, N, v_fs, i_fs, p_fs):
    need = {LAW_VOLTAGE: ("v_full_scale_v", v_fs), LAW_DAC_PWM: ("v_full_scale_v", v_fs),
            LAW_CURRENT: ("i_full_scale_a", i_fs), LAW_POWER: ("p_full_scale_w", p_fs)}
    for b in range(B):
        lc = int(law_codes[min(b, law_codes.shape[0] - 1)])
        name, arr = need[lc]
        row = arr[min(b, arr.shape[0] - 1)]
        if not np.all(np.isfinite(row) & (row > 0)):
            law_name = {v: k for k, v in DRIVER_LAWS.items()}[lc]
            raise ValueError(f"driver law {law_name!r} of world {b} needs a finite, positive {name} (got {row})")

def _bit_err_param(bit_err_lsb, B, N, n_bits, name):
    if bit_err_lsb is None:
        return np.zeros((1, 1, max(n_bits, 1)))
    a = np.asarray(bit_err_lsb, dtype=np.float64)
    while a.ndim < 3:
        a = a[None]
    if a.shape[0] not in (1, B) or a.shape[1] not in (1, N) or a.shape[2] < n_bits:
        raise ValueError(f"{name}: shape {a.shape} must be (1|B, 1|N, >= {n_bits})")
    return np.ascontiguousarray(a)

@property
def code_full_scale(self) -> int:
    return (1 << self.bits) - 1

def fs(x):
    x = np.asarray(x, dtype=float).reshape(-1, 1)
    return np.where(np.isfinite(x), x, np.inf)

@property
def applied_codes(self) -> np.ndarray:
    return self.reg

@property
def code_max(self) -> int:
    return (1 << self.bits) - 1

@property
def lsb_v(self) -> np.ndarray:
    return (self.v_max_v - self.v_min_v) / self.code_max

def code_for_voltage(self, v) -> np.ndarray:
    nearest_codes = np.rint((np.asarray(v, dtype=np.float64) - self.v_min_v) / self.lsb_v)
    return np.clip(nearest_codes, 0, self.code_max).astype(np.int64)

@property
def applied_codes(self) -> np.ndarray:
    return self.reg

def __post_init__(self):
    g = np.ascontiguousarray(np.asarray(self.v_reverse_v, dtype=np.float64))
    if g.ndim != 1 or g.size < 2 or np.any(np.diff(g) <= 0):
        raise ValueError("v_reverse_v must be a strictly increasing 1-D grid")
    self.v_reverse_v = g

    # one table column as (Bt, G) - a scalar is held over the grid.
    def col(x, name):
        a = np.asarray(x, dtype=np.float64)
        if a.ndim == 0:
            a = np.full(g.shape, float(a))
        a = np.atleast_2d(a)
        if a.shape[1] != g.size:
            raise ValueError(f"{name}: last axis {a.shape[1]} != grid size {g.size}")
        return np.ascontiguousarray(a)

    self.dneff = col(self.dneff, "dneff")
    self.alpha_fca_per_m = col(self.alpha_fca_per_m, "alpha_fca_per_m")
    self.capacitance_f_per_m = col(self.capacitance_f_per_m, "capacitance_f_per_m")
    self.r_series_ohm_m = col(self.r_series_ohm_m, "r_series_ohm_m")
    for name in ("dneff", "alpha_fca_per_m", "capacitance_f_per_m", "r_series_ohm_m"):
        if not np.all(np.isfinite(getattr(self, name))):
            raise ValueError(f"{name}: non-finite values")
    if np.any(self.alpha_fca_per_m < 0) or np.any(self.capacitance_f_per_m <= 0) or np.any(self.r_series_ohm_m < 0):
        raise ValueError("need alpha_fca_per_m >= 0 (absolute), capacitance_f_per_m > 0, r_series_ohm_m >= 0")
    if g[0] <= 0.0 <= g[-1]:
        # the schema defines dneff relative to 0 V - an absolute n_eff (~2.5) or an offset table fails here
        d0 = np.array([np.interp(0.0, g, row) for row in self.dneff])
        scale = np.max(np.abs(self.dneff), axis=1)
        if np.any(np.abs(d0) > 1e-2 * scale + 1e-12):
            raise ValueError(f"dneff must be relative to 0 V (ARCHITECTURE 5.4); dneff(0 V) = {d0}")

def col(x, name):
    a = np.asarray(x, dtype=np.float64)
    if a.ndim == 0:
        a = np.full(g.shape, float(a))
    a = np.atleast_2d(a)
    if a.shape[1] != g.size:
        raise ValueError(f"{name}: last axis {a.shape[1]} != grid size {g.size}")
    return np.ascontiguousarray(a)

def load_junction_table(path) -> JunctionTable:
    d = json.loads(Path(path).read_text())
    schema = d.get("schema")
    if schema is not None and not str(schema).startswith("junction/"):
        raise ValueError(f"{path}: schema {schema!r} is not junction/*")
    t = d.get("table", d)
    if "r_series_ohm_m" in t:
        rs = t["r_series_ohm_m"]
    elif "r_series_ohm" in t:
        length = t.get("junction_length_m", d.get("junction_length_m"))
        if length is None:
            raise ValueError(f"{path}: r_series_ohm (ohm) needs junction_length_m to convert to r_series_ohm_m "
                             "(ohm*m); or write r_series_ohm_m directly")
        rs = np.asarray(t["r_series_ohm"], dtype=np.float64) * float(length)
    else:
        raise ValueError(f"{path}: no r_series_ohm_m")
    jt = JunctionTable(t["v_reverse_v"], t["dneff"], t["alpha_fca_per_m"], t["capacitance_f_per_m"], rs,
                       method=str(d.get("method", t.get("method", "unknown"))), meta={"path": str(path)})
    if jt.v_reverse_v[0] > JUNCTION_GRID_V_MIN + 1e-9 or jt.v_reverse_v[-1] < JUNCTION_GRID_V_MAX - 1e-9:
        warnings.warn(f"{path}: junction grid {jt.v_reverse_v[0]}..{jt.v_reverse_v[-1]} V does not span "
                      f"{JUNCTION_GRID_V_MIN}..{JUNCTION_GRID_V_MAX} V (ARCHITECTURE 5.4)", stacklevel=2)
    return jt

@njit(cache=True)
def depletion_shift_m(v, shift_amp_m, v_bi, m):
    x = v + v_bi
    if x < 1e-6:
        x = 1e-6
    return shift_amp_m * (x ** m - v_bi ** m)

def junction_efficiency_m_per_v(table: JunctionTable, v, fill, lambda_m: float, n_g: float, row: int = 0,
                                dv: float = 1e-3):
    v = np.asarray(v, dtype=np.float64)
    hi = np.interp(v + dv, table.v_reverse_v, table.dneff[row])
    lo = np.interp(v - dv, table.v_reverse_v, table.dneff[row])
    return lambda_m / n_g * fill * (hi - lo) / (2 * dv)

def junction_dqi_dv_frac_per_v(table: JunctionTable, v, fill, alpha_i_total_per_m, row: int = 0,
                               dv: float = 1e-3):
    v = np.asarray(v, dtype=np.float64)
    hi = np.interp(v + dv, table.v_reverse_v, table.alpha_fca_per_m[row])
    lo = np.interp(v - dv, table.v_reverse_v, table.alpha_fca_per_m[row])
    return -fill * (hi - lo) / (2 * dv) / np.asarray(alpha_i_total_per_m, dtype=np.float64)

def heater_gain_w_per_code(code, h: int = 1, **kw):
    c = np.asarray(code, dtype=np.int64)
    bits = kw.get("bits", 16)
    hi = np.minimum(c + h, (1 << bits) - 1)
    lo = np.maximum(c - h, 0)
    return (heater_steady_state(hi, **kw)["p_w"] - heater_steady_state(lo, **kw)["p_w"]) / (hi - lo)

def electrothermal_loop_gain(law, p_w, tcr_per_k, r_th_heater_k_per_w, t_heater_minus_ref_k=None):
    law_c = DRIVER_LAWS[law] if isinstance(law, str) else int(law)
    p = np.asarray(p_w, dtype=np.float64)
    a = np.asarray(tcr_per_k, dtype=np.float64)
    rth = np.asarray(r_th_heater_k_per_w, dtype=np.float64)
    dth = rth * p if t_heater_minus_ref_k is None else np.asarray(t_heater_minus_ref_k, dtype=np.float64)
    mag = a * rth * p / (1.0 + a * dth)
    if law_c == LAW_CURRENT:
        return mag
    if law_c == LAW_POWER:
        return np.zeros_like(mag)
    return -mag

def compliance_headroom_v(i_a, r_cold_ohm, tcr_per_k, t_heater_minus_ref_k, compliance_v):
    r = np.asarray(r_cold_ohm, float) * (1.0 + np.asarray(tcr_per_k, float) * np.asarray(t_heater_minus_ref_k, float))
    return np.asarray(compliance_v, float) - np.asarray(i_a, float) * r

def dac_bit_errors_from_spec(dnl_sigma_lsb: float, n_bits: int, z) -> np.ndarray:
    z = np.asarray(z, dtype=np.float64)
    if z.shape[-1] != n_bits:
        raise ValueError("z must end in an axis of length n_bits")
    su = dnl_sigma_lsb / math.sqrt((1 << n_bits) - 1)
    return z * su * np.sqrt(2.0 ** np.arange(n_bits))

@classmethod
def from_spec(cls, spec) -> "ChannelMaps":
    layout = spec.layout
    temperature_channel_indices = {ts.channel: i for i, ts in enumerate(spec.temp_sensors)}
    sensor_rows = []
    for f in layout.obs:
        new_field = layout.new_field(f.name)
        if f.name in SRC_NAMES:
            source, aux = SRC_NAMES[f.name], 0
        elif f.name in temperature_channel_indices:
            source, aux = SRC_TEMP, temperature_channel_indices[f.name]
        else:
            raise ValueError(f"sensor channel {f.name!r} has no plant source in mrm.plant.io (optional channels "
                             "such as the reference tap need an io entry first)")
        sensor_rows.append((source, f.offset, f.size, new_field.offset, new_field.size, aux))
    actuator_rows = []
    initial_codes = np.zeros(layout.act_size, np.int64)
    for f in layout.act:
        channel = spec.channels[f.name]
        if f.name not in DST_NAMES:
            raise ValueError(f"actuator channel {f.name!r} has no plant destination in mrm.plant.io")
        actuator_rows.append((DST_NAMES[f.name], f.offset, f.size, int(channel.min), int(channel.max),
                      int(tuple(channel.shape[:2]) == ("B", "N") and len(channel.shape) == 2)))
        initial_codes[f.offset:f.offset + f.size] = int(channel.init)
    return cls(obs_map=np.array(sensor_rows, np.int64).reshape(-1, 6), act_map=np.array(actuator_rows,
        np.int64).reshape(-1, 6),
               obs_size=int(layout.obs_size), act_size=int(layout.act_size), act_init=initial_codes,
               m=int(spec.samples_per_step))

@njit(cache=True)
def pack_obs_row(obs, obs_map, tick, active_ring, mon_samples, mon_ticks, mon_count, mon_latest, mon_valid, mon_over,
                 mon_new, temp_latest, temp_new, rb_v, rb_i, rb_new, ones, bits, bs_above, bs_new, err_latest,
                 err_valid, heater_reg, bias_reg):
    obs[OBS_TICK] = tick
    obs[OBS_ACTIVE_RING] = active_ring
    n_rings = mon_count.shape[0]
    samples_per_ring = mon_samples.shape[1]
    for i in range(obs_map.shape[0]):
        source = obs_map[i, OM_SRC]
        value_offset = obs_map[i, OM_VAL_OFFSET]
        value_size = obs_map[i, OM_VAL_SIZE]
        new_offset = obs_map[i, OM_NEW_OFFSET]
        new_size = obs_map[i, OM_NEW_SIZE]
        aux = obs_map[i, OM_AUX]
        if source == SRC_MON_SAMPLES or source == SRC_MON_TICKS:
            for n in range(n_rings):
                for j in range(samples_per_ring):
                    obs[value_offset + n * samples_per_ring + j] = mon_samples[n,
                        j] if source == SRC_MON_SAMPLES else mon_ticks[n, j]
                obs[new_offset + n] = 1 if mon_new[n] else 0
        elif source == SRC_TEMP:
            obs[value_offset] = temp_latest[aux]
            obs[new_offset] = 1 if temp_new[aux] else 0
        else:                                   # one value and one delivery flag per element
            for n in range(value_size):
                if source == SRC_MON_COUNT:
                    value, is_new = mon_count[n], 1
                elif source == SRC_MON_LATEST:
                    value, is_new = mon_latest[n], 1 if mon_new[n] else 0
                elif source == SRC_MON_VALID:
                    value, is_new = 1 if mon_valid[n] else 0, 1
                elif source == SRC_ADC_OVER:
                    value, is_new = 1 if mon_over[n] else 0, 1
                elif source == SRC_RB_V:
                    value, is_new = rb_v[n], 1 if rb_new[n] else 0
                elif source == SRC_RB_I:
                    value, is_new = rb_i[n], 1 if rb_new[n] else 0
                elif source == SRC_ONES:
                    value, is_new = ones[n], 1
                elif source == SRC_BITS:
                    value, is_new = bits[n], 1
                elif source == SRC_BITSTAT:
                    value, is_new = bs_above[n], 1 if bs_new else 0
                elif source == SRC_ERR:
                    value, is_new = err_latest[n], 1 if err_valid[n] else 0
                elif source == SRC_ERR_VALID:
                    value, is_new = 1 if err_valid[n] else 0, 1
                elif source == SRC_HEATER_APPLIED:
                    value, is_new = heater_reg[n], 1
                else:
                    value, is_new = bias_reg[n], 1
                obs[value_offset + n] = value
                if n < new_size:
                    obs[new_offset + n] = is_new

@njit(cache=True)
def clip_act_row(act, act_map, sat):
    clipped_count = 0
    for i in range(act_map.shape[0]):
        offset = act_map[i, AM_OFFSET]
        code_min = act_map[i, AM_MIN]
        code_max = act_map[i, AM_MAX]
        for j in range(act_map[i, AM_SIZE]):
            command_code = act[offset + j]
            if command_code < code_min:
                act[offset + j] = code_min
                sat[offset + j] += 1
                clipped_count += 1
            elif command_code > code_max:
                act[offset + j] = code_max
                sat[offset + j] += 1
                clipped_count += 1
    return clipped_count

@njit(cache=True)
def pipe_push_row(vals, ticks, meta, act, latch_tick):
    capacity = vals.shape[0]
    if meta[1] >= capacity:
        return False
    tail = (meta[0] + meta[1]) % capacity
    for j in range(act.shape[0]):
        vals[tail, j] = act[j]
    ticks[tail] = latch_tick
    meta[1] += 1
    return True

@njit(cache=True)
def pipe_pop_row(vals, ticks, meta, now, out):
    command_ready = False
    capacity = vals.shape[0]
    while meta[1] > 0:
        head = meta[0]
        if ticks[head] > now:
            break
        for j in range(out.shape[0]):
            out[j] = vals[head, j]
        meta[0] = (head + 1) % capacity
        meta[1] -= 1
        command_ready = True
    return command_ready

@njit(cache=True)
def apply_act_row(act, act_map, cmd_heater, valid_heater, cmd_bias, valid_bias, assign, bs_thr, pga, tune):
    for i in range(act_map.shape[0]):
        destination = act_map[i, AM_DST]
        offset = act_map[i, AM_OFFSET]
        for j in range(act_map[i, AM_SIZE]):
            command_code = act[offset + j]
            if destination == DST_HEATER:
                cmd_heater[j] = command_code
                valid_heater[j] = True
            elif destination == DST_BIAS:
                cmd_bias[j] = command_code
                valid_bias[j] = True
            elif destination == DST_ASSIGN:
                assign[j] = command_code
            elif destination == DST_BS_THR:
                bs_thr[j] = command_code
            elif destination == DST_PGA:
                pga[j] = command_code
            else:
                tune[j] = command_code

def push(self, edge_tick: int, act: np.ndarray) -> None:
    act = np.asarray(act, np.int64).reshape(self.B, -1)
    for b in range(self.B):
        if not pipe_push_row(self.vals[b], self.ticks[b], self.meta[b], act[b],
                             np.int64(edge_tick + self.latency_ticks)):
            raise RuntimeError("controller pipeline overflow (more edges in flight than its capacity)")

def __post_init__(self):
    f = np.asarray(self.freq_hz, dtype=np.float64).reshape(-1)
    L = f.size
    for name in ("direction", "source_laser", "pol"):
        a = np.asarray(getattr(self, name), dtype=np.int64).reshape(-1)
        if a.size != L:
            raise ValueError(f"LineTable.{name} has {a.size} entries for {L} lines")
        object.__setattr__(self, name, a)
    object.__setattr__(self, "freq_hz", f)
    if L < 1 or not np.all(np.isfinite(f) & (f > 0)):
        raise ValueError("LineTable needs at least one positive finite frequency")
    if np.any((self.direction < 0) | (self.direction > 1)) or np.any((self.pol < 0) | (self.pol > 1)):
        raise ValueError("direction and pol codes must be 0 or 1")
    if np.any(self.source_laser < 0) or np.any(self.source_laser >= len(self.laser_names)):
        raise ValueError("source_laser indexes outside laser_names")
    object.__setattr__(self, "laser_names", tuple(str(x) for x in self.laser_names))

@property
def n_lines(self) -> int:
    return int(self.freq_hz.size)

@property
def n_lasers(self) -> int:
    return len(self.laser_names)

@property
def wavelength_m(self) -> np.ndarray:
    return C0 / self.freq_hz

def select(self, direction: str) -> "LineTable":
    direction_mask = self.direction == DIRECTIONS[direction]
    used_modules = sorted(set(self.source_laser[direction_mask].tolist()))
    module_indices = {old: i for i, old in enumerate(used_modules)}
    return LineTable(self.freq_hz[direction_mask], self.direction[direction_mask],
        np.array([module_indices[s] for s in self.source_laser[direction_mask]]),
                     self.pol[direction_mask], tuple(self.laser_names[i] for i in used_modules))

def records(self) -> list[dict]:
    inv_d = {v: k for k, v in DIRECTIONS.items()}
    inv_p = {v: k for k, v in POLS.items()}
    return [dict(freq_thz=float(f) / 1e12, direction=inv_d[int(d)], source_laser=self.laser_names[int(s)],
                 pol=inv_p[int(p)]) for f, d, s, p in zip(self.freq_hz, self.direction, self.source_laser,
                                                           self.pol)]

@classmethod
def from_records(cls, rows) -> "LineTable":
    names: list[str] = []
    frequencies_hz, directions, source_indices, polarizations = [], [], [], []
    for record in rows:
        record = {k: (v.get("value") if isinstance(v, dict) and "value" in v else v) for k,
            v in dict(record).items()}
        frequencies_hz.append(float(record["freq_hz"]) if "freq_hz" in record else float(record["freq_thz"]) * 1e12)
        directions.append(DIRECTIONS[str(record.get("direction", "tx"))])
        source_name = str(record.get("source_laser") or "laser0")
        if source_name not in names:
            names.append(source_name)
        source_indices.append(names.index(source_name))
        polarizations.append(POLS[str(record.get("pol", "te"))])
    return cls(np.array(frequencies_hz), np.array(directions), np.array(source_indices),
        np.array(polarizations), tuple(names) or ("laser0",))

@classmethod
def from_plant_params(cls, pp, source_laser: dict | None = None) -> "LineTable":
    las = pp.laser
    src = {"tx": "local", "rx": "remote"}
    src.update(source_laser or {})
    freqs = np.asarray(las.line_freq_grid_hz).reshape(-1)
    given = tuple(getattr(las, "source_laser", ()) or ())
    pols = tuple(getattr(las, "pol", ()) or ())
    rows = [dict(freq_hz=float(f), direction=str(d),
                 source_laser=(given[i] if i < len(given) and given[i] else src[str(d)]),
                 pol=(pols[i] if i < len(pols) and pols[i] else "te"))
            for i, (f, d) in enumerate(zip(freqs, las.direction))]
    return cls.from_records(rows)

def grid_line_table(center_hz: float, spacing_hz: float, n_lines: int, *, direction: str = "tx",
                    laser: str = "laser0") -> LineTable:
    frequencies_hz = center_hz + (np.arange(int(n_lines)) - (int(n_lines) - 1) / 2.0) * spacing_hz
    return LineTable(frequencies_hz, np.full(frequencies_hz.size, DIRECTIONS[direction]),
        np.zeros(frequencies_hz.size, np.int64),
                     np.zeros(frequencies_hz.size, np.int64), (laser,))

@njit(cache=True)
def levy_bm(key, ring, slot, j, depth):
    top = np.int64(1) << depth
    if j <= 0:
        return 0.0
    if j > top:
        j = top
    a = np.int64(0)
    b = top
    wa = 0.0
    wb = math.sqrt(float(top)) * rng.normal(key, ring, 0, slot)
    h = np.int64(1)
    while b - a > 1:
        m = (a + b) >> 1
        wm = 0.5 * (wa + wb) + math.sqrt((b - a) / 4.0) * rng.normal(key, ring, h, slot)
        if j == m:
            return wm
        if j < m:
            b = m
            wb = wm
            h = 2 * h
        else:
            a = m
            wa = wm
            h = 2 * h + 1
    return wa if j == a else wb

@njit(cache=True)
def _fill_brownian_nodes(key, j, depth, n_lines, n_mod, out):
    for s in range(2):
        for i in range(n_lines + n_mod):
            out[s, i] = levy_bm(key, i, s, j, depth)

@njit(cache=True)
def laser_tick(k, dt_s, tcomp, grid_s, depth, f0, p0, f_rate, p_rate, f_rw, p_rw, rho_f, rho_p, module, n_mod,
               rin_per_hz, enable, f_offset, p_scale, tune_hz, key_drift, key_rin, cache_j, w_lo, w_hi, out_f, out_p):
    for b in range(f0.shape[0]):
        laser_tick_row(k, dt_s, tcomp, grid_s, depth, f0[b], p0[b], f_rate[b], p_rate[b], f_rw[b], p_rw[b],
                       rho_f[b], rho_p[b], module, n_mod, rin_per_hz[b], enable[b], f_offset[b], p_scale[b],
                       tune_hz[b], key_drift[b], key_rin[b], cache_j[b], w_lo[b], w_hi[b], out_f[b], out_p[b])

@njit(cache=True, parallel=True)
def laser_tick_par(k, dt_s, tcomp, grid_s, depth, f0, p0, f_rate, p_rate, f_rw, p_rw, rho_f, rho_p, module, n_mod,
                   rin_per_hz, enable, f_offset, p_scale, tune_hz, key_drift, key_rin, cache_j, w_lo, w_hi, out_f,
                   out_p):
    for b in nb.prange(f0.shape[0]):
        laser_tick_row(k, dt_s, tcomp, grid_s, depth, f0[b], p0[b], f_rate[b], p_rate[b], f_rw[b], p_rw[b],
                       rho_f[b], rho_p[b], module, n_mod, rin_per_hz[b], enable[b], f_offset[b], p_scale[b],
                       tune_hz[b], key_drift[b], key_rin[b], cache_j[b], w_lo[b], w_hi[b], out_f[b], out_p[b])

def _arr_b(x, B, name, dtype=np.float64):
    array = np.asarray(x, dtype=dtype).reshape(-1)
    if array.size == 1:
        return np.full(B, array[0], dtype=dtype)
    if array.size != B:
        raise ValueError(f"{name}: shape {np.shape(x)} is not scalar or (B={B},)")
    return array.copy()

def _arr_bl(x, B, L, name, dtype=np.float64):
    array = np.asarray(x, dtype=dtype)
    if array.ndim == 1:
        array = array.reshape(1, -1) if array.shape[0] == L else array.reshape(-1, 1)
    try:
        return np.ascontiguousarray(np.broadcast_to(array, (B, L))).copy()
    except ValueError:
        raise ValueError(f"{name}: shape {np.shape(x)} does not broadcast to (B={B}, L={L})") from None

def _keys(seeds, B, stream: int) -> np.ndarray:
    seeds = _arr_b(seeds, B, "seeds", np.int64)
    return np.array([rng.stream_key(int(s), int(stream)) for s in seeds], dtype=np.uint64)

def draw_static_error_hz(device_seeds, lines: LineTable, bound_hz: float = LASER_ACCURACY_DEMONSTRATED_HZ, *,
                         common_weight: float = 0.0, dist: str = "uniform") -> np.ndarray:
    if not 0.0 <= common_weight <= 1.0:
        raise ValueError("common_weight must be in [0, 1]")
    line_uniforms, module_uniforms = _device_uniforms(device_seeds, lines, _TAG_STATIC, 0)
    if dist == "uniform":
        line_errors, module_errors = 2.0 * line_uniforms - 1.0, 2.0 * module_uniforms - 1.0
        return bound_hz * (common_weight * module_errors[:, lines.source_laser] + (1.0 - common_weight) * line_errors)
    if dist == "normal3sigma":
        from scipy.special import ndtri
        line_errors, module_errors = ndtri(line_uniforms), ndtri(module_uniforms)
        common_variance_fraction = common_weight
        return bound_hz / 3.0 * (math.sqrt(common_variance_fraction) * module_errors[:,
            lines.source_laser] + math.sqrt(1.0 - common_variance_fraction) * line_errors)
    raise ValueError("dist must be 'uniform' or 'normal3sigma'")

def drift_from_24h_bound(bound: float, mode: str, *, device_seeds=None, lines: LineTable | None = None,
                         what: str = "freq") -> tuple[np.ndarray | float, float]:
    if mode == "none":
        return 0.0, 0.0
    if mode == "worst_linear":
        return bound / SECONDS_PER_24H, 0.0
    if mode == "random_walk":
        return 0.0, 0.5 * bound / math.sqrt(SECONDS_PER_24H)
    if mode == "linear":
        if device_seeds is None or lines is None:
            raise ValueError("mode 'linear' draws per-line rates: give device_seeds and lines")
        ul, _um = _device_uniforms(device_seeds, lines, _TAG_RATE_F if what == "freq" else _TAG_RATE_P, 0)
        return bound * (2.0 * ul - 1.0) / SECONDS_PER_24H, 0.0
    raise ValueError("mode must be one of 'none', 'linear', 'worst_linear', 'random_walk'")

@classmethod
def build(cls, B: int, dt_s: float, lines: LineTable, *, power_w, static_error_hz=0.0, f_rate_hz_per_s=0.0,
          p_rate_per_s=0.0, f_rw_hz_per_rt_s=0.0, p_rw_per_rt_s=0.0, rho_f=0.0, rho_p=0.0, rin_per_hz=0.0,
          grid_s: float = DRIFT_GRID_S_DEFAULT, depth: int = LEVY_DEPTH, tune_lsb_hz: float = 0.0
          ) -> "LaserHw":
    L = lines.n_lines
    rf = _arr_b(rho_f, B, "rho_f")
    rp = _arr_b(rho_p, B, "rho_p")
    if np.any((rf < 0) | (rf > 1)) or np.any((rp < 0) | (rp > 1)):
        raise ValueError("rho_f and rho_p must be in [0, 1]")
    rin = _arr_b(rin_per_hz, B, "rin_per_hz")
    if np.any(rin < 0):
        raise ValueError("rin_per_hz must be >= 0 (linear 1/Hz)")
    if not (grid_s > 0 and 1 <= int(depth) <= 60):
        raise ValueError("need grid_s > 0 and 1 <= depth <= 60")
    p0 = _arr_bl(power_w, B, L, "power_w")
    if np.any(p0 < 0):
        raise ValueError("power_w must be >= 0")
    return cls(B=int(B), L=L, dt_s=float(dt_s), lines=lines,
               f0_hz=lines.freq_hz[None, :] + _arr_bl(static_error_hz, B, L, "static_error_hz"), p0_w=p0,
               f_rate_hz_per_s=_arr_bl(f_rate_hz_per_s, B, L, "f_rate_hz_per_s"),
               p_rate_per_s=_arr_bl(p_rate_per_s, B, L, "p_rate_per_s"),
               f_rw_hz_per_rt_s=_arr_bl(f_rw_hz_per_rt_s, B, L, "f_rw_hz_per_rt_s"),
               p_rw_per_rt_s=_arr_bl(p_rw_per_rt_s, B, L, "p_rw_per_rt_s"), rho_f=rf, rho_p=rp, rin_per_hz=rin,
               grid_s=float(grid_s), depth=int(depth), tune_lsb_hz=float(tune_lsb_hz))

def reset(self, scenario_seeds=None, noise_seeds=None) -> None:
    B = self.hw.B
    if scenario_seeds is not None:
        self.key_drift = _keys(scenario_seeds, B, rng.Stream.LASER_DRIFT)
        if noise_seeds is None:
            noise_seeds = scenario_seeds
    if noise_seeds is not None:
        self.key_rin = _keys(noise_seeds, B, rng.Stream.LASER_RIN)
    self.cache_j[:] = -1

@njit(cache=True)
def energy_decay_rates_from_ring(
    k2_th: float,  # k2_th = K_th^2 (1) - through-coupler power fraction - type float scalar
    k2_dr: float,  # k2_dr = K_dr^2 (1) - drop-coupler power fraction - type float scalar
    a_rt: float,  # a_rt = a (1) - field amplitude retained per round trip - type float scalar
    t_rt_s: float,  # t_rt_s = T_rt (s) - round-trip group delay - type float scalar
) -> tuple[
    float,  # intrinsic_decay_rate = kappa_i (1/s) - intrinsic energy loss - type float scalar
    float,  # through_coupling_decay_rate = kappa_e (1/s) - energy leakage to the bus - type float scalar
    float,  # drop_coupling_decay_rate = kappa_d (1/s) - energy leakage to the drop guide - type float scalar
]:
    ### given a loss a, how do i model this as an exponential decay? calculate the correct constants?
    intrinsic_decay_rate = -2.0 * math.log(a_rt) / t_rt_s
    through_coupling_decay_rate = -math.log1p(-k2_th) / t_rt_s
    drop_coupling_decay_rate = -math.log1p(-k2_dr) / t_rt_s
    return (
        intrinsic_decay_rate,
        through_coupling_decay_rate,
        drop_coupling_decay_rate,
    )

@njit(cache=True)
def tcmt_backscatter_rate(
    rb: NumericValue,  # rb = r_b (1) - complex round-trip coupling - type numeric scalar or NumPy array
    t_rt_s: RealValue,  # t_rt_s = T_rt (s) - round-trip group delay - type real scalar or real NumPy array
) -> (
    NumericValue  # return = g (rad/s), with g = r_b/T_rt - complex mode-coupling rate - type numeric scalar or NumPy array
):
    return rb / t_rt_s

def tcmt_to_exact(
    kappa_i: ArrayLike,  # kappa_i = kappa_i (1/s) - intrinsic energy loss - type scalar, sequence, or NumPy array
    kappa_e: ArrayLike,  # kappa_e = kappa_e (1/s) - leakage to the bus - type scalar, sequence, or NumPy array
    kappa_d: ArrayLike,  # kappa_d = kappa_d (1/s) - leakage to the drop guide - type scalar, sequence, or NumPy array
    t_rt_s: ArrayLike,  # t_rt_s = T_rt (s) - round-trip group delay - type scalar, sequence, or NumPy array
) -> tuple[
    RealValue,  # return[0] = K_th^2 (1), with K_th^2 = 1-exp(-kappa_e*T_rt) - through-coupler power fraction - type float64 scalar or float64 ndarray, broadcast input shape
    RealValue,  # return[1] = K_dr^2 (1), with K_dr^2 = 1-exp(-kappa_d*T_rt) - drop-coupler power fraction - type float64 scalar or float64 ndarray, broadcast input shape
    RealValue,  # return[2] = a (1), with a = exp(-kappa_i*T_rt/2) - retained round-trip field amplitude - type float64 scalar or float64 ndarray, broadcast input shape
]:
    kappa_i, kappa_e, kappa_d, t_rt_s = (
        np.asarray(x, dtype=float) for x in (kappa_i, kappa_e, kappa_d, t_rt_s)
    )
    return (
        -np.expm1(-kappa_e * t_rt_s),
        -np.expm1(-kappa_d * t_rt_s),
        np.exp(-0.5 * kappa_i * t_rt_s),
    )

@njit(cache=True)
def backscatter_hz_to_round_trip_coupling(
    beta_hz: NumericValue,  # beta_hz = g/(2*pi) (Hz) - complex coupling rate - type numeric scalar or NumPy array
    fsr_hz: RealValue,  # fsr_hz = FSR (Hz) - free spectral range - type real scalar or real NumPy array
) -> (
    NumericValue  # return = r_b (1), with r_b = 2*pi*beta_hz/FSR - round-trip backscatter coupling - type numeric scalar or NumPy array
):
    return TWO_PI * beta_hz / fsr_hz

@njit(cache=True)
def phase_sensitivity_to_resonance_shift(
    t_rt_s: RealValue,  # t_rt_s = T_rt (s) - round-trip group delay - type real scalar or real NumPy array
    lam_m: RealValue,  # lam_m = lambda_L (m) - laser wavelength - type real scalar or real NumPy array
) -> (
    RealValue  # return = dphi/dlambda_r (rad/m) - phase change per resonance-wavelength shift - type real scalar or real NumPy array
):
    return TWO_PI * C0 * t_rt_s / (lam_m * lam_m)

@njit(cache=True)
def average_binary_data_levels(
    p1: RealValue,  # p1 = Pr(bit=1) (1) - fraction of ones - type real scalar or real NumPy array
    x1: NumericValue,  # x1 = x_1 (same units as x0) - value at level one - type numeric scalar or NumPy array
    x0: NumericValue,  # x0 = x_0 (same units as x1) - value at level zero - type numeric scalar or NumPy array
) -> (
    NumericValue  # return = mean(x) (same units as x1 and x0) - binary-data average - type numeric scalar or NumPy array
):
    return p1 * x1 + (1.0 - p1) * x0

@njit(cache=True)
def _wrap_order_index(
    order_index: int,  # order_index = n (1) - signed absolute resonance order - type int scalar
    order_count: int,  # order_count = M_b (1) - positive number of table entries - type int scalar
) -> (
    int  # return = n mod M_b (1) - index in the repeating order table - type int scalar
):
    wrapped_index = order_index % order_count
    if wrapped_index < 0:
        wrapped_index += order_count
    return wrapped_index

@njit(cache=True)
def _squared_magnitude(
    amplitude: complex,  # amplitude = A (input amplitude units) - complex field, mode, or normalized coefficient - type complex scalar
) -> (
    float  # return = |A|^2 (squared input units) - squared amplitude magnitude - type float scalar
):
    return amplitude.real * amplitude.real + amplitude.imag * amplitude.imag

@njit(cache=True)
def _squared_magnitude_derivative(
    amplitude: complex,  # amplitude = A (input amplitude units) - complex field, mode, or normalized coefficient - type complex scalar
    d_amplitude_dphi: complex,  # d_amplitude_dphi = dA/dphi (input amplitude units/rad) - phase derivative of amplitude - type complex scalar
) -> (
    float  # return = d|A|^2/dphi (squared input units/rad) - phase derivative of squared amplitude magnitude - type float scalar
):
    return 2.0 * (amplitude.real * d_amplitude_dphi.real + amplitude.imag * d_amplitude_dphi.imag)

@njit(cache=True)
def calculate_quarter_ring_energy_per_power_and_loss_fraction(
    round_trip_field_loss_exponent: float,  # round_trip_field_loss_exponent = -ln(a) (1) - full-trip field attenuation - type float scalar
    round_trip_delay_s: float,  # round_trip_delay_s = T_rt (s) - full-trip group delay - type float scalar
) -> tuple[
    float,  # return[0] = U_segment/P_entering (J/W) - energy per entering watt - type float scalar
    float,  # return[1] = P_lost/P_entering (1) - lost power fraction - type float scalar
]:
    quarter_power_loss_exponent = 0.5 * round_trip_field_loss_exponent # sqiggle/2 = q
    quarter_ring_loss_fraction = -math.expm1(-quarter_power_loss_exponent) # loss fraction
    if quarter_power_loss_exponent > 1e-300:
        mean_quarter_power_ratio = quarter_ring_loss_fraction / quarter_power_loss_exponent
    else:
        mean_quarter_power_ratio = 1.0
    return (
        0.25 * round_trip_delay_s * mean_quarter_power_ratio,
        quarter_ring_loss_fraction,
    )

@njit(cache=True)
def _complex_reciprocal(
    value: complex,  # value = z (input units) - finite nonzero complex value - type complex scalar
) -> (
    complex  # return = 1/z (inverse input units) - complex reciprocal - type complex scalar
):
    # 1/z = conj(z)/|z|^2 - reverse the angle and invert the magnitude.
    if value == 0j:
        raise ZeroDivisionError("singular ring field calculation")
    inverse_squared_magnitude = 1.0 / (value.real * value.real + value.imag * value.imag)
    return complex(value.real * inverse_squared_magnitude, -value.imag * inverse_squared_magnitude)

def make_workspace(
    n_lines: int,  # n_lines = L (1) - number of laser lines - type int scalar
) -> tuple[
    ComplexWorkspace,  # return[0] = C_work (mixed units) - complex scratch with COMPLEX_WORKSPACE_* field units - type complex128 ndarray, capacity at least (8, L)
    RealWorkspace,  # return[1] = F_work (mixed units) - real scratch with REAL_WORKSPACE_* and RING_RESPONSE_* field units - type float64 ndarray, capacity at least (27, L)
    Float64Vector,  # return[2] = P_forward (W) - scratch for propagated per-line power - type float64 ndarray, shape (L,)
]:
    return (
        np.zeros((COMPLEX_WORKSPACE_ROW_COUNT, n_lines), np.complex128),
        np.zeros((REAL_WORKSPACE_ROW_COUNT, n_lines), np.float64),
        np.zeros(n_lines, np.float64),
    )

def make_bus_outputs(
    n_rings: int,  # n_rings = N (1) - number of rings - type int scalar
    n_lines: int,  # n_lines = L (1) - number of laser lines - type int scalar
) -> tuple[
    RingLineOutputs,  # return[0] = Y_ring,line (mixed units) - RING_LINE_OUTPUT_* powers (W), energies (J), and slope (W/rad) - type float64 ndarray, shape (16, N, L)
    RingOutputs,  # return[1] = Y_ring (mixed units) - RING_OUTPUT_* powers (W) and slope (W/m) - type float64 ndarray, shape (6, N)
    LaserLineOutputs,  # return[2] = Y_line (mixed units) - LASER_LINE_OUTPUT_* powers (W) and relative error bound (1) - type float64 ndarray, shape (3, L)
]:
    return (
        np.zeros((RING_LINE_OUTPUT_ROW_COUNT, n_rings, n_lines)),
        np.zeros((RING_OUTPUT_ROW_COUNT, n_rings)),
        np.zeros((LASER_LINE_OUTPUT_ROW_COUNT, n_lines)),
    )

@njit(cache=True, inline="always", _nrt=False)
def _validate_ring_workspace_buffers(
    line_count: int,  # line_count = L (1) - number of laser lines to evaluate - type int scalar
    complex_workspace: ComplexWorkspace,  # complex_workspace = C_work (mixed units) - two-dimensional complex128 workspace - type complex128 ndarray, capacity at least (8, L)
    real_workspace: RealWorkspace,  # real_workspace = F_work (mixed units) - two-dimensional float64 workspace - type float64 ndarray, capacity at least (27, L)
    round_trip_delay_row_s: Float64Vector,  # round_trip_delay_row_s = T_round_trip (s) - one-dimensional float64 delay row - type float64 ndarray, length at least L
    power_energy_response: RingResponseBlock,  # power_energy_response = R_opt (mixed units) - two-dimensional float64 response buffer - type float64 ndarray, capacity at least (8, L)
) -> (
    None  # return = None - incorrect dtypes, dimensions, or capacities raise an exception - type None
):
    if line_count < 0:
        raise ValueError("line_count must be nonnegative")
    if complex_workspace.ndim != 2 or real_workspace.ndim != 2 or power_energy_response.ndim != 2:
        raise ValueError("ring workspaces and response must be two-dimensional arrays")
    if round_trip_delay_row_s.ndim != 1:
        raise ValueError("round-trip delays must be a one-dimensional array")
    if not (complex_workspace.dtype == np.dtype(np.complex128)):
        raise TypeError("complex workspace must use complex128 storage")
    if not (real_workspace.dtype == np.dtype(np.float64)):
        raise TypeError("real workspace must use float64 storage")
    if not (round_trip_delay_row_s.dtype == np.dtype(np.float64)):
        raise TypeError("round-trip delays must use float64 storage")
    if not (power_energy_response.dtype == np.dtype(np.float64)):
        raise TypeError("ring response must use float64 storage")
    if complex_workspace.shape[0] < COMPLEX_WORKSPACE_ROW_COUNT or complex_workspace.shape[1] < line_count:
        raise ValueError("complex workspace has insufficient rows or laser-line capacity")
    if real_workspace.shape[0] < REAL_WORKSPACE_ROW_COUNT or real_workspace.shape[1] < line_count:
        raise ValueError("real workspace has insufficient rows or laser-line capacity")
    if power_energy_response.shape[0] < RING_RESPONSE_ROW_COUNT or power_energy_response.shape[1] < line_count:
        raise ValueError("ring response has insufficient rows or laser-line capacity")
    if round_trip_delay_row_s.shape[0] < line_count:
        raise ValueError("round-trip delay row has insufficient laser-line capacity")

@njit(cache=True, _nrt=False)
def write_bus_output_and_returned_reflection_powers(
    p_in_w: Float64Vector,  # p_in_w = P_in (W) - bus input power per laser line - type float64 ndarray, shape (L,)
    bus_order: Int64Vector,  # bus_order = b_j (1) - physical ring index at bus position j - type int64 ndarray, shape (N,)
    bus_t2: Float64Vector,  # bus_t2 = B_k (1) - power transmission of the bus segment before each ring - type float64 ndarray, shape (N,)
    bus_t2_out: float,  # bus_t2_out = B_out (1) - power transmission of the final bus segment - type float scalar
    out_rl: RingLineOutputs,  # out_rl = Y_ring,line (mixed units) - RING_LINE_OUTPUT_* powers (W), energies (J), and power slope (W/rad) - type float64 ndarray, shape (16, N, L)
    out_l: LaserLineOutputs,  # out_l = Y_line (mixed units) - LASER_LINE_OUTPUT_* powers (W) and relative error bound (1) - type float64 ndarray, shape (3, L)
) -> (
