@njit(cache=True, inline="always")
def unpack_self_heating_optical_outputs(
    packed_f: PackedOpticalValues,  # packed_f = optics_state (mixed units) - SELF_HEATING_HEADER_* blocks with SELF_HEATING_RING_ROW_*, SELF_HEATING_RING_LINE_ROW_*, and cache field units - type float64 ndarray, shape (packed_value_count,)
    packed_i: PackedOpticalIndices,  # packed_i = offsets (1) - SELF_HEATING_HEADER_* counts, flags, and packed-array positions - type int64 ndarray, shape (packed_index_count,)
) -> tuple[
    RingLineOutputs,  # ring_line_outputs = Y_ring,line (mixed units) - RING_LINE_OUTPUT_* powers (W), energies (J), and slope (W/rad) - type float64 ndarray, shape (16, N, L)
    RingOutputs,  # ring_outputs = Y_ring (mixed units) - RING_OUTPUT_* powers (W) and slope (W/m) - type float64 ndarray, shape (6, N)
    LaserLineOutputs,  # line_outputs = Y_line (mixed units) - LASER_LINE_OUTPUT_* powers (W) and relative error bound (1) - type float64 ndarray, shape (3, L)
]:
    ring_count = packed_i[SELF_HEATING_HEADER_INDEX_RING_COUNT]
    line_count = packed_i[SELF_HEATING_HEADER_INDEX_LASER_LINE_COUNT]
    block_offset = packed_i[SELF_HEATING_HEADER_INDEX_RING_LINE_OUTPUTS_OFFSET]
    ring_line_outputs = packed_f[
        block_offset : block_offset + RING_LINE_OUTPUT_ROW_COUNT * ring_count * line_count
    ].reshape((RING_LINE_OUTPUT_ROW_COUNT, ring_count, line_count))
    block_offset = packed_i[SELF_HEATING_HEADER_INDEX_RING_OUTPUTS_OFFSET]
    ring_outputs = packed_f[block_offset : block_offset + RING_OUTPUT_ROW_COUNT * ring_count].reshape(
        (RING_OUTPUT_ROW_COUNT, ring_count)
    )
    block_offset = packed_i[SELF_HEATING_HEADER_INDEX_LASER_LINE_OUTPUTS_OFFSET]
    line_outputs = packed_f[block_offset : block_offset + LASER_LINE_OUTPUT_ROW_COUNT * line_count].reshape(
        (LASER_LINE_OUTPUT_ROW_COUNT, line_count)
    )
    return (
        ring_line_outputs,
        ring_outputs,
        line_outputs,
    )

@njit(cache=True, _nrt=False)
def _set_trial_temperature_phase(
    trial_temperature_k: float,  # trial_temperature_k = T (K) - trial or accepted ring temperature - type float scalar
    ring_index: int,  # ring_index = k (1) - physical ring index - type int scalar
    bus_position: int,  # bus_position = j (1) - position in the forward bus traversal - type int scalar
    p_in: Float64Vector,  # p_in = P_in (W) - bus input power per laser line - type float64 ndarray, shape (L,)
    pcur: Float64Vector,  # pcur = P_current (W) - input power of the ring currently being solved - type float64 ndarray, shape (L,)
    ring_rows: Float64Matrix,  # ring_rows = R_ring (mixed units) - SELF_HEATING_RING_ROW_* ring parameters - type float64 ndarray, shape (5, N)
    line_rows: Float64Tensor,  # line_rows = R_line (mixed units) - SELF_HEATING_RING_LINE_ROW_* optical parameters and phase work arrays - type float64 ndarray, shape (13, N, L)
) -> (
    float  # return = dlambda_r/dT (m/K) - tuning slope at the trial temperature - type float scalar
):
    temperature_change_k = (
        trial_temperature_k - ring_rows[SELF_HEATING_RING_ROW_REFERENCE_TEMPERATURE, ring_index]
    )
    reference_tuning_slope_m_per_k = ring_rows[
        SELF_HEATING_RING_ROW_REFERENCE_THERMAL_TUNING_SLOPE, ring_index
    ]
    tuning_curvature_per_k = ring_rows[SELF_HEATING_RING_ROW_RELATIVE_THERMAL_TUNING_CURVATURE, ring_index]
    resonance_shift_m = reference_tuning_slope_m_per_k * (
        temperature_change_k + 0.5 * tuning_curvature_per_k * temperature_change_k * temperature_change_k
    )
    for line_index in range(line_rows.shape[2]):
        d_phase_d_resonance_wavelength = line_rows[
            SELF_HEATING_RING_LINE_ROW_PHASE_RESONANCE_WAVELENGTH_DERIVATIVE, ring_index, line_index
        ]
        line_rows[SELF_HEATING_RING_LINE_ROW_LEVEL_ZERO_CURRENT_ROUND_TRIP_PHASE, ring_index, line_index] = (
            line_rows[
                SELF_HEATING_RING_LINE_ROW_LEVEL_ZERO_REFERENCE_ROUND_TRIP_PHASE, ring_index, line_index
            ]
            + d_phase_d_resonance_wavelength * resonance_shift_m
        )
        line_rows[SELF_HEATING_RING_LINE_ROW_LEVEL_ONE_CURRENT_ROUND_TRIP_PHASE, ring_index, line_index] = (
            line_rows[SELF_HEATING_RING_LINE_ROW_LEVEL_ONE_REFERENCE_ROUND_TRIP_PHASE, ring_index, line_index]
            + d_phase_d_resonance_wavelength * resonance_shift_m
        )
    if bus_position == 0:  # the walk (re)starts at the first ring in bus order
        bus_segment_power_transmission = ring_rows[
            SELF_HEATING_RING_ROW_BUS_SEGMENT_POWER_TRANSMISSION, ring_index
        ]
        for line_index in range(pcur.shape[0]):
            pcur[line_index] = p_in[line_index] * bus_segment_power_transmission
    return reference_tuning_slope_m_per_k * (1.0 + tuning_curvature_per_k * temperature_change_k)

@njit(cache=True, _nrt=False)
def bound_absorbed_power_temperature_response(
    packed_f: PackedOpticalValues,  # packed_f = optics_state (mixed units) - SELF_HEATING_HEADER_* blocks with SELF_HEATING_RING_ROW_*, SELF_HEATING_RING_LINE_ROW_*, and cache field units - type float64 ndarray, shape (packed_value_count,)
    packed_i: PackedOpticalIndices,  # packed_i = offsets (1) - SELF_HEATING_HEADER_* counts, flags, and packed-array positions - type int64 ndarray, shape (packed_index_count,)
    dt_max_k: float,  # dt_max_k = Delta_T_max (K) - bound on the temperature excursion from the reference - type float scalar
    p_max: Float64Vector,  # p_max = P_max (W) - per-ring absorbed-power upper bounds - type float64 ndarray, shape (N,)
    d2p_max: Float64Vector,  # d2p_max = B_TT (W/K^2) - upper bounds on |d^2P_abs/dT^2| - type float64 ndarray, shape (N,)
    dpdt_max: Float64Vector,  # dpdt_max = B_T (W/K) - upper bounds on |dP_abs/dT| - type float64 ndarray, shape (N,)
) -> (
    None  # return = None - results are written into the output buffers - type None
):
    bound_absorbed_power_temperature_response_from_ring_parameters(packed_f, packed_i, dt_max_k, p_max, d2p_max, dpdt_max)

@njit(cache=True, _nrt=False)
def cache_matches_last_optical_evaluation(
    k: int,  # k = k (1) - physical ring index - type int scalar
    t: float,  # t = T (K) - trial or accepted ring temperature - type float scalar
    packed_f: PackedOpticalValues,  # packed_f = optics_state (mixed units) - SELF_HEATING_HEADER_* blocks with SELF_HEATING_RING_ROW_*, SELF_HEATING_RING_LINE_ROW_*, and cache field units - type float64 ndarray, shape (packed_value_count,)
    packed_i: PackedOpticalIndices,  # packed_i = offsets (1) - SELF_HEATING_HEADER_* counts, flags, and packed-array positions - type int64 ndarray, shape (packed_index_count,)
) -> (
    bool  # return = same_evaluation (1) - true when ring index and temperature match the cache - type bool scalar
):
    last_evaluation_header_offset = (
        packed_i[SELF_HEATING_HEADER_INDEX_LAST_EVALUATION_CACHE_OFFSET]
        + 2 * packed_i[SELF_HEATING_HEADER_INDEX_LASER_LINE_COUNT] * LAST_EVALUATION_CACHE_FIELD_COUNT
    )
    return (
        packed_f[last_evaluation_header_offset + LAST_EVALUATION_METADATA_FIELD_RING_INDEX] == k
        and packed_f[last_evaluation_header_offset + LAST_EVALUATION_METADATA_FIELD_TEMPERATURE] == t
    )

@njit(cache=True, _nrt=False)
def cache_clear_last_optical_evaluation(
    packed_f: PackedOpticalValues,  # packed_f = optics_state (mixed units) - SELF_HEATING_HEADER_* blocks with SELF_HEATING_RING_ROW_*, SELF_HEATING_RING_LINE_ROW_*, and cache field units - type float64 ndarray, shape (packed_value_count,)
    packed_i: PackedOpticalIndices,  # packed_i = offsets (1) - SELF_HEATING_HEADER_* counts, flags, and packed-array positions - type int64 ndarray, shape (packed_index_count,)
) -> (
    None  # return = None - results are written into the output buffers - type None
):
    packed_f[
        packed_i[SELF_HEATING_HEADER_INDEX_LAST_EVALUATION_CACHE_OFFSET]
        + 2 * packed_i[SELF_HEATING_HEADER_INDEX_LASER_LINE_COUNT] * LAST_EVALUATION_CACHE_FIELD_COUNT
        + LAST_EVALUATION_METADATA_FIELD_RING_INDEX
    ] = -1.0

@property
def p_refl(
    self: RingResponse,  # self = response (mixed units) - RingResponse fields with units defined above the class - type RingResponse record
) -> (
    RealValue  # return = P_reflected (W) - squared magnitude of the corresponding port field - type real scalar or real NumPy array
):
    return np.abs(self.refl) ** 2

@property
def p_thru(
    self: RingResponse,  # self = response (mixed units) - RingResponse fields with units defined above the class - type RingResponse record
) -> (
    RealValue  # return = P_through (W) - squared magnitude of the corresponding port field - type real scalar or real NumPy array
):
    return np.abs(self.thru) ** 2

@property
def p_drop(
    self: RingResponse,  # self = response (mixed units) - RingResponse fields with units defined above the class - type RingResponse record
) -> (
    RealValue  # return = P_drop (W) - squared magnitude of the corresponding port field - type real scalar or real NumPy array
):
    return np.abs(self.drop) ** 2

@property
def p_add_out(
    self: RingResponse,  # self = response (mixed units) - RingResponse fields with units defined above the class - type RingResponse record
) -> (
    RealValue  # return = P_add (W) - squared magnitude of the corresponding port field - type real scalar or real NumPy array
):
    return np.abs(self.add_out) ** 2

def p_in_total(
    self: RingResponse,  # self = response (mixed units) - RingResponse fields with units defined above the class - type RingResponse record
    s_in: ArrayLike,  # s_in = s_in,0 (sqrt(W)) - incoming field at port 0 - type scalar, sequence, or NumPy array
    s_thru_in: ArrayLike = 0.0,  # s_thru_in = s_in,1 (sqrt(W)) - incoming field at port 1 - type scalar, sequence, or NumPy array
    s_drop_in: ArrayLike = 0.0,  # s_drop_in = s_in,2 (sqrt(W)) - incoming field at port 2 - type scalar, sequence, or NumPy array
    s_add: ArrayLike = 0.0,  # s_add = s_in,3 (sqrt(W)) - incoming field at port 3 - type scalar, sequence, or NumPy array
) -> (
    RealValue  # return = sum_j|s_in,j|^2 (W) - total incoming power across all four ports - type real scalar or real NumPy array
):
    return sum(
        np.abs(np.asarray(incoming_amplitude)) ** 2
        for incoming_amplitude in (s_in, s_thru_in, s_drop_in, s_add)
    )

def _validate_backscatter_array(
    rb: ArrayLike | None,  # rb = r_b (1) - complex round-trip backscatter coupling by resonance order - type scalar, sequence, NumPy array, or None
) -> (
    Complex128Vector  # return = r_b[n] (1) - one-dimensional complex coupling table - type complex128 ndarray, shape (backscatter_order_count,)
):
    if rb is None:
        return np.zeros(1, dtype=np.complex128)
    rb = np.atleast_1d(np.asarray(rb, dtype=np.complex128))
    if rb.ndim != 1 or rb.size == 0:
        raise ValueError("rb must be a 1-D array of per-order round-trip backscatter values")
    if np.any(np.abs(rb) >= 2.0):
        raise ValueError("|r_b| must be < 2 (each scatterer of the pair has |rho| = |r_b|/2 < 1)")
    return rb

def _broadcast_finite_array(
    values: ArrayLike,  # values = A (input units) - numerical values to broadcast - type scalar, sequence, or NumPy array
    shape: tuple[int, ...],  # shape = dimensions (1) - target array dimensions - type tuple of integer dimensions
    name: str,  # name = label (1) - diagnostic name used in an error message - type str
    dtype: DTypeLike = np.float64,  # dtype = storage_type (1) - NumPy dtype selector - type NumPy dtype selector
) -> (
    NumericArray  # broadcast_values = A_broadcast (input units) - contiguous finite array with the requested shape - type NumPy array with the requested dtype and shape
):
    broadcast_values = np.ascontiguousarray(np.broadcast_to(np.asarray(values, dtype=dtype), shape))
    if not np.all(np.isfinite(broadcast_values)):
        raise ValueError(f"{name} has non-finite entries")
    return broadcast_values

REAL_WORKSPACE_LEVEL_ONE_RESPONSE_START_ROW = (
    REAL_WORKSPACE_LEVEL_ZERO_RESPONSE_START_ROW + RING_RESPONSE_ROW_COUNT
)

@property
def batch(
    self: PhaseParams,  # self = parameters (mixed units) - packed ring parameters and junction tables - type PhaseParams record
) -> (
    int  # return = B (1) - number of worlds - type int scalar
):
    return int(self.ring.shape[0])

def table_row(
    self: PhaseParams,  # self = parameters (mixed units) - packed ring parameters and junction tables - type PhaseParams record
    world_index: int,  # world_index = b (1) - world index - type int scalar
) -> (
    int  # return = b_table (1) - junction-table row for this world - type int scalar
):
    return world_index if self.dneff.shape[0] > 1 else 0

def per_ring(
    x: ArrayLike,  # x = values (input units) - values to broadcast across worlds and rings - type array-like with broadcast shape (B, N)
) -> (
    Float64Matrix  # return = values (input units) - values broadcast to every world and ring - type float64 ndarray, shape (B, N)
):
    return np.broadcast_to(np.asarray(x, dtype=float), (world_count, ring_count))

def calculate_bus_segment_power_transmission(
    pp: Any,  # pp = parameters (mixed units) - realized optics, thermal, junction, layout, and laser parameters - type PlantParams record
) -> (
    Float64Matrix  # return = B_segment (1) - bus power transmission before each physical ring - type float64 ndarray, shape (B, N)
):
    world_count, ring_count = int(pp.batch), int(pp.n_rings)
    order = np.asarray(pp.layout.bus_order, dtype=np.int64).reshape(-1)
    ring_spacing_m = float(getattr(pp.layout, "ring_spacing_on_bus_m", 0.0) or 0.0)
    bus_loss_per_m = np.broadcast_to(np.asarray(pp.laser.bus_loss_per_m, dtype=float).reshape(-1), (world_count,))
    power_transmission = np.ones((world_count, ring_count))
    if ring_count > 1 and ring_spacing_m > 0.0:
        segment_power_transmission = np.exp(-bus_loss_per_m * ring_spacing_m)
        if not np.all(np.isfinite(segment_power_transmission)) or np.any(segment_power_transmission > 1.0):
            raise ValueError(
                f"bus segment transmission must lie in [0, 1]: {segment_power_transmission} (bus_loss_per_m {bus_loss_per_m}, spacing "
                f"{ring_spacing_m} m)"
            )
        power_transmission[:, order[1:]] = segment_power_transmission[:, None]
    return power_transmission

@njit(cache=True, _nrt=False)
def calculate_thermal_resonance_shift_m(
    t_k: RealValue,  # t_k = T (K) - current ring temperature - type real scalar or ndarray, broadcast input shape
    t_ref_k: RealValue,  # t_ref_k = T_ref (K) - reference temperature for the shift - type real scalar or ndarray, broadcast input shape
    s0: RealValue,  # s0 = s_0 (m/K) - thermal tuning slope at T_0 - type real scalar or ndarray, broadcast input shape
    beta: RealValue,  # beta = beta (1/K) - relative curvature of the tuning slope - type real scalar or ndarray, broadcast input shape
    t0: RealValue,  # t0 = T_0 (K) - temperature at which the tuning slope equals s_0 - type real scalar or ndarray, broadcast input shape
) -> (
    RealValue  # return = Delta_lambda_r (m) - shift from the reference resonance - type real scalar or ndarray, broadcast input shape
):
    return s0 * ((t_k - t_ref_k) + 0.5 * beta * ((t_k - t0) ** 2 - (t_ref_k - t0) ** 2))

@njit(cache=True, _nrt=False)
def rebase_thermal_tuning_coefficients(
    t_prev_k: RealValue,  # t_prev_k = T_prev (K) - new expansion temperature - type real scalar or ndarray, broadcast input shape
    s0: RealValue,  # s0 = s_0 (m/K) - thermal tuning slope at T_0 - type real scalar or ndarray, broadcast input shape
    beta: RealValue,  # beta = beta (1/K) - relative curvature of the tuning slope - type real scalar or ndarray, broadcast input shape
    t0: RealValue,  # t0 = T_0 (K) - temperature at which the tuning slope equals s_0 - type real scalar or ndarray, broadcast input shape
) -> tuple[
    RealValue,  # return[0] = s_local (m/K) - tuning slope at T_prev - type real scalar or ndarray, broadcast input shape
    RealValue,  # return[1] = beta_local (1/K) - relative curvature at T_prev - type real scalar or ndarray, broadcast input shape
]:
    tuning_slope_ratio = 1.0 + beta * (t_prev_k - t0)
    return (
        s0 * tuning_slope_ratio,
        beta / tuning_slope_ratio,
    )

@njit(cache=True, inline="always")
def calculate_intrinsic_loss_temperature_factor(
    ring_parameters: Float64Matrix,  # ring_parameters = R_ring (mixed units) - packed RP_* parameters, one row per ring - type float64 ndarray, shape (N, RING_PARAMETER_COLUMN_COUNT)
    ring_index: int,  # ring_index = k (1) - physical ring index - type int scalar
    ring_temperature_k: float,  # ring_temperature_k = T_ring (K) - current ring temperature - type float scalar
    heater_temperature_k: float,  # heater_temperature_k = T_heater (K) - current heater-resistor temperature - type float scalar
) -> (
    float  # return = s_alpha (1) - temperature multiplier for intrinsic loss - type float scalar
):
    reference_temperature_k = ring_parameters[ring_index, RING_PARAMETER_COLUMN_REFERENCE_TEMPERATURE]
    return math.exp(ring_parameters[ring_index, RING_PARAMETER_COLUMN_LOG_LOSS_RING_TEMPERATURE_DERIVATIVE] * (ring_temperature_k - reference_temperature_k) + ring_parameters[ring_index, RING_PARAMETER_COLUMN_LOG_LOSS_HEATER_TEMPERATURE_DERIVATIVE] * (heater_temperature_k - reference_temperature_k))

@njit(cache=True, _nrt=False)
def evaluate_coupler_power_fractions(
    ring_parameters: Float64Matrix,  # ring_parameters = R_ring (mixed units) - packed RP_* parameters, one row per ring - type float64 ndarray, shape (N, RING_PARAMETER_COLUMN_COUNT)
    laser_wavelengths_m: Float64Vector,  # laser_wavelengths_m = lambda_L (m) - vacuum laser wavelengths - type float64 ndarray, shape (L,)
    out_through_power_coupling: Float64Matrix,  # out_through_power_coupling = K_th^2 (1) - per-pass coupler power fractions written in place - type float64 ndarray, shape (N, L)
    out_drop_power_coupling: Float64Matrix,  # out_drop_power_coupling = K_dr^2 (1) - per-pass coupler power fractions written in place - type float64 ndarray, shape (N, L)
) -> (
    None  # return = None - results are written into the output buffers - type None
):
    n_rings = ring_parameters.shape[0]
    for ring_index in range(n_rings):
        cold_resonance_m = ring_parameters[ring_index, RING_PARAMETER_COLUMN_COLD_RESONANCE_WAVELENGTH]
        for line_index in range(laser_wavelengths_m.shape[0]):
            wavelength_offset_m = laser_wavelengths_m[line_index] - cold_resonance_m
            through_power_coupling = ring_parameters[ring_index, RING_PARAMETER_COLUMN_THROUGH_POWER_COUPLING] * math.exp(ring_parameters[ring_index, RING_PARAMETER_COLUMN_LOG_THROUGH_COUPLING_WAVELENGTH_DERIVATIVE] * wavelength_offset_m)
            drop_power_coupling = ring_parameters[ring_index, RING_PARAMETER_COLUMN_DROP_POWER_COUPLING] * math.exp(ring_parameters[ring_index, RING_PARAMETER_COLUMN_LOG_DROP_COUPLING_WAVELENGTH_DERIVATIVE] * wavelength_offset_m)
            out_through_power_coupling[ring_index, line_index] = through_power_coupling if through_power_coupling < 1.0 else 1.0 - 1e-15
            out_drop_power_coupling[ring_index, line_index] = drop_power_coupling if drop_power_coupling < 1.0 else 1.0 - 1e-15

def __getattr__(self, name):
    truth_fields = self.__dict__.get("fields")
    if truth_fields is not None and name in truth_fields:
        return truth_fields[name]
    raise AttributeError(name)

def prepare_scenario(sc: Scenario, pp, *, ring_t0: str = "lock") -> tuple[Scenario, dict]:
    if not sc.pending_aggressors:
        return sc, {}
    from mrm.scenarios import calibrate_scenario, foster_from_system
    thermal_system = pp.thermal.system
    thermo_optic_models, thermal_responses = {}, {}
    for aggressor in sc.aggressors:
        if not aggressor.pending:
            continue
        tuning_model = {
            "s0_m_per_k": np.asarray(pp.thermal.dlambda_dt_s0_m_per_k)[:, aggressor.victim_ring],
            "beta_per_k": np.asarray(pp.thermal.dlambda_dt_beta_per_k)[:, 0],
            "t_ref_k": np.asarray(pp.thermal.dlambda_dt_t0_k)[:, 0],
        }
        if ring_t0 == "lock":
            tuning_model["ring_t0_k"] = np.asarray(pp.thermal.t_ring_lock_k)[:, aggressor.victim_ring]
        thermo_optic_models[aggressor.site] = tuning_model
        thermal_responses[aggressor.site] = foster_from_system(thermal_system, victim_ring=aggressor.victim_ring,
            site=aggressor.site)
    calibrated_scenario, calibrations = calibrate_scenario(sc, thermal_responses, model=thermo_optic_models)
    return calibrated_scenario, {k: v.record() for k, v in calibrations.items()}

def reset(self, noise_seed: int | None = None, *, k0: int = 0, protocol: str | None = None, heater_code=None,
          bias_code=None, settle: bool = False) -> None:
    self._reset(noise_seed, k0=k0, protocol=protocol, heater_code=heater_code, bias_code=bias_code)
    self.settle_info = None
    if settle:
        self.settle_info = self.settle(heater_code=heater_code, bias_code=bias_code)

def freeze(worlds):
    for name in names:
        kept_thermal_state[name][worlds] = getattr(S, name)[worlds]
    kept_ring_state[worlds] = S.ring_float[worlds][:, rows, :]

def _init_t_adc(self) -> None:
    S = self.S
    if int(self.P.mo_adc_site) == sensing.ADC_REF_MONITOR_PD:
        S.ring_float[:, kernel.RF_T_ADC, :] = S.ring_float[:, kernel.RF_T_PD, :]
    else:
        S.ring_float[:, kernel.RF_T_ADC, :] = S.world_float[:, kernel.WF_T_BASE1][:, None]

def bind_compiled(self, ctrl) -> None:
    if ctrl.state is None:
        raise RuntimeError("reset the compiled controller with this plant's spec first")
    if ctrl.act.shape != (self.B, self.maps.act_size):
        raise ValueError("controller act layout does not match the plant's spec")

    # return a when its type and layout fit the engine.
    # otherwise copy it to writable (B, -1) storage.
    def own(a, dtype):
        ok = a.dtype == dtype and a.flags.c_contiguous and a.flags.writeable and a.ndim == 2
        return a if ok else np.array(a, dtype=dtype, order="C", copy=True).reshape(self.B, -1)
    ctrl.state = tuple(own(a, d) for a, d in zip(ctrl.state, (np.int64, np.float64, np.int64, np.float64)))
    p_i, p_f, s_i, s_f = ctrl.state
    S = self.S._replace(ctrl_p_i64=p_i, ctrl_p_f64=p_f, ctrl_s_i64=s_i, ctrl_s_f64=s_f)
    S = S._replace(ctrl_s_i64_init=S.ctrl_s_i64.copy(), ctrl_s_f64_init=S.ctrl_s_f64.copy())
    if self.maps.act_size:
        ctrl.act[...] = S.act[:, :self.maps.act_size]
        if ctrl.act.dtype == np.int64 and ctrl.act.flags.c_contiguous:
            S = S._replace(act=ctrl.act, act_popped=np.zeros_like(ctrl.act))
    ctrl._act_synced = True
    self.S = S
    self._ctrl = ctrl
    self._run_block = None

def own(a, dtype):
    ok = a.dtype == dtype and a.flags.c_contiguous and a.flags.writeable and a.ndim == 2
    return a if ok else np.array(a, dtype=dtype, order="C", copy=True).reshape(self.B, -1)

def restart_compiled(self, ctrl) -> None:
    if ctrl is not self._ctrl or ctrl.state is None:
        raise RuntimeError("restart_compiled: the controller is not the one bound to this plant")
    S = self.S
    rows = (S.ctrl_p_i64, S.ctrl_p_f64, S.ctrl_s_i64, S.ctrl_s_f64)
    if all(np.shape(new) == np.shape(old) for new, old in zip(ctrl.state, rows)):
        for new, old in zip(ctrl.state, rows):
            old[...] = new
        ctrl.state = rows
    else:                                  # init gave other sizes — bind the new arrays (a new kernel type)
        def own(a, dtype):
            return np.array(a, dtype=dtype, order="C", copy=True).reshape(self.B, -1)
        ctrl.state = tuple(own(a, d) for a, d in zip(ctrl.state, (np.int64, np.float64, np.int64, np.float64)))
        S = S._replace(ctrl_p_i64=ctrl.state[0], ctrl_p_f64=ctrl.state[1], ctrl_s_i64=ctrl.state[2],
                       ctrl_s_f64=ctrl.state[3], ctrl_s_i64_init=ctrl.state[2].copy(),
                       ctrl_s_f64_init=ctrl.state[3].copy())
        self._run_block = None
    n = self.maps.act_size
    if n:
        act = S.act[:, :n]
        for i in range(self.maps.act_map.shape[0]):
            row = self.maps.act_map[i]
            dst, o, sz = int(row[AM_DST]), int(row[AM_OFFSET]), int(row[AM_SIZE])
            if dst in (DST_HEATER, DST_BIAS):    # tx.heater, tx.bias — from the latched registers
                act[:, o:o + sz] = S.ring_int[:, kernel.RI_HE_REG if dst == DST_HEATER else kernel.RI_BI_REG, :sz]
        if ctrl.act.shape == S.act.shape and ctrl.act.dtype == S.act.dtype:
            ctrl.act = S.act
        else:
            ctrl.act[...] = act
    ctrl._act_synced = True
    self.S = S

def _fn(self):
    if self._run_block is None:
        _check_kernel_arrays(self.P, "P")
        _check_kernel_arrays(self.S, "S")
        self._run_block = kernel.get_run_block(self.P, self.S)
    return self._run_block

def run(self, n_ticks: int, *, mode: int = kernel.MODE_OPEN, step_fn=None, fast_fn=None, resume: bool = False,
        n_threads: int | None = None) -> int:
    n = int(n_ticks)
    if n <= 0:
        return 0
    done = np.zeros(self.B, np.int64)
    fn = self._fn()
    fn(kernel.null_step if step_fn is None else step_fn, kernel.null_step if fast_fn is None else fast_fn,
       self.P, self.S, np.int64(self.tick), np.int64(n), np.int64(mode), np.int64(1 if resume else 0), done,
       n_threads=self.n_threads if n_threads is None else n_threads)
    if np.any(done != done[0]):
        raise RuntimeError(f"worlds advanced by different tick counts {done}: the Python path needs edges shared "
                           "by every world (no tick jitter)")
    self.tick += int(done[0])
    return int(done[0])

def advance(self, inputs: Mapping[str, Any] | None = None, n_ticks: int = 1) -> None:
    if inputs:
        acts = self.validator.validate(dict(inputs))
        self.spec.layout.pack_act(acts, self.S.act[:, :self.maps.act_size])
        latch = np.int64(self.tick + self.controller_latency_ticks)
        for b in range(self.B):
            S = self.S
            if not pipe_push_row(S.pipe_vals[b], S.pipe_ticks[b], S.pipe_meta[b], S.act[b], latch):
                self._grow_pipeline()
                S = self.S
                if not pipe_push_row(S.pipe_vals[b], S.pipe_ticks[b], S.pipe_meta[b], S.act[b], latch):
                    raise RuntimeError("controller pipeline: push failed after growing it")
    self.run(int(n_ticks), mode=kernel.MODE_OPEN)

def sample_sensors(self) -> tuple[dict, dict]:
    _, _, sensors, new = self.spec.layout.unpack_obs(self.S.obs)
    return sensors, new

def _kernel_arr_b(x, B, dtype=np.float64):
    flat_values = np.asarray(x, dtype=dtype).reshape(-1)
    return _kernel_arr(np.broadcast_to(flat_values, (B,)) if flat_values.size in (1, B) else flat_values, dtype)

def _check_kernel_arrays(tup, what: str) -> None:
    for name, value in zip(tup._fields, tup):
        if isinstance(value, np.ndarray) and not (value.flags.c_contiguous and value.flags.writeable):
            raise TypeError(f"kernel argument {what}.{name} must be a writeable C-contiguous array")

@njit
def solve_ring_temperature(
    pabs_fn, k, packed_f, packed_i, t_other, g, t_start, p_max, d2p_max, max_iter, tol_k
):
    if g == 0.0:
        absorbed_power_w, d_absorbed_power_dtemp_w_per_k = pabs_fn(t_other, k, packed_f, packed_i)
        return t_other, absorbed_power_w, d_absorbed_power_dtemp_w_per_k, 0, STATUS_CONVERGED
    if g != g:  # NaN gain - no bracket exists - counted as a failed solve by the caller
        absorbed_power_w, d_absorbed_power_dtemp_w_per_k = pabs_fn(t_other, k, packed_f, packed_i)
        return t_other, absorbed_power_w, d_absorbed_power_dtemp_w_per_k, 0, STATUS_NAN_GAIN
    # F(lo) = (lo - t_other) - g P(lo) <= 0 and F(hi) >= 0 for either sign of g when 0 <= P <= p_max
    lower_temp_bound_k = min(t_other, t_other + g * p_max)
    upper_temp_bound_k = max(t_other, t_other + g * p_max)
    start_temp_k = t_start
    if start_temp_k != start_temp_k:  # NaN starts at t_other - infinities select bracket ends below
        start_temp_k = t_other
    if start_temp_k < lower_temp_bound_k:
        start_temp_k = lower_temp_bound_k
    if start_temp_k > upper_temp_bound_k:
        start_temp_k = upper_temp_bound_k
    start_power_w, d_start_power_dtemp_w_per_k = pabs_fn(start_temp_k, k, packed_f, packed_i)
    start_residual_k = start_temp_k - t_other - g * start_power_w
    if abs(start_residual_k) <= tol_k:
        return start_temp_k, start_power_w, d_start_power_dtemp_w_per_k, 0, STATUS_CONVERGED
    search_direction = 1.0 if start_residual_k < 0.0 else -1.0  # the root lies in the direction sgn from t0
    # near - the last point on the start side of the root - far - the nearest point known beyond it (or the bracket end)
    near_temp_k, near_residual_k, near_absorbed_power_w, d_near_power_dtemp_w_per_k = (
        start_temp_k,
        start_residual_k,
        start_power_w,
        d_start_power_dtemp_w_per_k,
    )
    far_temp_k = upper_temp_bound_k if search_direction > 0.0 else lower_temp_bound_k
    far_residual_k, far_absorbed_power_w, d_far_power_dtemp_w_per_k = 0.0, 0.0, 0.0
    far_point_evaluated = False
    # K2 = abs(g)*d2p_max bounds residual curvature in 1/K
    residual_curvature_bound_per_k = abs(g) * d2p_max if d2p_max > 0.0 else 0.0
    iterations_used = 0
    for iteration in range(1, max_iter + 1):
        if (far_temp_k - near_temp_k) * search_direction <= tol_k:
            break
        iterations_used = iteration
        d_residual_dtemp = (
            1.0 - g * d_near_power_dtemp_w_per_k
        )  # F'(near) - |F| decreases at this rate along sgn
        abs_residual_k = abs(near_residual_k)
        candidate_temp_k = math.nan  # the next temperature to evaluate
        if residual_curvature_bound_per_k > 0.0 and math.isfinite(d_residual_dtemp):
            # d_min of the comments - no root lies closer than this
            temperature_step_k = (
                2.0
                * abs_residual_k
                / (
                    d_residual_dtemp
                    + math.sqrt(
                        d_residual_dtemp * d_residual_dtemp
                        + 2.0 * residual_curvature_bound_per_k * abs_residual_k
                    )
                )
            )
            trial_temp_k = near_temp_k + search_direction * temperature_step_k
            if (far_temp_k - trial_temp_k) * search_direction > 0.0:
                candidate_temp_k = trial_temp_k
            elif not far_point_evaluated:
                candidate_temp_k = far_temp_k  # the power bound supplies the bracket end's residual sign
            # else - the step reached a sign change already found (inexact dP/dT or d2p_max) - secant below
        elif math.isfinite(d_residual_dtemp) and d_residual_dtemp > 0.0:
            trial_temp_k = near_temp_k + search_direction * abs_residual_k / d_residual_dtemp
            if (trial_temp_k - near_temp_k) * search_direction > 0.0 and (
                far_temp_k - trial_temp_k
            ) * search_direction > 0.0:
                candidate_temp_k = trial_temp_k
        if math.isnan(candidate_temp_k):
            if far_point_evaluated and far_residual_k != near_residual_k:
                trial_temp_k = near_temp_k - near_residual_k * (far_temp_k - near_temp_k) / (
                    far_residual_k - near_residual_k
                )
                if (trial_temp_k - near_temp_k) * search_direction > 0.0 and (
                    far_temp_k - trial_temp_k
                ) * search_direction > 0.0:
                    candidate_temp_k = trial_temp_k
            if math.isnan(candidate_temp_k):
                candidate_temp_k = 0.5 * (near_temp_k + far_temp_k)
        candidate_power_w, d_candidate_power_dtemp_w_per_k = pabs_fn(candidate_temp_k, k, packed_f, packed_i)
        candidate_residual_k = candidate_temp_k - t_other - g * candidate_power_w
        if abs(candidate_residual_k) <= tol_k:
            return (
                candidate_temp_k,
                candidate_power_w,
                d_candidate_power_dtemp_w_per_k,
                iteration,
                STATUS_CONVERGED,
            )
        if candidate_residual_k * near_residual_k > 0.0:
            near_temp_k, near_residual_k, near_absorbed_power_w, d_near_power_dtemp_w_per_k = (
                candidate_temp_k,
                candidate_residual_k,
                candidate_power_w,
                d_candidate_power_dtemp_w_per_k,
            )
        else:
            far_temp_k, far_residual_k, far_absorbed_power_w, d_far_power_dtemp_w_per_k = (
                candidate_temp_k,
                candidate_residual_k,
                candidate_power_w,
                d_candidate_power_dtemp_w_per_k,
            )
            far_point_evaluated = True
    if (far_temp_k - near_temp_k) * search_direction <= tol_k:
        if far_point_evaluated:
            if abs(far_residual_k) < abs(near_residual_k):
                return (
                    far_temp_k,
                    far_absorbed_power_w,
                    d_far_power_dtemp_w_per_k,
                    iterations_used,
                    STATUS_CONVERGED,
                )
            return (
                near_temp_k,
                near_absorbed_power_w,
                d_near_power_dtemp_w_per_k,
                iterations_used,
                STATUS_CONVERGED,
            )
        # no sign change met up to the bracket end - with a valid p_max, F(bracket end) has the root's sign or is 0 (then |F| <= tol_k returned above) - here P_abs exceeded p_max
        return near_temp_k, near_absorbed_power_w, d_near_power_dtemp_w_per_k, iterations_used, STATUS_BOUND
    return near_temp_k, near_absorbed_power_w, d_near_power_dtemp_w_per_k, iterations_used, STATUS_MAX_ITER

@njit
def commit_none(t_k, k, packed_f, packed_i):
    return None

def to_lines(v):
    v = v if v.ndim == 3 else (v[None] if v.ndim == 2 else np.reshape(v, (1, -1, 1) if v.ndim == 1 else (1, 1, 1)))
    return np.broadcast_to(v, (B, N, L))

def lorentzian_folds(A: float):
    if A <= BISTABILITY_FACTOR:
        return None
    polynomial_roots = np.roots([1.0, 0.0, 2.0, 2.0 * A, 1.0])
    real_fold_detunings = np.sort(polynomial_roots[np.abs(polynomial_roots.imag) < 1e-9 * max(1.0, A)].real)
    if real_fold_detunings.size < 2:
        return None
    lower_fold_detuning, upper_fold_detuning = float(real_fold_detunings[0]), float(real_fold_detunings[-1])
    detuning_without_optical_heating = lambda v: v - A / (1.0 + v * v)
    return (
        lower_fold_detuning,
        upper_fold_detuning,
        detuning_without_optical_heating(lower_fold_detuning),
        detuning_without_optical_heating(upper_fold_detuning),
    )

def steady_detuning(y_o: float, A: float):
    equilibrium_roots = np.roots([1.0, -y_o, 1.0, -(y_o + A)])
    return np.sort(equilibrium_roots[np.abs(equilibrium_roots.imag) < 1e-7 * max(1.0, abs(A), abs(y_o))].real)

@njit(cache=True, _nrt=False)
def dark_current_a(i0_a, t_k, t0_k, ea_j):
    if not (i0_a > 0.0) or not (t_k > 0.0) or not (t0_k > 0.0):
        return 0.0
    return i0_a * math.exp(-(ea_j / K_B) * (1.0 / t_k - 1.0 / t0_k))

@njit(cache=True)
def _round_clip(x, cmax):
    if not (x == x) or x < 0.0:
        return np.int64(0)
    if x > cmax:
        return np.int64(cmax)
    return np.int64(math.floor(x + 0.5))

@njit(cache=True)
def _dnl_threshold(c, dnl, key, ring, slot):
    return c - 0.5 + dnl * (rng.uniform(key, ring, c, slot) - 0.5)

@njit(cache=True, _nrt=False)
def adc_quantize(v, inl_bow_lsb, dnl_lsb, code_max, key, ring, slot):
    if not (v == v):
        return np.int64(0), 1
    over = 0
    if v < -0.5 or v >= code_max + 0.5:
        over = 1
    if inl_bow_lsb != 0.0:
        u = v / code_max
        if u < 0.0:
            u = 0.0
        elif u > 1.0:
            u = 1.0
        v = v + inl_bow_lsb * 4.0 * u * (1.0 - u)
    if v < -0.5:
        return np.int64(0), 1
    if v >= code_max + 0.5:
        return np.int64(code_max), 1
    c = np.int64(math.floor(v + 0.5))
    if c < 0:
        c = np.int64(0)
    elif c > code_max:
        c = np.int64(code_max)
    if dnl_lsb > 0.0:
        while c > 0 and v < _dnl_threshold(c, dnl_lsb, key, ring, slot):
            c -= 1
        while c < code_max and v >= _dnl_threshold(c + 1, dnl_lsb, key, ring, slot):
            c += 1
    return c, over

@njit(cache=True, _nrt=False)
def _flicker_init(key, ring, tick, slot0, coef, fx, fc):
    for j in range(coef.shape[0]):
        z1, z2 = rng.normal2(key, ring, tick, slot0 + j)
        fx[j] = coef[j, _FL_S00] * z1
        fc[j] = coef[j, _FL_S10] * z1 + coef[j, _FL_S11] * z2

@njit(cache=True)
def monitor_tick(k, p_pd_w, p_bg_w, t_pd_k, t_adc_k, pga_sel, fault, pr, pw, lat, phase, pga_gains, fl_coef,
                 afe_type, window_ticks, period_ticks, code_max, shot_on, stuck_flagged, slot_base,
                 key_adc, key_shot, key_dnl, sf, si, fx, fc, fv, fr, fm, out_sampled):
    for b in range(p_pd_w.shape[0]):
        monitor_tick_row(k, p_pd_w[b], p_bg_w[b], t_pd_k[b], t_adc_k[b], pga_sel[b], fault[b], pr[b], pw[b],
                         lat[b], phase, pga_gains, fl_coef[b], afe_type, window_ticks, period_ticks, code_max,
                         shot_on, stuck_flagged, slot_base, key_adc[b], key_shot[b], key_dnl[b], sf[b], si[b],
                         fx[b], fc[b], fv[b], fr[b], fm[b], out_sampled[b])

@njit(cache=True, parallel=True)
def monitor_tick_par(k, p_pd_w, p_bg_w, t_pd_k, t_adc_k, pga_sel, fault, pr, pw, lat, phase, pga_gains, fl_coef,
                     afe_type, window_ticks, period_ticks, code_max, shot_on, stuck_flagged, slot_base,
                     key_adc, key_shot, key_dnl, sf, si, fx, fc, fv, fr, fm, out_sampled):
    for b in nb.prange(p_pd_w.shape[0]):
        monitor_tick_row(k, p_pd_w[b], p_bg_w[b], t_pd_k[b], t_adc_k[b], pga_sel[b], fault[b], pr[b], pw[b],
                         lat[b], phase, pga_gains, fl_coef[b], afe_type, window_ticks, period_ticks, code_max,
                         shot_on, stuck_flagged, slot_base, key_adc[b], key_shot[b], key_dnl[b], sf[b], si[b],
                         fx[b], fc[b], fv[b], fr[b], fm[b], out_sampled[b])

@njit(cache=True)
def monitor_release(now, lat, fv, fr, fm, out_samples, out_ticks, out_count, latest, out_valid, out_over, out_new):
    lost = 0
    for b in range(fm.shape[0]):
        lost += monitor_release_row(now, lat[b], fv[b], fr[b], fm[b], out_samples[b], out_ticks[b], out_count[b],
                                    latest[b], out_valid[b], out_over[b], out_new[b])
    return lost

@njit(cache=True)
def temp_tick(k, t_site_k, tp, period, lat, code_max, fl_coef, key, st, fx, fc, primed, fv, fr, fm, out_sampled):
    for b in range(t_site_k.shape[0]):
        temp_tick_row(k, t_site_k[b], tp[b], period, lat[b], code_max, fl_coef[b], key[b], st[b], fx[b], fc[b],
                      primed[b], fv[b], fr[b], fm[b], out_sampled[b])

@njit(cache=True, _nrt=False)
def temp_release_row(now, fv, fr, fm, latest, out_new):
    for i in range(fm.shape[0]):
        out_new[i] = False
        while True:
            ok, val, rel = fifo_pop_ready(fv, fr, fm, i, now)
            if not ok:
                break
            latest[i] = val
            out_new[i] = True

@njit(cache=True)
def temp_release(now, fv, fr, fm, latest, out_new):
    for b in range(fm.shape[0]):
        temp_release_row(now, fv[b], fr[b], fm[b], latest[b], out_new[b])

@njit(cache=True)
def readback_tick(k, v_v, i_a, lsb_v, lsb_i, noise_codes, period, lat, code_max, average, key, st, fv, fr, fm,
                  out_sampled):
    for b in range(v_v.shape[0]):
        readback_tick_row(k, v_v[b], i_a[b], lsb_v[b], lsb_i[b], noise_codes[b], period, lat[b], code_max, average,
                          key[b], st[b], fv[b], fr[b], fm[b], out_sampled[b])

@njit(cache=True, _nrt=False)
def readback_release_row(now, fv, fr, fm, latest_v, latest_i, out_new):
    mask = (np.int64(1) << _RB_I_SHIFT) - 1         # the V-code bits of a FIFO entry
    for n in range(fm.shape[0]):
        out_new[n] = False
        while True:
            ok, val, rel = fifo_pop_ready(fv, fr, fm, n, now)
            if not ok:
                break
            latest_v[n] = val & mask
            latest_i[n] = val >> _RB_I_SHIFT
            out_new[n] = True

@njit(cache=True)
def readback_release(now, fv, fr, fm, latest_v, latest_i, out_new):
    for b in range(fm.shape[0]):
        readback_release_row(now, fv[b], fr[b], fm[b], latest_v[b], latest_i[b], out_new[b])

@njit(cache=True)
def dac_glitch_row(codes, fault, glitch_codes, lo, hi, out):
    glitch_channels = glitch_codes.shape[0]
    for n in range(codes.shape[0]):
        glitched_code = codes[n]
        if fault[n] & FAULT_DAC_GLITCH:
            glitched_code = glitched_code + glitch_codes[n if glitch_channels > 1 else 0]
            if glitched_code < lo:
                glitched_code = lo
            elif glitched_code > hi:
                glitched_code = hi
        out[n] = glitched_code

@njit(cache=True)
def dac_glitch(codes, fault, glitch_codes, lo, hi, out):
    n_b = glitch_codes.shape[0]
    for b in range(codes.shape[0]):
        dac_glitch_row(codes[b], fault[b], glitch_codes[b if n_b > 1 else 0], lo, hi, out[b])

@njit(cache=True, _nrt=False)
def fault_mask_row(adc_drop, adc_stuck, adc_saturate, dac_glitch_codes, out):
    for n in range(out.shape[0]):
        fault_bits = 0
        if adc_drop[n] >= 0.5:
            fault_bits |= FAULT_ADC_DROP
        if adc_stuck[n] >= 0.5:
            fault_bits |= FAULT_ADC_STUCK
        if adc_saturate[n] >= 0.5:
            fault_bits |= FAULT_ADC_SATURATE
        if dac_glitch_codes[n] != 0.0:
            fault_bits |= FAULT_DAC_GLITCH
        out[n] = fault_bits

def flicker_pole_set(s_white: float, f_corner_hz: float, f_min_hz: float = _FLICKER_F_MIN_HZ,
                     f_max_hz: float | None = None, per_decade: int = _FLICKER_PER_DECADE
                     ) -> tuple[np.ndarray, np.ndarray]:
    if not (s_white > 0.0 and f_corner_hz > 0.0):
        return np.zeros(0), np.zeros(0)
    if f_max_hz is None:
        f_max_hz = 10.0 * f_corner_hz
    if not (0.0 < f_min_hz < f_max_hz):
        raise ValueError(f"flicker band needs 0 < f_min ({f_min_hz}) < f_max ({f_max_hz})")
    if int(per_decade) < 1:
        raise ValueError("per_decade must be >= 1")
    r = 10.0 ** (1.0 / per_decade)
    n_poles = max(1, int(math.ceil(per_decade * math.log10(f_max_hz / f_min_hz) - 1e-9)))
    f = f_min_hz * r ** (np.arange(n_poles) + 0.5)
    lam = 2.0 * math.pi * f
    var = np.full(n_poles, s_white * f_corner_hz * math.log(r))
    return lam, var

def flicker_psd(f_hz, lam, var) -> np.ndarray:
    w = 2.0 * math.pi * np.atleast_1d(np.asarray(f_hz, dtype=float))[:, None]
    lam = np.asarray(lam, dtype=float)[None, :]
    var = np.asarray(var, dtype=float)[None, :]
    return np.sum(4.0 * var * lam / (lam * lam + w * w), axis=1)

def _g_window(u: float) -> float:
    if u < 1e-2:
        return u ** 3 / 3.0 - u ** 4 / 4.0 + 7.0 * u ** 5 / 60.0 - u ** 6 / 24.0
    return u + 2.0 * math.expm1(-u) - 0.5 * math.expm1(-2.0 * u)

def flicker_coefficients(s_white: float, f_corner_hz: float, *, afe_type: int, period_s: float,
                         window_s: float = 0.0, tau_s: float = 0.0, f_min_hz: float = _FLICKER_F_MIN_HZ,
                         f_max_hz: float | None = None, per_decade: int = _FLICKER_PER_DECADE) -> np.ndarray:
    if not (s_white > 0.0 and f_corner_hz > 0.0):
        return np.zeros((0, N_FLICKER_COEF))
    f_afe = 1.0 / (2.0 * window_s) if afe_type == AFE_INTEGRATE_DUMP else 1.0 / (2.0 * math.pi * tau_s)
    if f_max_hz is None:
        f_max_hz = 10.0 * min(f_corner_hz, f_afe)
        if f_max_hz <= f_min_hz:
            # a corner this low puts the whole 1/f band below the lowest pole, where it acts as a static offset
            return np.zeros((0, N_FLICKER_COEF))
    lam, var = flicker_pole_set(s_white, f_corner_hz, f_min_hz, f_max_hz, per_decade)
    if lam.size >= _SLOT_FL_INIT - _SLOT_FLICKER:
        raise ValueError(f"{lam.size} flicker poles exceed the counter-RNG slot range "
                         f"({_SLOT_FL_INIT - _SLOT_FLICKER})")
    if afe_type == AFE_INTEGRATE_DUMP:
        return ou_window_coefficients(lam, var, period_s, window_s)
    return ou_rc_coefficients(lam, var, period_s, tau_s)

def _stack_coefs(coefs: list[np.ndarray]) -> np.ndarray:
    jmax = max((c.shape[0] for c in coefs), default=0)
    out = np.zeros((len(coefs), jmax, N_FLICKER_COEF))
    for b, c in enumerate(coefs):
        out[b, :c.shape[0]] = c
    return out

def _arr_bn(x, B, N, name, dtype=np.float64) -> np.ndarray:
    array = np.asarray(x, dtype=dtype)
    if array.ndim == 1:
        array = array.reshape(1, -1) if array.shape[0] == N else array.reshape(-1, 1)
    try:
        return np.ascontiguousarray(np.broadcast_to(array, (B, N))).copy()
    except ValueError:
        raise ValueError(f"{name}: shape {np.shape(x)} does not broadcast to (B={B}, N={N})") from None

def _arr_b(x, B, name, dtype=np.float64) -> np.ndarray:
    array = np.asarray(x, dtype=dtype).reshape(-1)
    if array.size == 1:
        return np.full(B, array[0], dtype=dtype)
    if array.size != B:
        raise ValueError(f"{name}: shape {np.shape(x)} is not scalar or (B={B},)")
    return array.copy()

def stream_keys(seeds, B, stream_name) -> np.ndarray:
    seeds = _arr_b(seeds, B, "seeds", np.int64)
    sid = rng.stream_id(stream_name)
    return np.array([rng.stream_key(int(s), sid) for s in seeds], dtype=np.uint64)

def integrator_full_scale_a(t_int_s: float = PAT2_T_INT_S, c_int_f: float = PAT2_C_INT_F,
                            v_swing_v: float = PAT2_V_REF_V) -> float:
    return c_int_f * v_swing_v / t_int_s

@property
def lsb_a(self) -> np.ndarray:
    return self.pw[:, PW_LSB].copy()

def adc_temperature(self, t_pd_k=None, t_base_k=None) -> np.ndarray:
    B, N = self.B, self.N
    if self.adc_ref_site == ADC_REF_MONITOR_PD:
        if t_pd_k is None:
            return np.ascontiguousarray(np.broadcast_to(self.pw[:, PW_DARK_T0][:, None], (B, N))).copy()
        return _arr_bn(t_pd_k, B, N, "t_pd_k")
    if t_base_k is None:
        return np.ascontiguousarray(np.broadcast_to(self.pw[:, PW_T_REF][:, None], (B, N))).copy()
    t = np.asarray(t_base_k, dtype=np.float64)
    if t.ndim == 1:                                  # a 1-D base temperature is per world, never per ring
        t = t.reshape(-1, 1)
    return _arr_bn(t, B, N, "t_base_k")

def codes_per_w(self, pga_select=0, t_adc_k=None) -> np.ndarray:
    one = self.ideal_code(1.0, pga_select, t_adc_k) - self.ideal_code(0.0, pga_select, t_adc_k)   # codes per A
    return one * self.pw[:, PW_GAIN_SCALE][:, None] * self.pr[:, :, PR_RESP]

def white_sigma_a(self, i_sig_a, i_dark_a=0.0) -> np.ndarray:
    total_current_a = _arr_bn(i_sig_a, self.B, self.N, "i_sig_a") + _arr_bn(i_dark_a, self.B, self.N, "i_dark_a")
    white_psd_a2_per_hz = (
        self.pw[:, PW_S_TIA][:, None] + (2.0 * Q_E * np.abs(total_current_a) if self.shot_on else 0.0)
    )
    if self.afe_type == AFE_INTEGRATE_DUMP:
        return np.sqrt(white_psd_a2_per_hz / (2.0 * self.window_ticks * self.dt_s))
    return np.sqrt(white_psd_a2_per_hz / (4.0 * self.afe_tau_s))

def channels(self, rel: MonitorRelease) -> tuple[dict, dict]:
    p = self.prefix
    always = np.ones_like(rel.new)
    sensors = {f"{p}.samples": rel.samples, f"{p}.sample_ticks": rel.sample_ticks, f"{p}.count": rel.count,
               f"{p}.latest": rel.latest, self.valid_name: rel.valid, self.overrange_name: rel.overrange}
    new = {f"{p}.samples": rel.new, f"{p}.sample_ticks": rel.new, f"{p}.count": always, f"{p}.latest": rel.new,
           self.valid_name: always, self.overrange_name: always}
    return sensors, new

@classmethod
def from_plant_params(cls, pp, *, adc_bits=12, code_zero_k=233.15) -> "TempSensorsHw":
    ts = pp.temp_sensors
    dt = float(pp.timing.dt_s)
    B = int(pp.batch)
    inv = {v: k for k, v in TEMP_SENSOR_TYPES.items()}
    sensors = []
    for i, name in enumerate(ts.names):
        if int(ts.sample_period_ticks[i]) < 1:
            raise ValueError(f"temp_sensors[{i}] ({name}): sample_rate_hz is missing or gives a period below one "
                             "tick")
        sensors.append(dict(
            name=name, type=inv[int(ts.type[i])], sample_rate_hz=1.0 / (int(ts.sample_period_ticks[i]) * dt),
            latency_s=np.asarray(ts.latency_ticks)[:, i] * dt, noise_rms_k=np.asarray(ts.noise_rms_k)[:, i],
            flicker_corner_hz=np.nan_to_num(np.asarray(ts.flicker_corner_hz)[:, i]),
            resolution_k=np.asarray(ts.resolution_k)[:, i], offset_k=np.asarray(ts.offset_k)[:, i],
            gain_error_frac=np.asarray(ts.gain_error_frac)[:, i],
            self_heating_k=np.asarray(ts.self_heating_k)[:, i], adc_bits=_ts_bits(ts, i, adc_bits),
            code_zero_k=_ts_zero(ts, i, code_zero_k)))
    return cls.build(B, dt, sensors)

def _ts_bits(ts, i: int, default: int) -> int:
    a = getattr(ts, "adc_bits", None)
    v = int(np.asarray(a)[i]) if a is not None and np.asarray(a).size > i else 0
    return v if v > 0 else int(default)

def _ts_zero(ts, i: int, default: float) -> float:
    a = getattr(ts, "code_zero_k", None)
    v = float(np.asarray(a)[i]) if a is not None and np.asarray(a).size > i else math.nan
    return v if math.isfinite(v) else float(default)

def release(self, now: int) -> tuple[dict, dict]:
    temp_release(np.int64(now), self.fv, self.fr, self.fm, self.latest, self.new)
    sensors, new = {}, {}
    for i, name in enumerate(self.hw.names):
        bits = int(self.hw.code_max[i]).bit_length()
        sensors[f"temp.{name}"] = self.latest[:, i:i + 1].astype(adc_channel_dtype(bits))
        new[f"temp.{name}"] = self.new[:, i:i + 1].copy()
    return sensors, new

@classmethod
def from_plant_params(cls, pp, *, adc_bits: int | None = None, noise_rms_codes=None, average: bool | None = None
                      ) -> "ReadbackHw":
    if not bool(getattr(pp.heater, "readback_present", False)):
        raise ValueError("ring.heater.readback.present is False: no heater readback channel")
    dt = float(pp.timing.dt_s)
    vals = getattr(pp, "values", {}) or {}

    def first(key, default):
        v = vals.get(key)
        return default if v is None else float(np.asarray(v, dtype=float).reshape(-1)[0])

    def per_world(key, default):
        v = vals.get(key)
        return default if v is None else np.asarray(v, dtype=float).reshape(-1)
    per = int(pp.timing.readback_period_ticks)
    rate = 1.0 / (per * dt) if per > 0 else 10e3      # assumed fallback, mrm.core.channels.ChannelHardware
    h = pp.heater
    if adc_bits is None:
        adc_bits = int(getattr(h, "readback_adc_bits", 0) or 0) or int(first("ring.heater.readback.adc_bits", 12))
        # 12 - assumed, ChannelHardware
    if noise_rms_codes is None:
        nz = getattr(h, "readback_noise_rms_codes", None)
        noise_rms_codes = 0.0 if nz is None else np.asarray(nz, dtype=float).reshape(-1)
    if average is None:
        average = bool(getattr(h, "readback_average", False))
    # fallbacks 2.0 V and 32 mA - assumed, mrm.core.channels.ChannelHardware (above the 1.5-1.6 V, ~29 mA drive)
    return cls.build(int(pp.batch), int(pp.n_rings), dt, adc_bits=int(adc_bits),
                     v_full_scale_v=per_world("ring.heater.readback.v_full_scale_v", 2.0),
                     i_full_scale_a=per_world("ring.heater.readback.i_full_scale_a", 0.032), rate_hz=rate,
                     latency_s=np.asarray(pp.timing.readback_latency_ticks).reshape(-1) * dt,
                     noise_rms_codes=noise_rms_codes, average=average)

def first(key, default):
    v = vals.get(key)
    return default if v is None else float(np.asarray(v, dtype=float).reshape(-1)[0])

def per_world(key, default):
    v = vals.get(key)
    return default if v is None else np.asarray(v, dtype=float).reshape(-1)

def release(self, now: int) -> tuple[dict, dict]:
    readback_release(np.int64(now), self.fv, self.fr, self.fm, self.latest_v, self.latest_i, self.new)
    dt = adc_channel_dtype(self.hw.adc_bits)
    return ({"heater.readback_v": self.latest_v.astype(dt), "heater.readback_i": self.latest_i.astype(dt)},
            {"heater.readback_v": self.new.copy(), "heater.readback_i": self.new.copy()})

def __init__(self, monitor: MonitorBank, temps: TempSensorBank | None = None,
             readback: ReadbackBank | None = None, ref_tap: MonitorBank | None = None):
    self.monitor, self.temps, self.readback, self.ref_tap = monitor, temps, readback, ref_tap

def reset(self, noise_seeds=None) -> None:
    for bank in (self.monitor, self.temps, self.readback, self.ref_tap):
        if bank is not None:
            bank.reset(noise_seeds)

def tick(self, k: int, *, p_pd_w, p_bg_w=0.0, t_pd_k=None, t_adc_k=None, pga_select=None, fault=None,
         t_site_k=None, heater_v=None, heater_i=None, p_ref_w=None, t_base_k=None) -> None:
    self.monitor.tick(k, p_pd_w, p_bg_w, t_pd_k, t_adc_k, pga_select, fault, t_base_k=t_base_k)
    if self.ref_tap is not None:
        self.ref_tap.tick(k, 0.0 if p_ref_w is None else p_ref_w, 0.0, t_pd_k, t_adc_k, pga_select, None,
                          t_base_k=t_base_k)
    if self.temps is not None and self.temps.hw.S > 0:
        if t_site_k is None:
            raise ValueError("temperature sensors need t_site_k (B, S)")
        self.temps.tick(k, t_site_k)
    if self.readback is not None:
        if heater_v is None or heater_i is None:
            raise ValueError("heater readback needs heater_v and heater_i (B, N)")
        self.readback.tick(k, heater_v, heater_i)

def release(self, now: int) -> tuple[dict, dict]:
    sensors, new = self.monitor.channels(self.monitor.release(now))
    for bank in (self.temps, self.readback):
        if bank is not None:
            bank_sensors, bank_new_flags = bank.release(now)
            sensors.update(bank_sensors)
            new.update(bank_new_flags)
    if self.ref_tap is not None:
        bank_sensors, bank_new_flags = self.ref_tap.channels(self.ref_tap.release(now))
        sensors.update(bank_sensors)
        new.update(bank_new_flags)
    return sensors, new

def calculate_constant_hold_coefficients(
    taus_s: ArrayLike,  # taus_s = tau (s) - thermal time constants - type array-like, broadcast input shape
    res_k_per_w: ArrayLike,  # res_k_per_w = r (K/W) - thermal residues - type array-like, broadcast input shape
    h_s: float,  # h_s = h (s) - thermal step duration - type float scalar
) -> tuple[
    Float64Array,  # return[0] = a (1) - retained state fractions - type float64 ndarray, shape broadcast input shape
    Float64Array,  # return[1] = c (K/W) - constant-power coefficients - type float64 ndarray, shape broadcast input shape
]:
    state_retention, start_power_gain_k_per_w, end_power_gain_k_per_w = calculate_linear_hold_coefficients(
        taus_s, res_k_per_w, h_s
    )
    return (
        state_retention,
        start_power_gain_k_per_w + end_power_gain_k_per_w,
    )

@njit(cache=True)
def advance_thermal_state_for_world(
    state_rise_k: Float64Array,  # state_rise_k = x (K) - lag-state temperature rises updated in place - type float64 ndarray, shape (M,)
    state_retention: Float64Array,  # state_retention = a (1) - retained thermal state fractions - type float64 ndarray, shape (M,)
    start_power_gain_k_per_w: Float64Array,  # start_power_gain_k_per_w = c0 (K/W) - starting-power gain - type float64 ndarray, shape (M,)
    end_power_gain_k_per_w: Float64Array,  # end_power_gain_k_per_w = c1 (K/W) - ending-power gain - type float64 ndarray, shape (M,)
    lag_source_indices: Int64Array,  # lag_source_indices = s_m (1) - source index driving each lag - type int64 ndarray, shape (M,)
    start_source_power_w: Float64Array,  # start_source_power_w = P_start (W) - source powers at the step boundary - type float64 ndarray, shape (S,)
    end_source_power_w: Float64Array,  # end_source_power_w = P_end (W) - source powers at the step boundary - type float64 ndarray, shape (S,)
    source_residue_scale: Float64Array,  # source_residue_scale = s_source (1) - per-source residue multipliers - type float64 ndarray, shape (S,)
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):
    for lag_index in range(state_rise_k.shape[0]):
        source_index = lag_source_indices[lag_index]
        state_rise_k[lag_index] = state_retention[lag_index] * state_rise_k[lag_index] + source_residue_scale[source_index] * (start_power_gain_k_per_w[lag_index] * start_source_power_w[source_index] + end_power_gain_k_per_w[lag_index] * end_source_power_w[source_index])

@njit(cache=True)
def advance_thermal_state_for_world_with_step_size(
    state_rise_k: Float64Array,  # state_rise_k = x (K) - lag-state temperature rises updated in place - type float64 ndarray, shape (M,)
    time_constants_s: Float64Array,  # time_constants_s = tau (s) - thermal time constants - type float64 ndarray, shape (M,)
    thermal_residues_k_per_w: Float64Array,  # thermal_residues_k_per_w = r (K/W) - thermal residues - type float64 ndarray, shape (M,)
    lag_source_indices: Int64Array,  # lag_source_indices = s_m (1) - source index driving each lag - type int64 ndarray, shape (M,)
    start_source_power_w: Float64Array,  # start_source_power_w = P_start (W) - source powers at the step boundary - type float64 ndarray, shape (S,)
    end_source_power_w: Float64Array,  # end_source_power_w = P_end (W) - source powers at the step boundary - type float64 ndarray, shape (S,)
    source_residue_scale: Float64Array,  # source_residue_scale = s_source (1) - per-source residue multipliers - type float64 ndarray, shape (S,)
    step_duration_s: float,  # step_duration_s = h (s) - thermal step duration - type float scalar
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):
    for lag_index in range(state_rise_k.shape[0]):
        source_index = lag_source_indices[lag_index]
        state_retention, start_power_weight, end_power_weight = calculate_linear_hold_lag_weights(time_constants_s[lag_index], step_duration_s)
        state_rise_k[lag_index] = state_retention * state_rise_k[lag_index] + source_residue_scale[source_index] * thermal_residues_k_per_w[lag_index] * (
            start_power_weight * start_source_power_w[source_index] + end_power_weight * end_source_power_w[source_index]
        )

@njit(cache=True)
def write_observer_temperatures_for_world(
    state_rise_k: Float64Array,  # state_rise_k = x (K) - lag-state temperature rises updated in place - type float64 ndarray, shape (M,)
    observer_lag_boundaries: Int64Array,  # observer_lag_boundaries = p_observer (1) - lag-array boundaries of each observer - type int64 ndarray, shape (O+1,)
    base_temperature_k: float,  # base_temperature_k = T_base (K) - base temperature - type float scalar
    out_observer_temperature_k: Float64Array,  # out_observer_temperature_k = T_observer (K) - absolute observer temperatures written in place - type float64 ndarray, shape (O,)
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):
    for observer_index in range(out_observer_temperature_k.shape[0]):
        temperature_k = base_temperature_k
        for lag_index in range(observer_lag_boundaries[observer_index], observer_lag_boundaries[observer_index + 1]):
            temperature_k += state_rise_k[lag_index]
        out_observer_temperature_k[observer_index] = temperature_k

@njit(cache=True)
def shared_or_world_row_index(
    world_index: int,  # world_index = b (1) - world index - type int scalar
    row_count: int,  # row_count = row_count (1) - number of shared or per-world rows - type int scalar
) -> (
    int  # return = row (1) - world row or shared row zero - type int scalar
):
    return world_index if row_count > 1 else 0

@njit(cache=True)
def validate_thermal_step_array_shapes(
    state_rise_k: Float64Array,  # state_rise_k = x (K) - lag-state temperature rises updated in place - type float64 ndarray, shape (B, M)
    state_retention: Float64Array,  # state_retention = a (1) - retained thermal state fractions - type float64 ndarray, shape (1 or B, M)
    start_power_gain_k_per_w: Float64Array,  # start_power_gain_k_per_w = c0 (K/W) - starting-power gain - type float64 ndarray, shape (1 or B, M)
    end_power_gain_k_per_w: Float64Array,  # end_power_gain_k_per_w = c1 (K/W) - ending-power gain - type float64 ndarray, shape (1 or B, M)
    lag_source_indices: Int64Array,  # lag_source_indices = s_m (1) - source index driving each lag - type int64 ndarray, shape (M,)
    start_source_power_w: Float64Array,  # start_source_power_w = P_start (W) - source powers at the step boundary - type float64 ndarray, shape (1 or B, S)
    end_source_power_w: Float64Array,  # end_source_power_w = P_end (W) - source powers at the step boundary - type float64 ndarray, shape (1 or B, S)
    source_residue_scale: Float64Array,  # source_residue_scale = s_source (1) - per-source residue multipliers - type float64 ndarray, shape (1 or B, S)
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):
    world_count = state_rise_k.shape[0]
    lag_count = state_rise_k.shape[1]
    coefficient_row_count = state_retention.shape[0]
    if start_power_gain_k_per_w.shape[0] != coefficient_row_count or end_power_gain_k_per_w.shape[0] != coefficient_row_count or (coefficient_row_count != 1 and coefficient_row_count != world_count):
        raise ValueError("thermal kernel: a, c0, c1 must all have 1 or B rows")
    if state_retention.shape[1] != lag_count or start_power_gain_k_per_w.shape[1] != lag_count or end_power_gain_k_per_w.shape[1] != lag_count or lag_source_indices.shape[0] != lag_count:
        raise ValueError("thermal kernel: a, c0, c1, lag_src must have M (= x.shape[1]) lags")
    for n in (start_source_power_w.shape[0], end_source_power_w.shape[0], source_residue_scale.shape[0]):
        if n != 1 and n != world_count:
            raise ValueError("thermal kernel: u0, u1, src_scale must have 1 or B rows")

@njit(cache=True)
def write_observer_temperatures(
    state_rise_k: Float64Array,  # state_rise_k = x (K) - lag-state temperature rises updated in place - type float64 ndarray, shape (B, M)
    observer_lag_boundaries: Int64Array,  # observer_lag_boundaries = p_observer (1) - lag-array boundaries of each observer - type int64 ndarray, shape (O+1,)
    base_temperature_k: ArrayLike,  # base_temperature_k = T_base (K) - base temperature of each world - type array-like, scalar or shape (1 or B,)
    out_observer_temperature_k: Float64Array,  # out_observer_temperature_k = T_observer (K) - absolute observer temperatures written in place - type float64 ndarray, shape (B, O)
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):
    if out_observer_temperature_k.shape[0] != state_rise_k.shape[0] or (base_temperature_k.shape[0] != 1 and base_temperature_k.shape[0] != state_rise_k.shape[0]):
        raise ValueError("thermal_outputs: out must have B rows and t_base 1 or B entries")
    if out_observer_temperature_k.shape[1] + 1 != observer_lag_boundaries.shape[0]:
        raise ValueError("thermal_outputs: out must have O = len(obs_ptr) - 1 columns")
    for world_index in range(state_rise_k.shape[0]):
        write_observer_temperatures_for_world(state_rise_k[world_index], observer_lag_boundaries, base_temperature_k[shared_or_world_row_index(world_index, base_temperature_k.shape[0])], out_observer_temperature_k[world_index])

@njit(cache=True)
def separate_known_heat_and_source_gain_for_observer(
    state_rise_k: Float64Array,  # state_rise_k = x (K) - lag-state temperature rises updated in place - type float64 ndarray, shape (M,)
    state_retention: Float64Array,  # state_retention = a (1) - retained thermal state fractions - type float64 ndarray, shape (M,)
    start_power_gain_k_per_w: Float64Array,  # start_power_gain_k_per_w = c0 (K/W) - starting-power gain - type float64 ndarray, shape (M,)
    end_power_gain_k_per_w: Float64Array,  # end_power_gain_k_per_w = c1 (K/W) - ending-power gain - type float64 ndarray, shape (M,)
    lag_source_indices: Int64Array,  # lag_source_indices = s_m (1) - source index driving each lag - type int64 ndarray, shape (M,)
    observer_lag_boundaries: Int64Array,  # observer_lag_boundaries = p_observer (1) - lag-array boundaries of each observer - type int64 ndarray, shape (O+1,)
    observer_index: int,  # observer_index = o (1) - observer index - type int scalar
    unknown_source_index: int,  # unknown_source_index = s_self (1) - unknown heat-source index - type int scalar
    start_source_power_w: Float64Array,  # start_source_power_w = P_start (W) - source powers at the step boundary - type float64 ndarray, shape (S,)
    end_source_power_w: Float64Array,  # end_source_power_w = P_end (W) - source powers at the step boundary - type float64 ndarray, shape (S,)
    source_residue_scale: Float64Array,  # source_residue_scale = s_source (1) - per-source residue multipliers - type float64 ndarray, shape (S,)
) -> tuple[
    float,  # return[0] = T_known (K) - temperature rise from stored heat and known sources - type float scalar
    float,  # return[1] = g_self (K/W) - gain from the unknown source held over the step - type float scalar
]:
    known_rise_k = 0.0
    self_gain_k_per_w = 0.0
    for lag_index in range(observer_lag_boundaries[observer_index], observer_lag_boundaries[observer_index + 1]):
        source_index = lag_source_indices[lag_index]
        known_rise_k += state_retention[lag_index] * state_rise_k[lag_index]
        if source_index == unknown_source_index:
            self_gain_k_per_w += source_residue_scale[source_index] * (start_power_gain_k_per_w[lag_index] + end_power_gain_k_per_w[lag_index])
        else:
            known_rise_k += source_residue_scale[source_index] * (start_power_gain_k_per_w[lag_index] * start_source_power_w[source_index] + end_power_gain_k_per_w[lag_index] * end_source_power_w[source_index])
    return (
        known_rise_k,
        self_gain_k_per_w,
    )

def sha256_file(
    path: str | Path,  # path = path (1) - thermal artifact path - type str or Path
) -> (
    str  # return = digest (1) - hexadecimal SHA-256 checksum - type str
):
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for chunk in iter(lambda: stream.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()

def build_rom_sidecar_path(
    path: str | Path,  # path = path (1) - thermal artifact path - type str or Path
) -> (
    Path  # return = path (1) - canonical sidecar artifact path - type Path
):
    return path.with_name(path.stem + ".sidecar.json")

def find_rom_sidecar_path(
    path: str | Path,  # path = path (1) - thermal artifact path - type str or Path
) -> (
    Path | None  # return = path (1) - existing sidecar path or no match - type Path or None
):
    # same candidates as mrm.params.config.sidecar_candidates (minus the .meta.json names)
    for candidate in (build_rom_sidecar_path(path), path.with_name(path.name + ".sidecar.json"), path.with_suffix(".json")):
        if candidate.exists():
            return candidate
    return None

def build_thermal_rom_path(
    family: str,  # family = family (1) - heater-family artifact name - type str
    film_nm: float,  # film_nm = d_film (nm) - silicon-film thickness - type float scalar
    root: str | Path | None = None,  # root = root (1) - optional artifact directory - type str, Path, or None
) -> (
    Path  # return = path (1) - thermal ROM artifact path - type Path
):
    base = Path(root) if root is not None else Path(__file__).resolve().parents[1] / "data" / "extracted"
    return base / f"thermal_rom_{family}_{int(round(float(film_nm)))}.npz"

def __post_init__(
    self: ThermalRom,  # self = self (mixed units) - record fields and units described above the class - type ThermalRom record
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):
    k = np.asarray(self.taus_s).shape[0]
    s, o = len(self.sources), len(self.observers)
    if np.asarray(self.self_res).shape != (s, o, k):
        raise RomIntegrityError(f"self_res shape {np.asarray(self.self_res).shape} != (S, O, K) = {(s, o, k)}")
    d = np.asarray(self.cross_r_um).shape[0]
    if np.asarray(self.cross_res).shape != (s, o, d, k):
        raise RomIntegrityError(f"cross_res shape {np.asarray(self.cross_res).shape} != {(s, o, d, k)}")
    bad = ([n for n in self.sources if n not in SOURCE_KINDS]
           + [n for n in self.observers if n not in OBSERVER_KINDS])
    if bad:
        raise RomIntegrityError(f"unknown source/observer kinds {bad}")
    tau = np.asarray(self.taus_s, dtype=float)
    if np.any(~(tau > 0)) or np.any(np.diff(tau) <= 0):
        raise RomIntegrityError("taus_s must be positive and strictly increasing")
    if d and np.any(np.diff(np.asarray(self.cross_r_um, dtype=float)) <= 0):
        raise RomIntegrityError("cross_r_um must be strictly increasing")
    for nm, arr in (("self_res", self.self_res), ("cross_res", self.cross_res)):
        if not np.all(np.isfinite(arr)):
            raise RomIntegrityError(f"{nm} contains non-finite values")

def load_rom(
    path: str | Path,  # path = path (1) - thermal artifact path - type str or Path
    *,
    verify: bool = True,  # verify = verify (1) - require schema and checksum verification - type bool scalar
    warn: bool = True,  # warn = warn (1) - emit warnings for missing or failed validation metrics - type bool scalar
) -> (
    ThermalRom  # return = model (mixed units) - validated poles, residues, and sidecar metadata - type ThermalRom record
):
    path = Path(path)
    side_path = find_rom_sidecar_path(path)
    meta: dict = {}
    if side_path is not None:
        meta = json.loads(side_path.read_text())
    elif verify:
        raise RomIntegrityError(f"missing sidecar {build_rom_sidecar_path(path)}")
    if verify:
        if meta.get("schema") != SCHEMA_ROM:
            raise RomIntegrityError(f"{side_path}: schema {meta.get('schema')!r} != {SCHEMA_ROM!r}")
        digest = sha256_file(path)
        if meta.get("sha256") != digest:
            raise RomIntegrityError(f"{path}: sha256 {digest} does not match the sidecar ({meta.get('sha256')})")
    with np.load(path, allow_pickle=False) as z:
        taus = np.asarray(z["taus_s"], np.float64)
        sources = tuple(str(s) for s in z["sources"])
        observers = tuple(str(s) for s in z["observers"])
        self_res = np.asarray(z["self_res"], np.float64)
        cross_r = np.asarray(z["cross_r_um"], np.float64)
        cross_res = np.asarray(z["cross_res"], np.float64)
        offsets = {}
        # names key - 'site_offset_names' (what both writers write).
        # 'site_names' is accepted as a fallback
        name_key = next((k for k in ("site_offset_names", "site_names") if k in z.files), None)
        if name_key is not None and "site_offsets_um" in z.files:
            for n, xy in zip(z[name_key], np.asarray(z["site_offsets_um"], np.float64).reshape(-1, 2)):
                offsets[str(n)] = (float(xy[0]), float(xy[1]))
    # sidecar fallbacks - a top-level site_offsets_um dict, or the extraction config (inputs.config.site_offsets_um)
    cfg_offs = ((meta.get("inputs") or {}).get("config") or {}).get("site_offsets_um") or {}
    for src in (meta.get("site_offsets_um") or {}, cfg_offs):
        offsets.update({k: tuple(map(float, v)) for k, v in src.items() if k not in offsets})
    meta = dict(meta)
    meta["path"] = str(path)
    rom = ThermalRom(taus, sources, observers, self_res, cross_r, cross_res, offsets, meta)
    if warn:
        warn_about_rom_quality(rom)
    return rom

def read_rom_validation_metrics(
    meta: dict[str, Any],  # meta = metadata (mixed units) - provenance and validation fields - type dict with string keys and metadata values
) -> (
    dict[str, float | None]  # return = metrics (mixed units) - relative step error, magnitude error in dB, phase error in deg, and relative superposition error - type dict of named floats or None
):
    v = dict(meta.get("validation") or {})
    out = {k: v.get(k) for k in ("step_max_rel_err", "freq_max_db_err", "freq_max_deg_err", "superposition_rel_err")}
    nested = {"step_max_rel_err": "max_time_err_frac_of_dc", "freq_max_db_err": "max_db",
              "freq_max_deg_err": "max_deg"}
    for key, sub in nested.items():
        if out[key] is None:
            vals = [float(v[g][sub]) for g in ("self", "nearest_neighbour")
                    if isinstance(v.get(g), Mapping) and v[g].get(sub) is not None]
            out[key] = max(vals) if vals else None
    if out["superposition_rel_err"] is None:
        for st in (meta.get("stages") or {}).values():
            if isinstance(st, Mapping) and st.get("superposition_rel_err") is not None:
                out["superposition_rel_err"] = float(st["superposition_rel_err"])
    return out

def warn_about_rom_quality(
    rom: ThermalRom,  # rom = model (mixed units) - extracted poles, thermal residues, and site metadata - type ThermalRom record
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):
    v = read_rom_validation_metrics(rom.meta)
    checks = (("step_max_rel_err", ROM_STEP_ERR_MAX), ("freq_max_db_err", ROM_FREQ_DB_MAX),
              ("freq_max_deg_err", ROM_FREQ_DEG_MAX), ("superposition_rel_err", ROM_SUPERPOSITION_MAX))
    for key, lim in checks:
        val = v.get(key)
        if val is None:
            warnings.warn(f"thermal ROM {rom.meta.get('path')}: sidecar lacks validation.{key}",
                          RuntimeWarning, stacklevel=3)
        elif not (abs(float(val)) <= lim):
            warnings.warn(f"thermal ROM {rom.meta.get('path')}: validation.{key} = {val} exceeds {lim}",
                          RuntimeWarning, stacklevel=3)
    if rom.taus_s[0] > ROM_TAU_FAST_MAX_S:
        warnings.warn(f"thermal ROM has no pole below {ROM_TAU_FAST_MAX_S} s; the optical self-heating solve needs "
                      "the fast poles of the waveguide core", RuntimeWarning, stacklevel=3)
    if rom.taus_s[-1] < ROM_TAU_SLOW_MIN_S:
        warnings.warn(f"thermal ROM has no pole above {ROM_TAU_SLOW_MIN_S} s; the crosstalk needs the ms poles",
                      RuntimeWarning, stacklevel=3)

def validate_site_coordinates_um(
    coordinates_um: ArrayLike,  # coordinates_um = r (um) - site coordinates - type array-like, shape (2,) or (N, 2)
    expected_site_count: int | None = None,  # expected_site_count = N (1) - optional required coordinate count - type int or None
    name: str = "xy",  # name = name (1) - element name or diagnostic parameter label - type str
) -> (
    Float64Array  # return = r_sites (um) - validated site coordinates - type float64 ndarray, shape (N, 2)
):
    coordinates = np.asarray(coordinates_um, dtype=np.float64)
    if coordinates.ndim == 1 and coordinates.shape[0] == 2:
        coordinates = coordinates[None, :]
    if coordinates.ndim != 2 or coordinates.shape[1] != 2:
        raise ValueError(f"{name} must be (n, 2) in um, got shape {coordinates.shape}")
    if expected_site_count is not None and coordinates.shape[0] != expected_site_count:
        raise ValueError(f"{name} must have {expected_site_count} rows, got {coordinates.shape[0]}")
    return coordinates

def __post_init__(
    self: LayoutSites,  # self = self (mixed units) - record fields and units described above the class - type LayoutSites record
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):
    n = validate_site_coordinates_um(self.ring_xy_um, name="ring_xy_um").shape[0]
    object.__setattr__(self, "ring_xy_um", validate_site_coordinates_um(self.ring_xy_um, name="ring_xy_um"))
    for nm in ("pd_xy_um", "driver_xy_um"):
        v = getattr(self, nm)
        if v is not None:
            object.__setattr__(self, nm, validate_site_coordinates_um(v, n, nm))
    if self.temp_sensor_xy_um is not None:
        ts = validate_site_coordinates_um(self.temp_sensor_xy_um, name="temp_sensor_xy_um")
        object.__setattr__(self, "temp_sensor_xy_um", ts)
        ring = (np.full(ts.shape[0], -1, np.int64) if self.temp_sensor_ring is None
                else np.asarray(self.temp_sensor_ring, np.int64).reshape(-1))
        if ring.shape[0] != ts.shape[0] or np.any(ring >= n) or np.any(ring < -1):
            raise ValueError("temp_sensor_ring must have one entry per sensor, each -1 or a ring index")
        object.__setattr__(self, "temp_sensor_ring", ring)
        names = tuple(self.temp_sensor_names) or tuple(f"ts{i}" for i in range(ts.shape[0]))
        object.__setattr__(self, "temp_sensor_names", names)
    if self.aggressor_xy_um is not None:
        ag = validate_site_coordinates_um(self.aggressor_xy_um, name="aggressor_xy_um")
        object.__setattr__(self, "aggressor_xy_um", ag)
        names = tuple(self.aggressor_names) or tuple(f"aggressor{i}" for i in range(ag.shape[0]))
        object.__setattr__(self, "aggressor_names", names)

@property
def n_rings(
    self: LayoutSites,  # self = self (mixed units) - record fields and units described above the class - type LayoutSites record
) -> (
    int  # return = N (1) - number of rings - type int scalar
):
    return self.ring_xy_um.shape[0]

@staticmethod
def from_sites(
    sites: Mapping[str, Mapping[str, Any]] | None,  # sites = sites (mixed units) - named site records with x_um, y_um, kind, and optional ring - type mapping or None
    n_rings: int,  # n_rings = N (1) - number of rings - type int scalar
    ring_pitch_um: float | None = None,  # ring_pitch_um = d_pitch (um) - optional spacing for missing ring sites - type float or None
    temp_sensors: Sequence[Mapping[str, Any]] | None = None,  # temp_sensors = sensors (mixed units) - sensor site or attachment records - type sequence of mappings or None
) -> (
    LayoutSites  # return = sites (um) - parsed ring, driver, sensor, photodiode, and aggressor positions - type LayoutSites record
):
    sites = dict(sites or {})
    referenced = {str(spec["site"]) for spec in (temp_sensors or ()) if spec.get("site")}
    ring_xy = np.full((n_rings, 2), np.nan)
    pd = np.full((n_rings, 2), np.nan)
    drv = np.full((n_rings, 2), np.nan)
    shared_drv = None
    ag_xy, ag_names, ts_xy, ts_ring, ts_names = [], [], [], [], []

    # read a ring index from the site field or trailing digits.
    def site_ring_index(
        name: str,  # name = name (1) - element name or diagnostic parameter label - type str
        spec: Mapping[str, Any],  # spec = site (mixed units) - site record with an optional ring field - type mapping
    ) -> (
        int | None  # return = k (1) - ring index from the field or trailing digits - type int or None
    ):
        if "ring" in spec and spec["ring"] is not None:
            return int(spec["ring"])
        digits = ""
        for ch in reversed(str(name)):
            if ch.isdigit():
                digits = ch + digits
            else:
                break
        return int(digits) if digits else None

    for name, spec in sites.items():
        kind = spec.get("kind", "other")
        p = (float(spec["x_um"]), float(spec["y_um"]))
        i = site_ring_index(name, spec)
        if kind == "ring":
            if i is None or not 0 <= i < n_rings:
                raise ValueError(f"ring site {name!r} needs a ring index 0..{n_rings - 1}")
            ring_xy[i] = p
        elif kind == "monitor_pd":
            if i is None or not 0 <= i < n_rings:
                raise ValueError(f"monitor_pd site {name!r} needs a ring index")
            pd[i] = p
        elif kind == "driver":
            if i is None:
                shared_drv = p
            elif 0 <= i < n_rings:
                drv[i] = p
        elif kind == "aggressor" or (kind == "heater" and (i is None or "ring" not in spec)):
            ag_xy.append(p)
            ag_names.append(str(name))
        elif kind == "temp_sensor" and str(name) not in referenced:
            ts_xy.append(p)
            ts_ring.append(-1)
            ts_names.append(str(name))
    missing = np.isnan(ring_xy[:, 0])
    if np.any(missing):
        if ring_pitch_um is None and n_rings > 1:
            raise ValueError(f"layout has no site for rings {np.flatnonzero(missing).tolist()} and no "
                             "layout.ring_pitch_um")
        pitch = 0.0 if ring_pitch_um is None else float(ring_pitch_um)
        ring_xy[missing, 0] = np.flatnonzero(missing) * pitch
        ring_xy[missing, 1] = 0.0
    if shared_drv is not None:
        drv[np.isnan(drv[:, 0])] = shared_drv
    centroid = ring_xy.mean(axis=0)
    for k, spec in enumerate(temp_sensors or ()):
        name = str(spec.get("name", f"ts{k}"))
        if spec.get("site"):
            s = sites[spec["site"]]
            ts_xy.append((float(s["x_um"]), float(s["y_um"])))
            ts_ring.append(-1)
        else:
            att = str(spec.get("attach", "die"))
            if att.startswith("ring_"):
                i = int(att.split("_", 1)[1])
                ts_xy.append(tuple(ring_xy[i]))
                ts_ring.append(i)
            elif att == "bank":
                ts_xy.append(tuple(centroid))
                ts_ring.append(-1)
            else:   # die - assumed 1 mm from the bank centroid
                ts_xy.append((centroid[0], centroid[1] + 1000.0))
                ts_ring.append(-1)
        ts_names.append(name)
    return LayoutSites(          # NaN rows - PD at the model's default offset, no driver for that ring
        ring_xy,
        None if np.all(np.isnan(pd[:, 0])) else pd,
        None if np.all(np.isnan(drv[:, 0])) else drv,
        np.array(ts_xy, float).reshape(-1, 2) if ts_xy else None,
        np.array(ts_ring, np.int64) if ts_xy else None, tuple(ts_names),
        np.array(ag_xy, float).reshape(-1, 2) if ag_xy else None, tuple(ag_names))

def site_ring_index(
    name: str,  # name = name (1) - element name or diagnostic parameter label - type str
    spec: Mapping[str, Any],  # spec = site (mixed units) - site record with an optional ring field - type mapping
) -> (
    int | None  # return = k (1) - ring index from the field or trailing digits - type int or None
):
    if "ring" in spec and spec["ring"] is not None:
        return int(spec["ring"])
    digits = ""
    for ch in reversed(str(name)):
        if ch.isdigit():
            digits = ch + digits
        else:
            break
    return int(digits) if digits else None

@staticmethod
def textbook_corner(
    **kw: Any,  # kw = overrides (field units) - InterimRom field overrides - type keyword values with InterimRom field types
) -> (
    InterimRom  # return = model (mixed units) - interim parameters for the textbook corner - type InterimRom record
):
    base = dict(tau_fast_s=10e-6, share_fast_frac=0.75, tau_slow_s=300e-6, tail_share_frac=0.0,
                xt_nearest_frac=0.10, xt_next_frac=0.03, xt_floor_frac=0.0, crosstalk_dynamics="self",
                name="interim_textbook_corner")
    base.update(kw)
    return InterimRom(**base)

def calculate_crosstalk_time_constant_s(
    d_um: ArrayLike,  # d_um = d (um) - source-to-victim distance or site centre distance - type array-like, broadcast input shape
    tau_ref_s: ArrayLike = 4.1e-3,  # tau_ref_s = tau_ref (s) - reference or minimum crosstalk time constant - type array-like, broadcast input shape
    dist_ref_um: float = 60.0,  # dist_ref_um = d_ref (um) - reference distance for the diffusion law - type float scalar
    tau_min_s: ArrayLike = 1.0e-4,  # tau_min_s = tau_min (s) - reference or minimum crosstalk time constant - type array-like, broadcast input shape
    tau_far_s: ArrayLike | None = None,  # tau_far_s = tau_far (s) - optional far-field time constant, or the extracted distance table - type array-like or None
    far_um: float = 100.0,  # far_um = d_far (um) - near-field cutoff for the literal distance law - type float scalar
    law: str = "capped",  # law = law (1) - capped or literal distance law - type str
) -> (
    RealValue  # return = tau_cross (s) - crosstalk time constant at each distance - type real scalar or float64 ndarray, shape broadcast input shape
):
    d = np.asarray(d_um, dtype=np.float64)
    near = np.maximum(np.asarray(tau_min_s, float), np.asarray(tau_ref_s, float) * (d / float(dist_ref_um)) ** 2)
    if tau_far_s is None:
        far = np.interp(d, XT_TABLE_D_UM, XT_TABLE_TAU_S)
    else:
        far = np.broadcast_to(np.asarray(tau_far_s, float), np.broadcast(d, np.asarray(tau_far_s, float)).shape)
    if law == "literal":
        return np.where(d <= float(far_um), near, far)
    if law != "capped":
        raise ValueError(f"crosstalk tau law must be 'capped' or 'literal', got {law!r}")
    return np.maximum(np.minimum(near, far), np.asarray(tau_min_s, float))

def calculate_site_coupling_fraction(
    d_um: ArrayLike,  # d_um = d (um) - source-to-victim distance or site centre distance - type array-like, broadcast input shape
    nearest_frac: ArrayLike = 0.03,  # nearest_frac = c_nearest (1) - coupling fraction at the reference distance - type array-like, broadcast input shape
    floor_frac: ArrayLike = 0.015,  # floor_frac = c_floor (1) - minimum site coupling fraction - type array-like, broadcast input shape
    ref_um: float = 60.0,  # ref_um = d_ref (um) - reference distance for site coupling - type float scalar
    max_frac: float = 1.0,  # max_frac = c_max (1) - maximum site coupling fraction - type float scalar
) -> (
    RealValue  # return = c_site (1) - site coupling relative to heater-to-ring DC gain - type real scalar or float64 ndarray, shape broadcast input shape
):
    d = np.maximum(np.asarray(d_um, dtype=np.float64), 1e-6)
    c = np.asarray(nearest_frac, float) * float(ref_um) / d
    return np.clip(c, np.asarray(floor_frac, float), float(max_frac))

@property
def batch(
    self: ThermalSystem,  # self = self (mixed units) - record fields and units described above the class - type ThermalSystem record
) -> (
    int  # return = B (1) - number of worlds - type int scalar
):
