@property
def n_lags(
    self: ThermalSystem,  # self = self (mixed units) - record fields and units described above the class - type ThermalSystem record
) -> (
    int  # return = M (1) - number of thermal lag states - type int scalar
):
    return self.taus_s.shape[1]

@property
def n_src(
    self: ThermalSystem,  # self = self (mixed units) - record fields and units described above the class - type ThermalSystem record
) -> (
    int  # return = S (1) - number of heat sources - type int scalar
):
    return self.src_kind.shape[0]

@property
def n_obs(
    self: ThermalSystem,  # self = self (mixed units) - record fields and units described above the class - type ThermalSystem record
) -> (
    int  # return = O (1) - number of temperature observers - type int scalar
):
    return self.obs_kind.shape[0]

def coefficients(
    self: ThermalSystem,  # self = self (mixed units) - record fields and units described above the class - type ThermalSystem record
    h_s: float,  # h_s = h (s) - thermal step duration - type float scalar
) -> tuple[
    Float64Array,  # return[0] = a (1) - retained state fractions - type float64 ndarray, shape (B, M)
    Float64Array,  # return[1] = c_start (K/W) - starting-power gains - type float64 ndarray, shape (B, M)
    Float64Array,  # return[2] = c_end (K/W) - ending-power gains - type float64 ndarray, shape (B, M)
]:
    return calculate_linear_hold_coefficients(self.taus_s, self.res_k_per_w, h_s)

def zero_state(
    self: ThermalSystem,  # self = self (mixed units) - record fields and units described above the class - type ThermalSystem record
    batch: int | None = None,  # batch = B (1) - optional number of worlds - type int or None
) -> (
    Float64Array  # return = x (K) - zero initial temperature rises - type float64 ndarray, shape (B, M)
):
    return np.zeros((self.batch if batch is None else int(batch), self.n_lags))

def steady_state(
    self: ThermalSystem,  # self = self (mixed units) - record fields and units described above the class - type ThermalSystem record
    u_w: ArrayLike,  # u_w = P_source (W) - constant source powers - type array-like, shape (S,) or (B, S)
) -> (
    Float64Array  # return = x_ss (K) - steady lag-state temperature rises - type float64 ndarray, shape (B, M)
):
    u = np.atleast_2d(np.asarray(u_w, dtype=np.float64))
    return self.res_k_per_w * u[:, self.lag_src]

def source_index(
    self: ThermalSystem,  # self = self (mixed units) - record fields and units described above the class - type ThermalSystem record
    kind: str,  # kind = kind (1) - source or observer kind name - type str
    ring: int | None = None,  # ring = k (1) - physical ring index or no ring filter - type int or None
    name: str | None = None,  # name = name (1) - optional exact element name - type str or None
) -> (
    int  # return = s (1) - matching heat-source index - type int scalar
):
    return find_thermal_element_index(self.src_names, self.src_kind, self.src_ring, SOURCE_KINDS, kind, ring, name)

def observer_index(
    self: ThermalSystem,  # self = self (mixed units) - record fields and units described above the class - type ThermalSystem record
    kind: str,  # kind = kind (1) - source or observer kind name - type str
    ring: int | None = None,  # ring = k (1) - physical ring index or no ring filter - type int or None
    name: str | None = None,  # name = name (1) - optional exact element name - type str or None
) -> (
    int  # return = o (1) - matching temperature-observer index - type int scalar
):
    return find_thermal_element_index(self.obs_names, self.obs_kind, self.obs_ring, OBSERVER_KINDS, kind, ring, name)

def find_thermal_element_index(
    names: tuple[str, ...],  # names = names (1) - ordered element names - type tuple of strings
    kinds: Int64Array,  # kinds = kind_indices (1) - kind code of each element - type int64 ndarray, shape (element_count,)
    rings: Int64Array,  # rings = ring_indices (1) - ring attachment of each element - type int64 ndarray, shape (element_count,)
    kind_list: tuple[str, ...],  # kind_list = kind_names (1) - ordered source or observer kind names - type tuple of strings
    kind: str,  # kind = kind (1) - source or observer kind name - type str
    ring: int | None,  # ring = k (1) - physical ring index or no ring filter - type int or None
    name: str | None,  # name = name (1) - optional exact element name - type str or None
) -> (
    int  # return = index (1) - unique matching element index - type int scalar
):
    if name is not None:
        if name in names:
            return names.index(name)
        raise KeyError(f"no element named {name!r}")
    k = kind_list.index(kind)
    hit = np.flatnonzero((kinds == k) & ((rings == ring) if ring is not None else True))
    if hit.size != 1:
        raise KeyError(f"{kind} ring={ring}: {hit.size} matches")
    return int(hit[0])

def normalize_world_parameter_vector(
    values: ArrayLike,  # values = values (input units) - parameter values to normalize - type array-like, scalar, (B,), or (B, 1)
    name: str,  # name = name (1) - element name or diagnostic parameter label - type str
) -> (
    Float64Array  # return = parameter (input units) - normalized world-parameter vector - type float64 ndarray, shape (1 or B,)
):
    parameter_array = np.asarray(values, dtype=np.float64)
    if parameter_array.ndim == 0:
        return parameter_array.reshape(1)
    if parameter_array.ndim == 2 and parameter_array.shape[1] == 1:
        return parameter_array[:, 0]
    if parameter_array.ndim != 1:
        raise ValueError(f"{name}: expected a scalar or (B,), got shape {parameter_array.shape}")
    return parameter_array

def infer_world_count(
    values: dict[str, Float64Array],  # values = parameters (parameter units) - world-parameter arrays keyed by parameter name - type dict of float64 ndarrays with 1 or B rows
) -> (
    int  # return = B (1) - common world count inferred from parameter arrays - type int scalar
):
    world_count = 1
    for name, parameter_array in values.items():
        row_count = parameter_array.shape[0]
        if row_count != 1:
            if world_count not in (1, row_count):
                raise ValueError(f"inconsistent batch sizes: {name} has {row_count}, another has {world_count}")
            world_count = row_count
    return world_count

def encode_thermal_scaling_hypotheses(
    hypotheses: str | Sequence[str] | ArrayLike,  # hypotheses = hypotheses (1) - scaling hypothesis names or integer codes - type str, sequence of strings, or integer array-like
    world_count: int,  # world_count = B (1) - number of worlds - type int scalar
) -> (
    Int64Array  # return = hypothesis (1) - integer scaling-hypothesis codes - type int64 ndarray, shape (B,)
):
    if isinstance(hypotheses, str):
        hypotheses = [hypotheses]
    hypothesis_values = np.asarray(hypotheses)
    if hypothesis_values.dtype.kind in "iu":
        codes = hypothesis_values.astype(np.int64).reshape(-1)
    else:
        try:
            codes = np.array([SCALING_HYPOTHESES.index(str(x)) for x in hypothesis_values.reshape(-1)], np.int64)
        except ValueError as e:
            raise ValueError(f"scaling_hypothesis must be one of {SCALING_HYPOTHESES}, got {hypotheses!r}") from e
    if np.any((codes < 0) | (codes >= len(SCALING_HYPOTHESES))):
        raise ValueError(f"scaling_hypothesis codes out of range: {codes}")
    if codes.shape[0] not in (1, world_count):
        raise ValueError(f"scaling_hypothesis has {codes.shape[0]} entries, batch is {world_count}")
    return np.broadcast_to(codes, (world_count,)).copy()

def __init__(
    self: _Lags,  # self = self (mixed units) - record fields and units described above the class - type _Lags record
    B: int,  # B = B (1) - number of worlds - type int scalar
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):
    self.world_count = B
    self.observer_indices, self.source_indices, self.time_constants_s, self.residues_k_per_w = [], [], [], []
    self.layer_codes, self.pair_codes, self.tail_replaceable, self.tail_flags, self.fixed_time_constants = [], [], [], [], []

def __init__(
    self: _Elements,  # self = self (mixed units) - record fields and units described above the class - type _Elements record
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):
    self.src_kind, self.src_ring, self.src_names, self.src_xy = [], [], [], []
    self.obs_kind, self.obs_ring, self.obs_names, self.obs_xy = [], [], [], []

def build_thermal_sources_and_observers(
    layout: LayoutSites,  # layout = sites (um) - source and observer site coordinates - type LayoutSites record
    n: int,  # n = N (1) - number of rings - type int scalar
    src_kinds: Sequence[str],  # src_kinds = source_kinds (1) - source kind names to include - type sequence of strings
    obs_kinds: Sequence[str],  # obs_kinds = observer_kinds (1) - observer kind names to include - type sequence of strings
    pd_offset: Sequence[float],  # pd_offset = Delta_r_PD (um) - default monitor offset from its ring centre - type two coordinates
    ts_offset: Sequence[float],  # ts_offset = Delta_r_sensor (um) - default attached-sensor offset - type two coordinates
    driver_offset: Sequence[float] | None = None,  # driver_offset = Delta_r_driver (um) - optional driver offset from its ring centre - type two coordinates or None
) -> tuple[
    _Elements,  # return[0] = elements (mixed units) - source and observer kinds, names, coordinates, and ring attachments - type thermal element builder
    dict[str, Int64Array],  # return[1] = indices (1) - per-ring, temperature-sensor, and aggressor index maps - type dict of named int64 ndarrays
]:
    el = _Elements()
    idx = {k: np.full(n, -1, np.int64) for k in ("heater_src", "wg_src", "junction_src", "driver_src",
                                                    "ring_obs", "heater_obs", "pd_obs")}
    ring_xy = layout.ring_xy_um
    for i in range(n):
        if "heater" in src_kinds:
            idx["heater_src"][i] = el.add_src(SRC_HEATER, i, f"heater{i}", ring_xy[i])
        if "waveguide_absorption" in src_kinds:
            idx["wg_src"][i] = el.add_src(SRC_WG, i, f"waveguide_absorption{i}", ring_xy[i])
        if "junction" in src_kinds:
            idx["junction_src"][i] = el.add_src(SRC_JUNCTION, i, f"junction{i}", ring_xy[i])
        if "driver" in src_kinds and (layout.driver_xy_um is not None or driver_offset is not None):
            dxy = (layout.driver_xy_um[i] if layout.driver_xy_um is not None
                   else ring_xy[i] + np.asarray(driver_offset, float))
            if np.all(np.isfinite(dxy)):          # a NaN row - this ring has no driver site
                idx["driver_src"][i] = el.add_src(SRC_DRIVER, i, f"driver{i}", dxy)
    agg = []
    if "aggressor" in src_kinds and layout.aggressor_xy_um is not None:
        for a, (nm, xy) in enumerate(zip(layout.aggressor_names, layout.aggressor_xy_um)):
            agg.append(el.add_src(SRC_AGGRESSOR, -1, nm, xy))
    for i in range(n):
        if "ring_mode_weighted" in obs_kinds:
            idx["ring_obs"][i] = el.add_obs(OBS_RING, i, f"ring_mode_weighted{i}", ring_xy[i])
        if "heater_resistor" in obs_kinds:
            idx["heater_obs"][i] = el.add_obs(OBS_HEATER, i, f"heater_resistor{i}", ring_xy[i])
        if "monitor_pd" in obs_kinds:
            pxy = layout.pd_xy_um[i] if layout.pd_xy_um is not None else np.full(2, np.nan)
            if not np.all(np.isfinite(pxy)):      # no PD site for this ring - the model's default offset
                pxy = ring_xy[i] + np.asarray(pd_offset, float)
            idx["pd_obs"][i] = el.add_obs(OBS_PD, i, f"monitor_pd{i}", pxy)
    ts = []
    if "temp_sensor" in obs_kinds and layout.temp_sensor_xy_um is not None:
        for t, nm in enumerate(layout.temp_sensor_names):
            r = int(layout.temp_sensor_ring[t])
            # an attached sensor sits at its ring plus the model's default offset (the offset of the ROM self table)
            xy = ring_xy[r] + np.asarray(ts_offset, float) if r >= 0 else layout.temp_sensor_xy_um[t]
            ts.append(el.add_obs(OBS_TEMP, r, nm, xy))
    idx["temp_obs"] = np.array(ts, np.int64)
    idx["aggressor_src"] = np.array(agg, np.int64)
    return (
        el,
        idx,
    )

def calculate_neighbor_ranks_and_distances(
    ring_xy: Float64Array,  # ring_xy = r_ring (um) - ring centre coordinates - type float64 ndarray, shape (N, 2)
) -> tuple[
    Int64Array,  # return[0] = rank (1) - symmetric neighbour ranks - type int64 ndarray, shape (N, N)
    Float64Array,  # return[1] = d (um) - ring centre distances - type float64 ndarray, shape (N, N)
]:
    n = ring_xy.shape[0]
    d = np.linalg.norm(ring_xy[:, None, :] - ring_xy[None, :, :], axis=-1)
    rank = np.full((n, n), 99, np.int64)
    for i in range(n):
        others = np.delete(np.arange(n), i)
        if others.size == 0:
            continue
        uniq = []
        for v in np.sort(d[i, others]):
            if not uniq or v > uniq[-1] * (1 + 1e-6) + 1e-9:
                uniq.append(v)
        for j in others:
            for r, v in enumerate(uniq[:2]):
                if abs(d[i, j] - v) <= v * 1e-6 + 1e-9:
                    rank[i, j] = r + 1
    rank = np.minimum(rank, rank.T)
    np.fill_diagonal(rank, 0)
    return (
        rank,
        d,
    )

def calculate_path_time_constant_s(
    d_cc: ArrayLike,  # d_cc = d_centres (um) - centre separation - type array-like, broadcast input shape
    r_src: ArrayLike,  # r_src = R_source (um) - element radius - type array-like, broadcast input shape
    r_obs: ArrayLike,  # r_obs = R_observer (um) - element radius - type array-like, broadcast input shape
) -> (
    Float64Array  # return = tau_cross (s) - time constants at source-to-victim distances - type float64 ndarray, shape (B,)
):
    # the law's distance is heat source to victim (its imec anchor, crosstalk_tau_s) - the centre distance less the radius of each ring element (0 for a point site)
    distance_um = np.maximum(d_cc - r_src - r_obs, 0.0)
    return calculate_crosstalk_time_constant_s(distance_um, parameter_arrays["xt_tau_ref"][:, 0], spec.xt_dist_ref_um, parameter_arrays["xt_tau_min"][:, 0],
                           None if spec.xt_tau_far_s is None else parameter_arrays["xt_tau_far"][:, 0], spec.xt_far_um,
                           spec.xt_tau_law)

def calculate_path_coupling_fraction(
    distance_um: ArrayLike,  # distance_um = d (um) - source-to-observer distance - type array-like, broadcast input shape
) -> (
    Float64Array  # return = c_site (1) - site coupling fractions - type float64 ndarray, shape (B,)
):
    return calculate_site_coupling_fraction(distance_um, parameter_arrays["xt_nearest"][:, 0], parameter_arrays["site_floor"][:, 0], spec.site_ref_um, spec.site_max_frac)

def append_extracted_heat_path_lags(
    rom: ThermalRom,  # rom = model (mixed units) - extracted poles, thermal residues, and site metadata - type ThermalRom record
    elements: _Elements,  # elements = elements (mixed units) - source and observer instances with ring attachments and coordinates - type thermal element builder
    layout: LayoutSites,  # layout = sites (um) - source and observer site coordinates - type LayoutSites record
    world_count: int,  # world_count = B (1) - number of worlds - type int scalar
    tau_split: float,  # tau_split = tau_split (s) - boundary between fast and slow time scales - type float scalar
    lag_builder: _Lags,  # lag_builder = lags (mixed units) - lag indices, time constants, and thermal residues - type thermal lag builder
    meta: dict[str, Any],  # meta = metadata (mixed units) - provenance and validation fields - type dict with string keys and metadata values
    tol_um: float = 1.0,  # tol_um = d_tol (um) - allowed site-offset deviation from the ROM self table - type float scalar
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):   # assumed - 1 um, well below the site sizes and offsets (tens of um)
    time_constants_s = np.asarray(rom.taus_s, float)
    site_src = {SRC_DRIVER: "driver"}
    site_obs = {OBS_PD: "monitor_pd", OBS_TEMP: "temp_sensor"}
    moved = set()

    # check whether a site matches the extracted self-table offset.
    def site_matches_rom_offset(
        name: str,  # name = name (1) - element name or diagnostic parameter label - type str
        xy: ArrayLike,  # xy = r_site (um) - site coordinates - type array-like, shape (2,)
        ring: int | None,  # ring = k (1) - physical ring index or no ring filter - type int or None
    ) -> (
        bool  # return = matches (1) - whether the site matches the ROM self-table offset - type bool scalar
    ):
        if name not in rom.site_offsets_um:
            return True                    # no default known - keep the self table (warned at assembly)
        offset_deviation_um = np.linalg.norm(xy - layout.ring_xy_um[ring] - np.asarray(rom.site_offsets_um[name], float))
        if offset_deviation_um > tol_um:
            moved.add(name)
            return False
        return True
    layer = np.where(time_constants_s < tau_split, LAYER_FAST, LAYER_SLOW)
    rom_source_indices = {SOURCE_KINDS.index(pole_index): i for i, pole_index in enumerate(rom.sources)}
    rom_observer_indices = {OBSERVER_KINDS.index(pole_index): i for i, pole_index in enumerate(rom.observers)}
    skipped, out_of_grid = set(), []
    distance_grid_um = np.asarray(rom.cross_r_um, float)

    # interpolate cross-path thermal residues at the site distance.
    def interpolate_cross_residues(
        rom_source_index: int,  # rom_source_index = si (1) - ROM source index - type int scalar
        rom_observer_index: int,  # rom_observer_index = oi (1) - ROM observer index - type int scalar
        distance_um: ArrayLike,  # distance_um = d (um) - source-to-observer distance - type array-like, broadcast input shape
    ) -> (
        Float64Array  # return = r (K/W) - distance-interpolated thermal residues - type float64 ndarray, shape (K,)
    ):
        if distance_grid_um.size == 0:
            return np.zeros_like(time_constants_s)
        if distance_um < distance_grid_um[0] or distance_um > distance_grid_um[-1]:
            out_of_grid.append(distance_um)
        return np.array([np.interp(distance_um, distance_grid_um, rom.cross_res[rom_source_index, rom_observer_index, :, pole_index]) for pole_index in range(time_constants_s.size)])

    for source_index in range(len(elements.src_kind)):
        source_kind, source_ring, source_xy_um = elements.src_kind[source_index], elements.src_ring[source_index], elements.src_xy[source_index]
        if source_kind not in rom_source_indices:
            skipped.add(SOURCE_KINDS[source_kind])
            continue
        rom_source_index = rom_source_indices[source_kind]
        for observer_index in range(len(elements.obs_kind)):
            observer_kind, observer_ring, observer_xy_um = elements.obs_kind[observer_index], elements.obs_ring[observer_index], elements.obs_xy[observer_index]
            if observer_kind not in rom_observer_indices:
                skipped.add(OBSERVER_KINDS[observer_kind])
                continue
            rom_observer_index = rom_observer_indices[observer_kind]
            same = source_ring >= 0 and observer_ring >= 0 and source_ring == observer_ring
            if same and (source_kind not in site_src or site_matches_rom_offset(site_src[source_kind], source_xy_um, source_ring)) and (
                    observer_kind not in site_obs or site_matches_rom_offset(site_obs[observer_kind], observer_xy_um, observer_ring)):
                thermal_residues_k_per_w, pair = np.asarray(rom.self_res[rom_source_index, rom_observer_index], float), PAIR_SELF
            elif same:
                thermal_residues_k_per_w, pair = interpolate_cross_residues(rom_source_index, rom_observer_index, float(np.linalg.norm(source_xy_um - observer_xy_um))), PAIR_SITE
            else:
                # interpolate using the extracted source-centre to observer-centre distance.
                # ring and heater elements use ring centres - other elements use site centres.
                thermal_residues_k_per_w = interpolate_cross_residues(rom_source_index, rom_observer_index, float(np.linalg.norm(source_xy_um - observer_xy_um)))
                pair = PAIR_CROSS if (source_ring >= 0 and observer_ring >= 0) else PAIR_SITE
            for pole_index in range(time_constants_s.size):
                if thermal_residues_k_per_w[pole_index] != 0.0:
                    lag_builder.add(observer_index, source_index, time_constants_s[pole_index], thermal_residues_k_per_w[pole_index], int(layer[pole_index]), pair, tailable=(pair == PAIR_SELF))
    if skipped:
        meta["rom_skipped_kinds"] = sorted(skipped)
    if moved:
        meta["rom_sites_off_default"] = sorted(moved)
        warnings.warn(f"layout {sorted(moved)} sites are more than {tol_um} um from the ROM self-table offsets "
                      f"{ {pole_index: rom.site_offsets_um[pole_index] for pole_index in sorted(moved)} } um: their same-ring pairs use the "
                      "distance table cross_res at the actual site distance", RuntimeWarning, stacklevel=3)
    if out_of_grid:
        warnings.warn(f"thermal ROM cross_r_um grid {distance_grid_um[0]}..{distance_grid_um[-1]} um does not cover distances "
                      f"{sorted(set(round(v, 2) for v in out_of_grid))[:6]} um; clamped to the grid ends "
                      "(radially symmetric table, valid for d > 2R)", RuntimeWarning, stacklevel=3)

def site_matches_rom_offset(
    name: str,  # name = name (1) - element name or diagnostic parameter label - type str
    xy: ArrayLike,  # xy = r_site (um) - site coordinates - type array-like, shape (2,)
    ring: int | None,  # ring = k (1) - physical ring index or no ring filter - type int or None
) -> (
    bool  # return = matches (1) - whether the site matches the ROM self-table offset - type bool scalar
):
    if name not in rom.site_offsets_um:
        return True                    # no default known - keep the self table (warned at assembly)
    offset_deviation_um = np.linalg.norm(xy - layout.ring_xy_um[ring] - np.asarray(rom.site_offsets_um[name], float))
    if offset_deviation_um > tol_um:
        moved.add(name)
        return False
    return True

def interpolate_cross_residues(
    rom_source_index: int,  # rom_source_index = si (1) - ROM source index - type int scalar
    rom_observer_index: int,  # rom_observer_index = oi (1) - ROM observer index - type int scalar
    distance_um: ArrayLike,  # distance_um = d (um) - source-to-observer distance - type array-like, broadcast input shape
) -> (
    Float64Array  # return = r (K/W) - distance-interpolated thermal residues - type float64 ndarray, shape (K,)
):
    if distance_grid_um.size == 0:
        return np.zeros_like(time_constants_s)
    if distance_um < distance_grid_um[0] or distance_um > distance_grid_um[-1]:
        out_of_grid.append(distance_um)
    return np.array([np.interp(distance_um, distance_grid_um, rom.cross_res[rom_source_index, rom_observer_index, :, pole_index]) for pole_index in range(time_constants_s.size)])

def replace_package_tail_preserving_dc_gain(
    lg: _Lags,  # lg = lags (mixed units) - lag indices, time constants, and thermal residues - type thermal lag builder
    tail_tau: ArrayLike,  # tail_tau = tau_tail (s) - absolute package-tail time constants - type array-like, shape (B,)
    tail_share: ArrayLike,  # tail_share = f_tail (1) - share of pair DC gain assigned to the package tail - type array-like, shape (B,)
) -> (
    None  # return = None - results are written into the supplied state or record - type None
):
    pairs: dict = {}
    for m in range(len(lg.observer_indices)):
        if lg.tail_replaceable[m]:
            pairs.setdefault((lg.observer_indices[m], lg.source_indices[m]), []).append(m)
    for (o, s), ms in pairs.items():
        pair_type = lg.pair_codes[ms[0]]
        dc = np.sum([lg.residues_k_per_w[m] for m in ms], axis=0)
        body = [m for m in ms if not lg.tail_flags[m]]
        tails = [m for m in ms if lg.tail_flags[m]]
        body_sum = np.sum([lg.residues_k_per_w[m] for m in body], axis=0) if body else np.zeros(lg.world_count)
        with np.errstate(divide="ignore", invalid="ignore"):
            fac = np.where(body_sum != 0.0, dc * (1.0 - tail_share) / body_sum, 0.0)
        for m in body:
            lg.residues_k_per_w[m] = lg.residues_k_per_w[m] * fac
        if tails:
            m = tails[0]
            lg.residues_k_per_w[m] = tail_share * dc
            lg.time_constants_s[m] = np.broadcast_to(tail_tau, (lg.world_count,)).copy()
            lg.fixed_time_constants[m] = True
            for extra in tails[1:]:
                lg.residues_k_per_w[extra] = np.zeros(lg.world_count)
        else:
            lg.add(o, s, tail_tau, tail_share * dc, LAYER_SLOW, pair_type, tailable=True, tail=True, fixed_tau=True)

def calculate_pair_dc_scale(
    dc_scale: ArrayLike | Mapping[str, ArrayLike],  # dc_scale = s_DC (1) - DC residue scales or source-to-observer matching rules - type array-like or mapping to array-like values
    sk_name: str,  # sk_name = source_kind (1) - source kind of the heat path - type str
    ok_name: str,  # ok_name = observer_kind (1) - observer kind of the heat path - type str
    B: int,  # B = B (1) - number of worlds - type int scalar
) -> (
    Float64Array  # return = s_DC (1) - product of all matching DC-scale rules - type float64 ndarray, shape (B,)
):
    if not isinstance(dc_scale, Mapping):
        return np.broadcast_to(normalize_world_parameter_vector(dc_scale, "dc_scale"), (B,))
    factor = np.ones(B)
    for key, value in dc_scale.items():
        if key == "*":
            factor = factor * normalize_world_parameter_vector(value, "dc_scale[*]")
            continue
        if "->" not in key:
            raise ValueError(f"dc_scale key {key!r} must be '*' or '<source>-><observer>'")
        source_pattern, observer_pattern = (pattern.strip() for pattern in key.split("->", 1))
        for pattern, valid_kinds in ((source_pattern, SOURCE_KINDS), (observer_pattern, OBSERVER_KINDS)):
            if pattern != "*" and pattern not in valid_kinds:
                raise ValueError(f"dc_scale key {key!r}: unknown kind {pattern!r}")
        if source_pattern in ("*", sk_name) and observer_pattern in ("*", ok_name):
            factor = factor * normalize_world_parameter_vector(value, f"dc_scale[{key}]")
    return np.broadcast_to(factor, (B,))

def validate_and_broadcast_interim_parameters(
    spec: InterimRom,  # spec = model (mixed units) - interim thermal resistance and time-constant parameters - type InterimRom record
    n: int,  # n = N (1) - number of rings - type int scalar
) -> (
    dict[str, Float64Array]  # return = parameters (field units) - validated interim parameters with defaults resolved - type dict of float64 ndarrays, shape (1 or B, 1 or N)
):
    # broadcast one interim parameter over worlds and rings.
    def broadcast_interim_ring_parameter(
        v: ArrayLike,  # v = parameter (field units) - interim parameter to broadcast - type array-like, scalar, (B,), or (B, N)
        name: str,  # name = name (1) - element name or diagnostic parameter label - type str
    ) -> (
        Float64Array  # return = parameter (input units) - parameter broadcast over worlds and rings - type float64 ndarray, shape (1 or B, 1 or N)
    ):
        a = np.asarray(v, dtype=np.float64)
        if a.ndim == 0:
            return a.reshape(1, 1)
        if a.ndim == 1:
            return a[:, None]
        if a.ndim == 2 and a.shape[1] in (1, n):
            return a
        raise ValueError(f"InterimRom.{name}: expected scalar, (B,) or (B, N), got shape {a.shape}")

    p = {"z0": broadcast_interim_ring_parameter(spec.z_heater_ring_k_per_w, "z_heater_ring_k_per_w"),
         "z_ratio": broadcast_interim_ring_parameter(spec.z_ratio_opt_heater, "z_ratio_opt_heater"),
         "tau_fast": broadcast_interim_ring_parameter(spec.tau_fast_s, "tau_fast_s"), "share_fast": broadcast_interim_ring_parameter(spec.share_fast_frac, "share_fast_frac"),
         "tau_slow": broadcast_interim_ring_parameter(spec.tau_slow_s, "tau_slow_s"), "tail_tau": broadcast_interim_ring_parameter(spec.tail_tau_s, "tail_tau_s"),
         "tail_share": broadcast_interim_ring_parameter(spec.tail_share_frac, "tail_share_frac"),
         "selfheat_tau": broadcast_interim_ring_parameter(spec.selfheat_tau_s, "selfheat_tau_s"),
         "heater_self_ratio": broadcast_interim_ring_parameter(spec.heater_self_ratio, "heater_self_ratio"),
         "heater_node_tau": broadcast_interim_ring_parameter(spec.heater_node_tau_s, "heater_node_tau_s"),
         "xt_nearest": broadcast_interim_ring_parameter(spec.xt_nearest_frac, "xt_nearest_frac"), "xt_floor": broadcast_interim_ring_parameter(spec.xt_floor_frac, "xt_floor_frac"),
         "xt_next": broadcast_interim_ring_parameter(0.0 if spec.xt_next_frac is None else spec.xt_next_frac, "xt_next_frac"),
         "xt_tau_ref": broadcast_interim_ring_parameter(spec.xt_tau_ref_s, "xt_tau_ref_s"), "xt_tau_min": broadcast_interim_ring_parameter(spec.xt_tau_min_s, "xt_tau_min_s"),
         "xt_tau_far": broadcast_interim_ring_parameter(0.0 if spec.xt_tau_far_s is None else spec.xt_tau_far_s, "xt_tau_far_s"),
         "ring_radius": broadcast_interim_ring_parameter(spec.ring_radius_um, "ring_radius_um")}
    p["site_floor"] = (p["xt_floor"] if spec.site_floor_frac is None
                       else broadcast_interim_ring_parameter(spec.site_floor_frac, "site_floor_frac"))
    z = p["z_ratio"]
    p["f_sh"] = (broadcast_interim_ring_parameter(spec.selfheat_share_frac, "selfheat_share_frac") if spec.selfheat_share_frac is not None
                 else (z - 1.0) / z)
    if np.any(p["z0"] <= 0):
        raise ValueError("z_heater_ring_k_per_w must be > 0")
    if np.any(z < 1.0):
        raise ValueError("z_ratio_opt_heater must be >= 1 (Z_opt/Z_heater >= 1 by reciprocity)")
    if np.any(p["heater_self_ratio"] < 1.0):
        raise ValueError("heater_self_ratio must be >= 1 (R_th,H >= Z_heater->ring)")
    if np.any((p["f_sh"] < 0) | (p["f_sh"] > 1)):
        raise ValueError("selfheat_share_frac must be in [0, 1]")
    if np.any(p["ring_radius"] < 0):
        raise ValueError("ring_radius_um must be >= 0")
    if np.any(p["site_floor"] < 0):
        raise ValueError("site_floor_frac must be >= 0")
    if np.any(p["share_fast"] < 0) or np.any(p["tail_share"] < 0) or np.any(p["share_fast"] + p["tail_share"] > 1):
        raise ValueError("share_fast_frac and tail_share_frac must be >= 0 with a sum <= 1")
    for k in ("tau_fast", "tau_slow", "tail_tau", "selfheat_tau", "heater_node_tau", "xt_tau_ref", "xt_tau_min"):
        if np.any(p[k] <= 0):
            raise ValueError(f"interim time constant {k} must be > 0")
    if spec.crosstalk_dynamics not in ("imec", "self"):
        raise ValueError("crosstalk_dynamics must be 'imec' or 'self'")
    return p

def broadcast_interim_ring_parameter(
    v: ArrayLike,  # v = parameter (field units) - interim parameter to broadcast - type array-like, scalar, (B,), or (B, N)
    name: str,  # name = name (1) - element name or diagnostic parameter label - type str
) -> (
    Float64Array  # return = parameter (input units) - parameter broadcast over worlds and rings - type float64 ndarray, shape (1 or B, 1 or N)
):
    a = np.asarray(v, dtype=np.float64)
    if a.ndim == 0:
        return a.reshape(1, 1)
    if a.ndim == 1:
        return a[:, None]
    if a.ndim == 2 and a.shape[1] in (1, n):
        return a
    raise ValueError(f"InterimRom.{name}: expected scalar, (B,) or (B, N), got shape {a.shape}")

def frequency_response(
    system: ThermalSystem,  # system = system (mixed units) - assembled thermal states, source maps, and observer maps - type ThermalSystem record
    f_hz: ArrayLike,  # f_hz = f (Hz) - frequencies at which to evaluate thermal response - type array-like, scalar or shape (F,)
    obs: ArrayLike | None = None,  # obs = observer_indices (1) - selected observers, or all observers when None - type integer scalar, array-like, or None
    src: ArrayLike | None = None,  # src = source_indices (1) - selected sources, or all sources when None - type integer scalar, array-like, or None
) -> (
    Complex128Array  # return = Z (K/W) - complex source-to-observer thermal impedances - type complex128 ndarray, shape (B, O_selected, S_selected, F)
):
    w = 2.0 * np.pi * np.atleast_1d(np.asarray(f_hz, np.float64))
    return sum_selected_thermal_responses(system, obs, src,
                       lambda tau, r: r[..., None] / (1.0 + 1j * w[None, None, :] * tau[..., None]))

def step_response(
    system: ThermalSystem,  # system = system (mixed units) - assembled thermal states, source maps, and observer maps - type ThermalSystem record
    t_s: ArrayLike,  # t_s = t (s) - times at which to evaluate thermal response - type array-like, scalar or shape (T,)
    obs: ArrayLike | None = None,  # obs = observer_indices (1) - selected observers, or all observers when None - type integer scalar, array-like, or None
    src: ArrayLike | None = None,  # src = source_indices (1) - selected sources, or all sources when None - type integer scalar, array-like, or None
) -> (
    Float64Array  # return = Z_step (K/W) - temperature rise per unit source-power step - type float64 ndarray, shape (B, O_selected, S_selected, T)
):
    t = np.atleast_1d(np.asarray(t_s, np.float64))
    return sum_selected_thermal_responses(system, obs, src, lambda tau, r: r[..., None] * -np.expm1(-t[None, None, :] / tau[..., None]))

def ramp_response(
    system: ThermalSystem,  # system = system (mixed units) - assembled thermal states, source maps, and observer maps - type ThermalSystem record
    t_s: ArrayLike,  # t_s = t (s) - times at which to evaluate thermal response - type array-like, scalar or shape (T,)
    obs: ArrayLike | None = None,  # obs = observer_indices (1) - selected observers, or all observers when None - type integer scalar, array-like, or None
    src: ArrayLike | None = None,  # src = source_indices (1) - selected sources, or all sources when None - type integer scalar, array-like, or None
) -> (
    Float64Array  # return = Z_ramp (K*s/W) - temperature response per unit source-power ramp rate - type float64 ndarray, shape (B, O_selected, S_selected, T)
):
    t = np.atleast_1d(np.asarray(t_s, np.float64))
    return sum_selected_thermal_responses(system, obs, src, lambda tau, r: r[..., None] * (
        t[None, None, :] + tau[..., None] * np.expm1(-t[None, None, :] / tau[..., None])))

def dc_gain(
    system: ThermalSystem,  # system = system (mixed units) - assembled thermal states, source maps, and observer maps - type ThermalSystem record
    obs: ArrayLike | None = None,  # obs = observer_indices (1) - selected observers, or all observers when None - type integer scalar, array-like, or None
    src: ArrayLike | None = None,  # src = source_indices (1) - selected sources, or all sources when None - type integer scalar, array-like, or None
) -> (
    Float64Array  # return = Z_DC (K/W) - steady thermal resistance of each source-to-observer path - type float64 ndarray, shape (B, O_selected, S_selected)
):
    return sum_selected_thermal_responses(system, obs, src, lambda tau, r: r[..., None])[..., 0]

def reciprocity_error(
    system: ThermalSystem,  # system = system (mixed units) - assembled thermal states, source maps, and observer maps - type ThermalSystem record
    f_hz: ArrayLike = (0.0, 1e3, 1e4, 1e5, 1e6),  # f_hz = f (Hz) - frequencies at which to evaluate thermal response - type array-like, scalar or shape (F,)
    b: int | None = None,  # b = b (1) - optional world index, or all worlds - type int or None
) -> (
    float  # return = error (1) - largest relative thermal reciprocity error - type float scalar
):
    H = frequency_response(system, f_hz)
    if b is not None:
        H = H[b:b + 1]
    n = system.n_rings
    num, scale = 0.0, 0.0
    combos = ((system.heater_src, system.heater_obs, system.heater_src, system.heater_obs),
              (system.wg_src, system.ring_obs, system.wg_src, system.ring_obs),
              (system.heater_src, system.ring_obs, system.wg_src, system.heater_obs))
    for s1, o1, s2, o2 in combos:
        for i in range(n):
            for j in range(n):
                if min(s1[j], o1[i], s2[i], o2[j]) < 0:
                    continue
                z1 = H[:, o1[i], s1[j]]
                z2 = H[:, o2[j], s2[i]]
                num = max(num, float(np.max(np.abs(z1 - z2))))
                scale = max(scale, float(np.max(np.abs(z1))), float(np.max(np.abs(z2))))
    return num / scale if scale > 0 else 0.0

def selfheat_dc_k_per_w(
    system: ThermalSystem,  # system = system (mixed units) - assembled thermal states, source maps, and observer maps - type ThermalSystem record
) -> (
    Float64Array  # return = Z_optical_self (K/W) - optical self-heating resistance of each ring - type float64 ndarray, shape (B, N)
):
    out = np.zeros((system.batch, system.n_rings))
    m = np.flatnonzero(system.lag_kind == LAG_OPT_SELF)
    np.add.at(out, (slice(None), system.src_ring[system.lag_src[m]]), system.res_k_per_w[:, m])
    return out

def __post_init__(self):
    time_constants_s = np.atleast_1d(np.asarray(self.taus_s, dtype=np.float64))
    residues_k_per_w = np.atleast_1d(np.asarray(self.res_k_per_w, dtype=np.float64))
    if time_constants_s.shape != residues_k_per_w.shape or time_constants_s.ndim != 1:
        raise ValueError("taus_s and res_k_per_w must be 1-D arrays of the same length")
    if np.any(~(time_constants_s > 0)) or not np.all(np.isfinite(residues_k_per_w)):
        raise ValueError("taus must be > 0 and residues finite")
    object.__setattr__(self, "taus_s", time_constants_s)
    object.__setattr__(self, "res_k_per_w", residues_k_per_w)

def step(self, t_s) -> np.ndarray:
    time_s = np.asarray(t_s, dtype=np.float64)[..., None]
    rise_per_w = np.sum(self.res_k_per_w * -np.expm1(-np.clip(time_s, 0, None) / self.taus_s), axis=-1)
    return np.where(time_s[..., 0] > 0, rise_per_w, 0.0)

def describe(self) -> dict:
    return {"form": "foster", "taus_s": self.taus_s.tolist(), "res_k_per_w": self.res_k_per_w.tolist(),
            **dict(self.info)}

def _as_response(r) -> FosterResponse | Callable:
    if isinstance(r, FosterResponse):
        return r
    if hasattr(r, "taus_s") and hasattr(r, "res_k_per_w"):
        return FosterResponse(r.taus_s, r.res_k_per_w)
    if callable(r):
        return r
    raise TypeError("a response must be a FosterResponse, an object with taus_s/res_k_per_w, or a callable step "
                    "response g(t) in K/W")

def resonance_to_rise_k(shift_m, *, s0_m_per_k, beta_per_k: float = 0.0, t_ref_k: float | None = None,
                        t_base_k: float) -> np.ndarray:
    shift = np.asarray(shift_m, dtype=np.float64)
    reference_k = t_base_k if t_ref_k is None else t_ref_k
    b = s0_m_per_k * (1.0 + beta_per_k * (t_base_k - reference_k))
    a = 0.5 * s0_m_per_k * beta_per_k
    discriminant = b * b + 4.0 * a * shift
    if np.any(discriminant < 0) or np.any(b <= 0):
        raise ValueError("the resonance target is outside the range the model's s(T) can reach")
    return 2.0 * shift / (b + np.sqrt(discriminant))

def rise_to_resonance_m(rise_k, *, s0_m_per_k, beta_per_k: float = 0.0, t_ref_k: float | None = None,
                        t_base_k: float) -> np.ndarray:
    x = np.asarray(rise_k, dtype=np.float64)
    reference_k = t_base_k if t_ref_k is None else t_ref_k
    return s0_m_per_k * ((1.0 + beta_per_k * (t_base_k - reference_k)) * x + 0.5 * beta_per_k * x * x)

def __post_init__(self):
    if self.units not in ("resonance", "temperature"):
        raise ValueError(f"target units must be resonance or temperature, got {self.units!r}")
    if self.form not in ("rectified_sine", "trapezoid", "table"):
        raise ValueError(f"unknown target form {self.form!r}")
    if self.period_s is None and not (self.horizon_s and self.horizon_s > 0):
        raise ValueError("a one-shot target (period_s None) needs horizon_s > 0")
    if self.period_s is not None and not self.period_s > 0:
        raise ValueError("period_s must be > 0")
    if self.form == "trapezoid":
        period = self.period_s if self.period_s is not None else math.inf
        if min(self.rise_s, self.high_s, self.fall_s) < 0 or self.rise_s + self.high_s + self.fall_s > period:
            raise ValueError("trapezoid rise/high/fall must be >= 0 and fit in the period")
    if self.form == "table":
        times_s = np.asarray(self.table_t_s, dtype=np.float64)
        temperatures_k = np.asarray(self.table_k, dtype=np.float64)
        if times_s.ndim != 1 or times_s.shape != temperatures_k.shape or times_s.size < 2 or np.any(np.diff(times_s) <= 0):
            raise ValueError("table target needs increasing table_t_s and table_k of equal length")
    if not 0 < self.thermometer_fraction <= 1.0:
        raise ValueError("thermometer_fraction must be in (0, 1]")
    if not self.s_ref_m_per_k > 0:
        raise ValueError("s_ref_m_per_k must be > 0")

def printed_k(self, t_s) -> np.ndarray:
    x = np.asarray(t_s, dtype=np.float64) + self.phase_s
    if self.form == "rectified_sine":
        return self.t_max_k - self.delta_k * generators.np_rect_sine(x, self.period_s)
    if self.form == "trapezoid":
        period = self.period_s if self.period_s is not None else 1e300
        return self.t_low_k + self.delta_k * generators.np_trapezoid(x, period, self.rise_s, self.high_s,
            self.fall_s)
    times_s = np.asarray(self.table_t_s, dtype=np.float64)
    temperatures_k = np.asarray(self.table_k, dtype=np.float64)
    if self.period_s is not None:
        x = times_s[0] + np.mod(x - times_s[0], self.period_s)
        return np.interp(x, np.append(times_s, times_s[0] + self.period_s), np.append(temperatures_k,
            temperatures_k[0]))
    return np.interp(x, times_s, temperatures_k)

def ring_rise_k(self, t_s, *, s0_m_per_k=None, beta_per_k: float = 0.0, t_ref_k: float | None = None,
                ring_t0_k: float | None = None):
    if self.units == "temperature":
        return self.excursion_k(t_s) / self.thermometer_fraction
    if s0_m_per_k is None:
        raise ValueError("a resonance target needs the model's dlambda/dT (s0_m_per_k, beta_per_k, t_ref_k)")
    return resonance_to_rise_k(self.resonance_m(t_s), s0_m_per_k=s0_m_per_k, beta_per_k=beta_per_k,
                               t_ref_k=t_ref_k, t_base_k=self.t_base_k if ring_t0_k is None else ring_t0_k)

def peak_rate_k_per_s(self) -> float:
    if self.form == "rectified_sine":
        return math.pi * self.delta_k / self.period_s
    if self.form == "trapezoid":
        ramp_rates = [self.delta_k / x for x in (self.rise_s, self.fall_s) if x > 0]
        return max(ramp_rates) if ramp_rates else math.inf
    times_s = np.asarray(self.table_t_s, dtype=np.float64)
    temperatures_k = np.asarray(self.table_k, dtype=np.float64)
    return float(np.max(np.abs(np.diff(temperatures_k) / np.diff(times_s))))

def mean_rate_k_per_s(self) -> float:
    if self.period_s is None:
        raise ValueError("mean rate needs a periodic target")
    t = np.linspace(0, self.period_s, 20001)
    return float(np.mean(np.abs(np.gradient(self.printed_k(t), t))))

def describe(self) -> dict:
    description = {k: getattr(self, k) for k in ("units", "form", "period_s", "t_base_k", "t_max_k", "t_low_k",
                                       "delta_k", "rise_s", "high_s", "fall_s", "phase_s", "horizon_s",
                                       "s_ref_m_per_k", "thermometer_fraction", "name", "provenance",
                                       "source", "note")}
    if self.form == "table":
        description["table_t_s"] = np.asarray(self.table_t_s, dtype=np.float64).tolist()
        description["table_k"] = np.asarray(self.table_k, dtype=np.float64).tolist()
    return description

def _gauss_legendre_01(n: int = 8):
    x, w = np.polynomial.legendre.leggauss(n)
    return 0.5 * (x + 1.0), 0.5 * w

def R(idx):                                               # ramp response at grid index idx (0 for idx <= 0)
    idx = np.asarray(idx)
    return np.where(idx > 0, ramp_tab[np.clip(idx, 0, ramp_tab.size - 1)], 0.0)

def _estimate_settle_time(step: Callable, period: float) -> float:
    t = period * 2.0 ** np.arange(0, 40)
    g = np.asarray(step(t), dtype=np.float64)
    scale = max(float(np.max(np.abs(g))), 1e-300)
    for i in range(len(t) - 1):
        if abs(g[i + 1] - g[i]) <= 1e-9 * scale:
            return float(t[i])
    warnings.warn("step response did not settle within 2**39 periods", RuntimeWarning, stacklevel=3)
    return float(t[-1])

def _difference_operator(n: int, order: int, periodic: bool) -> np.ndarray:
    if order == 0:
        return np.eye(n)
    op = np.eye(n)
    for _ in range(order):
        if periodic:
            op = np.roll(np.eye(n), 1, axis=1) @ op - op
        else:
            op = (np.eye(op.shape[0])[1:] - np.eye(op.shape[0])[:-1]) @ op if op.shape[0] > 1 else op
    return op

@property
def n_knots(self) -> int:
    return int(self.t_knots_s.size)

@property
def peak_power_w(self) -> np.ndarray:
    return np.max(self.power_w, axis=1)

@property
def mean_power_w(self) -> np.ndarray:
    if self.period_s is not None:
        return np.mean(self.power_w, axis=1)
    n = self.power_w.shape[1]
    return (np.sum(self.power_w[:, :-1], axis=1) + 0.5 * self.power_w[:, -1]) / n

def power_at(self, t_s, b: int = 0) -> np.ndarray:
    times_s = np.asarray(t_s, dtype=np.float64)
    knot_times_s = self.t_knots_s
    power_w = self.power_w[b]
    if self.period_s is not None:
        return np.interp(np.mod(times_s, self.period_s), np.append(knot_times_s, self.period_s),
            np.append(power_w, power_w[0]))
    return np.interp(times_s, np.concatenate([[0.0], knot_times_s]), np.concatenate([[0.0], power_w]))

def _per_world(v, nb: int, name: str) -> np.ndarray:
    values = np.atleast_1d(np.asarray(v, dtype=np.float64))
    if values.size == 1:
        return np.full(nb, float(values[0]))
    if values.size != nb:
        raise ValueError(f"{name} has {values.size} values but there are {nb} worlds")
    return values

def signal_id(name: str) -> int:
    try:
        return SIGNAL_BY_NAME[name].id
    except KeyError:
        import difflib
        near = difflib.get_close_matches(name, list(SIGNAL_BY_NAME), n=3)
        raise ScenarioError(f"unknown scenario signal {name!r}" + (f"; did you mean {near}?" if near else
                            f"; known: {sorted(SIGNAL_BY_NAME)}")) from None

@njit(cache=True, inline="always")
def _mod_positive(x, p):
    r = x - p * math.floor(x / p)
    if r < 0.0:
        r += p
    if r >= p:
        r -= p
    return r

@njit(cache=True, inline="always")
def _pwl_segment(tab, tab_off, n, x):
    if x < tab[tab_off]:
        return -1
    if x >= tab[tab_off + n - 1]:
        return n - 1
    lo = 0
    hi = n - 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if tab[tab_off + mid] <= x:
            lo = mid
        else:
            hi = mid
    return lo

@njit(cache=True, inline="always")
def _random_level_value(x, interval, dist, a, b, lo, hi, key, rng_elem, slot, tab, tab_off, n, cache, cache_off):
    j = np.int64(0)
    if interval > 0.0 and interval < math.inf and x > 0.0:
        j = np.int64(math.floor(x / interval))
    if cache[cache_off] == float(j):
        return cache[cache_off + 1]
    if dist == DIST_NORMAL:
        v = a + b * rng.normal(key, rng_elem, j, slot)
    elif dist == DIST_CHOICE:
        u = rng.uniform(key, rng_elem, j, slot)
        i = np.int64(math.floor(u * n))
        if i > n - 1:
            i = n - 1
        v = tab[tab_off + i]
    else:
        u = rng.uniform(key, rng_elem, j, slot)
        v = a + (b - a) * u
    if v < lo:
        v = lo
    if v > hi:
        v = hi
    cache[cache_off] = float(j)
    cache[cache_off + 1] = v
    return v

@njit(cache=True, inline="always")
def _raw_value(kind, x, period, p0, p1, p2, p3, p4, flags, dist, tab, tab_off, tab_len, e_rel, key, rng_elem, slot,
               cache, cache_off):
    if kind == K_CONST:
        return 1.0
    if kind == K_TRAPEZOID:                                  # p0 rise, p1 high, p2 fall (ticks)
        xm = _mod_positive(x, period)
        if xm < p0:
            return xm / p0
        xm -= p0
        if xm < p1:
            return 1.0
        xm -= p1
        if xm < p2:
            return 1.0 - xm / p2
        return 0.0
    if kind == K_RECT_SINE:
        return abs(math.sin(math.pi * (_mod_positive(x, period) / period)))
    if kind == K_SINE:
        return math.sin(2.0 * math.pi * (_mod_positive(x, period) / period))
    if kind == K_SMOOTH_STEP:                                # p0 duration (ticks)
        if x <= 0.0:
            return 0.0
        if x >= p0:
            return 1.0
        return 0.5 * (1.0 - math.cos(math.pi * x / p0))
    if kind == K_PWL:
        # table layout - n times (ticks), then n values (or n values per element when FL_PER_ELEMENT is set)
        n = tab_len
        val_off = tab_off + n + (e_rel * n if (flags & FL_PER_ELEMENT) != 0 else 0)
        x_tab = _mod_positive(x, period) if (flags & FL_PERIODIC) != 0 else x
        i = _pwl_segment(tab, tab_off, n, x_tab)
        if i < 0:
            return tab[val_off]
        if i >= n - 1:
            return tab[val_off + n - 1]
        ta = tab[tab_off + i]
        tb = tab[tab_off + i + 1]
        fr = (x_tab - ta) / (tb - ta)
        return tab[val_off + i] + fr * (tab[val_off + i + 1] - tab[val_off + i])
    if kind == K_SAMPLED:                                    # p0 sample interval (ticks)
        n = tab_len
        base = tab_off + (e_rel * n if (flags & FL_PER_ELEMENT) != 0 else 0)
        u = x / p0                                           # position, in samples
        if (flags & FL_PERIODIC) != 0:
            u = _mod_positive(u, float(n))
            i0 = np.int64(math.floor(u))
            if i0 > n - 1:
                i0 = n - 1
            fr = u - i0
            i1 = i0 + 1
            if i1 >= n:
                i1 = 0
        else:
            if u <= 0.0:
                return tab[base]
            if u >= n - 1:
                return tab[base + n - 1]
            i0 = np.int64(math.floor(u))
            fr = u - i0
            i1 = i0 + 1
        if (flags & FL_LINEAR) != 0:
            return tab[base + i0] + fr * (tab[base + i1] - tab[base + i0])
        return tab[base + i0]
    if kind == K_RANDOM_WALK:                                # p0 knot (ticks), p1 sd per knot, p2 drift per knot
        return _random_walk_value(x, p0, p1, p2, key, rng_elem, slot, cache, cache_off)
    if kind == K_RANDOM_LEVELS:                              # p0 interval (ticks), p1 a, p2 b, p3 lo, p4 hi
        return _random_level_value(x, p0, dist, p1, p2, p3, p4, key, rng_elem, slot, tab, tab_off, tab_len, cache,
                                   cache_off)
    return 0.0

@njit(cache=True, inline="always")
def _is_per_element(kind, flags):
    if (flags & FL_PER_ELEMENT) != 0:
        return True
    return (kind == K_RANDOM_WALK or kind == K_RANDOM_LEVELS) and (flags & FL_COMMON) == 0

@njit(cache=True, inline="always")
def scen_init_b(elem_default, out):
    for i in range(out.shape[0]):
        out[i] = elem_default[i]

@njit(cache=True)
def scen_eval_b(tick, compression, sig_i64, sig_f64, elem_default, comp_i64, comp_f64_b, tab_b, keys_b, cache_b,
                out):
    for s in range(sig_i64.shape[0]):
        if sig_i64[s, SI_NC] > 0:
            scen_eval_signal_b(s, tick, compression, sig_i64, sig_f64, elem_default, comp_i64, comp_f64_b, tab_b,
                               keys_b, cache_b, out)

@njit(cache=True)
def scen_eval(tick, compression, sig_i64, sig_f64, elem_default, comp_i64, comp_f64, tab_f64, keys, cache, out):
    bs = comp_f64.shape[0]
    for b in range(out.shape[0]):
        bb = b if bs > 1 else 0
        scen_init_b(elem_default, out[b])
        scen_eval_b(tick, compression, sig_i64, sig_f64, elem_default, comp_i64, comp_f64[bb], tab_f64[bb], keys[b],
                    cache[b], out[b])

@njit(cache=True)
def scen_render(ticks, compression, sig_i64, sig_f64, elem_default, comp_i64, comp_f64, tab_f64, keys, cache, out):
    for i in range(ticks.shape[0]):
        scen_eval(ticks[i], compression, sig_i64, sig_f64, elem_default, comp_i64, comp_f64, tab_f64, keys, cache,
                  out[i])

@njit(cache=True, inline="always")
def _raw_next_break(kind, x, period, p0, p1, p2, flags, tab, tab_off, tab_len, hsmooth):
    inf = math.inf
    if kind == K_CONST:
        return inf
    if kind == K_TRAPEZOID:                                  # corners at p0, p0 + p1, p0 + p1 + p2 and the period end
        xm = _mod_positive(x, period)
        best = period - xm
        for pos in (p0, p0 + p1, p0 + p1 + p2):
            if pos > xm and pos - xm < best:
                best = pos - xm
        return best
    if kind == K_RECT_SINE:                                  # curved, with a cusp at every period end
        return min(hsmooth, period - _mod_positive(x, period))
    if kind == K_SINE:
        return hsmooth
    if kind == K_SMOOTH_STEP:                                # flat before 0, curved on [0, p0], flat after
        if x < 0.0:
            return -x
        if x < p0:
            return min(hsmooth, p0 - x)
        return inf
    if kind == K_PWL:                                        # the next table time (and the period end if periodic)
        n = tab_len
        if (flags & FL_PERIODIC) != 0:
            xm = _mod_positive(x, period)
            i = _pwl_segment(tab, tab_off, n, xm)
            if i + 1 <= n - 1 and tab[tab_off + i + 1] > xm:
                return min(tab[tab_off + i + 1] - xm, period - xm)
            return period - xm
        i = _pwl_segment(tab, tab_off, n, x)
        if i >= n - 1:
            return inf
        return tab[tab_off + i + 1] - x
    if kind == K_RANDOM_WALK or kind == K_RANDOM_LEVELS or kind == K_SAMPLED:
        d = p0                                               # knot, interval or sample spacing (ticks)
        if not (d > 0.0 and d < inf):
            return inf
        periodic_sampled = kind == K_SAMPLED and (flags & FL_PERIODIC) != 0
        if kind == K_SAMPLED and not periodic_sampled and x >= (tab_len - 1) * d:
            return inf
        if x < 0.0 and not periodic_sampled:
            # constant before x = 0 (walk at 0, first sample held) or first level up to x = d
            return d - x if kind == K_RANDOM_LEVELS else -x
        # knots at every multiple of d (a periodic table also has them at negative x, e.g. a negative phase)
        return (math.floor(x / d) + 1.0) * d - x
    return inf

@njit(cache=True)
def scen_next_break_b(sig, tick, compression, sig_i64, comp_i64, comp_f64_b, tab_b):
    if sig_i64[sig, SI_CLIP] != 0:
        return tick + 1
    t = float(tick)
    t_next = math.inf
    c0 = sig_i64[sig, SI_C0]
    for c in range(c0, c0 + sig_i64[sig, SI_NC]):
        t_comp = _component_next_break(c, t, compression, comp_i64, comp_f64_b, tab_b)
        if t_comp < t_next:
            t_next = t_comp
    if not (t_next < 4.0e18):                                     # no break inside the int64 tick range
        return np.int64(NO_BREAK)
    kb = np.int64(math.ceil(t_next - (1e-6 + 1e-14 * t_next))) - 1
    if kb < tick + 1:
        kb = tick + 1
    return kb

def np_smooth_step(x, duration):
    x = np.asarray(x, dtype=np.float64)
    return np.where(x <= 0, 0.0, np.where(x >= duration, 1.0, 0.5 * (1.0 - np.cos(np.pi * np.clip(x, 0, duration)
                                                                                    / duration))))

def _world_array(v, name: str) -> np.ndarray:
    a = np.atleast_1d(np.asarray(v, dtype=np.float64))
    if a.ndim != 1:
        raise ScenarioError(f"{name} must be a scalar or a (B,) array of per-world values, got shape {a.shape}")
    return a

def __post_init__(self):
    spec = SIGNAL_BY_NAME.get(self.signal)
    if spec is None:
        signal_id(self.signal)                    # raises with a suggestion
    if self.kind not in KINDS:
        raise ScenarioError(f"unknown generator kind {self.kind!r}; known: {KINDS}")
    if self.map not in MAPS:
        raise ScenarioError(f"unknown map {self.map!r}; known: {MAPS}")
    if self.dist not in DISTS:
        raise ScenarioError(f"unknown distribution {self.dist!r}; known: {DISTS}")
    if spec.level == "aggressor":
        if self.site is None:
            raise ScenarioError(f"{self.signal} components need site=<aggressor site name>")
    elif self.site is not None:
        raise ScenarioError(f"site= is only for thermal.aggressor_w, not {self.signal}")
    if self.slow and not spec.slow_eligible:
        raise CompressionError(
            f"{self.label or self.kind} on {self.signal}: only slow exogenous signals may be time-compressed "
            f"(compression must never speed up a fast transient); eligible: "
            f"{[s.name for s in SIGNALS if s.slow_eligible]}")
    if not self.stream.startswith("scenario_"):
        raise ScenarioError(f"stream {self.stream!r} must be named scenario_<name> (mrm.core.rng)")
    if not (self.t1_s > self.t0_s):
        raise ScenarioError(f"{self.label or self.kind}: window [t0, t1) = [{self.t0_s}, {self.t1_s}) is empty")
    p = tuple(float(v) for v in self.params) + (0.0,) * (5 - len(self.params))      # always 5 parameters
    object.__setattr__(self, "params", p[:5])
    periodic_kinds = ("trapezoid", "rect_sine", "sine")
    if (self.kind in periodic_kinds or self.periodic) and not (self.period_s > 0 or self.kind == "sampled"):
        raise ScenarioError(f"{self.label or self.kind}: period_s must be > 0")
    if self.kind == "trapezoid":
        r, h, f = p[0], p[1], p[2]
        if min(r, h, f) < 0 or r + h + f > self.period_s * (1 + 1e-12):
            raise ScenarioError(f"trapezoid rise/high/fall {r, h, f} must be >= 0 and fit in period "
                                f"{self.period_s}")
    if self.kind == "smooth_step" and not p[0] > 0:
        raise ScenarioError("smooth_step needs a duration > 0")
    if self.kind in ("random_walk", "sampled") and not p[0] > 0:
        raise ScenarioError(f"{self.kind} needs an interval > 0")
    if self.kind == "random_levels" and not p[0] > 0:
        raise ScenarioError("random_levels needs an interval > 0 (math.inf for a single level)")
    if self.kind in ("pwl", "sampled") or (self.kind == "random_levels" and self.dist == "choice"):
        if self.table_v is None:
            raise ScenarioError(f"{self.label or self.kind} needs table_v")
    if self.kind == "pwl":
        tt = np.asarray(self.table_t, dtype=np.float64)
        if tt.ndim != 1 or tt.size < 1 or np.any(np.diff(tt) < 0) or not np.all(np.isfinite(tt)):
            raise ScenarioError("pwl table_t must be a non-decreasing finite 1-D array")
    if self.burst_on_s < 0 or self.burst_off_s < 0:
        raise ScenarioError("burst_on_s and burst_off_s must be >= 0")
    if self.map == "bernoulli_td" and self.kind == "random_walk":
        raise ScenarioError("map bernoulli_td needs a bounded raw value in [0, 1]; a random walk is unbounded")
    _world_array(self.amp, "amp")
    _world_array(self.offset, "offset")

@property
def spec(self) -> SignalSpec:
    return SIGNAL_BY_NAME[self.signal]

@property
def is_random(self) -> bool:
    return self.kind in ("random_walk", "random_levels")

@property
def slot(self) -> int:
    return _rng_slot(self.link or f"{self.signal}|{self.label}|{self.kind}")

def world_count(self) -> int:
    n = {len(_world_array(self.amp, "amp")), len(_world_array(self.offset, "offset"))}
    if self.table_v is not None and self.kind in ("pwl", "sampled"):
        tv = np.asarray(self.table_v, dtype=np.float64)
        if tv.ndim >= 2:
            n.add(tv.shape[0])
    n.discard(1)
    if len(n) > 1:
        raise ScenarioError(f"{self.label or self.kind}: per-world arrays disagree in length {sorted(n)}")
    return n.pop() if n else 1

def describe(self) -> dict:
    def enc(v):
        if v is None:
            return None
        a = np.asarray(v, dtype=np.float64)
        if a.ndim == 0:
            return float(a)
        return {"shape": list(a.shape), "sha256": hashlib.sha256(np.ascontiguousarray(a).tobytes()).hexdigest()}
    d = {f.name: getattr(self, f.name) for f in dataclasses.fields(self)}
    for k in ("amp", "offset", "table_t", "table_v"):
        d[k] = enc(d[k])
    d["params"] = list(self.params)
    d["elements"] = None if self.elements is None else list(self.elements)
    return d

def enc(v):
    if v is None:
        return None
    a = np.asarray(v, dtype=np.float64)
    if a.ndim == 0:
        return float(a)
    return {"shape": list(a.shape), "sha256": hashlib.sha256(np.ascontiguousarray(a).tobytes()).hexdigest()}

@property
def pending(self) -> bool:
    return self.target is not None and not self.power

def __post_init__(self):
    if self.start not in ("cold", "warm"):
        raise ScenarioError(f"reset start must be cold or warm, got {self.start!r}")
    if self.heater_init not in ("factory", "zero"):
        raise ScenarioError(f"heater_init must be factory or zero, got {self.heater_init!r}")

def __post_init__(self):
    c = float(self.time_compression)
    if not (math.isfinite(c) and c >= 1.0):
        raise CompressionError(f"time_compression must be a finite number >= 1, got {self.time_compression!r}")
    for k in self.defaults:
        signal_id(k)
    labels = [x.label for x in self.components if x.label]
    dup = {l for l in labels if labels.count(l) > 1}
    if dup:
        raise ScenarioError(f"scenario {self.name!r}: duplicate component labels {sorted(dup)}")
    sites = [a.site for a in self.aggressors]
    if len(set(sites)) != len(sites):
        raise ScenarioError(f"scenario {self.name!r}: aggressor site listed twice: {sites}")

def with_defaults(self, **defaults) -> "Scenario":
    d = dict(self.defaults)
    d.update({k.replace("__", "."): v for k, v in defaults.items()})
    return dataclasses.replace(self, defaults=d)

def with_aggressor_power(self, site: str, t_knots_s, power_w, *, period_s: float | None,
                         record: Mapping[str, Any] | None = None, linear: bool = True) -> "Scenario":
    tk = np.asarray(t_knots_s, dtype=np.float64)
    pw = np.asarray(power_w, dtype=np.float64)
    if pw.ndim == 1:
        pw = pw[None, :]
    if tk.ndim != 1 or pw.shape[-1] != tk.size or tk.size < 2:
        raise ScenarioError("t_knots_s must be (n,) and power_w (n,) or (Bs, n), n >= 2")
    if np.any(pw < -1e-15):
        raise ScenarioError("aggressor power must be >= 0 (a heater can only heat, PAT-1 [0050])")
    d = np.diff(tk)
    if abs(tk[0]) > 1e-15 or np.max(np.abs(d - d[0])) > 1e-9 * max(d[0], 1e-300):
        raise ScenarioError("t_knots_s must be uniform and start at 0")
    if period_s is not None and abs(tk.size * d[0] - period_s) > 1e-9 * period_s:
        raise ScenarioError(f"periodic knots: n * spacing = {tk.size * d[0]} != period {period_s}")
    rec = dict(record or {})
    comp = Component("thermal.aggressor_w", "sampled", site=site, params=(float(d[0]),),
                     table_v=np.clip(pw, 0.0, None), periodic=period_s is not None, linear=linear,
                     period_s=float(period_s or 0.0), hold_after=period_s is None,
                     provenance=rec.get("provenance", "calibrated"), source=rec.get("source", ""),
                     note=rec.get("note", "aggressor power waveform"), label=f"aggressor_power:{site}",
                     stream="scenario_aggressor")
    aggs = []
    found = False
    for a in self.aggressors:
        if a.site == site:
            aggs.append(dataclasses.replace(a, power=(comp,), record=rec))
            found = True
        else:
            aggs.append(a)
    if not found:
        aggs.append(AggressorSpec(site=site, power=(comp,), record=rec))
    return dataclasses.replace(self, aggressors=tuple(aggs))

@property
def all_components(self) -> tuple[Component, ...]:
    out = list(self.components)
    for a in self.aggressors:
        out.extend(a.power)
    return tuple(out)

@property
def aggressor_sites(self) -> tuple[str, ...]:
    seen: list[str] = []
    for a in self.aggressors:
        if a.site not in seen:
            seen.append(a.site)
    for c in self.components:
        if c.site is not None and c.site not in seen:
            seen.append(c.site)
    return tuple(seen)

@property
def pending_aggressors(self) -> tuple[str, ...]:
    return tuple(a.site for a in self.aggressors if a.pending)

@property
def drives(self) -> tuple[str, ...]:
    used = self.signals_used()
    if "tx.bias_v" in used:
        d = self.defaults.get("tx.bias_v")
        if any(c.signal == "tx.bias_v" for c in self.all_components) or (
                d is not None and np.all(np.isfinite(np.asarray(d, dtype=np.float64)))):
            return ("tx.bias",)
    return ()

@property
def offsets(self) -> tuple[str, ...]:
    return ("tx.bias",) if "tx.bias_offset_v" in self.signals_used() else ()

def summary(self) -> str:
    lines = [f"scenario {self.name} (time_compression {self.time_compression:g})"]
    if self.description:
        lines.append(f"  {self.description}")
    for c in self.all_components:
        where = f" site={c.site}" if c.site else (f" elements={list(c.elements)}" if c.elements else "")
        lines.append(f"  - {c.label or c.kind}: {c.kind} on {c.signal}{where}"
                     f"{' [slow]' if c.slow else ''}{' [absolute]' if c.absolute else ''}; "
                     f"{c.provenance} {c.source}; {c.note}")
    for a in self.aggressors:
        state = "PENDING CALIBRATION" if a.pending else a.record.get("provenance", "direct")
        lines.append(f"  aggressor {a.site} -> victim ring {a.victim_ring}: {state}")
    if self.reset is not None:
        lines.append(f"  reset: {self.reset.start} (heater_init {self.reset.heater_init}, factory_cal "
                     f"{self.reset.factory_cal})")
    return "\n".join(lines)

def compile(self, *, dt_s: float, n_rings: int, n_lines: int, batch: int = 1, seed: int = 0,
            aggressor_sites: Sequence[str] | None = None, check_compression: bool = True) -> "ScenarioArrays":
    return _compile_scenario(self, dt_s=float(dt_s), n_rings=int(n_rings), n_lines=int(n_lines),
                             batch=int(batch), seed=int(seed), aggressor_sites=aggressor_sites,
                             check_compression=check_compression)

def render(self, *, dt_s: float, n_ticks: int | None = None, ticks=None, stride_ticks: int = 1, tick0: int = 0,
           n_rings: int = 1, n_lines: int = 1, batch: int = 1, seed: int = 0,
           aggressor_sites: Sequence[str] | None = None) -> "DisturbanceFrame":
    arr = self.compile(dt_s=dt_s, n_rings=n_rings, n_lines=n_lines, batch=batch, seed=seed,
                       aggressor_sites=aggressor_sites)
    return arr.render(n_ticks=n_ticks, ticks=ticks, stride_ticks=stride_ticks, tick0=tick0)

@classmethod
def from_frame(cls, frame: "DisturbanceFrame", name: str = "recorded", **kw) -> "Scenario":
    return cls(name=name, components=frame.to_components(), **kw)

def stack(scenarios: Iterable[Scenario], name: str | None = None) -> Scenario:
    scs = [s for s in scenarios]
    if not scs:
        return Scenario(name=name or "static")
    comps: list[Component] = []
    aggs: list[AggressorSpec] = []
    defaults: dict[str, Any] = {}
    reset = None
    comp_c = 1.0
    prov: list = []
    dur = None
    cyc = None
    fast = math.inf
    for s in scs:
        for c in s.components:
            if c.label and any(c.label == o.label for o in comps):
                c = dataclasses.replace(c, label=f"{s.name}.{c.label}")
            comps.append(c)
        for a in s.aggressors:
            if any(a.site == o.site for o in aggs):
                raise ScenarioError(f"aggressor site {a.site!r} is defined by two stacked scenarios")
            aggs.append(a)
        for k, v in s.defaults.items():
            if k in defaults and not np.array_equal(np.asarray(defaults[k]), np.asarray(v), equal_nan=True):
                raise ScenarioError(f"stacked scenarios disagree on the default of {k}: {defaults[k]} vs {v}")
            defaults[k] = v
        if s.reset is not None:
            if reset is not None and reset != s.reset:
                raise ScenarioError("two stacked scenarios define different reset specs")
            reset = s.reset
        if s.time_compression != 1.0:
            if comp_c != 1.0 and comp_c != s.time_compression:
                raise CompressionError("stacked scenarios disagree on time_compression")
            comp_c = s.time_compression
        prov.extend(s.provenance)
        if s.duration_s is not None:
            dur = s.duration_s if dur is None else max(dur, s.duration_s)
        if s.slow_cycle_s is not None:
            cyc = s.slow_cycle_s if cyc is None else max(cyc, s.slow_cycle_s)
        fast = min(fast, s.fast_rate_ref_k_per_s)        # the strictest reference wins
    return Scenario(name=name or "+".join(s.name for s in scs), components=tuple(comps), aggressors=tuple(aggs),
                    time_compression=comp_c, defaults=defaults, reset=reset, duration_s=dur, slow_cycle_s=cyc,
                    fast_rate_ref_k_per_s=fast, description="; ".join(s.description for s in scs if s.description),
                    provenance=tuple(prov))

def _check_options(kw: dict) -> dict:
    allowed = {f.name for f in dataclasses.fields(Component)} - {"signal", "kind", "params", "table_t", "table_v",
                                                                 "amp", "offset", "period_s"}
    bad = set(kw) - allowed
    if bad:
        raise ScenarioError(f"unknown component options {sorted(bad)}; allowed: {sorted(allowed)}")
    return kw

def pwl(signal: str, t_s, values, *, amp=1.0, offset=0.0, periodic: bool = False, period_s: float | None = None,
        **kw) -> Component:
    t = np.asarray(t_s, dtype=np.float64)
    v = np.asarray(values, dtype=np.float64)
    if periodic:
        period_s = float(period_s if period_s is not None else t[-1] - t[0])
        if abs(t[0]) > 0:
            raise ScenarioError("a periodic pwl table must start at t = 0")
        if not period_s > 0 or t[-1] > period_s * (1 + 1e-12):
            raise ScenarioError(f"a periodic pwl table must end within its period ({t[-1]} > {period_s})")
    per_el = v.ndim == 3                                     # one table row per element
    return Component(signal, "pwl", table_t=t, table_v=v, amp=amp, offset=offset, periodic=periodic,
                     period_s=float(period_s or 0.0),
                     **_check_options(dict(kw, **({"common": False} if per_el else {}))))

def trapezoid(signal: str, period_s: float, rise_s: float, high_s: float, fall_s: float, *, amp=1.0, offset=0.0,
              **kw) -> Component:
    return Component(signal, "trapezoid", period_s=float(period_s), params=(rise_s, high_s, fall_s), amp=amp,
                     offset=offset, **_check_options(kw))

def square(signal: str, period_s: float, duty: float, *, amp=1.0, offset=0.0, **kw) -> Component:
    if not 0.0 <= duty <= 1.0:
        raise ScenarioError("duty must be in [0, 1]")
    return trapezoid(signal, period_s, 0.0, duty * period_s, 0.0, amp=amp, offset=offset, **kw)

def triangle(signal: str, period_s: float, *, amp=1.0, offset=0.0, rise_frac: float = 0.5, **kw) -> Component:
    if not 0.0 < rise_frac < 1.0:
        raise ScenarioError("rise_frac must be in (0, 1)")
    return trapezoid(signal, period_s, rise_frac * period_s, 0.0, (1.0 - rise_frac) * period_s, amp=amp,
                     offset=offset, **kw)

def random_walk(signal: str, *, knot_s: float, sigma_per_rt_s: float, drift_per_s: float = 0.0, amp=1.0,
                **kw) -> Component:
    return Component(signal, "random_walk", params=(knot_s, sigma_per_rt_s, drift_per_s), amp=amp,
                     **_check_options(kw))

def random_levels(signal: str, *, interval_s: float, dist: str = "uniform", a: float = 0.0, b: float = 1.0,
                  lo: float = -math.inf, hi: float = math.inf, choices=None, amp=1.0, offset=0.0,
                  **kw) -> Component:
    tv = None if choices is None else np.asarray(choices, dtype=np.float64)
    if dist == "choice" and (tv is None or tv.ndim != 1 or tv.size == 0):
        raise ScenarioError("dist='choice' needs a non-empty 1-D choices list")
    return Component(signal, "random_levels", params=(interval_s, a, b, lo, hi), dist=dist, table_v=tv, amp=amp,
                     offset=offset, **_check_options(kw))

def with_burst(comp: Component, on_s: float, off_s: float, phase_s: float = 0.0) -> Component:
    if on_s <= 0 or off_s < 0:
        raise ScenarioError("burst needs on_s > 0 and off_s >= 0")
    return dataclasses.replace(comp, burst_on_s=float(on_s), burst_off_s=float(off_s), burst_phase_s=float(phase_s))

@property
def active_signals(self) -> tuple[str, ...]:
    return tuple(s.name for s in SIGNALS if self.sig_i64[s.id, SI_NC] > 0)

@property
def clipped_signals(self) -> tuple[str, ...]:
    return tuple(s.name for s in SIGNALS if self.sig_i64[s.id, SI_CLIP] != 0)

def kernel_args(self, cache: np.ndarray | None = None) -> tuple:
    return (self.compression, self.sig_i64, self.sig_f64, self.elem_default, self.comp_i64, self.comp_f64,
            self.tab_f64, self.keys, self.new_cache() if cache is None else cache)

def row(self, b: int) -> tuple[np.ndarray, np.ndarray]:
    bb = b if self.comp_f64.shape[0] > 1 else 0
    return self.comp_f64[bb], self.tab_f64[bb]

def evaluate(self, tick: int, cache: np.ndarray | None = None) -> dict[str, np.ndarray]:
    out = np.zeros((self.batch, self.n_out))
    cache = self.new_cache() if cache is None else cache
    scen_eval(np.int64(tick), self.compression, self.sig_i64, self.sig_f64, self.elem_default, self.comp_i64,
              self.comp_f64, self.tab_f64, self.keys, cache, out)
    return {name: out[:, o:o + w].copy() for name, (o, w) in self.layout.items()}

def next_break(self, signal: str, tick: int, b: int = 0) -> int:
    component_row, table_row = self.row(b)
    return int(scen_next_break_b(np.int64(signal_id(signal)), np.int64(tick), self.compression, self.sig_i64,
                                 self.comp_i64, component_row, table_row))

def render(self, *, n_ticks: int | None = None, ticks=None, stride_ticks: int = 1, tick0: int = 0,
           signals: Sequence[str] | None = None) -> "DisturbanceFrame":
    if ticks is None:
        if n_ticks is None:
            raise ScenarioError("render needs n_ticks or ticks")
        ticks = int(tick0) + int(stride_ticks) * np.arange(int(n_ticks), dtype=np.int64)
        stride = int(stride_ticks)
    else:
        ticks = np.asarray(ticks, dtype=np.int64)
        d = np.diff(ticks)
        stride = int(d[0]) if d.size and np.all(d == d[0]) and d[0] > 0 else 0
    if np.any(ticks < 0):
        raise ScenarioError("ticks must be >= 0")
    out = np.zeros((ticks.size, self.batch, self.n_out))
    scen_render(ticks, self.compression, self.sig_i64, self.sig_f64, self.elem_default, self.comp_i64,
                self.comp_f64, self.tab_f64, self.keys, self.new_cache(), out)
    names = list(self.layout) if signals is None else list(signals)
    sig = {n: out[:, :, self.layout[n][0]:self.layout[n][0] + self.layout[n][1]].copy() for n in names}
    return DisturbanceFrame(dt_s=self.dt_s, tick0=int(ticks[0]) if ticks.size else 0, stride_ticks=stride,
                            signals=sig, ticks=ticks.copy(), interp="linear", source=f"render of "
                            f"{self.fingerprint}", provenance="derived", aggressor_sites=self.aggressor_sites)

def _element_runs(idx: Sequence[int]) -> list[tuple[int, int, list[int]]]:
    positions_by_element = sorted(range(len(idx)), key=lambda i: idx[i])
    runs: list[tuple[int, int, list[int]]] = []
    for position in positions_by_element:
        e = idx[position]
        if runs and runs[-1][1] == e:
            lo, hi, positions = runs[-1]
            runs[-1] = (lo, hi + 1, positions + [position])
        elif runs and runs[-1][1] > e:
            raise ScenarioError(f"element {e} listed twice")
        else:
            runs.append((e, e + 1, [position]))
    return runs

def _to_ticks_array(v_s: np.ndarray, dt_s: float) -> np.ndarray:
    ticks = np.asarray(v_s, dtype=np.float64) / dt_s
    nearest_ticks = np.round(ticks)
    return np.where(np.abs(ticks - nearest_ticks) <= _SNAP_TICKS + 1e-12 * np.abs(ticks), nearest_ticks, ticks)

def _as_rows_elements(tv: np.ndarray) -> np.ndarray:
    if tv.ndim == 1:
        return tv[None, None, :]
    if tv.ndim == 2:
        return tv[:, None, :]
    if tv.ndim == 3:
        return tv
    raise ScenarioError(f"table values must be (n,), (Bs, n) or (Bs, E, n), got shape {tv.shape}")

def _check_element_rows(c: Component, tv: np.ndarray, idx: list[int]) -> None:
    if tv.shape[1] != len(idx):
        raise ScenarioError(f"{c.label or c.kind}: per-element table has {tv.shape[1]} rows but the component "
                            f"covers {len(idx)} elements")

def _smooth_curvature(c: Component, amp_max: float) -> float:
    if c.kind == "rect_sine":
        c1, c2, m12 = math.pi / c.period_s, (math.pi / c.period_s) ** 2, 1.0
    elif c.kind == "sine":
        c1, c2, m12 = 2.0 * math.pi / c.period_s, (2.0 * math.pi / c.period_s) ** 2, 3.0
    elif c.kind == "smooth_step":
        c1, c2, m12 = math.pi / (2.0 * c.params[0]), 0.5 * (math.pi / c.params[0]) ** 2, 1.0
    elif c.map == "bernoulli_td" and c.kind in ("trapezoid", "pwl") or (c.kind == "sampled" and c.linear
                                                                         and c.map == "bernoulli_td"):
        # linear segments (r'' = 0) become parabolas under the map - |m''| = 4 r'^2 with r' the steepest segment
        c1 = component_max_rate(dataclasses.replace(c, amp=1.0, map="identity"))
        return amp_max * 4.0 * c1 * c1
    else:
        return 0.0
    if c.map == "bernoulli_td":
        return amp_max * (2.0 * c2 * m12 + 4.0 * c1 * c1)
    return amp_max * c2

def _raw_range(c: Component) -> tuple[float, float]:
    k = c.kind
    p = c.params
    if k == "const":
        lo, hi = 1.0, 1.0
    elif k in ("trapezoid", "rect_sine", "smooth_step"):
        lo, hi = 0.0, 1.0
    elif k == "sine":
        lo, hi = -1.0, 1.0
    elif k in ("pwl", "sampled"):
        v = np.asarray(c.table_v, dtype=np.float64)
        lo, hi = (float(np.nanmin(v)), float(np.nanmax(v))) if v.size and np.any(~np.isnan(v)) else (0.0, 0.0)
    elif k == "random_walk":
        lo, hi = (0.0, 0.0) if (p[1] == 0.0 and p[2] == 0.0) else (-math.inf, math.inf)
    elif k == "random_levels":
        if c.dist == "uniform":
            lo, hi = min(p[1], p[2]), max(p[1], p[2])
        elif c.dist == "normal":
            lo, hi = (p[1], p[1]) if p[2] == 0.0 else (-math.inf, math.inf)
        else:
            v = np.asarray(c.table_v, dtype=np.float64)
            lo, hi = float(np.min(v)), float(np.max(v))
        lo, hi = max(lo, p[3]), min(hi, p[4])
    else:
        lo, hi = -math.inf, math.inf
    if c.map == "bernoulli_td":                              # m(r) = 2 r (1 - r) - concave, peak 0.5 at r = 0.5
        if math.isfinite(lo) and math.isfinite(hi):
            lo, hi = min(2.0 * lo * (1.0 - lo), 2.0 * hi * (1.0 - hi)), \
                (0.5 if lo <= 0.5 <= hi else max(2.0 * lo * (1.0 - lo), 2.0 * hi * (1.0 - hi)))
        else:
            lo, hi = -math.inf, 0.5
    return lo, hi

def _component_value_range(c: Component, amp: np.ndarray, off: np.ndarray) -> tuple[float, float]:
    rlo, rhi = _raw_range(c)
    vals = [0.0]
    for a, o in zip(np.atleast_1d(amp), np.atleast_1d(off)):
        for r in (rlo, rhi):
            if a == 0.0:
                vals.append(float(o))
            elif math.isfinite(r):
                vals.append(float(o + a * r))
            else:
                vals.append(math.copysign(math.inf, a * r))
    return min(vals), max(vals)

def __post_init__(self):
    if self.interp not in ("linear", "zoh"):
        raise ScenarioError("interp must be linear or zoh")
    self.signals = dict(self.signals)                  # never mutate the caller's mapping
    self.aggressor_sites = tuple(self.aggressor_sites)
    T = None
    for k, v in self.signals.items():
        signal_id(k)
        a = np.asarray(v, dtype=np.float64)
        if a.ndim == 1:
            a = a[:, None, None]
        elif a.ndim == 2:
            a = a[:, None, :]
        if a.ndim != 3:
            raise ScenarioError(f"frame signal {k}: expected (T, Bs, K), got {a.shape}")
        if T is not None and a.shape[0] != T:
            raise ScenarioError("frame signals must share T")
        T = a.shape[0]
        self.signals[k] = a

@property
def n_samples(self) -> int:
    return next(iter(self.signals.values())).shape[0] if self.signals else 0

def times_s(self) -> np.ndarray:
    t = self.ticks if self.ticks is not None else self.tick0 + self.stride_ticks * np.arange(self.n_samples)
    return np.asarray(t, dtype=np.float64) * self.dt_s

def to_components(self) -> tuple[Component, ...]:
    if self.stride_ticks <= 0:
        raise ScenarioError("only a uniform tick grid (stride_ticks > 0) can be replayed")
    out = []
    for name, a in self.signals.items():
        spec = SIGNAL_BY_NAME[name]
        if a.shape[2] == 0 or np.all(np.isnan(a)):
            continue
        vals = np.transpose(a, (1, 2, 0))                     # (Bs, K, T)
        kw = dict(params=(self.stride_ticks * self.dt_s,), t0_s=self.tick0 * self.dt_s,
                  linear=self.interp == "linear", hold_before=True, hold_after=True,
                  absolute=name not in self.additive, slow=name in self.slow, provenance=self.provenance,
                  source=self.source, note=self.note or "recorded profile", stream="scenario_frame")
        if spec.level == "aggressor":
            if len(self.aggressor_sites) != a.shape[2]:
                raise ScenarioError(f"frame has {a.shape[2]} aggressor columns but aggressor_sites "
                                    f"{list(self.aggressor_sites)}; name the sites to replay aggressor power")
            for j, site in enumerate(self.aggressor_sites):
                out.append(Component(name, "sampled", site=site, table_v=vals[:, j, :],
                                     label=f"frame:{name}:{site}", **kw))
            continue
        out.append(Component(name, "sampled", table_v=vals, common=vals.shape[1] == 1, label=f"frame:{name}",
                             **kw))
    return tuple(out)

def component_max_rate(c: Component) -> float:
    amp = float(np.max(np.abs(_world_array(c.amp, "amp"))))
    p = c.params
    if c.kind == "pwl":
        table_times_s = np.asarray(c.table_t, dtype=np.float64)
        table_values = np.asarray(c.table_v, dtype=np.float64)
        time_steps_s = np.diff(table_times_s)
        value_steps = np.abs(np.diff(table_values, axis=-1))
        positive_steps = time_steps_s > 0
        return (amp * float(np.max(value_steps[..., positive_steps] / time_steps_s[positive_steps]))
                if np.any(positive_steps) else 0.0)
    if c.kind == "trapezoid":
        edge_rates_per_s = [1.0 / x for x in (p[0], p[2]) if x > 0]
        return amp * max(edge_rates_per_s) if edge_rates_per_s else 0.0
    if c.kind == "rect_sine":
        return amp * math.pi / c.period_s
    if c.kind == "sine":
        return amp * 2.0 * math.pi / c.period_s
    if c.kind == "smooth_step":
        return amp * math.pi / (2.0 * p[0])
    if c.kind == "random_walk":
        return amp * (abs(p[2]) + 4.0 * p[1] / math.sqrt(p[0]))
    if c.kind == "sampled" and c.linear:
        table_values = np.asarray(c.table_v, dtype=np.float64)
        if table_values.shape[-1] < 2:
            return 0.0
        sampled_steps = np.abs(np.diff(table_values, axis=-1))
        if c.periodic:
            sampled_steps = np.concatenate([sampled_steps, np.abs(table_values[..., :1] - table_values[..., -1:])],
                                           axis=-1)
        return amp * float(np.max(sampled_steps)) / p[0]
    return 0.0

def check_time_compression(sc: Scenario, *, fraction: float = COMPRESSION_RATE_FRACTION) -> dict:
    factor = float(sc.time_compression)
    limit = fraction * float(sc.fast_rate_ref_k_per_s)
    rep: dict[str, Any] = {"time_compression": factor, "limit_k_per_s": limit, "components": {}}
    errors = []
    for comp in sc.all_components:
        if not comp.slow:
            continue
        rate = component_max_rate(comp)
        to_k_per_s = comp.spec.rate_to_k_per_s
        name = comp.label or comp.kind
        if to_k_per_s is None:
            rep["components"][name] = {"rate_per_s": rate * factor, "unit": comp.spec.unit, "checked": False}
            if factor > 1.0 and rate > 0.0:
                warnings.warn(f"{name} on {comp.signal} is time-compressed but its unit ({comp.spec.unit}) has no "
                              f"K/s equivalent; the time-compression rate rule cannot check it", RuntimeWarning,
                              stacklevel=3)
            continue
        rate_k_per_s = rate * to_k_per_s
        max_factor = limit / rate_k_per_s if rate_k_per_s > 0 else math.inf
        rep["components"][name] = {"rate_k_per_s": rate_k_per_s * factor, "limit_k_per_s": limit,
                                   "max_compression": max_factor, "checked": True}
        if rate_k_per_s * factor > limit * (1 + 1e-12):
            errors.append(f"{name} on {comp.signal}: {rate_k_per_s:.4g} K/s-equivalent x compression {factor:g} = "
                          f"{rate_k_per_s * factor:.4g} K/s exceeds {fraction:.0%} of the fast-transient rate "
                          f"{sc.fast_rate_ref_k_per_s:.4g} K/s (largest allowed compression {max_factor:.4g})")
    if errors:
        raise CompressionError("time_compression rule (compressed ramps must stay slow): " + "; ".join(errors))
    return rep

def to_dict(self) -> dict:
    return {"scenario_fingerprint": self.scenario_fingerprint, "plant_fingerprint": self.plant_fingerprint,
            "code_fingerprint": self.code_fingerprint,
            "factors": list(self.factors), "max_validated_factor": self.max_validated_factor,
            "metrics": {str(k): dict(v) for k, v in self.metrics.items()},
            "tolerances": {k: list(v) for k, v in self.tolerances.items()}}

@classmethod
def from_dict(cls, d: Mapping) -> "ConvergenceCertificate":
    return cls(scenario_fingerprint=d["scenario_fingerprint"], plant_fingerprint=d["plant_fingerprint"],
               factors=tuple(float(x) for x in d["factors"]), max_validated_factor=float(d["max_validated_factor"]),
               metrics=d["metrics"], tolerances={k: tuple(v) for k, v in d["tolerances"].items()},
               code_fingerprint=str(d.get("code_fingerprint") or ""))

def convergence_plan(sc: Scenario, factors: Sequence[float] = (1.0, 10.0, 100.0), *, cycles: float = 1.0,
                     cycle_s: float | None = None) -> dict[float, tuple[Scenario, float]]:
    cycle_duration_s = cycle_s if cycle_s is not None else sc.slow_cycle_s
    if cycle_duration_s is None:
        raise ScenarioError("convergence_plan needs cycle_s (the scenario declares no slow_cycle_s)")
    compression_factors = sorted({float(factor) for factor in factors} | {1.0})
    out = {}
    for factor in compression_factors:
        scenario = sc.with_compression(factor)
        check_time_compression(scenario)
        out[factor] = (scenario, cycles * cycle_duration_s / factor)
    return out

def assess_convergence(sc: Scenario, results: Mapping[float, Mapping[str, Any]], *,
                       tolerances: Mapping[str, tuple[float, ...]] | None = None,
                       plant_fingerprint: str = "", code_fingerprint: str = "") -> ConvergenceReport:
    tol = dict(DEFAULT_CONVERGENCE_TOLERANCES)
    tol.update(tolerances or {})
    res = {float(k): v for k, v in results.items()}
    if 1.0 not in res:
        raise ScenarioError("assess_convergence needs the factor-1 (uncompressed) results")
    ref = res[1.0]
    missing = [m for m in CONVERGENCE_METRICS if m not in ref]
    if missing:
        raise ScenarioError(f"factor-1 results lack the metrics {missing} (all of CONVERGENCE_METRICS are needed)")
    details: dict[float, dict[str, dict[str, float]]] = {}
    failures: list[str] = []
    passed_upto = 1.0
    ok_chain = True
    for f in sorted(res):
        if f == 1.0:
            continue
        d = {}
        ok = True
        for m in CONVERGENCE_METRICS:
            if m not in res[f]:
                failures.append(f"factor {f:g}: metric {m} missing")
                ok = False
                continue
            a, r, *cap = tol[m]
            x1 = np.asarray(ref[m], float)
            xc = np.asarray(res[f][m], float)
            if x1.shape != xc.shape:
                raise ScenarioError(f"factor {f:g}: {m} has shape {xc.shape}, the factor-1 value {x1.shape}")
            allowed = np.maximum(a, r * np.abs(x1))
            if cap:
                allowed = np.minimum(allowed, cap[0])
            excess = np.abs(xc - x1) - allowed
            good = bool(np.all(excess <= 0.0))
            if x1.ndim == 0:
                d[m] = {"reference": float(x1), "compressed": float(xc), "allowed": float(allowed),
                        "pass": float(good)}
            else:
                d[m] = {"reference": x1.tolist(), "compressed": xc.tolist(), "allowed": allowed.tolist(),
                        "pass": float(good)}
            if not good:
                ok = False
                if x1.ndim == 0:
                    failures.append(f"factor {f:g}: {m} = {float(xc):.6g} vs {float(x1):.6g} "
                                    f"(allowed +-{float(allowed):.3g})")
                else:
                    i = int(np.argmax(np.where(np.isnan(excess), np.inf, excess)))
                    failures.append(f"factor {f:g}: {m} ring {i} = {xc.flat[i]:.6g} vs {x1.flat[i]:.6g} "
                                    f"(allowed +-{allowed.flat[i]:.3g})")
        details[f] = d
        if ok and ok_chain:
            passed_upto = f
        else:
            ok_chain = False
    passed = not failures
    cert = None
    if passed_upto > 1.0:
        cert = ConvergenceCertificate(scenario_fingerprint=sc.fingerprint(include_compression=False),
                                      plant_fingerprint=plant_fingerprint, factors=tuple(sorted(res)),
                                      max_validated_factor=passed_upto,
                                      metrics={str(k): {m: (np.asarray(x).tolist() if np.ndim(x) else x)
                                                        for m, x in v.items()} for k, v in res.items()},
                                      tolerances=tol, code_fingerprint=code_fingerprint)
    return ConvergenceReport(passed=passed, details=details, failures=tuple(failures), certificate=cert)

def require_compression_validated(sc: Scenario, certificate: ConvergenceCertificate | None, *,
                                  plant_fingerprint: str = "", code_fingerprint: str | None = None) -> None:
    factor = float(sc.time_compression)
    if factor == 1.0:
        return
    if certificate is None:
        raise CompressionError(f"scenario {sc.name!r} runs at time_compression {factor:g} without a convergence "
                               f"certificate; run convergence_plan / assess_convergence first")
    if certificate.scenario_fingerprint != sc.fingerprint(include_compression=False):
        raise CompressionError("the convergence certificate belongs to a different scenario")
    if certificate.plant_fingerprint != plant_fingerprint:
        raise CompressionError("the convergence certificate belongs to a different plant configuration")
    if code_fingerprint is not None and certificate.code_fingerprint != code_fingerprint:
        if not certificate.code_fingerprint:
            raise CompressionError("the convergence certificate records no engine-code fingerprint (written before "
                                   "2026-10-16), so it cannot show that the code that runs now converges; run the "
                                   "convergence experiment again")
        raise CompressionError(f"the convergence certificate was made by other engine code or numerics (code "
                               f"fingerprint {certificate.code_fingerprint[:12]}, now {code_fingerprint[:12]}: "
                               f"mrm.sim.manifest.code_fingerprint); run the convergence experiment again")
    if factor > certificate.max_validated_factor * (1 + 1e-12):
        raise CompressionError(f"time_compression {factor:g} exceeds the validated factor "
                               f"{certificate.max_validated_factor:g}")

def static(*, ambient_c: float | None = None) -> generators.Scenario:
    defaults = {} if ambient_c is None else {"thermal.t_base_k": _c_to_k(ambient_c)}
    return generators.Scenario(name="static", defaults=defaults, description="constant ambient, no disturbance")

