def _without_site(fn, base):
    signature = inspect.signature(base)
    fn.__signature__ = signature.replace(parameters=[p for p in signature.parameters.values() if p.name != "site"])
    return fn

def aggressor_direct(*, site: str = "aggressor", waveform: str = "square", power_w: float = 0.1,
                     period_s: float = 0.1, duty: float = 0.5, fall_s: float = 0.0, phase_s: float = 0.0,
                     burst_on_s: float = 0.0, burst_off_s: float = 0.0, t0_s: float = 0.0,
                     provenance: str = "assumed", victim_ring: int = 0) -> generators.Scenario:
    component_options = dict(site=site, phase_s=phase_s, t0_s=t0_s, label=f"aggressor_direct:{site}",
        stream="scenario_aggressor",
              provenance=provenance, source="", note=f"direct {waveform} power waveform")
    if waveform == "parabolic":
        raise generators.ScenarioError("waveform 'parabolic' was the uncorrected slide-10 reading; the shape is a "
                                       "rectified sine of the TEMPERATURE (docs/research/01_lightmatter_public.md, "
                                       "verification log item 5): use a1_slide10_aggressor with a target, or "
                                       "waveform='rectified_sine' for a power waveform")
    if waveform == "square":
        component = generators.square("thermal.aggressor_w", period_s, duty, amp=power_w, **component_options)
    elif waveform == "burst":
        if burst_on_s <= 0:
            raise generators.ScenarioError("burst needs burst_on_s > 0")
        component = generators.const("thermal.aggressor_w", power_w, **component_options)
    elif waveform == "sawtooth":
        component = generators.sawtooth("thermal.aggressor_w", period_s, fall_s=fall_s, amp=power_w,
            **component_options)
    elif waveform == "triangle":
        component = generators.triangle("thermal.aggressor_w", period_s, amp=power_w, **component_options)
    elif waveform == "rectified_sine":
        component = generators.rect_sine("thermal.aggressor_w", period_s, amp=power_w, **component_options)
    elif waveform == "const":
        component = generators.const("thermal.aggressor_w", power_w, **component_options)
    else:
        raise generators.ScenarioError(f"unknown aggressor waveform {waveform!r}")
    if burst_on_s > 0:
        component = generators.with_burst(component, burst_on_s, burst_off_s)
    record = {"provenance": provenance, "source": "", "note": f"direct power waveform {waveform}"}
    return generators.Scenario(name="aggressor_direct",
                               aggressors=(generators.AggressorSpec(site=site, victim_ring=int(victim_ring),
                                                                    power=(component,), record=record),),
                               description=f"direct aggressor power {waveform} {power_w} W at {site}")

def aggressor_from_config(aggressor: Mapping[str, Any] | None,
                          target: Mapping[str, Any] | None) -> generators.Scenario:
    source_options = dict(aggressor or {})
    target_options = dict(target or {})
    site = source_options.pop("site", "aggressor")
    if not target_options:
        try:
            return aggressor_direct(site=site, **source_options)
        except TypeError as e:
            raise generators.ScenarioError(f"scenario.aggressor: {e}") from None
    trajectory = str(target_options.pop("trajectory", target_options.pop("name", "a1"))).lower()
    units = target_options.pop("units", "resonance")
    victim = int(source_options.pop("victim_ring", target_options.pop("victim_ring", 0)))
    if source_options:
        raise generators.ScenarioError(f"scenario.aggressor keys {sorted(source_options)} conflict with scenario.target: a "
                                       f"target calibrates the power, so give the waveform under scenario.target")
    if trajectory in ("a1", "slide10", "a1_slide10_aggressor"):
        return a1_slide10_aggressor(site=site, victim_ring=victim, referencing=units, **target_options)
    if trajectory in ("a2", "808", "a2_808_aggressor"):
        return a2_808_aggressor(site=site, victim_ring=victim, referencing=units, **target_options)
    raise generators.ScenarioError(f"unknown target trajectory {trajectory!r}; known: a1, a2")

def line_enable(*, events: Sequence[Sequence[Any]] = ((0.01, 0, False),)) -> generators.Scenario:
    per_line: dict[int, list[tuple[float, float]]] = {}
    for event in events:
        time_s, lines, on = float(event[0]), event[1], bool(event[2])
        for line_index in _elements(lines) or ():
            per_line.setdefault(line_index, []).append((time_s, 1.0 if on else 0.0))
    components = []
    for line_index, line_events in sorted(per_line.items()):
        line_events.sort()
        components.append(_state_pwl("laser.line_enable", [e[0] for e in line_events],
            [1.0] + [e[1] for e in line_events],
                                elements=(line_index,), label=f"line_enable_{line_index}",
                                    stream="scenario_line_enable",
                                provenance="assumed", source="", note="line enable schedule (07 P1-12)"))
    return generators.Scenario(name="line_enable", components=tuple(components),
                               description=f"line enable events {list(events)}")

def idle(*, t0_s: float = 0.01, t1_s: float | None = None, level: float = 0.0, rings=None) -> generators.Scenario:
    if level not in (0.0, 1.0, 0, 1):
        raise generators.ScenarioError("idle level must be 0 or 1")
    edges = [t0_s] + ([t1_s] if t1_s is not None else [])
    def st(v_idle, v_norm):             # state before t0_s, while idle (and after t1_s)
        return [v_norm, v_idle] + ([v_norm] if t1_s is not None else [])
    elements = _elements(rings)
    component_options = dict(elements=elements, stream="scenario_idle", provenance="assumed", source="",
        note="idle constant level")
    components = (_state_pwl("data.ones_density", edges, st(float(level), 0.5), label="idle_ones", **component_options),
             _state_pwl("data.transition_density", edges, st(0.0, 0.5), label="idle_td", **component_options))
    return generators.Scenario(name="idle", components=components, description=f"idle at level {level} from {t0_s} s")

def bias_step(*, t_s: float = 0.01, delta_v: float = -0.05, rings=None) -> generators.Scenario:
    component = generators.step("tx.bias_offset_v", t_s, delta_v, elements=_elements(rings), label="bias_step",
                        stream="scenario_bias", provenance="assumed", note="bias droop (assumed)")
    return generators.Scenario(name="bias_step", components=(component,),
        description=f"bias step {delta_v} V at {t_s} s")

def _elements(x) -> tuple[int, ...] | None:
    if x is None:
        return None
    if isinstance(x, (int, np.integer)):
        return (int(x),)
    return tuple(int(i) for i in x)

def _state_pwl(signal: str, edges_s: Sequence[float], states: Sequence[float], *, label: str, elements=None,
               stream: str, provenance: str, source: str, note: str) -> generators.Component:
    if len(states) != len(edges_s) + 1:
        raise generators.ScenarioError("state machine needs len(states) == len(edges) + 1")
    edges = [float(x) for x in edges_s]
    if any(b < a for a, b in zip(edges, edges[1:])) or (edges and edges[0] < 0):
        raise generators.ScenarioError("state edges must be >= 0 and non-decreasing")
    times_s = [0.0]
    values = [float(states[0])]
    for i, edge_s in enumerate(edges):
        times_s += [edge_s, edge_s]
        values += [float(states[i]), float(states[i + 1])]
    if len(times_s) == 1:
        times_s, values = [0.0, 1.0], [values[0], values[0]]
    return generators.pwl(signal, times_s, values, absolute=True, elements=elements, label=label, stream=stream,
                          provenance=provenance, source=source, note=note)

def register(name: str, *, aliases: tuple[str, ...] = (), overwrite: bool = False):
    def deco(fn):
        for candidate in (name,) + tuple(aliases):
            if not overwrite and (candidate in _REGISTRY or candidate in ALIASES) and _REGISTRY.get(candidate,
                None) is not fn:
                raise ValueError(f"scenario name {candidate!r} is already registered")
        _REGISTRY[name] = fn
        for alias in aliases:
            ALIASES[alias] = name
        return fn
    return deco

def deco(fn):
    for candidate in (name,) + tuple(aliases):
        if not overwrite and (candidate in _REGISTRY or candidate in ALIASES) and _REGISTRY.get(candidate,
            None) is not fn:
            raise ValueError(f"scenario name {candidate!r} is already registered")
    _REGISTRY[name] = fn
    for alias in aliases:
        ALIASES[alias] = name
    return fn

def resolve(name: str) -> Callable[..., generators.Scenario]:
    if not isinstance(name, str) or not name:
        raise generators.ScenarioError(f"scenario name must be a non-empty string, got {name!r}")
    key = name.strip()
    if key in _REGISTRY:
        return _REGISTRY[key]
    if key.lower() in ALIASES:
        return _REGISTRY[ALIASES[key.lower()]]
    if ":" in key:
        module_name, attribute_name = key.split(":", 1)
        try:
            builder = getattr(importlib.import_module(module_name), attribute_name)
        except (ImportError, AttributeError) as e:
            raise generators.ScenarioError(f"cannot import scenario builder {key!r}: {e}") from None
        if not callable(builder):
            raise generators.ScenarioError(f"{key!r} is not callable")
        return builder
    import difflib
    suggestions = difflib.get_close_matches(key, available() + sorted(ALIASES), n=3)
    raise generators.ScenarioError(f"unknown scenario {name!r}" + (f"; did you mean {suggestions}?" if suggestions else
                                                                  f"; known: {available()}"))

def create(name: str, **params) -> generators.Scenario:
    builder = resolve(name)
    try:
        signature = inspect.signature(builder)
        signature.bind(**params)
    except TypeError as e:
        raise generators.ScenarioError(
            f"scenario {name!r}: {e}; signature {name}{inspect.signature(builder)}") from None
    except ValueError:
        pass
    scenario = builder(**params)
    if not isinstance(scenario, generators.Scenario):
        raise generators.ScenarioError(f"builder {name!r} returned {type(scenario).__name__}, not a Scenario")
    return scenario

def unflatten(d: Mapping[str, Any] | None) -> dict:
    out: dict = {}
    for key, value in (d or {}).items():
        parts = str(key).split(".")
        node = out
        for p in parts[:-1]:
            node = node.setdefault(p, {})
            if not isinstance(node, dict):
                raise generators.ScenarioError(f"conflicting scenario parameter {key!r}")
        if isinstance(value, Mapping):
            node.setdefault(parts[-1], {}).update(unflatten(value))
        else:
            node[parts[-1]] = value
    return out

def _config_getter(cfg) -> Callable[[str, Any], Any]:
    if hasattr(cfg, "get") and hasattr(cfg, "leaves"):          # mrm.params.config.Config
        return lambda path, default=None: cfg.get(path, default)
    if isinstance(cfg, Mapping):
        def get(path, default=None):
            if path in cfg:
                v = cfg[path]
            else:
                v = cfg
                for p in path.split("."):
                    if isinstance(v, Mapping) and p in v:
                        v = v[p]
                    else:
                        return default
            if isinstance(v, Mapping) and "value" in v and "provenance" in v:      # a provenance leaf
                return v["value"]
            return v
        return get
    raise TypeError("cfg must be a mrm.params Config or a mapping")

def get(path, default=None):
    if path in cfg:
        v = cfg[path]
    else:
        v = cfg
        for p in path.split("."):
            if isinstance(v, Mapping) and p in v:
                v = v[p]
            else:
                return default
    if isinstance(v, Mapping) and "value" in v and "provenance" in v:      # a provenance leaf
        return v["value"]
    return v

def __getattr__(name):
    if name == "record_vectors":
        from mrm.sim.vectors import record_vectors
        return record_vectors
    raise AttributeError(f"module 'mrm.sim' has no attribute {name!r}")

def _wire_int(lo: int, hi: int, name: str) -> str:
    if lo >= 0:
        for wire_type in ("<u1", "<u2", "<u4", "<u8"):
            if hi <= np.iinfo(np.dtype(wire_type)).max:
                return wire_type
    else:
        for wire_type in ("<i1", "<i2", "<i4", "<i8"):
            info = np.iinfo(np.dtype(wire_type))
            if lo >= info.min and hi <= info.max:
                return wire_type
    raise BridgeError(f"{name}: range [{lo}, {hi}] fits no 64-bit integer")

def _flag_word(nbits: int, group: str) -> str:
    for wire_type, capacity_bits in (("<u1", 8), ("<u2", 16), ("<u4", 32), ("<u8", 64)):
        if nbits <= capacity_bits:
            return wire_type
    raise BridgeError(f"{nbits} flag bits in {group}: more than 64")

@property
def nbytes(self) -> int:
    return np.dtype(self.dtype).itemsize * self.count

def group_of(shape: tuple, name: str) -> str:
    if shape == (int(spec.n_rings),) and "N" in spec.channels[name].shape:
        return "flags"
    if shape == (1,):
        return "dflags"
    raise BridgeError(f"{name}: flag shape {shape} is neither per ring (N,) nor per world (1,)")

@property
def sensors(self) -> list[str]:
    out = [f.name for f in self.obs_fields if f.name not in ("flags", "dflags")]
    out += [b.channel for b in self.flag_bits if b.what == "value"]
    return [n for n in self.channels if n in set(out)]

@property
def actuators(self) -> list[str]:
    return [f.name for f in self.act_fields]

@property
def obs_payload_bytes(self) -> int:
    return 8 + self.n_batch * self.obs_record_bytes

@property
def act_payload_bytes(self) -> int:
    return 16 + self.n_batch * self.act_record_bytes

def describe(self) -> dict:
    return {"protocol": PROTOCOL_VERSION, "profile": self.profile, "B": self.n_batch, "N": self.n_rings,
            "obs": [self._row(f) for f in self.obs_fields],
            "act": [self._row(f) for f in self.act_fields],
            "flag_bits": [dict(channel=b.channel, what=b.what, group=b.group, bit=b.bit) for b in self.flag_bits],
            "obs_record_bytes": self.obs_record_bytes, "act_record_bytes": self.act_record_bytes,
            "sensors": self.sensors, "actuators": self.actuators}

def _np_dtype(self, fields: tuple) -> np.dtype:
    return np.dtype({"names": [f.name for f in fields],
                     "formats": [(f.dtype, (f.count,)) if f.count > 1 or f.name in ("flags",) else f.dtype
                                 for f in fields],
                     "offsets": [f.offset for f in fields],
                     "itemsize": sum(f.nbytes for f in fields)})

@property
def obs_dtype(self) -> np.dtype:
    return self._np_dtype(self.obs_fields)

@property
def act_dtype(self) -> np.dtype:
    return self._np_dtype(self.act_fields)

@cached_property
def _plan(self) -> dict:
    B = self.n_batch
    value_fields = []
    for field_info in self.obs_fields:
        if field_info.name in ("flags", "dflags"):
            continue
        channel = self.channels[field_info.name]
        value_fields.append((field_info.name, np.dtype(field_info.dtype), field_info.count, field_info.offset,
            field_info.nbytes, (B,) + field_info.shape, channel.np_dtype))
    lo = np.concatenate([np.full(v[2], int(self.channels[v[0]].min),
        np.int64) for v in value_fields]) if value_fields \
        else np.zeros(0, np.int64)
    hi = np.concatenate([np.full(v[2], int(self.channels[v[0]].max),
        np.int64) for v in value_fields]) if value_fields \
        else np.zeros(0, np.int64)
    groups = []
    for field_info in self.obs_fields:
        if field_info.name not in ("flags", "dflags"):
            continue
        bits = []
        for b in self.flag_bits:
            if b.group != field_info.name:
                continue
            shape = (B, field_info.count)
            if b.what == "value":
                shape = (B,) + self.channels[b.channel].element_shape({"B": B, "N": self.n_rings, "M": 1, "L": 1,
                                                                       "S": 1})
            bits.append((b.what, b.channel, np.uint64(b.bit), shape))
        shifts = np.array([int(b[2]) for b in bits], dtype=np.uint64)
        groups.append((field_info.name, field_info.count, np.dtype(field_info.dtype), field_info.offset,
            field_info.nbytes, bits, shifts))
    action_fields = []
    for field_info in self.act_fields:
        channel = self.channels[field_info.name]
        action_fields.append((field_info.name, np.dtype(field_info.dtype), field_info.count, field_info.offset,
            field_info.nbytes, (B,) + field_info.shape, channel.np_dtype,
                     int(channel.min), int(channel.max)))
    return {"vals": value_fields, "lo": lo, "hi": hi, "groups": groups, "acts": action_fields}

def _range_error(self, names_counts, a: np.ndarray, lo: np.ndarray, hi: np.ndarray) -> BridgeError:
    bad_column = np.flatnonzero(((a < lo) | (a > hi)).any(axis=0))[0]
    column_offset = 0
    for name, count in names_counts:
        if bad_column < column_offset + count:
            channel = self.channels[name]
            return BridgeError(f"{name}: value outside the channel range [{channel.min}, {channel.max}] cannot be framed")
        column_offset += count
    return BridgeError("value outside its channel range")              # pragma: no cover

def encode_obs(self, tick: int, sensors: Mapping[str, np.ndarray], new: Mapping[str, np.ndarray]) -> bytes:
    B = self.n_batch
    plan = self._plan
    buffer = np.empty((B, self.obs_record_bytes), dtype=np.uint8)
    value_fields = plan["vals"]
    if value_fields:
        columns = []
        for name, _wire_dtype, count, *_ in value_fields:
            a = np.asarray(sensors[name])
            if a.dtype == np.uint64:
                a = np.minimum(a, np.uint64(2**63 - 1))
            columns.append(a.reshape(B, count).astype(np.int64, copy=False))
        all_values = np.concatenate(columns, axis=1)
        if (all_values < plan["lo"]).any() or (all_values > plan["hi"]).any():
            raise self._range_error([(v[0], v[2]) for v in value_fields], all_values, plan["lo"], plan["hi"])
        for (name, wire_dtype, count, offset, nbytes, _shape, _chan_dtype), column in zip(value_fields, columns):
            buffer[:, offset:offset + nbytes] = column.astype(wire_dtype).view(np.uint8).reshape(B, nbytes)
    for _group, count, wire_dtype, offset, nbytes, bits, shifts in plan["groups"]:
        bit_values = np.stack([np.asarray(sensors[ch] if what == "value" else new[ch]).reshape(B, count)
                               for what, ch, _bit, _shape in bits], axis=-1)
        words = np.bitwise_or.reduce(bit_values.astype(np.uint64) << shifts, axis=-1)
        buffer[:, offset:offset + nbytes] = words.astype(wire_dtype).view(np.uint8).reshape(B, nbytes)
    return struct.pack("<Q", int(tick)) + buffer.tobytes()

def decode_obs(self, payload: bytes) -> tuple[int, dict[str, np.ndarray], dict[str, np.ndarray]]:
    if len(payload) != self.obs_payload_bytes:
        raise BridgeError(f"OBS payload of {len(payload)} bytes, layout needs {self.obs_payload_bytes}")
    B = self.n_batch
    plan = self._plan
    tick = struct.unpack_from("<Q", payload, 0)[0]
    buffer = np.frombuffer(payload, dtype=np.uint8, offset=8).reshape(B, self.obs_record_bytes)
    sensors: dict[str, np.ndarray] = {}
    new: dict[str, np.ndarray] = {}
    for name, wire_dtype, count, offset, nbytes, shape, chan_dtype in plan["vals"]:
        sensors[name] = np.ascontiguousarray(buffer[:, offset:offset + nbytes]).view(wire_dtype).reshape(
            shape).astype(chan_dtype)
    for _group, count, wire_dtype, offset, nbytes, bits, shifts in plan["groups"]:
        words = np.ascontiguousarray(buffer[:, offset:offset + nbytes]).view(wire_dtype).reshape(B, count,
            1).astype(
            np.uint64)
        all_bits = ((words >> shifts) & np.uint64(1)).astype(bool)          # (B, count, bits)
        for j, (what, ch, _bit, shape) in enumerate(bits):
            flag_values = np.ascontiguousarray(all_bits[:, :, j])
            if what == "value":
                sensors[ch] = flag_values.reshape(shape)
            else:
                new[ch] = flag_values
    return int(tick), sensors, new

def encode_act(self, tick: int, actions: Mapping[str, np.ndarray]) -> bytes:
    B = self.n_batch
    buffer = np.zeros((B, self.act_record_bytes), dtype=np.uint8)
    mask = 0
    for j, (name, wire_dtype, count, offset, nbytes, _shape, _chan_dtype, lo, hi) in enumerate(self._plan["acts"]):
        if name not in actions:
            continue
        values = np.asarray(actions[name])
        if values.dtype.kind not in "biu":
            raise BridgeError(f"{name}: integer codes expected, got {values.dtype}")
        if values.dtype == np.uint64:
            values = np.minimum(values, np.uint64(2**63 - 1))
        values = values.reshape(B, count).astype(np.int64, copy=False)
        if values.size and (values.min() < lo or values.max() > hi):
            raise BridgeError(f"{name}: value outside the channel range [{lo}, {hi}] cannot be framed")
        buffer[:, offset:offset + nbytes] = values.astype(wire_dtype).view(np.uint8).reshape(B, nbytes)
        mask |= 1 << j
    return struct.pack("<QII", int(tick), mask, 0) + buffer.tobytes()

def decode_act(self, payload: bytes) -> tuple[int, int, dict[str, np.ndarray]]:
    if len(payload) != self.act_payload_bytes:
        raise BridgeError(f"ACT payload of {len(payload)} bytes, layout needs {self.act_payload_bytes}")
    B = self.n_batch
    tick, mask, _reserved = struct.unpack_from("<QII", payload, 0)
    if mask >> len(self.act_fields):
        raise BridgeError(f"write_mask 0x{mask:x} sets bits beyond the {len(self.act_fields)} action fields")
    buffer = np.frombuffer(payload, dtype=np.uint8, offset=16).reshape(B, self.act_record_bytes)
    out = {}
    for j, (name, wire_dtype, count, offset, nbytes, shape, chan_dtype, lo, hi) in enumerate(self._plan["acts"]):
        if mask >> j & 1:
            values = np.ascontiguousarray(buffer[:, offset:offset + nbytes]).view(wire_dtype).reshape(shape).astype(
                np.int64)
            if values.size and (values.min() < lo or values.max() > hi):
                raise BridgeError(f"{name}: value outside the channel range [{lo}, {hi}] in an ACT frame")
            out[name] = values.astype(chan_dtype)
    return int(tick), int(mask), out

def __init__(self, rfd: int, wfd: int, *, proc: subprocess.Popen | None = None, own_fds: bool = False):
    self.rfd, self.wfd, self.proc, self.own_fds = int(rfd), int(wfd), proc, own_fds
    self._closed = False

def send(self, data: bytes) -> None:
    remaining = memoryview(data)
    while remaining:
        try:
            written = os.write(self.wfd, remaining)
        except BrokenPipeError:
            raise BridgeError(self._lost("write")) from None
        remaining = remaining[written:]

def recv_exact(self, n: int, eof_ok: bool = False) -> bytes:
    buffer = bytearray(n)
    view = memoryview(buffer)
    received = 0
    while received < n:
        chunk = os.read(self.rfd, n - received)
        if not chunk:
            if eof_ok and received == 0:
                return b""
            raise BridgeError(self._lost("read") + f" ({received} of {n} bytes)")
        view[received:received + len(chunk)] = chunk
        received += len(chunk)
    return bytes(buffer)

def _lost(self, what: str) -> str:
    exit_code = None if self.proc is None else self.proc.poll()
    return f"bridge peer closed the stream during {what}" + ("" if exit_code is None else f" (exit code {exit_code})")

def close(self) -> None:
    if self._closed:
        return
    self._closed = True
    if self.proc is not None:
        for f in (self.proc.stdin,):
            try:
                f.close()
            except OSError:
                pass
        try:
            self.proc.wait(timeout=30)
        except subprocess.TimeoutExpired:
            self.proc.kill()
            self.proc.wait()
        if self.proc.stdout is not None:
            self.proc.stdout.close()
    elif self.own_fds:
        for fd in {self.rfd, self.wfd}:
            try:
                os.close(fd)
            except OSError:
                pass

def __init__(self, sock: socket.socket, *, timeout_s: float | None = None):
    self.sock = sock
    if sock.family in (socket.AF_INET, socket.AF_INET6):
        sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
    if timeout_s is not None:
        sock.settimeout(float(timeout_s))

def send(self, data: bytes) -> None:
    try:
        self.sock.sendall(data)
    except (BrokenPipeError, ConnectionResetError):
        raise BridgeError("bridge peer closed the socket during write") from None
    except TimeoutError:
        raise self._timeout("write") from None

def recv_exact(self, n: int, eof_ok: bool = False) -> bytes:
    buffer = bytearray(n)
    view = memoryview(buffer)
    received = 0
    while received < n:
        try:
            read_count = self.sock.recv_into(view[received:], n - received)
        except TimeoutError:
            raise self._timeout(f"read ({received} of {n} bytes)") from None
        except ConnectionResetError:
            raise BridgeError(f"bridge peer reset the connection during read ({received} of {n} bytes)") from None
        if read_count == 0:
            if eof_ok and received == 0:
                return b""
            raise BridgeError(f"bridge peer closed the socket during read ({received} of {n} bytes)")
        received += read_count
    return bytes(buffer)

def close(self) -> None:
    try:
        self.sock.close()
    except OSError:
        pass

def spawn(cmd: Sequence[str], *, env: Mapping[str, str] | None = None, cwd: str | None = None,
          stderr=None) -> StreamTransport:
    proc = subprocess.Popen(list(cmd), stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=stderr, bufsize=0,
                            env=None if env is None else dict(env), cwd=cwd)
    return StreamTransport(proc.stdout.fileno(), proc.stdin.fileno(), proc=proc)

def stdio() -> StreamTransport:
    sys.stdout.flush()
    wfd = os.dup(1)
    os.dup2(2, 1)
    return StreamTransport(0, wfd, own_fds=False)

def connect(host: str, port: int, *, timeout_s: float | None = None) -> SocketTransport:
    connection = socket.create_connection((host, int(port)), timeout=timeout_s)
    connection.settimeout(timeout_s)
    return SocketTransport(connection, timeout_s=timeout_s)

def read_frame(tr: Transport, *, eof_ok: bool = False) -> tuple[int, bytes] | None:
    header = tr.recv_exact(_HEADER.size, eof_ok=eof_ok)
    if not header:
        return None
    magic, version, kind, n_payload = _HEADER.unpack(header)
    if magic != MAGIC:
        raise BridgeError(f"bad frame magic {magic!r} (expected {MAGIC!r}); the stream is out of sync")
    if version != PROTOCOL_VERSION:
        raise BridgeError(f"peer speaks bridge protocol {version}, this side {PROTOCOL_VERSION}")
    if kind not in _KIND_NAME:
        raise BridgeError(f"unknown frame kind {kind}")
    if n_payload > _MAX_PAYLOAD:
        raise BridgeError(f"frame payload of {n_payload} bytes is implausible")
    payload = tr.recv_exact(n_payload) if n_payload else b""
    if kind == KIND["ERROR"]:
        raise BridgeError("peer error: " + payload.decode("utf-8", "replace"))
    return kind, payload

def _expect(tr: Transport, kind: str) -> bytes:
    got_kind, payload = read_frame(tr)
    if got_kind != KIND[kind]:
        raise BridgeError(f"expected a {kind} frame, got {_KIND_NAME[got_kind]}")
    return payload

def _send_error(tr: Transport, msg: str) -> None:
    try:
        write_frame(tr, KIND["ERROR"], msg.encode("utf-8")[:4096])
    except (BridgeError, OSError):
        pass

@classmethod
def unpack(cls, payload: bytes) -> "Hello":
    if len(payload) < _HELLO_FIXED.size:
        raise BridgeError("HELLO frame too short")
    fields = _HELLO_FIXED.unpack_from(payload, 0)
    layout_json = payload[_HELLO_FIXED.size:_HELLO_FIXED.size + fields[-1]]      # v[-1] - length of the layout JSON
    if len(layout_json) != fields[-1]:
        raise BridgeError("HELLO frame truncated")

    def text(b):
        return b.rstrip(b"\0").decode()
    return cls(text(fields[0]), text(fields[1]), text(fields[2]), *fields[3:13], fields[13], fields[14],
        json.loads(layout_json))

def _hello_for(spec: ControllerSpec, layout: FrameLayout, latency_ticks: int) -> Hello:
    return Hello(layout.fingerprint(), spec.fingerprint(), layout.profile, spec.n_batch, spec.n_rings, spec.n_lines,
                 len(spec.temp_sensors), spec.samples_per_step, spec.period_ticks, layout.obs_record_bytes,
                 layout.act_record_bytes, layout.obs_payload_bytes, layout.act_payload_bytes, int(latency_ticks),
                 float(spec.tick_s), layout.describe())

@property
def round_trip_us(self) -> float:
    return 1e6 * self.stats["rt_s"] / max(1, self.stats["steps"])

def close(self) -> None:
    if self._closed:
        return
    self._closed = True
    try:
        write_frame(self.transport, KIND["BYE"])
    except (BridgeError, OSError):
        pass
    self.transport.close()

def _check_bridgeable(controller: Any) -> None:
    from mrm.control.api import controller_fast_kernel
    if getattr(controller, "truth_fed", False):
        raise BridgeError(f"{getattr(controller, 'name', controller)!r} is Truth-fed (the oracle): Truth never "
                          f"crosses the bridge")
    if controller_fast_kernel(controller) is not None:
        raise BridgeError(f"{getattr(controller, 'name', controller)!r} has a fast_kernel: its per-sample inputs and "
                          f"offsets are not in the edge frame, so a bridged run would silently drop it; "
                          f"run it in-process")

def _warm_start_registers() -> frozenset:
    from mrm.plant.io import DST_BIAS, DST_HEATER, DST_NAMES
    return frozenset(n for n, d in DST_NAMES.items() if d in (DST_HEATER, DST_BIAS))

def restrict_spec(spec: ControllerSpec, sensors: Sequence[str]) -> ControllerSpec:
    import dataclasses
    from mrm.core.channels import make_abi_layout
    keep = set(sensors)
    channels = {n: c for n, c in spec.channels.items() if c.kind == "actuator" or n in keep}
    if len(channels) == len(spec.channels):
        return spec
    abi = make_abi_layout(channels, spec.dims, spec.bindings, obs_ids={f.name: f.ch_id for f in spec.layout.obs},
                          act_ids={f.name: f.ch_id for f in spec.layout.act})
    return dataclasses.replace(spec, channels=channels, layout=abi)

def spec_for(cfg, scenario=None, batch: int = 1) -> ControllerSpec:
    from mrm import params
    from mrm.scenarios import registry as scenario_registry
    from mrm.scenarios.generators import Scenario
    cfg_loaded = params.load(cfg) if isinstance(cfg, str) else cfg
    if scenario is None:
        scenario_object = scenario_registry.from_config(cfg_loaded)
    elif isinstance(scenario, str):
        scenario_object = scenario_registry.create(scenario)
    elif isinstance(scenario, Scenario):
        scenario_object = scenario
    else:
        raise TypeError(f"scenario must be None, a name or a Scenario, got {type(scenario).__name__}")
    return ControllerSpec.from_config(cfg_loaded, n_batch=int(batch), nominal=cfg_loaded,
        scenario_drives=scenario_object.drives,
                                      scenario_offsets=scenario_object.offsets)

def _load_cfg(preset: str, overrides: Sequence[str]):
    from mrm import params
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", category=UserWarning)
        return params.load(preset, overrides=list(overrides) or None)

def _scenario(name: str | None, params_json: str | None):
    if name is None:
        return None
    from mrm.scenarios import registry as scenario_registry
    return scenario_registry.create(name, **(json.loads(params_json) if params_json else {}))

def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="python -m mrm.sim.bridge", description='exchange sensor readings and commands with an external controller at each control tick.')
    add_arguments(parser)
    return run_command(parser.parse_args(argv))

