def _declared_line(P, S, b, n):
    return _declared_line_a(S.ring_int[b, RI_ASSIGN], P.ring_to_line, P.n_lines, n)

@njit(cache=True, inline="always")
def _declared_line_a(assign, ring_to_line, n_lines, n):
    a = assign[n]
    return a if (a >= 0 and a < n_lines) else ring_to_line[n]

@njit(cache=True, inline="always")
def _input_row_views(packed_f, packed_i):
    n_rings = packed_i[optics.SELF_HEATING_HEADER_INDEX_RING_COUNT]
    n_lines = packed_i[optics.SELF_HEATING_HEADER_INDEX_LASER_LINE_COUNT]
    offset = packed_i[optics.SELF_HEATING_HEADER_INDEX_RING_PARAMETER_BLOCK_OFFSET]
    ring_rows = packed_f[offset : offset + optics.SELF_HEATING_RING_ROW_COUNT * n_rings].reshape(
        (optics.SELF_HEATING_RING_ROW_COUNT, n_rings)
    )
    offset = packed_i[optics.SELF_HEATING_HEADER_INDEX_RING_LINE_PARAMETER_BLOCK_OFFSET]
    line_rows = packed_f[
        offset : offset + optics.SELF_HEATING_RING_LINE_ROW_COUNT * n_rings * n_lines
    ].reshape((optics.SELF_HEATING_RING_LINE_ROW_COUNT, n_rings, n_lines))
    return ring_rows, line_rows

@njit(cache=True, _nrt=False)
def dphi_dlamres(lam_l, shift, t_rt):
    x = lam_l - shift
    return _TWO_PI * C0 * t_rt / (x * x)

@njit(cache=True, _nrt=False)
def resonance_detuning(rp_row, lam_l, shift, m):
    x_end = lam_l - shift
    return cold_coordinate(rp_row, x_end, float(m)) - x_end

@njit(cache=True, inline="always")
def _ext_offset(packed_i, j):
    return packed_i[packed_i.shape[0] - N_EXT + j]

@njit(cache=True, _nrt=False)
def cache_update_laser_wavelengths(packed_f, packed_i, lam_l):
    o = _ext_offset(packed_i, E_LAM)
    changed = False
    for l in range(lam_l.shape[0]):
        if not (packed_f[o + l] == lam_l[l]):
            changed = True
            packed_f[o + l] = lam_l[l]
    return changed

@njit(cache=True, _nrt=False, inline="always")
def eng_pabs(t, k, packed_f, packed_i):
    return _eng_pabs_general(t, k, packed_f, packed_i)

@njit(cache=True, _nrt=False)
def eng_commit(t, k, packed_f, packed_i, full):
    if optics.cache_matches_last_optical_evaluation(k, t, packed_f, packed_i):
        o_thru = _ext_offset(packed_i, E_THRU)
        o_pcur = packed_i[optics.SELF_HEATING_HEADER_INDEX_CURRENT_RING_INPUT_POWER_OFFSET]
        for l in range(packed_i[optics.SELF_HEATING_HEADER_INDEX_LASER_LINE_COUNT]):
            packed_f[o_pcur + l] = packed_f[o_thru + l]
        optics.sh_pass_on(k, packed_f, packed_i, full)
    else:
        optics.selfheat_commit(t, k, packed_f, packed_i)
    optics.cache_clear_last_optical_evaluation(packed_f, packed_i)

@njit(cache=True, _nrt=False)
def swing_capacitance_row(v_lo, v_hi, grid, c_col, cum_q, fill, length_m, out_c_eff):
    g = grid.shape[0]
    for n in range(out_c_eff.shape[0]):
        lo = v_lo[n]
        hi = v_hi[n]
        fl = fill[electrical._bidx(fill, n)] * length_m[electrical._bidx(length_m, n)]
        if abs(hi - lo) > 1e-9:
            out_c_eff[n] = fl * (_charge_at(hi, grid, c_col, cum_q, g)
                                 - _charge_at(lo, grid, c_col, cum_q, g)) / (hi - lo)
        else:
            cp, _ = electrical._interp_lin(0.5 * (lo + hi), grid, c_col)
            out_c_eff[n] = fl * cp

@njit(cache=True, inline="always")
def _charge_at(x, grid, col, cum, g):
    if x <= grid[0]:
        return col[0] * (x - grid[0])
    if x >= grid[g - 1]:
        return cum[g - 1] + col[g - 1] * (x - grid[g - 1])
    j = _as_unsigned_array_index(
        electrical.grid_index(x, grid)
    )  # np.searchsorted(grid, x) - 1, without the binary search
    gj = grid[j]
    h = grid[j + _as_unsigned_array_index(1)] - gj
    d = x - gj
    cj = col[j]
    return cum[j] + d * (cj + 0.5 * (d / h) * (col[j + _as_unsigned_array_index(1)] - cj))

@njit(cache=True, _nrt=False)
def _solve_ring_eng(k, packed_f, packed_i, t_other, g, t_start, p_max, d2p_max, max_iter, tol_k):
    if g == 0.0:
        p, d = eng_pabs(t_other, k, packed_f, packed_i)
        return t_other, p, d, 0, STATUS_CONVERGED
    if g != g:                                # NaN gain - no bracket exists. counted as a failed solve by the caller
        p, d = eng_pabs(t_other, k, packed_f, packed_i)
        return t_other, p, d, 0, STATUS_NAN_GAIN
    # F(lo) = (lo - t_other) - g P(lo) <= 0 and F(hi) >= 0 for either sign of g when 0 <= P <= p_max
    lo = min(t_other, t_other + g * p_max)
    hi = max(t_other, t_other + g * p_max)
    t0 = t_start
    if t0 != t0:                              # NaN - start at the cold end. +-inf select the high/low end (below)
        t0 = t_other
    if t0 < lo:
        t0 = lo
    if t0 > hi:
        t0 = hi
    p0, d0 = eng_pabs(t0, k, packed_f, packed_i)
    f0 = t0 - t_other - g * p0
    if abs(f0) <= tol_k:
        return t0, p0, d0, 0, STATUS_CONVERGED
    sgn = 1.0 if f0 < 0.0 else -1.0          # the root lies in the direction sgn from t0
    near, f_near, p_near, d_near = t0, f0, p0, d0
    far = hi if sgn > 0.0 else lo
    f_far, p_far, d_far = 0.0, 0.0, 0.0
    have_far = False
    curv_k = abs(g) * d2p_max if d2p_max > 0.0 else 0.0
    used = 0
    for it in range(1, max_iter + 1):
        if (far - near) * sgn <= tol_k:
            break
        used = it
        fp = 1.0 - g * d_near                # F'(near). |F| decreases at this rate along sgn
        af = abs(f_near)
        cand = math.nan
        if curv_k > 0.0 and math.isfinite(fp):
            step = 2.0 * af / (fp + math.sqrt(fp * fp + 2.0 * curv_k * af))
            c = near + sgn * step
            if (far - c) * sgn > 0.0:
                cand = c
            elif not have_far:
                cand = far                    # the bracket end - F(far) has the root's sign by the p_max bound
            # if this reaches a known sign change, use the secant fallback below
        elif math.isfinite(fp) and fp > 0.0:
            c = near + sgn * af / fp
            if (c - near) * sgn > 0.0 and (far - c) * sgn > 0.0:
                cand = c
        if math.isnan(cand):
            if have_far and f_far != f_near:
                c = near - f_near * (far - near) / (f_far - f_near)
                if (c - near) * sgn > 0.0 and (far - c) * sgn > 0.0:
                    cand = c
            if math.isnan(cand):
                cand = 0.5 * (near + far)
        pc, dc = eng_pabs(cand, k, packed_f, packed_i)
        fc = cand - t_other - g * pc
        if abs(fc) <= tol_k:
            return cand, pc, dc, it, STATUS_CONVERGED
        if fc * f_near > 0.0:
            near, f_near, p_near, d_near = cand, fc, pc, dc
        else:
            far, f_far, p_far, d_far = cand, fc, pc, dc
            have_far = True
    if (far - near) * sgn <= tol_k:
        if have_far:
            if abs(f_far) < abs(f_near):
                return far, p_far, d_far, used, STATUS_CONVERGED
            return near, p_near, d_near, used, STATUS_CONVERGED
        # no sign change met up to the bracket end - with a valid p_max, F(bracket end) has the root's sign or is 0 (then |F| <= tol_k returned above).
        # here P_abs exceeded p_max
        return near, p_near, d_near, used, STATUS_BOUND
    return near, p_near, d_near, used, STATUS_MAX_ITER

@njit(cache=True)
def _lag_lists(lag_src, lag_kind, obs_ptr, heater_obs, heater_src, src_scale):
    m_tot = lag_kind.shape[0]
    n_exo = 0
    n_cross = 0
    for m in range(m_tot):
        if lag_kind[m] == LAG_EXOGENOUS:
            n_exo += 1
        elif lag_kind[m] == LAG_OPT_CROSS_RING:
            n_cross += 1
    idx_exo = np.empty(n_exo, np.int64)
    idx_cross = np.empty(n_cross, np.int64)
    idx_ax = np.empty(m_tot - n_exo - n_cross, np.int64)
    i0 = 0
    i1 = 0
    i2 = 0
    for m in range(m_tot):
        if lag_kind[m] == LAG_EXOGENOUS:
            idx_exo[i0] = m
            i0 += 1
        elif lag_kind[m] == LAG_OPT_CROSS_RING:
            idx_cross[i1] = m
            i1 += 1
        else:
            idx_ax[i2] = m
            i2 += 1
    unit = True
    for s in range(src_scale.shape[0]):
        if not (src_scale[s] == 1.0):
            unit = False
    nr = heater_obs.shape[0]
    hs_lo = np.full(nr, -1, np.int64)
    hs_hi = np.full(nr, -1, np.int64)
    for n in range(nr):
        o = heater_obs[n]
        lo = -1
        hi = -1
        for m in range(obs_ptr[o], obs_ptr[o + 1]):
            if lag_src[m] == heater_src[n]:
                if lo < 0:
                    lo = m
                hi = m + 1
        ok = lo >= 0
        for m in range(max(lo, 0), max(hi, 0)):
            if lag_src[m] != heater_src[n]:
                ok = False
        if ok:
            hs_lo[n] = lo
            hs_hi[n] = hi
    return idx_exo, idx_cross, idx_ax, unit, hs_lo, hs_hi

@njit(cache=True, _nrt=False)
def _thermal_gains(c0, c1, lag_src, lag_kind, obs_ptr, heater_obs, heater_src, src_scale, w, gobs, gsplit):
    for m in range(lag_kind.shape[0]):
        w[m] = src_scale[lag_src[m]] * (c0[m] + c1[m])
    for o in range(obs_ptr.shape[0] - 1):
        g = 0.0
        for m in range(obs_ptr[o], obs_ptr[o + 1]):
            if lag_kind[m] == LAG_OPT_SELF:
                g += src_scale[lag_src[m]] * (c0[m] + c1[m])
        gobs[o] = g
    for n in range(heater_obs.shape[0]):
        o = heater_obs[n]
        g = 0.0
        for m in range(obs_ptr[o], obs_ptr[o + 1]):
            if lag_src[m] == heater_src[n]:
                g += src_scale[lag_src[m]] * (c0[m] + c1[m])
        gsplit[n] = g

@njit(cache=True, _nrt=False)
def _heater_split(x, a, c0, c1, lag_src, obs_ptr, obs_end, obs, self_src, lo_s, hi_s, unit, u0, u1, src_scale):
    pre = 0.0
    lo = obs_ptr[obs]
    hi = obs_end[obs]
    if lo_s < 0 or not unit:
        for m in range(lo, hi):
            s = lag_src[m]
            pre += a[m] * x[m]
            if s != self_src:
                pre += src_scale[s] * (c0[m] * u0[s] + c1[m] * u1[s])
        return pre
    for m in range(lo, lo_s):
        s = lag_src[m]
        pre += a[m] * x[m]
        pre += c0[m] * u0[s] + c1[m] * u1[s]
    for m in range(lo_s, hi_s):
        pre += a[m] * x[m]
    for m in range(hi_s, max(hi, hi_s)):
        s = lag_src[m]
        pre += a[m] * x[m]
        pre += c0[m] * u0[s] + c1[m] * u1[s]
    return pre

@njit(cache=True, _nrt=False)
def _heater_split_table(obs_ptr, obs_end, lag_src, heater_obs, heater_src, hs_tab):
    nr = heater_obs.shape[0]
    ln = obs_end[heater_obs[0]] - obs_ptr[heater_obs[0]] if nr > 0 else 0
    for n in range(nr):
        if obs_end[heater_obs[n]] - obs_ptr[heater_obs[n]] != ln:
            ln = -1
    for j in range(max(ln, 0)):
        for n in range(nr):
            m = obs_ptr[heater_obs[n]] + j
            q = _PAIR_STRIDE * (j * nr + n)
            hs_tab[q + _PAIR_LAG] = m
            hs_tab[q + _PAIR_SRC] = -1 if lag_src[m] == heater_src[n] else lag_src[m]
    return ln

@njit(cache=True)
def _find_dead_sources(x, lag_src, lag_kind, n_src, dead):
    for s in range(n_src):
        dead[s] = False
    n_lags = np.zeros(n_src, np.int64)
    ok = np.ones(n_src, np.bool_)
    for m in range(lag_src.shape[0]):
        s = lag_src[m]
        n_lags[s] += 1
        if lag_kind[m] != LAG_EXOGENOUS or not (x[m] == 0.0 and math.copysign(1.0, x[m]) > 0.0):
            ok[s] = False
    nd = 0
    for s in range(n_src):
        if ok[s] and n_lags[s] > 0:
            dead[s] = True
            nd += 1
    return nd

@njit(cache=True, _nrt=False)
def _live_lags(dead, lag_src, obs_ptr, idx_exo, out_ms, out_obs_end):
    n = 0
    for i in range(idx_exo.shape[0]):
        m = idx_exo[i]
        if not dead[lag_src[m]]:
            out_ms[_PAIR_STRIDE * n + _PAIR_LAG] = m
            out_ms[_PAIR_STRIDE * n + _PAIR_SRC] = lag_src[m]
            n += 1
    for o in range(obs_ptr.shape[0] - 1):
        e = obs_ptr[o + 1]
        while e > obs_ptr[o] and dead[lag_src[e - 1]]:
            e -= 1
        out_obs_end[o] = e
    return n

@njit(cache=True, _nrt=False)
def _pack_lag_coefs(a, c0, c1, w, coef):
    for m in range(a.shape[0]):
        q = _COEF_STRIDE * m
        coef[q + _COEF_A] = a[m]
        coef[q + _COEF_C0] = c0[m]
        coef[q + _COEF_C1] = c1[m]
        coef[q + _COEF_W] = w[m]

@njit(cache=True, _nrt=False)
def _pack_source_inputs(u0, u1, uu):
    for s in range(u0.shape[0]):
        uu[_UU_STRIDE * s + _UU_START] = u0[s]
        uu[_UU_STRIDE * s + _UU_END] = u1[s]

@njit(cache=True, _nrt=False)
def _wake_dead_sources(dead, u0, u1):
    woke = False
    for s in range(dead.shape[0]):
        if dead[s] and (u0[s] != 0.0 or u1[s] != 0.0):
            dead[s] = False
            woke = True
    return woke

