                world_int[WI_SAT_FIRST_TICK] = k
                world_int[WI_SAT_FIRST_ELEM] = o + j
                world_int[WI_SAT_FIRST_VAL] = v
                return

@njit(cache=True, _nrt=False)
def _push_act_a(act, act_map, sat, pipe_vals, pipe_ticks, pipe_meta, world_int, k, latency):
