@njit(cache=True, _nrt=False)
def _round_robin_apply_a(act, save, act_map, active):
    for i in range(act_map.shape[0]):
        if act_map[i, AM_PER_RING] == 0:
            continue
        o = act_map[i, AM_OFFSET]
        for j in range(act_map[i, AM_SIZE]):
            if j != active:
                act[o + j] = save[o + j]

@njit(cache=True, _nrt=False)
def _advance_edge_a(world_int, phase_tick, period, jitter, key_sched):
