@njit(cache=True, _nrt=False)
def _auto_substep_a(k, k_end, n_rings, fast_on, au_max_pow, reset_protocol, ramp_ticks, oracle_on, he_ripple,
                    bi_noise_per, bi_noise, au_max_det, au_pabs_tol, world_int, world_float, ring_int, ring_int8,
                    ring_float, ring_bool, pipe_meta, pipe_ticks, he_fifo, bi_fifo, sc_sig_i, sc_sig_f, sc_def, sc_comp,
                    sc_comp_i, sc_comp_f, sc_tab, sc_keys, sc_cache, sc_vp, sc_v0, sc_v1, sc_va, rec_i, rec_idx,
                    rec_cnt, mp_i, m_ai):
    if fast_on != 0:
        return 1
    hmax = np.int64(1) << au_max_pow
    lim = k_end - k
    e = world_int[WI_EDGE_NEXT] - k
    if e > 0 and e < lim:
        lim = e
    meta = pipe_meta                       # [head, count] of the controller pipeline
    if meta[1] > 0:
        t = pipe_ticks[meta[0]] - k        # ticks until the next queued command latches
        if t <= 0:
            return 1
        if t < lim:
            lim = t
    if reset_protocol == 0 and ramp_ticks > 0 and k - world_int[WI_K_RESET] < ramp_ticks:
        return 1
    if world_int[WI_ORACLE_NEXT] - k > 0 and world_int[WI_ORACLE_NEXT] - k < lim and oracle_on != 0:
        lim = world_int[WI_ORACLE_NEXT] - k
    # allow at most twice the previous step length while the detuning rate estimate develops
    g2 = 2 * world_int[WI_LAST_H]
    if g2 < lim:
        lim = g2
    if lim < 2:
        return 1
    if not electrical.actuator_quiescent_row(ring_int[RI_HE_REG], ring_int8[R8_HE_HAS], he_fifo, ring_float[RF_HE_YS],
                                             ring_float[RF_HE_YO], ring_float[RF_HE_UT], 1e-9):
        return 1
    if not electrical.actuator_quiescent_row(ring_int[RI_BI_REG], ring_int8[R8_BI_HAS], bi_fifo, ring_float[RF_BI_YS],
                                             ring_float[RF_BI_YO], ring_float[RF_BI_VT], 1e-9):
        return 1
    for n in range(n_rings):
        if ring_int[RI_HE_ADD, n] != 0:
            return 1
        # a command latched at this tick changes the register - one tick first
        if ring_bool[RB_VAL_H, n] and ring_int[RI_HE_CMD, n] != ring_int[RI_HE_REG, n]:
            return 1
        if ring_bool[RB_VAL_B, n] and ring_int[RI_BI_CMD, n] != ring_int[RI_BI_REG, n]:
            return 1
    if he_ripple != 0:
        return 1
    # bias-DAC noise - never across a redraw when it is redrawn less often than every tick (with a per-tick redraw the draw of the first tick is held over the substep, a stated approximation)
    if bi_noise_per > 1:
        nz = bi_noise
        on = False
        for n in range(nz.shape[0]):
            if nz[n] != 0.0:
                on = True
        if on:
            nxt = (k // bi_noise_per + 1) * bi_noise_per - k
            if nxt < lim:
                lim = nxt
    # start a new scenario event at k with one tick
    hp = world_int[WI_LAST_H]
    if hp < 1:
        hp = 1
    vp = sc_vp
    v0 = sc_v0
    v1 = sc_v1
    for s in range(sc_sig_i.shape[0]):
        if sc_sig_i[s, _SI_NC] == 0:
            continue
        off = sc_sig_i[s, _SI_OFF]
        foh = s == _SIG_T_BASE or s == _SIG_XPU_RISE or s == _SIG_AGGRESSOR
        for j in range(sc_sig_i[s, generators.SI_WIDTH]):
            a = vp[off + j]
            c = v0[off + j]
            if foh:
                # a kink - the slope per tick changed by more than half (a ramp starts, ends or reverses).
                # the smooth curvature of a sine or rect_sine between its scenario breaks does not count, and changes below 1e-12 of the value per tick (0.3 mK/s at 300 K) are float noise
                s_prev = (c - a) / hp
                s_now = v1[off + j] - c
                ds = abs(s_now - s_prev)
                if ds > 0.5 * max(abs(s_now), abs(s_prev)) and ds > 1e-12 * abs(c):
                    return 1
            elif not (a == c or (a != a and c != c)):
                return 1
    # scenario - FOH signals (base temperature, XPU rise, aggressor power) must stay linear.
    # every other active signal must stay constant (held over the substep)
    for s in range(sc_sig_i.shape[0]):
        if sc_sig_i[s, _SI_NC] == 0:
            continue
        kb = generators.scen_next_break_b(s, k, sc_comp, sc_sig_i, sc_comp_i, sc_comp_f, sc_tab)
        if kb - k < lim:
            lim = kb - k
        if lim < 2:
            return 1
    # detuning-rate and P_abs criteria from the previous substep
    rate = world_float[WF_RATE]
    if rate > 0.0:
        hr = au_max_det / rate
        if hr < lim:
            lim = np.int64(hr) if hr >= 1.0 else 1
    for n in range(n_rings):
        pa = ring_float[RF_P_ABS, n]
        pp_ = ring_float[RF_PABS_PREV, n]
        sc = max(abs(pa), abs(pp_))
        if sc > 0.0 and abs(pa - pp_) > au_pabs_tol * sc:
            return 1
    # record windows (while the record still records) and BER windows - a substep never straddles one
    for r in range(rec_i.shape[0]):
        if rec_idx[r] >= rec_i[r, _REC_SAMPLES]:
            continue
        dec = rec_i[r, _REC_DECIMATION]
        left = dec - rec_cnt[r]
        if left < lim:
            lim = left
    win = mp_i[MPI_BER_WIN]
    if win > 0:
        left = win - m_ai[0, AI_WIN_TICKS]
        if left > 0 and left < lim:
            lim = left
    if lim > hmax:
        lim = hmax
    h = np.int64(1)
    while h * 2 <= lim:
        h *= 2
    if h > 1:
        # held scenario signals must not change over [k, k + h] - compare the values at k + h with those at k
        va = sc_va
        for i in range(va.shape[0]):
            va[i] = sc_v1[i]
        generators.scen_eval_b(k + h, sc_comp, sc_sig_i, sc_sig_f, sc_def, sc_comp_i, sc_comp_f, sc_tab, sc_keys,
                               sc_cache, va)
        while h > 1:
            ok = True
            for s in range(sc_sig_i.shape[0]):
                if sc_sig_i[s, _SI_NC] == 0 or s == _SIG_T_BASE or s == _SIG_XPU_RISE or s == _SIG_AGGRESSOR:
                    continue
                off = sc_sig_i[s, _SI_OFF]
                for e in range(sc_sig_i[s, generators.SI_WIDTH]):
                    a = sc_v0[off + e]
                    c = va[off + e]
                    if not (a == c or (a != a and c != c)):
                        ok = False
            if ok:
                break
            h //= 2
            generators.scen_eval_b(k + h, sc_comp, sc_sig_i, sc_sig_f, sc_def, sc_comp_i, sc_comp_f, sc_tab, sc_keys,
                                   sc_cache, va)
    return h

def _run_chunk_py(step_fn, fast_fn, P, S, k0, n_ticks, mode, resume, b0, b1, done):
    for b in range(b0, b1):
        done[b] = _world_block(step_fn, fast_fn, b, k0, n_ticks, mode, resume, P, S)

def _threads() -> int:
    from numba import config as numba_config
    return max(1, int(getattr(numba_config, "NUMBA_NUM_THREADS", 1) or 1))

def _declared(self):
    ring_to_line = np.asarray(self.P.ring_to_line)
    assignment = self.act.assign
    return np.where((assignment >= 0) & (assignment < self.L), assignment, ring_to_line[None, :])

def run(self, n_ticks: int, controller=None):
    for _ in range(int(n_ticks)):
        self.step(controller)

def file_sha256(path: str | Path) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for chunk in iter(lambda: stream.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()

def _git(args: list[str], root: Path) -> tuple[int, bytes]:
    try:
        process = subprocess.run(["git", *args], cwd=root, capture_output=True, timeout=60)
        return process.returncode, process.stdout
    except (OSError, subprocess.TimeoutExpired):
        return 1, b""

def git_state(root: str | Path | None = None) -> dict:
    root = Path(root) if root is not None else REPO_ROOT
    exit_code, out = _git(["rev-parse", "HEAD"], root)
    if exit_code != 0:
        return {"available": False, "commit": None, "dirty": None, "diff_sha256": None, "branch": None,
                "status": []}
    commit = out.decode().strip()
    _, branch = _git(["rev-parse", "--abbrev-ref", "HEAD"], root)
    _, diff = _git(["diff", "HEAD", "--binary"], root)
    _, porcelain = _git(["status", "--porcelain", "--untracked-files=all"], root)
    status = [line for line in porcelain.decode(errors="replace").splitlines() if line.strip()]
    digest = hashlib.sha256(diff)
    for line in sorted(status):
        if line.startswith("??"):
            relative_path = line[3:].strip().strip('"')
            path = root / relative_path
            digest.update(b"\0untracked\0" + relative_path.encode())
            if path.is_file():
                try:
                    digest.update(file_sha256(path).encode())
                except OSError:
                    pass
    return {"available": True, "commit": commit, "branch": branch.decode().strip() or None, "dirty": bool(status),
            "diff_sha256": digest.hexdigest(), "status": status[:200]}

def environment() -> dict:
    def ver(mod):
        try:
            return __import__(mod).__version__
        except Exception:                                   # noqa: BLE001 - a missing package is recorded as None
            return None
    return {"python": sys.version.split()[0], "implementation": platform.python_implementation(),
            "numpy": ver("numpy"), "scipy": ver("scipy"), "numba": ver("numba"), "llvmlite": ver("llvmlite"),
            "h5py": ver("h5py"), "pyyaml": ver("yaml"), "mrm": ver("mrm"),
            "platform": platform.platform(), "machine": platform.machine(), "processor": platform.processor(),
            "cpu_count": os.cpu_count(), "byteorder": sys.byteorder,
            "numba_disable_jit": os.environ.get("NUMBA_DISABLE_JIT", "0"),
            "numba_num_threads": os.environ.get("NUMBA_NUM_THREADS")}

def ver(mod):
    try:
        return __import__(mod).__version__
    except Exception:                                   # noqa: BLE001 - a missing package is recorded as None
        return None

def code_fingerprint_files() -> list[Path]:
    package_root = REPO_ROOT / "mrm"
    files = [package_root / module for module in CODE_MODULES if (package_root / module).is_file()]
    for package in CODE_PACKAGES:
        files += [p for p in (package_root / package).rglob("*.py") if "__pycache__" not in p.parts]
    files += [p for p in DATA_ROOT.rglob("*") if p.is_file() and "__pycache__" not in p.parts
              and not p.name.startswith(".")]
    return sorted(set(files))

def code_fingerprint() -> str:
    digest = hashlib.sha256()
    for path in code_fingerprint_files():
        digest.update(str(path.relative_to(REPO_ROOT)).encode() + b"\0" + file_sha256(path).encode() + b"\n")
    versions = environment()
    digest.update(json.dumps({k: versions.get(k) for k in CODE_ENVIRONMENT}, sort_keys=True, default=str).encode())
    return digest.hexdigest()

def _artefact_file(spec: str) -> str | None:
    if not isinstance(spec, str) or not spec:
        return None
    return spec.split(":", 1)[0]

def artefacts_used(cfg, pp=None, *, data_root: str | Path | None = None) -> list[dict]:
    root = Path(data_root) if data_root is not None else Path(getattr(cfg, "data_root", DATA_ROOT))
    found: dict[str, dict] = {}

    # record that config path `path` uses the file `rel` (relative to the data root).
    def add(rel: str | None, path: str, selected: bool, recorded: str | None = None):
        if not rel:
            return
        entry = found.setdefault(rel, {"file": rel, "used_by": [], "selected": False, "recorded_sha256": None})
        if path not in entry["used_by"]:
            entry["used_by"].append(path)
        entry["selected"] = entry["selected"] or selected
        if recorded and not entry["recorded_sha256"]:
            entry["recorded_sha256"] = recorded

    for p, leaf in sorted(getattr(cfg, "leaves", {}).items()):
        artefact = getattr(leaf, "artefact", None)
        if artefact:
            add(artefact.get("file"), p, True, artefact.get("sha256"))
        for alt_name, alt in sorted((getattr(leaf, "alternatives", None) or {}).items()):
            alternative_artefact = alt.get("artefact") or alt.get("_resolved_artefact")
            if alternative_artefact:
                add(alternative_artefact.get("file"), f"{p}#{alt_name}", False, alternative_artefact.get("sha256"))
            spec = alt.get("from")
            if spec is None and isinstance(alt.get("value"), dict):
                spec = alt["value"].get("from")
            add(_artefact_file(spec), f"{p}#{alt_name}", False)
    # include active ROM and junction-table files selected through settings.
    # use the same model switches as realization.
    for key, switch, value in (("ring.thermal.rom_file", "fidelity.thermal_model", "rom"),
                               ("ring.junction.lut_file", "fidelity.junction_model", "lut")):
        try:
            f, selected_model = cfg.get(key), cfg.get(switch)
        except Exception:                                   # noqa: BLE001 - a mapping config
            f, selected_model = None, None
        if f and selected_model == value:
            add(_artefact_file(str(f)), key, True)
    thermal_inputs = getattr(pp, "thermal_inputs", None) if pp is not None else None
    if thermal_inputs is not None and getattr(thermal_inputs, "rom_path", None):
        rom_path = Path(thermal_inputs.rom_path)
        try:
            rel = str(rom_path.relative_to(root))
        except ValueError:
            rel = str(rom_path)
        add(rel, "thermal_rom", True, getattr(thermal_inputs, "sha256", None))
    materials = root / "materials.json"
    if materials.exists():
        add("materials.json", "mrm.materials", True)
    out = []
    from mrm.params.config import sidecar_candidates
    for rel, e in sorted(found.items()):
        p = Path(rel) if Path(rel).is_absolute() else root / rel
        e["exists"] = p.exists()
        e["sha256"] = file_sha256(p) if p.is_file() else None
        sidecar = None
        for c in sidecar_candidates(p):
            if c.is_file() and c != p:
                sidecar = c
                break
        e["sidecar"] = sidecar.name if sidecar is not None else None
        e["sidecar_sha256"] = file_sha256(sidecar) if sidecar is not None else None
        if e["recorded_sha256"] and e["sha256"] and e["recorded_sha256"] != e["sha256"]:
            e["mismatch"] = True
        out.append(e)
    return out

def add(rel: str | None, path: str, selected: bool, recorded: str | None = None):
    if not rel:
        return
    entry = found.setdefault(rel, {"file": rel, "used_by": [], "selected": False, "recorded_sha256": None})
    if path not in entry["used_by"]:
        entry["used_by"].append(path)
    entry["selected"] = entry["selected"] or selected
    if recorded and not entry["recorded_sha256"]:
        entry["recorded_sha256"] = recorded

def runs_root(runs_dir: str | Path | None = None) -> Path:
    if runs_dir is not None:
        return Path(runs_dir)
    env = os.environ.get("MRM_RUNS_DIR")
    return Path(env) if env else Path.cwd() / "runs"

def to_jsonable(x: Any) -> Any:
    if x is None or isinstance(x, (bool, str)):
        return x
    if isinstance(x, (np.bool_,)):
        return bool(x)
    if isinstance(x, (int, np.integer)):
        return int(x)
    if isinstance(x, (float, np.floating)):
        v = float(x)
        if math.isnan(v):
            return None
        if math.isinf(v):
            return "inf" if v > 0 else "-inf"
        return v
    if isinstance(x, np.ndarray):
        if x.ndim == 0:
            return to_jsonable(x.item())
        if x.dtype.kind in "fc":
            return [to_jsonable(v) for v in x.tolist()] if x.ndim == 1 else [to_jsonable(v) for v in x]
        return [to_jsonable(v) for v in x] if x.ndim > 1 else [to_jsonable(v) for v in x.tolist()]
    if isinstance(x, Mapping):
        return {str(k): to_jsonable(v) for k, v in x.items()}
    if isinstance(x, (list, tuple, set, frozenset)):
        return [to_jsonable(v) for v in x]
    if hasattr(x, "to_dict") and callable(x.to_dict):
        return to_jsonable(x.to_dict())
    import dataclasses
    if dataclasses.is_dataclass(x) and not isinstance(x, type):
        return to_jsonable(dataclasses.asdict(x))
    if isinstance(x, Path):
        return str(x)
    return str(x)

def _h5_put(g, name: str, v: Any) -> None:
    name = str(name).replace("/", "|")
    if v is None:
        g.attrs[name] = "null"
        return
    if isinstance(v, Mapping):
        subgroup = g.require_group(name)
        for k, x in v.items():
            _h5_put(subgroup, k, x)
        return
    if isinstance(v, str):
        g.attrs[name] = v
        return
    if isinstance(v, (bool, np.bool_, int, float, np.integer, np.floating)):
        g.create_dataset(name, data=np.asarray(v))
        return
    if isinstance(v, np.ndarray):
        if v.dtype.kind in "biufc":
            g.create_dataset(name, data=v)
        else:
            g.attrs[name] = json.dumps(to_jsonable(v))
        return
    if isinstance(v, (list, tuple)):
        try:
            array = np.asarray(v)
        except (ValueError, TypeError):
            array = None
        if array is not None and array.dtype.kind in "biuf" and array.dtype != object:
            g.create_dataset(name, data=array)
        else:
            g.attrs[name] = json.dumps(to_jsonable(v))
        return
    g.attrs[name] = json.dumps(to_jsonable(v))

def write_trace_h5(path: str | Path, groups: Mapping[str, Any], *, attrs: Mapping[str, Any] | None = None) -> None:
    import h5py
    with h5py.File(path, "w") as file:
        file.attrs["schema"] = TRACE_SCHEMA
        for k, v in (attrs or {}).items():
            file.attrs[str(k)] = v if isinstance(v, (str, int, float)) else json.dumps(to_jsonable(v))
        for name, tree in groups.items():
            if tree is None:
                continue
            _h5_put(file, name, tree)

def _h5_get(g) -> dict:
    import h5py
    out: dict = {}
    for k, v in g.items():
        out[k] = _h5_get(v) if isinstance(v, h5py.Group) else v[()]
    for k, v in g.attrs.items():
        out.setdefault(f"@{k}", v)
    return out

def read_trace_h5(path: str | Path) -> dict:
    import h5py
    with h5py.File(path, "r") as file:
        return _h5_get(file)

def read_run(run_dir: str | Path) -> dict:
    directory = Path(run_dir)
    if not (directory / "manifest.json").exists():
        raise FileNotFoundError(f"{directory}: not a run directory (no manifest.json)")
    with open(directory / "manifest.json") as stream:
        manifest = json.load(stream)
    metrics = None
    if (directory / "metrics.json").exists():
        with open(directory / "metrics.json") as stream:
            metrics = json.load(stream)
    trace = read_trace_h5(directory / "trace.h5") if (directory / "trace.h5").exists() else {}
    resolved_yaml = (directory / "experiment.resolved.yaml").read_text() if (directory / "experiment.resolved.yaml").exists() else None
    return {"dir": directory, "manifest": manifest, "metrics": metrics, "trace": trace, "resolved_yaml": resolved_yaml}

def _flat_arrays(tree: Mapping, prefix: str = "") -> dict[str, Any]:
    out = {}
    for k, v in tree.items():
        path = f"{prefix}/{k}" if prefix else str(k)
        if isinstance(v, Mapping):
            out.update(_flat_arrays(v, path))
        else:
            out[path] = v
    return out

def _bit_equal(a, b) -> bool:
    if isinstance(a, np.ndarray) or isinstance(b, np.ndarray):
        a, b = np.asarray(a), np.asarray(b)
        if a.shape != b.shape or a.dtype != b.dtype:
            return False
        if a.dtype.kind in "fc":
            return a.tobytes() == b.tobytes()
        if a.dtype == object:
            return a.tolist() == b.tolist()
        return np.array_equal(a, b)
    if isinstance(a, float) and isinstance(b, float):
        return np.asarray(a).tobytes() == np.asarray(b).tobytes()
    return a == b

def _canonical_names(flat: Mapping[str, Any]) -> dict[str, Any]:
    from mrm.params.schema import ENUM_ALIASES
    aliases = ENUM_ALIASES["experiment.kind"]

    def segment(p: str) -> str:
        head, sep, rest = p.partition("|")
        return aliases[head] + sep + rest if head in aliases else p
    out = {}
    for k, v in flat.items():
        if k.rsplit("/", 1)[-1] == "@kind" and isinstance(v, str):
            v = aliases.get(v, v)
        out["/".join(segment(p) for p in k.split("/"))] = v
    return out

def segment(p: str) -> str:
    head, sep, rest = p.partition("|")
    return aliases[head] + sep + rest if head in aliases else p

def compare_runs(a: str | Path | Mapping, b: str | Path | Mapping, *, ignore: Iterable[str] = ()) -> dict:
    run_a = read_run(a) if not isinstance(a, Mapping) else a
    run_b = read_run(b) if not isinstance(b, Mapping) else b
    flat_a = {k: v for k, v in _canonical_names(_flat_arrays(run_a["trace"])).items()
              if k.rsplit("/", 1)[-1] not in _VOLATILE_ATTRS}
    flat_b = {k: v for k, v in _canonical_names(_flat_arrays(run_b["trace"])).items()
              if k.rsplit("/", 1)[-1] not in _VOLATILE_ATTRS}
    ignored = tuple(ignore)
    keys_a = {k for k in flat_a if not any(k.startswith(i) for i in ignored)}
    keys_b = {k for k in flat_b if not any(k.startswith(i) for i in ignored)}
    differences, max_differences = [], {}
    for k in sorted(keys_a & keys_b):
        if not _bit_equal(flat_a[k], flat_b[k]):
            differences.append(k)
            try:
                x, y = np.asarray(flat_a[k], float), np.asarray(flat_b[k], float)
                if x.shape == y.shape:
                    with np.errstate(invalid="ignore"):
                        max_differences[k] = float(np.nanmax(np.abs(x - y))) if x.size else 0.0
            except (TypeError, ValueError):
                pass
    return {"identical": not differences and keys_a == keys_b, "n_compared": len(keys_a & keys_b),
        "differing": differences,
            "only_in_a": sorted(keys_a - keys_b), "only_in_b": sorted(keys_b - keys_a), "max_abs_diff": max_differences}

@njit(cache=True)
def metrics_reset_row(k0, reg, af, ai, hist, runhist):
    for n in range(af.shape[0]):
        for j in range(af.shape[1]):
            af[n, j] = 0.0
        for j in range(ai.shape[1]):
            ai[n, j] = 0
        ai[n, AI_FIRST_LOCK] = -1
        ai[n, AI_LAST_LOCK] = -1
        ai[n, AI_ORDER_LOCK] = _INT_MIN
        ai[n, AI_ORDER_PREV] = _INT_MIN
        ai[n, AI_CODE_MIN] = reg[n]
        ai[n, AI_CODE_MAX] = reg[n]
        ai[n, AI_PREV_POP_REG] = reg[n]
        ai[n, AI_PREV_POP_TICK] = k0
        ai[n, AI_T0] = k0
        for j in range(hist.shape[1]):
            hist[n, j] = 0
        for j in range(runhist.shape[1]):
            runhist[n, j] = 0

@njit(cache=True)
def _hist_bin(d, mpf, mpi):
    fine_bins = mpi[MPI_NFINE]
    coarse_bins = mpi[MPI_NCOARSE]
    fine_half_width = mpf[MP_FINE_W]
    if d >= -fine_half_width and d < fine_half_width:
        j = int(math.floor((d + fine_half_width) / mpf[MP_FINE_BIN]))
        if j >= fine_bins:
            j = fine_bins - 1
        return 1 + coarse_bins + j
    if d < -fine_half_width:
        j = int(math.floor((-fine_half_width - d) / mpf[MP_COARSE_BIN]))      # 0 next to the fine region
        if j >= coarse_bins:
            return 0                                            # underflow
        return coarse_bins - j
    j = int(math.floor((d - fine_half_width) / mpf[MP_COARSE_BIN]))
    if j >= coarse_bins:
        return 1 + coarse_bins + fine_bins + coarse_bins                                 # overflow
    return 1 + coarse_bins + fine_bins + j

@njit(cache=True)
def _log2_bin(n):
    j = 0
    while n > 1 and j < N_RUNHIST - 1:
        n >>= 1
        j += 1
    return j

def __post_init__(self):
    if self.channel not in TR:
        raise ValueError(f"record channel {self.channel!r} is not a Truth field; known: {TRUTH_FIELDS}")
    if int(self.decimation) < 1:
        raise ValueError("record decimation must be >= 1 tick")
    if self.reducer not in REDUCERS:
        raise ValueError(f"record reducer {self.reducer!r} not in {REDUCERS}")

@property
def key(self) -> str:
    return f"{self.channel}@{int(self.decimation)}:{self.reducer}"

def _as_record_specs(record) -> list[RecordSpec]:
    if record is None:
        return []
    out = []
    for r in record:
        if isinstance(r, RecordSpec):
            out.append(r)
        elif isinstance(r, str):
            out.append(RecordSpec(r))
        elif isinstance(r, Mapping):
            out.append(RecordSpec(r["channel"], int(r.get("decimation", 1)), r.get("reducer", "mean")))
        else:
            channel, decimation, *reducer = r
            out.append(RecordSpec(channel, int(decimation), reducer[0] if reducer else "mean"))
    keys = [r.key for r in out]
    if len(set(keys)) != len(keys):
        raise ValueError(f"duplicate record specs: {keys}")
    return out

def traces(self, dt_s: float, t0_tick: int = 0) -> dict[str, dict[str, np.ndarray]]:
    out = {}
    for r, spec in enumerate(self.specs):
        _, window_ticks, _, first_slot, allocated_slots = (int(x) for x in self.rec_i[r])
        done = int(self.idx[:, r].min()) if self.idx.shape[0] else 0
        done = min(done, allocated_slots)
        end_times_s = (t0_tick + window_ticks * (np.arange(done) + 1)) * float(dt_s)
        out[spec.key] = {"t_s": end_times_s, "value": np.moveaxis(self.trace[:, first_slot:first_slot + done,
            :], 1, 0).copy()}
    return out

@njit(cache=True, _nrt=False)
def record_tick_row(h, tv, rec_i, acc, cnt, idx, trace):
    for r in range(rec_i.shape[0]):
        truth_field = rec_i[r, _REC_FIELD]
        window_ticks = rec_i[r, _REC_DECIMATION]
        reducer = rec_i[r, _REC_REDUCER]
        if idx[r] >= rec_i[r, _REC_SAMPLES]:
            continue
        window_count = cnt[r]                       # ticks already in the current window
        for n in range(tv.shape[1]):
            value = tv[truth_field, n]
            if reducer == _RED_MEAN:
                if window_count == 0:
                    acc[r, n] = value * h
                else:
                    acc[r, n] += value * h
            elif reducer == _RED_MIN:
                if window_count == 0 or value < acc[r, n]:
                    acc[r, n] = value
            elif reducer == _RED_MAX:
                if window_count == 0 or value > acc[r, n]:
                    acc[r, n] = value
            else:                        # last
                acc[r, n] = value
        window_count += h
        if window_count >= window_ticks:
            slot = rec_i[r, _REC_FIRST_SLOT] + idx[r]
            for n in range(tv.shape[1]):
                trace[slot, n] = acc[r, n] / window_count if reducer == _RED_MEAN else acc[r, n]
            idx[r] += 1
            window_count = 0
        cnt[r] = window_count

def __post_init__(self):
    if self.reloma_definition != "oma_over_pin":
        raise ValueError("metrics.reloma_definition: only oma_over_pin (relOMA = OMA / P_in) is defined")
    if self.allowed_assignments not in ("fixed", "cyclic", "any"):
        raise ValueError("metrics.allowed_assignments must be fixed, cyclic or any")
    if not (self.lock_threshold_pm > 0 and 0 <= self.hysteresis_pm < self.lock_threshold_pm):
        raise ValueError("need lock_threshold_pm > 0 and 0 <= hysteresis_pm < lock_threshold_pm")
    if self.lock_reference not in LOCK_REFERENCES:
        raise ValueError(f"metrics.lock_reference must be one of {LOCK_REFERENCES}")
    if self.lock_reference == "oracle" and not self.oracle:
        raise ValueError("lock_reference='oracle' needs the oracle (oracle=True)")
    if self.lock_reference == "target" and self.lock_target_pm is None:
        raise ValueError("lock_reference='target' needs lock_target_pm (pm, scalar or (B, N))")
    thresholds = tuple(float(x) for x in (self.time_above_pm or (self.lock_threshold_pm,)))
    if len(thresholds) > N_ABOVE_MAX:
        raise ValueError(f"at most {N_ABOVE_MAX} time_above thresholds")
    object.__setattr__(self, "time_above_pm", thresholds)

@property
def lock_reference_mode(self) -> int:
    return 1 if self.lock_reference == "oracle" else 0

def reference_m(self, batch: int, n_rings: int) -> np.ndarray:
    if self.lock_reference != "target":
        return np.zeros((batch, n_rings))
    return np.ascontiguousarray(np.broadcast_to(np.asarray(self.lock_target_pm, float) * 1e-12,
                                                (batch, n_rings)), dtype=np.float64).copy()

@classmethod
def from_config(cls, cfg, **overrides) -> "MetricsSpec":
    def val(key, default):
        try:
            v = cfg.get(key, None) if hasattr(cfg, "get") else None
        except Exception:              # noqa: BLE001 - a Config raises for unknown keys in some modes
            v = None
        if isinstance(v, Mapping) and "value" in v:
            v = v["value"]
        return default if v is None else v
    settings = dict(lock_threshold_pm=float(val("metrics.lock_threshold_pm", 5.0)),
              hysteresis_pm=float(val("metrics.hysteresis_pm", 1.0)),
              ber_sample_period_s=float(val("metrics.ber_sample_period_s", 2.0)),
              reloma_definition=str(val("metrics.reloma_definition", "oma_over_pin")),
              allowed_assignments=str(val("metrics.allowed_assignments", "fixed")),
              lock_reference=str(val("metrics.lock_reference", "line")),
              lock_target_pm=val("metrics.lock_target_pm", None))
    settings.update(overrides)
    return cls(**settings)

