def _block_end(plant: Plant, k_end: int, chunk: int) -> int:
    end = plant.tick + chunk
    if end >= k_end:
        return k_end
    kernel_params = plant.P
    period, phase0 = int(kernel_params.period), int(kernel_params.phase)
    if int(kernel_params.jitter) == 0 and period > 0:
        end = phase0 if end <= phase0 else phase0 + -(-(end - phase0) // period) * period
    return min(end, k_end)

def _run_open(plant: Plant, n_ticks: int, n_threads=None, chunk: int = DEFAULT_CHUNK_TICKS) -> None:
    end_tick = plant.tick + n_ticks
    while plant.tick < end_tick:
        plant.run(_block_end(plant, end_tick, chunk) - plant.tick, mode=kernel.MODE_OPEN)

def rb_of(b, n):
