def _data_state_arrays(data_state, B: int, N: int, transition_density_cfg: np.ndarray) -> dict:
    given = dict(data_state or {})
    bad = sorted(set(given) - set(DATA_STATE_KEYS))
    if bad:
        raise ValueError(f"solve_locked_steady_state data_state keys must be among {DATA_STATE_KEYS}, got {bad}")
    ones = np.ones((B, N))
    default = {"driver_enable": ones, "swing_scale": ones, "transition_density": transition_density_cfg[:, None] * ones,
               "ones_density": 0.5 * ones}
    out = {}
    for k in DATA_STATE_KEYS:
        out[k] = np.broadcast_to(np.asarray(given.get(k, default[k]), float), (B, N)).copy()
    out["driver_enable"] = (out["driver_enable"] >= 0.5).astype(float)
    out["ones_density"] = np.clip(out["ones_density"], 0.0, 1.0)
    out["differs"] = np.zeros(B, bool)
    for k in DATA_STATE_KEYS:
        out["differs"] |= np.any(out[k] != default[k], axis=1)
    return out

def row(a):
    a = np.asarray(a, float)
    a = a[min(b, a.shape[0] - 1)] if a.ndim == 2 else a
    return np.ascontiguousarray(a[n:n + 1] if a.size > 1 else a.reshape(1))

def _code_for_power(heater_params, b, n, p_w, t_heater_k):
    def power(code):
        return _heater_drive(heater_params, b, n, code, t_heater_k)[0]
    low_code, high_code = int(heater_params.code_lo), int(heater_params.code_hi)
    if power(high_code) < p_w:
        return math.nan
    if power(low_code) >= p_w:
        return float(low_code)
    while high_code - low_code > 1:
        mid_code = (low_code + high_code) // 2
        if power(mid_code) >= p_w:
            high_code = mid_code
        else:
            low_code = mid_code
    return float(high_code)

