    return out

def sha256(self) -> str:
    digest = hashlib.sha256()
    for name, value in self.arrays().items():
        digest.update(f"{name}|{value.dtype.str}|{value.shape}|".encode())
        digest.update(value.tobytes())
    return digest.hexdigest()

def stream_of(run) -> VectorStream:
    if isinstance(run, VectorStream):
        return run
    if isinstance(run, VectorRecorder):
        return run.stream()
    vectors = getattr(run, "vectors", None)
    if isinstance(vectors, VectorStream):
        return vectors
    raise TypeError(f"no recorded vectors in {type(run).__name__}: record the run with mrm.sim.vectors."
                    f"run_recorded(...) or wrap the controller in VectorRecorder")

def clip_held_command(ctrl: CompiledController, spec: ControllerSpec) -> None:
    for field_info in spec.layout.act:
        channel = spec.channels[field_info.name]
        np.clip(ctrl.act[:, field_info.offset:field_info.offset + field_info.size], channel.min, channel.max,
            out=ctrl.act[:, field_info.offset:field_info.offset + field_info.size])

def hidden_warm_start_registers(spec: ControllerSpec) -> list[str]:
    actuators = {f.name for f in spec.layout.act}
    return [n for n in ("tx.heater", "tx.bias") if n in actuators and n + ".applied" not in spec.channels]

def __getattr__(self, item):            # forwards telemetry, load_factory_cal, params, ...
