def run_recorded(cfg_or_params, controller, scenario=None, duration_s: float = 1e-3, *,
                 max_steps: int | None = None, **run_kwargs) -> RecordedRun:
    from mrm.sim import runner
    if isinstance(controller, str):
        from mrm.control import registry
        controller = registry.create(controller, dict(run_kwargs.pop("controller_params", None) or {}))
    recorder = VectorRecorder(controller, max_steps=max_steps)
    if run_kwargs.get("path", "auto") == "compiled":
        raise ValueError("vectors are recorded on the Python path (path='python' or 'auto')")
    result = runner.run(cfg_or_params, recorder, scenario, duration_s, **run_kwargs)
    manifest_inputs = result.manifest_inputs
    meta = {k: manifest_inputs.get(k) for k in ("config_fingerprint", "config_hash", "seeds", "scenario",
        "scenario_fingerprint",
                                   "duration_s", "n_ticks", "dt_s", "spec_fingerprint")}
    meta["warm_start"] = {k: manifest_inputs.get("warm_start", {}).get(k) for k in ("reset_protocol", "factory_table")}
    return RecordedRun(result=result, vectors=recorder.stream(meta=_jsonable(meta)))

def _json_default(o):
    if isinstance(o, np.integer):
        return int(o)
    if isinstance(o, np.floating):
        return float(o)
    if isinstance(o, np.ndarray):
        return o.tolist()
    if isinstance(o, (set, frozenset, tuple)):
        return list(o)
    return repr(o)

def _stem(path) -> Path:
    path_obj = Path(path)
    return path_obj.with_suffix("") if path_obj.suffix == ".npz" else path_obj

def load_vectors(path) -> VectorStream:
    vector_path = Path(path)
    if vector_path.suffix != ".npz":
        vector_path = vector_path.with_name(vector_path.name + ".npz")
    with np.load(vector_path, allow_pickle=False) as archive:
        if "meta_json" not in archive.files:
            raise VectorError(f"{vector_path}: not a {FORMAT} file (no meta_json)")
        header = json.loads(str(archive["meta_json"]))
        arrays = {k: np.array(archive[k]) for k in archive.files if k != "meta_json"}
    if header.get("format") != FORMAT:
        raise VectorError(f"{vector_path}: format {header.get('format')!r}, this reader understands {FORMAT!r}")
    if int(header.get("abi_version", -1)) != ABI_VERSION:
        raise VectorError(f"{vector_path}: ABI version {header.get('abi_version')} != {ABI_VERSION}")
    vec = VectorStream(ticks=arrays["ticks"], obs=arrays["obs"], act=arrays["act"], written=arrays["written"],
                       reset_before=arrays["reset_before"], layout_rows=header["layout"],
                       layout_fingerprint=header["layout_fingerprint"], spec_fingerprint=header["spec_fingerprint"],
                       act_in=arrays.get("act_in"), spec_i64=arrays.get("spec_i64"), spec_f64=arrays.get("spec_f64"),
                       meta=header.get("meta", {}))
    if vec.sha256() != header.get("sha256"):
        raise VectorError(f"{vector_path}: sha256 of the arrays does not match the recorded one (file corrupted or edited)")
    return vec

def read_hex(path) -> np.ndarray:
    values = []
    for line in Path(path).read_text().splitlines():
        line = line.split("//", 1)[0].strip()
        if not line:
            continue
        for token in line.split():
            if token.startswith("@"):
                raise VectorError(f"{path}: @address records are not supported")
            values.append(int(token.replace("_", ""), 16))
    unsigned_words = np.array(values, dtype=np.uint64)
    return unsigned_words.view(np.int64).copy()

def observation_from_flat(spec: ControllerSpec, obs_i64: np.ndarray, tick: int | None = None) -> Observation:
    observation_vector = np.asarray(obs_i64, dtype=np.int64)
    if observation_vector.ndim == 1:
        observation_vector = observation_vector[None, :]
    recorded_tick, active_ring, sensors, new = spec.layout.unpack_obs(observation_vector)
    active = None
    if active_ring >= 0:
        active = np.zeros(spec.n_rings, dtype=bool)
        active[active_ring] = True
    return Observation(int(recorded_tick if tick is None else tick), spec.tick_s, sensors, new, active)

@property
def ok(self) -> bool:
    return self.mismatches == 0

def _check_layout(spec: ControllerSpec, vec: VectorStream, check_spec: bool) -> None:
    if spec.layout.fingerprint() != vec.layout_fingerprint:
        raise VectorError(f"layout {spec.layout.fingerprint()} of this spec != {vec.layout_fingerprint} of the "
                          f"vectors")
    if check_spec and spec.fingerprint() != vec.spec_fingerprint:
        raise VectorError(f"ControllerSpec {spec.fingerprint()} != {vec.spec_fingerprint} of the vectors (pass "
                          f"check_spec=False to replay against another spec with the same layout)")
    if spec.n_batch != vec.n_batch:
        raise VectorError(f"spec B = {spec.n_batch}, vectors B = {vec.n_batch}")

def compare_actions(vec: VectorStream, act: np.ndarray, written: np.ndarray | None = None) -> tuple[int, dict | None]:
    act = np.asarray(act, dtype=np.int64)
    if act.shape != vec.act.shape:
        raise VectorError(f"action shape {act.shape} != recorded {vec.act.shape}")
    written_flags = vec.written if written is None else np.asarray(written, bool)
    mask = np.zeros(vec.act.shape, dtype=bool)
    for j, r in enumerate(vec.act_fields):
        mask[:, :, r["offset"]:r["offset"] + r["size"]] = written_flags[:, j][:, None, None]
    differences = (act != vec.act) & mask
    mismatch_count = int(differences.sum())
    if not mismatch_count:
        return 0, None
    k, b, i = (int(x) for x in np.argwhere(differences)[0])
    channel = next(r for r in vec.act_fields if r["offset"] <= i < r["offset"] + r["size"])
    return mismatch_count, {"k": k, "tick": int(vec.ticks[k]), "b": b, "channel": channel["name"],
        "index": i - channel["offset"],
               "recorded": int(vec.act[k, b, i]), "replayed": int(act[k, b, i])}

def _replay_result(vec: VectorStream, out: np.ndarray, wr: np.ndarray) -> ReplayResult:
    if not np.array_equal(wr, vec.written):
        warnings.warn("the replayed controller returned other channels than the recorded one; only channels "
                      "written in the recording are compared", stacklevel=3)
    n, first = compare_actions(vec, out)
    return ReplayResult(act=out, written=wr, mismatches=n, first=first)

