    else:
        _, pp = resolve_plant(cfg0, batch=n_dies if variation == "sample" else 1, uncertainty="nominal",
                              variation=variation, seeds={"device": int(a.get("seed", 0)), "uncertainty": 0},
                              alts=alts, overrides=ov)
    stats, info = [], {}
    if ambient:
