def __getattr__(name):
    # the LUT names are imported on first use (PEP 562), so `python -m mrm.waveform.lut` does not import lut.py twice (once as a package member, once as __main__)
    if name in _LUT_NAMES:
        from mrm.waveform import lut
        return getattr(lut, name)
    raise AttributeError(f"module 'mrm.waveform' has no attribute {name!r}")

def prbs(order: int, n_bits: int | None = None) -> np.ndarray:
    if order not in PRBS_TAPS:
        raise ValueError(f"unknown PRBS order {order}; known {sorted(PRBS_TAPS)}")
    period = (1 << order) - 1
    if n_bits is None:
        if order > 23:
            raise ValueError("give n_bits for PRBS31 (period 2^31 - 1 bits)")
        n_bits = period
    if n_bits < 1:
        raise ValueError("n_bits must be >= 1")
    return _prbs_nb(order, PRBS_TAPS[order], int(n_bits))

def pattern_stats(bits) -> tuple[float, float]:
    pattern = np.asarray(bits, dtype=np.int64)
    if pattern.size == 0:
        raise ValueError("empty pattern")
    return float(pattern.mean()), float(np.mean(pattern != np.roll(pattern, 1)))

@njit(cache=True)
def _prbs_nb(k, t, n):
    a = np.empty(n + k, np.uint8)
    for i in range(k):
        a[i] = 1
    for m in range(k, n + k):
        a[m] = a[m - t] ^ a[m - k]
    return a[:n].copy()

@njit(cache=True)
def _markov_chain_nb(u, p1, p10, p01):
    n = u.shape[0]
    b = np.empty(n, np.uint8)
    b[0] = 1 if u[0] < p1 else 0
    for i in range(1, n):
        if b[i - 1]:
            b[i] = 0 if u[i] < p10 else 1
        else:
            b[i] = 1 if u[i] < p01 else 0
    return b

@njit(cache=True)
def _std_normal_cdf(z):
    return 0.5 * math.erfc(-z / math.sqrt(2.0))

@njit(cache=True)
def _network_rhs(v_src, v_pad, v_j, r_drv, c_pad, grid, c_tab, rs_tab, two_node):
    junction_capacitance_f, series_resistance_ohm = _interp_held_pair(v_j, grid, c_tab, rs_tab)
    if two_node:
        d_pad_voltage_dt_v_per_s = ((v_src - v_pad) / r_drv - (v_pad - v_j) / series_resistance_ohm) / c_pad
        d_junction_voltage_dt_v_per_s = (v_pad - v_j) / (series_resistance_ohm * junction_capacitance_f)
        return d_pad_voltage_dt_v_per_s, d_junction_voltage_dt_v_per_s
    d_junction_voltage_dt_v_per_s = (v_src - v_j) / ((r_drv + series_resistance_ohm) * junction_capacitance_f)
    return 0.0, d_junction_voltage_dt_v_per_s

@njit(cache=True)
def _interp_held(x, grid, col):
    g = grid.shape[0]
    if x <= grid[0]:
        return col[0]
    if x >= grid[g - 1]:
        return col[g - 1]
    lo = 0
    hi = g - 1
    while hi - lo > 1:
        mid = (lo + hi) >> 1
        if grid[mid] <= x:
            lo = mid
        else:
            hi = mid
    w = (x - grid[lo]) / (grid[hi] - grid[lo])
    return col[lo] + w * (col[hi] - col[lo])

@njit(cache=True)
def _interp_held_pair(x, grid, col_a, col_b):
    g = grid.shape[0]
    if x <= grid[0]:
        return col_a[0], col_b[0]
    if x >= grid[g - 1]:
        return col_a[g - 1], col_b[g - 1]
    lo = 0
    hi = g - 1
    while hi - lo > 1:
        mid = (lo + hi) >> 1
        if grid[mid] <= x:
            lo = mid
        else:
            hi = mid
    w = (x - grid[lo]) / (grid[hi] - grid[lo])
    return col_a[lo] + w * (col_a[hi] - col_a[lo]), col_b[lo] + w * (col_b[hi] - col_b[lo])

def __post_init__(self):
    self.v_grid = np.ascontiguousarray(np.asarray(self.v_grid, dtype=float))
    if self.v_grid.ndim != 1 or self.v_grid.size < 2 or np.any(np.diff(self.v_grid) <= 0):
        raise ValueError("v_grid must be strictly increasing")
    for name in ("c_j_tab", "r_s_tab"):
        table = np.asarray(getattr(self, name), dtype=float)
        if table.ndim == 0:
            table = np.full(self.v_grid.shape, float(table))
        if table.shape != self.v_grid.shape or not np.all(np.isfinite(table)):
            raise ValueError(f"{name} must be finite with the shape of v_grid")
        setattr(self, name, np.ascontiguousarray(table))
    if np.any(self.c_j_tab <= 0) or np.any(self.r_s_tab < 0):
        raise ValueError("need C_j > 0 and R_s >= 0")
    if not (np.isfinite(self.r_drv_ohm) and self.r_drv_ohm >= 0) or self.c_pad_f < 0 or self.rise_time_s < 0:
        raise ValueError("need finite r_drv_ohm >= 0, c_pad_f >= 0, rise_time_s >= 0")
    if self.r_drv_ohm == 0 and np.any(self.r_s_tab == 0):
        raise ValueError("R_drv + R_s must be > 0")
    self.r_drv_ohm = float(self.r_drv_ohm)
    self.c_pad_f = float(self.c_pad_f)
    self.rise_time_s = float(self.rise_time_s)

@property
def sigma_s(self) -> float:
    return rise_to_sigma(self.rise_time_s)

def h_electrical(self, v_bias, f_hz, include_driver: bool = True):
    s = 2j * math.pi * np.atleast_1d(np.asarray(f_hz, dtype=float))
    c_j = float(self.c_j(v_bias))
    r_s = float(self.r_s(v_bias))
    r_drv = self.r_drv_ohm
    c_pad = self.c_pad_f
    if c_pad > 0 and r_drv > 0:
        response = 1.0 / (1.0 + s * (r_drv * c_pad + (r_drv + r_s) * c_j) + s * s * r_drv * r_s * c_pad * c_j)
    else:
        response = 1.0 / (1.0 + s * (r_drv + r_s) * c_j)
    if include_driver and self.rise_time_s > 0:
        response = response * np.exp(-0.5 * (np.abs(s) * self.sigma_s) ** 2)
    return response

def rc_pole_hz(self, v_bias) -> float:
    from scipy.optimize import brentq
    half_power_gap = lambda x: abs(self.h_electrical(v_bias, x, include_driver=False)[0]) ** 2 - 0.5  # noqa: E731
    hi = 1e9
    while half_power_gap(hi) > 0:
        hi *= 2.0
    return float(brentq(half_power_gap, 1e6, hi, xtol=1e3))

def tau_min_s(self) -> float:
    rs_min = max(float(np.min(self.r_s_tab)), 1e-3)
    cj_min = float(np.min(self.c_j_tab))
    if self.c_pad_f > 0 and self.r_drv_ohm > 0:
        r_parallel = self.r_drv_ohm * rs_min / (self.r_drv_ohm + rs_min)
        return min(rs_min * cj_min, r_parallel * self.c_pad_f)
    return (self.r_drv_ohm + rs_min) * cj_min

def crossing(seg_t, seg_e, level, rising):
    idx = np.nonzero(seg_e >= level)[0] if rising else np.nonzero(seg_e <= level)[0]
    i = int(idx[0])
    return np.interp(level, [seg_e[i - 1], seg_e[i]] if rising else [seg_e[i], seg_e[i - 1]],
                     [seg_t[i - 1], seg_t[i]] if rising else [seg_t[i], seg_t[i - 1]])

@njit(cache=True)
def _best_phase(values):
    n_phase = values.shape[0]
    j_best = 0
    for j in range(1, n_phase):
        if values[j] > values[j_best]:
            j_best = j
    v0 = values[j_best]
    d = 0.0
    peak = v0
    if 0 < j_best < n_phase - 1:
        v_minus = values[j_best - 1]
        v_plus = values[j_best + 1]
        curvature = v_minus - 2.0 * v0 + v_plus              # second difference - < 0 when the parabola opens downward
        if curvature < 0.0:
            vertex_offset = 0.5 * (v_minus - v_plus) / curvature
            if -0.5 < vertex_offset < 0.5:
                d = vertex_offset
                peak = v0 - 0.125 * (v_minus - v_plus) * (v_minus - v_plus) / curvature
    return j_best, d, peak

@njit(cache=True)
def _at_phase(y, j_best, d):
    if d == 0.0:
        return y[j_best]
    y_minus = y[j_best - 1]
    y0 = y[j_best]
    y_plus = y[j_best + 1]
    return y0 + 0.5 * d * (y_plus - y_minus) + 0.5 * d * d * (y_plus - 2.0 * y0 + y_minus)

def eo_response(ring: RingTCMT, drv: DriverJunction | None, v_bias: float, f_hz, *, port: str = "through",
                p_in_w: float = 1e-3, include_driver: bool = False, loss_modulation: bool = True):
    response = ring.optical_response(v_bias, f_hz, port=port, p_in_w=p_in_w, loss_modulation=loss_modulation)
    if drv is not None:
        response = response * drv.h_electrical(v_bias, f_hz, include_driver=include_driver)
    return response

def bandwidth_3db(f_hz, h) -> tuple[float, float]:
    frequencies = np.asarray(f_hz, dtype=float)
    power = np.abs(np.asarray(h)) ** 2
    if power[0] == 0:
        return float("nan"), float("nan")
    relative_power = power / power[0]
    below = np.nonzero(relative_power < 0.5)[0]
    if below.size == 0:
        return float("inf"), float(10 * np.log10(relative_power.max()))
    i = int(below[0])
    crossing_hz = frequencies[i - 1] + (0.5 - relative_power[i - 1]) * (frequencies[i] - frequencies[i - 1]) / (relative_power[i] - relative_power[i - 1])
    return float(crossing_hz), float(10 * np.log10(max(relative_power[:i].max(), 1.0)))

def eo_bandwidth(ring: RingTCMT, drv: DriverJunction | None, v_bias: float, *, port: str = "through",
                 include_driver: bool = False, loss_modulation: bool = True, f_max_hz: float | None = None,
                 n: int = 4001) -> dict:
    from scipy.optimize import brentq

    linewidth_hz = float(ring.fwhm_hz(v_bias))
    if f_max_hz is None:
        f_max_hz = 8.0 * linewidth_hz
    frequencies = np.linspace(f_max_hz / n * 1e-3, f_max_hz, n)

    def resp(ff):
        return eo_response(ring, drv, v_bias, ff, port=port, include_driver=include_driver,
                           loss_modulation=loss_modulation)

    h0 = resp(np.array([1e3]))[0]
    # Natural scale of the response (W/V at the 1 mW of eo_response) - P_in |dDelta/dV, dkappa_i/dV| / kappa.
    # a DC gain below 1e-9 of it leaves no 3 dB point to define.
    # That happens with the laser on resonance and no loss modulation - pure index modulation then gives no first-order intensity modulation (section 5.6).
    scale = 1e-3 * (abs(ring.ddelta_dv(v_bias)) + (abs(ring.dkappa_i_dv(v_bias)) if loss_modulation else 0.0)) \
        / float(ring.kappa(v_bias))
    if not abs(h0) > 1e-9 * scale:
        nan = float("nan")
        return {"f3db_hz": nan, "peaking_db": nan, "f_hz": frequencies, "h_rel": np.full(frequencies.shape,
            complex(nan, nan)),
                "x_bias": float(ring.x(v_bias)), "fwhm_hz": linewidth_hz,
                "rc_pole_hz": drv.rc_pole_hz(v_bias) if drv is not None else float("inf")}
    h_rel = resp(frequencies) / h0
    bandwidth_hz, peak_db = bandwidth_3db(np.concatenate([[1e3], frequencies]), np.concatenate([[1.0 + 0j], h_rel]))
    if np.isfinite(bandwidth_hz):
        half_power_gap = lambda x: abs(resp(np.array([x]))[0] / h0) ** 2 - 0.5  # noqa: E731
        i = int(np.searchsorted(frequencies, bandwidth_hz))
        lo = frequencies[max(i - 1, 0)] if i > 0 else 1e3
        hi = frequencies[min(i, n - 1)]
        if half_power_gap(lo) > 0 > half_power_gap(hi):
            bandwidth_hz = float(brentq(half_power_gap, lo, hi, xtol=1e-3 * linewidth_hz * 1e-6, rtol=1e-12))
    return {"f3db_hz": bandwidth_hz, "peaking_db": peak_db, "f_hz": frequencies, "h_rel": h_rel,
        "x_bias": float(ring.x(v_bias)),
            "fwhm_hz": linewidth_hz, "rc_pole_hz": drv.rc_pole_hz(v_bias) if drv is not None else float("inf")}

def resp(ff):
    return eo_response(ring, drv, v_bias, ff, port=port, include_driver=include_driver,
                       loss_modulation=loss_modulation)

@njit(cache=True)
def _lorentzian(x):
    return 1.0 / (1.0 + x * x)

@njit(cache=True)
def _oma_max(level_diff):
    n_phase = level_diff.shape[0]
    abs_diff = np.empty(n_phase)
    for j in range(n_phase):
        abs_diff[j] = abs(level_diff[j])
    _j_best, _d, peak = _best_phase(abs_diff)
    return peak

@njit(cache=True)
def lut_eval_strict_nb(ax_xc, ax_w, ax_p1, ax_td, ax_tr, ax_tau, ax_re, tab6, tab7, x0, x1, p1, td, tr_ui, tau_ui,
                       r_e, out):
    status = lut_eval_nb(ax_xc, ax_w, ax_p1, ax_td, ax_tr, ax_tau, ax_re, tab6, tab7, x0, x1, p1, td, tr_ui, tau_ui,
                         r_e, out)
    if status != 0:
        raise ValueError("waveform LUT query outside its validity domain")
    return status

@njit(cache=True)
def _locate_cell(ax, v):
    n = ax.shape[0]
    if v < ax[0]:
        return 0, 0.0, True
    if v > ax[n - 1]:
        return n - 2, 1.0, True
    i = np.searchsorted(ax, v, side="right") - 1
    if i > n - 2:
        i = n - 2
    if i < 0:
        i = 0
    return i, (v - ax[i]) / (ax[i + 1] - ax[i]), False

def __post_init__(self):
    self.axes = {k: np.ascontiguousarray(np.asarray(v, dtype=float)) for k, v in self.axes.items()}
    for k in _TAB6_AXES + ("re",):
        axis = self.axes[k]
        if axis.ndim != 1 or axis.size < 2 or np.any(np.diff(axis) <= 0):
            raise ValueError(f"axis {k} must be strictly increasing with >= 2 nodes")
    n6 = int(np.prod([self.axes[k].size for k in _TAB6_AXES]))
    self.tab6 = np.ascontiguousarray(np.asarray(self.tab6, dtype=np.float64).reshape(N_F6, n6))
    self.tab7 = np.ascontiguousarray(np.asarray(self.tab7, dtype=np.float64).reshape(N_F7,
                                                                                    n6 * self.axes["re"].size))

@property
def domain(self) -> dict:
    axes = self.axes
    return {"abs_xc": [0.0, float(axes["xc"][-1])], "w": [0.0, float(axes["w"][-1])],
            "p1": [float(axes["p1"][0]), float(axes["p1"][-1])], "td": [0.0, float(axes["td"][-1])],
            "tr_ui": [float(axes["tr"][0]), float(axes["tr"][-1])], "tau_ui": [float(axes["tau"][0]),
                float(axes["tau"][-1])],
            "r_e": [float(axes["re"][0]), float(axes["re"][-1])]}

def kernel_args(self) -> tuple:
    axes = self.axes
    return (axes["xc"], axes["w"], axes["p1"], axes["td"], axes["tr"], axes["tau"], axes["re"], self.tab6,
        self.tab7)

def load_lut(name_or_path: str | Path = "nrz", *, verify: bool = True) -> WaveformLUT:
    path = Path(name_or_path)
    if path.suffix != ".npz":
        path = EXTRACTED_DIR / f"waveform_lut_{name_or_path}.npz"
    side_path = path.with_suffix(".json")
    if not path.exists():
        raise FileNotFoundError(f"{path} not found (build it with python -m mrm.waveform.lut --name <name>)")
    if not side_path.exists():
        raise FileNotFoundError(f"sidecar {side_path.name} missing")
    sidecar = json.loads(side_path.read_text())
    if sidecar.get("schema") != SCHEMA:
        raise ValueError(f"{side_path.name}: schema {sidecar.get('schema')!r} is not {SCHEMA}")
    digest = _sha256(path)
    if verify and sidecar.get("sha256") != digest:
        raise ValueError(f"{path.name}: sha256 does not match its sidecar")
    with np.load(path, allow_pickle=False) as archive:
        axes = {k[3:]: archive[k] for k in archive.files if k.startswith("ax_")}
        config = json.loads(str(archive["config_json"]))
        lut = WaveformLUT(axes, archive["tab6"], archive["tab7"], config, str(archive["config_hash"]),
                          validation=sidecar.get("validation", {}), path=str(path), sha256=digest)
    if lut.config_hash != sidecar.get("config_hash") or _config_hash(config) != lut.config_hash:
        raise ValueError(f"{path.name}: config hash mismatch")
    return lut

def _sha256(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()

def _tool_versions() -> dict:
    from importlib.metadata import PackageNotFoundError, version
    out = {"python": sys.version.split()[0], "platform": platform.platform()}
    for p in ("numpy", "numba", "scipy"):
        try:
            out[p] = version(p)
        except PackageNotFoundError:
            out[p] = None
    return out

_STATUS_NAMES = {ST_XC: "|x_c| (detuning/HWHM)", ST_W: "w (swing/FWHM)", ST_P1: "mark density",
                 ST_TD: "transition density (incl. td <= 2 min(p1, 1 - p1))", ST_TR: "rise time/UI",
                 ST_TAU: "tau_p/UI", ST_RE: "kappa_e/kappa", ST_NONFINITE: "non-finite input"}

@njit(cache=True)
def tcmt_steady_nb(delta, kappa_i, kappa_e, kappa_d, g, s_in):
    complex_mode_decay_rate_per_s = 0.5 * (kappa_i + kappa_e + kappa_d) + 1j * delta
    backscatter_rate_magnitude_squared = g.real * g.real + g.imag * g.imag
    coupled_mode_determinant = (
        complex_mode_decay_rate_per_s * complex_mode_decay_rate_per_s + backscatter_rate_magnitude_squared
    )
    through_mode_drive_coefficient = math.sqrt(kappa_e)
    cw_mode_amplitude = (
        -1j * through_mode_drive_coefficient * complex_mode_decay_rate_per_s * s_in / coupled_mode_determinant
    )
    ccw_mode_amplitude = -through_mode_drive_coefficient * g.conjugate() * s_in / coupled_mode_determinant
    return cw_mode_amplitude, ccw_mode_amplitude

@njit(cache=True)
def _mode_step(
    mode_amplitude, mode_drive, start_growth_rate, midpoint_growth_rate, end_growth_rate, step_duration
):
    exponent = (
        step_duration * (start_growth_rate + 4.0 * midpoint_growth_rate + end_growth_rate) / 6.0
    )  # Lambda - Simpson's rule for int lambda dt
    half_step_propagator = cmath.exp(0.5 * exponent)
    full_step_propagator = half_step_propagator * half_step_propagator
    mean_growth_rate = exponent / step_duration
    drive_integral_weight = (
        full_step_propagator - 1.0
    ) / mean_growth_rate + step_duration * step_duration * (
        end_growth_rate - start_growth_rate
    ) * half_step_propagator / 12.0
    return full_step_propagator * mode_amplitude + mode_drive * drive_integral_weight

@njit(cache=True)
def tables_at_nb(v, grid, delta_tab, kappa_i_tab, out_delta, out_kappa_i):
    for j in range(v.shape[0]):
        out_delta[j] = np.interp(v[j], grid, delta_tab)
        out_kappa_i[j] = np.interp(v[j], grid, kappa_i_tab)

def optical_response_rates(
    kappa_i, kappa_e, kappa_d, delta, f_hz, *, ddelta=1.0, dkappa_i=0.0, g=0j, s_in=1.0, port="through"
):
    frequencies = np.atleast_1d(np.asarray(f_hz, dtype=float))
    mode_growth_rate = -(1j * delta + 0.5 * (kappa_i + kappa_e + kappa_d))
    backscatter_rate = complex(g)
    steady_cw_mode_amplitude, steady_ccw_mode_amplitude = tcmt_steady_nb(
        float(delta), float(kappa_i), float(kappa_e), float(kappa_d), backscatter_rate, complex(s_in)
    )
    cw_perturbation_drive = (
        -(1j * ddelta + 0.5 * dkappa_i) * steady_cw_mode_amplitude
    )  # forcing vector f = -(i Delta' + kappa_i'/2) a0
    ccw_perturbation_drive = -(1j * ddelta + 0.5 * dkappa_i) * steady_ccw_mode_amplitude
    # port power P = P0 + 2 Re(k_port da_mode)
    if port == "through":
        steady_through_field = s_in - 1j * math.sqrt(kappa_e) * steady_cw_mode_amplitude
        power_linearization_coefficient, observed_mode_index = (
            np.conj(steady_through_field) * (-1j * math.sqrt(kappa_e)),
            0,
        )
    elif port == "drop":
        power_linearization_coefficient, observed_mode_index = kappa_d * np.conj(steady_cw_mode_amplitude), 0
    elif port == "refl":
        power_linearization_coefficient, observed_mode_index = kappa_e * np.conj(steady_ccw_mode_amplitude), 1
    else:
        raise ValueError("port must be 'through', 'drop' or 'refl'")
    backscatter_rate_magnitude_squared = abs(backscatter_rate) ** 2

    def mode_response(s):
        # (sI - M)^{-1} f with M = [[lam, -i g], [-i g*, lam]] - det = (s - lam)^2 + |g|^2
        laplace_minus_growth_rate = s - mode_growth_rate
        coupled_mode_determinant = (
            laplace_minus_growth_rate * laplace_minus_growth_rate + backscatter_rate_magnitude_squared
        )
        if observed_mode_index == 0:
            return (
                laplace_minus_growth_rate * cw_perturbation_drive
                - 1j * backscatter_rate * ccw_perturbation_drive
            ) / coupled_mode_determinant
        return (
            -1j * backscatter_rate.conjugate() * cw_perturbation_drive
            + laplace_minus_growth_rate * ccw_perturbation_drive
        ) / coupled_mode_determinant

    s = 1j * _TWO_PI * frequencies
    return power_linearization_coefficient * mode_response(s) + np.conj(
        power_linearization_coefficient * mode_response(-s)
    )

def mode_response(s):
    # (sI - M)^{-1} f with M = [[lam, -i g], [-i g*, lam]] - det = (s - lam)^2 + |g|^2
    laplace_minus_growth_rate = s - mode_growth_rate
    coupled_mode_determinant = (
        laplace_minus_growth_rate * laplace_minus_growth_rate + backscatter_rate_magnitude_squared
    )
    if observed_mode_index == 0:
        return (
            laplace_minus_growth_rate * cw_perturbation_drive
            - 1j * backscatter_rate * ccw_perturbation_drive
        ) / coupled_mode_determinant
    return (
        -1j * backscatter_rate.conjugate() * cw_perturbation_drive
        + laplace_minus_growth_rate * ccw_perturbation_drive
    ) / coupled_mode_determinant

def h_opt_closed_form(s, kappa_i, kappa_e, kappa_d, delta):
    s = np.asarray(s, dtype=complex)
    total_decay_rate = kappa_i + kappa_e + kappa_d
    natural_frequency_squared = 0.25 * total_decay_rate * total_decay_rate + delta * delta
    d_through_power_fraction_d_detuning = (
        2.0 * delta * kappa_e * (kappa_i + kappa_d) / (natural_frequency_squared * natural_frequency_squared)
    )
    return (
        -d_through_power_fraction_d_detuning
        * (1.0 + s / (kappa_i + kappa_d))
        * natural_frequency_squared
        / (s * s + total_decay_rate * s + natural_frequency_squared)
    )

def __post_init__(self):
    self.v_grid = np.ascontiguousarray(np.asarray(self.v_grid, dtype=float))
    grid = self.v_grid
    if grid.ndim != 1 or grid.size < 2 or np.any(np.diff(grid) <= 0):
        raise ValueError("v_grid must be strictly increasing")
    for name in ("delta_tab", "kappa_i_tab", "eta_tab"):
        arr = np.asarray(getattr(self, name), dtype=float)
        if arr.ndim == 0:
            arr = np.full(grid.shape, float(arr))
        if arr.shape != grid.shape or not np.all(np.isfinite(arr)):
            raise ValueError(f"{name} must be finite with the shape of v_grid")
        setattr(self, name, np.ascontiguousarray(arr))
    if np.any(self.kappa_i_tab < 0) or not (self.kappa_e > 0) or not (self.kappa_d >= 0):
        raise ValueError("need kappa_i >= 0, kappa_e > 0, kappa_d >= 0")
    self.kappa_e = float(self.kappa_e)
    self.kappa_d = float(self.kappa_d)
    self.g = complex(self.g)

@classmethod
def from_rates(cls, kappa_i, kappa_e, kappa_d, delta_bias, *, v_bias=0.0, ddelta_dv=0.0, dkappa_i_dv=0.0,
               g=0j, eta=1.0, v_span=(-0.5, 4.0), n_grid=451) -> "RingTCMT":
    voltages = np.linspace(float(v_span[0]), float(v_span[1]), int(n_grid))
    detuning = delta_bias + ddelta_dv * (voltages - v_bias)
    intrinsic_loss = np.maximum(kappa_i + dkappa_i_dv * (voltages - v_bias), 0.0)
    return cls(kappa_e, kappa_d, g, voltages, detuning, intrinsic_loss, np.full(voltages.shape, float(eta)),
        meta={"kind": "linear"})

def f_detune(t_ring):
    phi, a_rt, _, k2_thru, k2_drop, trt = optics_at(t_ring, v_bias)
    kappa_i, kappa_e, kappa_d = tcmt_rates(k2_thru, k2_drop, a_rt, trt)
    delta = (phi - _TWO_PI * m_line) / trt
    return delta - 0.5 * x_bias * (kappa_i + kappa_e + kappa_d)

def steady(self, v, p_in_w=1.0) -> dict:
    v = np.atleast_1d(np.asarray(v, dtype=float))
    s_in = math.sqrt(p_in_w)
    cw_mode_amplitude = np.empty(v.shape, complex)
    ccw_mode_amplitude = np.empty(v.shape, complex)
    for i, vi in enumerate(v):
        cw_mode_amplitude[i], ccw_mode_amplitude[i] = tcmt_steady_nb(
            float(self.delta(vi)), float(self.kappa_i(vi)), self.kappa_e, self.kappa_d, self.g, complex(s_in)
        )
    return port_powers(
        cw_mode_amplitude, ccw_mode_amplitude, s_in, self.kappa_i(v), self.kappa_e, self.kappa_d, self.eta(v)
    )

def optical_response(self, v_bias, f_hz, *, port="through", p_in_w=1.0, loss_modulation=True):
    return optical_response_rates(float(self.kappa_i(v_bias)), self.kappa_e, self.kappa_d,
                                  float(self.delta(v_bias)), f_hz, ddelta=float(self.ddelta_dv(v_bias)),
                                  dkappa_i=float(self.dkappa_i_dv(v_bias)) if loss_modulation else 0.0,
                                  g=self.g, s_in=math.sqrt(p_in_w), port=port)

def _table_slope(v: float, grid: np.ndarray, tab: np.ndarray) -> float:
    if v < grid[0] or v > grid[-1]:
        return 0.0
    segment = int(np.searchsorted(grid, v, side="right")) - 1
    segment = min(max(segment, 0), grid.size - 2)
    d_table_value_d_voltage = (tab[segment + 1] - tab[segment]) / (grid[segment + 1] - grid[segment])
    node_tolerance = 1e-9 * (grid[-1] - grid[0])
    if abs(v - grid[segment]) <= node_tolerance and segment > 0:
        d_table_value_d_voltage = 0.5 * (
            d_table_value_d_voltage + (tab[segment] - tab[segment - 1]) / (grid[segment] - grid[segment - 1])
        )
    elif abs(v - grid[segment + 1]) <= node_tolerance and segment + 2 < grid.size:
        d_table_value_d_voltage = 0.5 * (
            d_table_value_d_voltage
            + (tab[segment + 2] - tab[segment + 1]) / (grid[segment + 2] - grid[segment + 1])
        )
    return float(d_table_value_d_voltage)

